        ["Select an Option"] = "Selecciona una opción",
        ["Can you decant some potions for me?"] = "¿Puedes decantarme algunas pociones?",
        ["Can you help me out with the prices for herbs?"] = "¿Me pueden ayudar con los precios de las hierbas?",
        ["I'd be happy to!"] = "¡Estaría encantado de hacerlo!",
        ["How much do you charge for decanting potions?"] = "¿Cuanto cobran por decantar pociones?",
        ["If you want potions decanted into 4, 3, 2 or 1 dose versions, I charge 2 coins for each normal vial, 2 coins for each juju vial and 15 coins for each powerburst vial."] = "Si quieres pociones decantadas en versiones de 4, 3, 2 o 1 dosis, cobro 2 coins por cada vial normal, 2 coins por cada vial de juju y 15 coins por cada vial de powerburst.",
        ["Sorry, I've got to go."] = "Lo siento, tengo que irme.",
        ["Okay, I'll be here if you ever need me, mesmerised by the lady's voice."] = "Está bien, estaré aquí si alguna vez me necesitas, hipnotizado por la voz de la dama.",
        ["Decant vials"] = "Decantar viales",
        ["How many doses do you want to decant into?"] = "¿En cuántas dosis quieres decantar?",
        ["One dose"] = "una dosis",
        ["There you go, chum."] = "Ahí lo tienes, amigo.",
        ["Sorry, I don't know how to decant anything that you're carrying."] = "Lo siento, no sé cómo decantar nada de lo que llevas.",
        ["Sorry, you don't have enough money to pay for enough empty vials."] = "Lo sentimos, no tienes suficiente dinero para pagar suficientes viales vacíos.",
        ["Your inventory's a bit too full for me to do anything for you."] = "Tu inventario está demasiado lleno para que pueda hacer algo por ti.",
        ["Two doses"] = "Dos dosis",
        ["Three doses"] = "Tres dosis",
        ["Four doses"] = "Cuatro dosis",
        ["Decant flasks"] = "Decantar matraces",
        ["Sorry, you don't seem to have anything I can use. Make sure you have 2 flasks that aren't completely full!"] = "Lo siento, parece que no tienes nada que pueda usar. ¡Asegúrate de tener 2 matraces que no estén completamente llenos!",
        ["Let's see what you have. I will decant your potion flasks back into 6 dosed flasks. I can make use of the flasks, so I'll take those as payment."] = "Veamos qué tienes. Decantaré sus frascos de poción nuevamente en 6 frascos dosificados. Puedo hacer uso de los frascos, así que los aceptaré como pago.",
        ["Here you go. That's the best I can do! If the flasks don't look too different, I gave them a clean"] = "Aquí tienes. ¡Eso es lo mejor que puedo hacer! Si los matraces no se ven muy diferentes, los limpié.",
        ["Convert vials to flasks"] = "Convertir viales en matraces",
        ["You'll need to supply the empty flasks yourself; they're not cheap. You can bring them to me noted or unnoted."] = "Tendrás que proporcionar los frascos vacíos tú mismo; no son baratos. Puedes traérmelos anotados o sin anotaciones.",
        ["Let's see what you have. I will decant potion vials and all flasks up to 4 doses into 6 dose flasks. You'll need to supply the empty flasks yourself; they're not cheap."] = "Veamos qué tienes. Decantaré los viales de poción y todos los frascos hasta 4 dosis en frascos de 6 dosis. Tendrás que proporcionar los matraces vacíos tú mismo; no son baratos.",
        ["Here you go. That's the best I can do!"] = "Aquí tienes. ¡Eso es lo mejor que puedo hacer!",
        ["Sorry you don't seem to have anything I can help you with! Make sure you have the correct potions and some free space in your inventory and I can try again."] = "¡Lo siento, parece que no tienes nada en lo que pueda ayudarte! Asegúrate de tener las pociones correctas y algo de espacio libre en tu inventario y podré intentarlo de nuevo.",
        ["Convert flasks to vials"] = "Convertir matraces en viales",
        ["Sorry, you don't seem to have anything I can use. Make sure you have at least 1 flask!"] = "Lo siento, parece que no tienes nada que pueda usar. ¡Asegúrate de tener al menos 1 matraz!",
        ["Certainly. I think I can make use of the flasks, so I'll give you the vials for free."] = "Por supuesto. Creo que puedo utilizar los matraces, así que te daré los viales gratis.",
        ["There you go, that's the best I can do!"] = "Ahí lo tienes, ¡eso es lo mejor que puedo hacer!",
        ["Cancel"] = "Cancelar",
    },
