        ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
        ["Yes."] = "Sí.",
        ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
        ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
