        ["First, go and kill [number] [monster]."] = "Primero, ve y mata a [número] [monster].",
        ["What have the [monster] done to anger the almighty Crondis?"] = "¿Qué han hecho los [monster] para enojar al todopoderoso Crondis?",
        ["You don't need to know. Will you go to kill them?"] = "No necesitas saberlo. ¿Irás a matarlos?",
        ["Select an option"] = "Selecciona una opción",
        ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
