dialogues.all = {
    ["Welcome to R.P.D.T.!"] = "¡Bienvenido a R.P.D.T.!",
    ["Thank you very much."] = "Muchas gracias.",
    ["You feed an ogleroot to one of the rabbits and it starts to disappear..."] = "Le das de comer una raíz de ogle a uno de los conejos y comienza a desaparecer...",
    ["Welcome to the Burthorpe Games Rooms!"] = "¡Bienvenido a las salas de juegos Burthorpe!",
    ["Select an Option"] = "Selecciona una opción",
    ["How do I play board games?"] = "¿Cómo juego juegos de mesa?",
    ["You can challenge someone to a game anywhere in the games rooms by using the right click option. Choose the type of game and then choose the options you want such as time per move. If you want to play a particular game"] = "Puedes desafiar a alguien a un juego en cualquier lugar de las salas de juegos usando la opción de clic derecho. Elige el tipo de juego y luego elige las opciones que quieras, como el tiempo por jugada. Si quieres jugar un juego en particular",
    ["there are challenge rooms dedicated to that game. In the challenge rooms you can see other players ranks by right clicking them, their skill will be displayed instead of their combat level. Once you have enough experience you will be"] = "hay salas de desafío dedicadas a ese juego. En las salas de desafío puedes ver los rangos de otros jugadores haciendo clic derecho sobre ellos; se mostrará su habilidad en lugar de su nivel de combate. Una vez que tengas suficiente experiencia, serás",
    ["able to use the challenge rooms on the first floor! If your opponent accepts the challenge you will be taken to one of the tables in the main room where you will play your game of choice. Once you have finished your game you will"] = "¡puedo usar las salas de desafío en el primer piso! Si tu oponente acepta el desafío, serás llevado a una de las mesas de la sala principal donde jugarás el juego que elijas. Una vez que hayas terminado tu juego podrás",
    ["go back to the challenge room where you can challenge again!"] = "¡Vuelve a la sala de desafíos donde podrás desafiar nuevamente!",
    ["What games can I play?"] = "¿Qué juegos puedo jugar?",
    ["Currently we offer Draughts, Runelink, Runesquares, and Runeversi."] = "Actualmente ofrecemos Drafts, Runelink, Runesquares y Runeversi.",
    ["Draughts?"] = "¿Borradores?",
    ["Draughts uses standard rules, apart from: a draw is declared if no piece has been taken or promoted for forty moves. To play Draughts go to the challenge room in the SW corner."] = "Drafts utiliza reglas estándar, aparte de: se declara empate si no se ha tomado ni promovido ninguna pieza durante cuarenta movimientos. Para jugar Drafts, ve a la sala de desafíos en la esquina SO.",
    ["Runelink?"] = "¿Enlace rune?",
    ["Yup, you have to get four runes in a row. The challenge room for Runelink is in the SE corner."] = "Sí, tienes que conseguir cuatro runas seguidas. La sala de desafíos de Runelink está en la esquina SE.",
    ["Runesquares?"] = "¿Cuadrados rúnicos?",
    ["Yes, you take it in turns to add a line with the goal of making squares. Everytime you make a square you take another turn. The challenge room for Runesquares is in the SW corner."] = "Sí, se turnan para agregar una línea con el objetivo de hacer cuadrados. Cada vez que haces un cuadrado das otro turno. La sala de desafíos de Runesquares está en la esquina suroeste.",
    ["Runeversi?"] = "¿Runeversi?",
    ["Yep, the aim is to have more of your runes on the board than your opponent. You can take your opponents pieces by trapping them between your own. The challenge room for Runeversi is in the SE corner."] = "Sí, el objetivo es tener más runas tuyas en el tablero que tu oponente. Puedes tomar las piezas de tus oponentes atrapándolas entre las tuyas. La sala de desafíos de Runeversi está en la esquina SE.",
    ["Do you have any news?"] = "¿Tienes alguna noticia?",
    ["There are some notice boards in the main entrance, check them from time to time for the latest news."] = "Hay algunos tablones de anuncios en la entrada principal, revísalos de vez en cuando para conocer las últimas novedades.",
    ["Can I buy a drink please?"] = "¿Puedo comprar una bebida, por favor?",
    ["Certainly [sir/miss], our speciality is Asgarnian Ale, we also serve Wizard's Mind Bomb and Dwarven Stout."] = "Ciertamente [sir/miss], nuestra especialidad es Asgarnian Ale, también servimos Wizard's Mind Bomb y Dwarven Stout.",
    ["Thanks!"] = "¡Gracias!",
    ["Bout ye?"] = "¿Sobre ti?",
    ["*(On first time the second option is selected without a prompt:)*"] = "*(La primera vez se selecciona la segunda opción sin que se le indique :)*",
    ["Select an option"] = "Selecciona una opción",
    ["I'd like to have a run around the track."] = "Me gustaría correr por la pista.",
    ["I'd like to go for a run around the track."] = "Me gustaría salir a correr por la pista.",
    ["Ah, ye want to run round the oul track, do ye?"] = "Ah, quieres correr por la pista, ¿verdad?",
    ["Yes."] = "Sí.",
    ["Aye, before ye go, have a wee pint, keep ye hydrated... I think."] = "Sí, antes de irte, tómate una pinta y mantente hidratado... creo.",
    ["*(If the warning has not been toggled off:)*"] = "*(Si la advertencia no se ha desactivado:)*",
    ["This activity gives Constitution XP. Are you sure you want to continue?"] = "Esta actividad le da XP a Constitution. ¿Estás seguro de que quieres continuar?",
    ["Start racing?"] = "¿Empezar a correr?",
    ["*(Dialogue terminates.)*"] = "*(El diálogo termina.)*",
    ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    ["*(If the warning has been toggled off:)*"] = "*(Si la advertencia se ha desactivado:)*",
    ["Ach, come back if ye change yer mind!"] = "¡Ach, vuelve si cambias de opinión!",
    ["What do I have to do here again?"] = "¿Qué tengo que hacer aquí otra vez?",
    ["What do I have to do here?"] = "¿Qué tengo que hacer aquí?",
    ["Let me tell ye a wee story about a wolpertinger and a tortoise."] = "Déjame contarte una pequeña historia sobre un wolpertinger y una tortuga.",
    ["Sure."] = "Claro.",
    ["Aye, it's a cracker! Ye see, there's this here wolpertinger an' he wants a race."] = "¡Sí, es una galleta! Verás, aquí hay un Wolpertinger que quiere una carrera.",
    ["Ye might think he's gonna go for a wee dander, but wait til I tell ye..."] = "Podrías pensar que le va a dar un poco de caspa, pero espera a que te lo diga...",
    ["The eejit's tearin' round the track!"] = "¡El eejit está dando vueltas por la pista!",
    ["Hic!"] = "¡Hola!",
    ["He's weavin' in an' out o' the lanes..."] = "Está entrando y saliendo de los carriles...",
    ["Eatin' all the pretzels..."] = "Comiendo todos los pretzels...",
    ["Wathin' out fer the stools..."] = "Esperando los taburetes...",
    ["Not drinkin' too much!"] = "¡No beber demasiado!",
    ["Ye see, here's the situation... here it is..."] = "Verás, esta es la situación... aquí está...",
    ["She makes a fantastic casserole..."] = "Hace una cazuela fantástica...",
    ["Uh?"] = "¿Eh?",
    ["Casserole?"] = "¿Cazuela?",
    ["Wait... wasn't there supposed to be a tortoise in this story?"] = "Espera... ¿no se suponía que había una tortuga en esta historia?",
    ["Nah, it was a chicken casserole."] = "No, era una cazuela de pollo.",
    ["You definitely said something about a tortoise."] = "Definitivamente dijiste algo sobre una tortuga.",
    ["Why would ye put tortoise in a casserole?"] = "¿Por qué pondrías una tortuga en una cazuela?",
    ["Tortoise... now, tortoise goes in a stew."] = "Tortuga... ahora, la tortuga va en un guiso.",
    ["Let me tell ye about makin' a good stew... First of all ye need to get some bananas..."] = "Déjame contarte cómo hacer un buen guiso... Primero que nada necesitas conseguir algunos plátanos...",
    ["The dwarf continues to ramble on about a stew recipe. It is quite clear that he is a little too tipsy to tell a coherent story."] = "El enano sigue divagando sobre una receta de guiso. Está bastante claro que está demasiado borracho para contar una historia coherente.",
    ["You manage to read between the lines of the dwarf's story."] = "Consigues leer entre líneas la historia del enano.",
    ["Run around the track to gain constitution XP. Collecting pretzels will increase the rate at which XP is gained while tripping over stools will reduce the amount. Avoid kegs altogether or you will be too drunk to continue!"] = "Corre por la pista para ganar XP de constitución. Recolectar pretzels aumentará la velocidad a la que se gana XP, mientras que tropezar con las heces reducirá la cantidad. ¡Evita los barriles por completo o estarás demasiado borracho para continuar!",
    ["Give me the short version."] = "Dame la versión corta.",
    ["A short version? Aye, okay... So there's this wolpertinger..."] = "¿Una versión corta? Sí, está bien... Entonces está este wolpertinger...",
    ["The dwarf goes on a bit of a ramble."] = "El enano se pone a divagar un poco.",
    ["Ye can't bring followers on the track! Send 'em away and then give me a shout."] = "¡No puedes traer seguidores a la pista! Envíalos lejos y luego avísame.",
    ["*(Before River of Blood:)*"] = "*(Antes de Río de Sangre:)*",
    ["Hey it's the hero! Wow, you're amazing! How on earth did you manage to tackle those two juvinates and Gadderanks? And the town is lovely - you've done a great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo diablos lograste enfrentarte a esos dos juvinates y Gadderanks? Y la ciudad es preciosa. ¡Has hecho un gran trabajo!",
    ["*(After River of Blood:)*"] = "*(Después de Río de Sangre :)*",
    ["Hey it's the hero! Wow, you're amazing! How did you manage to return all the villagers? Things feel so much safer around here now too - great job!"] = "¡Oye, es el héroe! ¡Guau, eres increíble! ¿Cómo conseguiste devolver a todos los aldeanos? Ahora las cosas también se sienten mucho más seguras por aquí: ¡excelente trabajo!",
    ["You're more than welcome."] = "De nada.",
    ["What do you do here?"] = "¿Qué haces aquí?",
    ["Oh, my name's Radu. I just help out around here, you know, look for food and so on."] = "Oh, mi nombre es Radu. Sólo ayudo por aquí, ya sabes, busco comida y demás.",
    ["How do you like your town?"] = "¿Qué te parece tu ciudad?",
    ["It's just perfect, thanks so much for your efforts."] = "Es simplemente perfecto, muchas gracias por tus esfuerzos.",
    ["What's happening around here?"] = "¿Qué está pasando por aquí?",
    ["Oh, not much really, we're all still hiding from the vampyres and eking out a living from this terrible place, hopefully soon we'll be strong enough to make the journey to the temple on the Salve."] = "Oh, no mucho en realidad, todos todavía nos estamos escondiendo del vampyres y ganándonos la vida a duras penas en este terrible lugar, con suerte pronto seremos lo suficientemente fuertes para hacer el viaje al templo en la Salve.",
    ["Oh, not much really, we're all just trying to eke out a living in this place. Some of us still want to head for the Salve and into Misthalin, but honestly, it's not so bad here anymore...in spite of how it might look."] = "Oh, no mucho en realidad, todos estamos tratando de ganarnos la vida a duras penas en este lugar. Algunos de nosotros todavía queremos dirigirnos a la Salve y a Misthalin, pero, sinceramente, ya no está tan mal aquí... a pesar de cómo pueda parecer.",
    ["Is there anything I can do to help out?"] = "¿Hay algo que pueda hacer para ayudar?",
    ["Not as far as I know, we have some basic amenities now which is so very useful, we're all incredibly grateful to you. I've never really seen or known a hero before, so I have nothing to compare one to, but I suspect in most people's judgement, you would be one! I for one am very pleased to have met you."] = "No que yo sepa, ahora contamos con algunos servicios básicos que son muy útiles y todos te estamos increíblemente agradecidos. Nunca antes había visto o conocido a un héroe, así que no tengo nada con qué compararlo, pero sospecho que, a juicio de la mayoría de la gente, ¡tú serías uno! Por mi parte, estoy muy contento de haberte conocido.",
    ["Okay, thanks."] = "Está bien, gracias.",
    ["Hello."] = "Hola.",
    ["I see you have managed to mess things up again."] = "Veo que has logrado estropear las cosas otra vez.",
    ["Why do you say that?"] = "¿Por qué dices eso?",
    ["Well the ceremony should have been over by now, yet the plagues remain."] = "Bueno, la ceremonia ya debería haber terminado, pero las plagas persisten.",
    ["Unfortunately some other hapless adventurer was tricked in the same manner as me."] = "Desafortunadamente, otro desafortunado aventurero fue engañado de la misma manera que yo.",
    ["All you adventurers are alike!"] = "¡Todos ustedes, aventureros, son iguales!",
    ["Well if it isn't the great adventurer Player? Ready to mess things up here again?"] = "¿Y si no es el gran aventurero Player? ¿Listo para estropear las cosas aquí otra vez?",
    ["What are you talking about?"] = "¿De qué estás hablando?",
    ["I've had these spots since the last time you tried to help. I'm wondering what's going to happen this time."] = "He tenido estos granos desde la última vez que intentaste ayudar. Me pregunto qué va a pasar esta vez.",
    ["I fixed everything I disturbed, the spots you are suffering from are the result of the actions of another adventurer."] = "Arreglé todo lo que molesté, los puntos que estás sufriendo son el resultado de las acciones de otro aventurero.",
    ["**Player:** In what way?"] = "**Player:** ¿De qué manera?",
    ["You're all trouble. Well I could hold it against you, but then again adventurers are my best customers. So may I interest you in any of my wares?"] = "Eres todo un problema. Bueno, podría reprochártelo, pero claro, los aventureros son mis mejores clientes. Entonces, ¿puedo interesarle alguno de mis productos?",
    ["What do you have?"] = "¿Qué tienes?",
    ["No thanks."] = "No, gracias.",
    ["What are you doing?"] = "¿Qué estás haciendo?",
    ["I thought this acne potion might help ease your spots."] = "Pensé que esta poción para el acné podría ayudar a aliviar tus manchas.",
    ["Ok let's give it a go so."] = "Ok, intentémoslo.",
    ["Aghhh!!! I got some in my eye. Owwww it stings."] = "¡¡¡Aghhh!!! Tengo algo en el ojo. Owww duele.",
    ["Oh stop being so soft."] = "Oh, deja de ser tan suave.",
    ["Well?"] = "¿Y bien?",
    ["Well what?"] = "¿Y bien qué?",
    ["Did it work?"] = "¿Funcionó?",
    ["Well...umm...no."] = "Bueno... umm... no.",
    ["What? You intolerable, insufferable idiot. I've just burned out my eye for no reason? I would say get out of my sight but that's not far enough away."] = "¿Qué? Eres un idiota intolerable e insoportable. ¿Me acabo de quemar el ojo sin motivo alguno? Yo diría que te fueras de mi vista, pero eso no es lo suficientemente lejos.",
    ["Sorry I was just trying to help."] = "Lo siento, solo estaba tratando de ayudar.",
    ["Scram or I'll give you something to feel sorry about!"] = "¡Lárgate o te daré algo por lo que sentir pena!",
    ["*(One of the following is seen every 30 seconds:)*"] = "*(Se ve uno de los siguientes cada 30 segundos:)*",
    ["Balthazar Beauregard's RuneScape Raffle in Burthorpe."] = "Rifa RuneScape de Balthazar Beauregard en Burthorpe.",
    ["Check out Balthazar Beauregard's RuneScape Raffle in Burthorpe for great prizes!"] = "¡Echa un vistazo al sorteo RuneScape de Balthazar Beauregard en Burthorpe para obtener fantásticos premios!",
    ["From the team that brought you the Greatest Show on RuneScape win prizes galore!"] = "¡Del equipo que te trajo el mejor espectáculo en RuneScape, gana premios en abundancia!",
    ["Have you got your ticket? The prizes are huge!"] = "¿Tienes tu entrada? ¡Los premios son enormes!",
    ["Have you heard of Balthazar's RuneScape Raffle? Get your ticket south of the Burthorpe lodestone!"] = "¿Has oído hablar del sorteo RuneScape de Balthazar? ¡Consigue tu entrada al sur del Burthorpe lodestone!",
    ["Ok thanks."] = "Ok, gracias.",
    ["Roll up! Roll up! Head to Burthorpe to check out Balthazar's RuneScape Raffle!"] = "¡Enróllate! ¡Arremangar! ¡Dirígete a Burthorpe para ver el sorteo RuneScape de Balthazar!",
    ["Will do."] = "Lo haré.",
    ["I'm sorry, the raffle is over now. You're too late! But you can hand in any leftover tickets to Balthazar at Burthorpe!"] = "Lo siento, el sorteo ya terminó. ¡Llegas demasiado tarde! ¡Pero puedes entregarle las entradas sobrantes a Balthazar en Burthorpe!",
    ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    ["You don't look so well, is everything alright?"] = "No te ves muy bien, ¿está todo bien?",
    ["No, outerlander. Now go away."] = "No, extranjero. Ahora vete.",
    ["It is most unusual, outerlander, that you were able to help us in this manner. But you have my thanks."] = "Es muy inusual, extranjero, que hayas podido ayudarnos de esta manera. Pero tienes mi agradecimiento.",
    ["Please, now, leave me alone for awhile while I watch the rippling of the water."] = "Por favor, ahora déjame en paz un rato mientras observo las ondas del agua.",
    ["I have good news. I have been to the afterlife and Asleif is there, happy and peaceful."] = "Tengo buenas noticias. He estado en el más allá y Asleif está allí, feliz y en paz.",
    ["Thank you, friend. This is great news."] = "Gracias, amigo. Esta es una gran noticia.",
    ["Hello there!"] = "¡Hola!",
    ["Oh, er, hello. What do you want?"] = "Ah, ejem, hola. ¿Qué deseas?",
    ["What can you tell me about Al Kharid?"] = "¿Qué puedes contarme sobre Al Kharid?",
    ["There's not much farming land around here. Only that little patch outside."] = "No hay mucha tierra agrícola por aquí. Sólo ese pequeño parche afuera.",
    ["Can you give me any advice on farming here in the desert?"] = "¿Puedes darme algún consejo sobre cómo cultivar aquí en el desierto?",
    ["Like I said, I only know about cactuses..."] = "Como dije, solo sé de cactus...",
    ["Just tell me about cactuses, then."] = "Entonces, háblame de los cactus.",
    ["First you have to weed the patch using a rake."] = "Primero debes quitar las malas hierbas del parche con un rastrillo.",
    ["Can you give me any other advice?"] = "¿Puedes darme algún otro consejo?",
    ["Not really. I've not done much farming recently."] = "En realidad, no. No he cultivado mucho últimamente.",
    ["Well, can you at least sell me any gardening tools or seeds?"] = "Bueno, ¿al menos podrías venderme herramientas de jardinería o semillas?",
    ["Sorry. They haven't been delivered yet."] = "Lo siento. Aún no han sido entregados.",
    ["So, what do you do here?"] = "Entonces, ¿qué haces aquí?",
    ["I'm going to set up a shop selling farming implements. That patch out there may be small, but it's all we've got."] = "Voy a montar una tienda que venda implementos agrícolas. Ese parche puede ser pequeño, pero es todo lo que tenemos.",
    ["*If the player has asked any of the Al Kharid merchants about Ali Morrisane:*"] = "*Si el player ha preguntado a alguno de los comerciantes de Al Kharid sobre Ali Morrisane:*",
    ["I hear you work for Ali Morrisane..."] = "He oído que trabajas para Ali Morrisane...",
    ["Yes, he bought these tents and had them put up for us. He says he'll also get our goods in so we can start selling them soon."] = "Sí, compró estas tiendas de campaña y las hizo montar para nosotros. Dice que también recibirá nuestros productos para que podamos empezar a venderlos pronto.",
    ["I only know how to farm cactuses, so this spot is perfect."] = "Sólo sé cultivar cactus, así que este lugar es perfecto.",
    ["Maybe I should talk to him..."] = "Quizás debería hablar con él...",
    ["Of course. He's always happy to talk to possible business partners."] = "Por supuesto. Siempre está feliz de hablar con posibles socios comerciales.",
    ["*If the player has asked Shop assistant or Shopkeeper about Ali Morrisane:*"] = "*Si el player ha preguntado a Shop assistant o Shopkeeper sobre Ali Morrisane:*",
    ["I hear you've been threatening the other shopkeepers."] = "He oído que has estado amenazando a los demás comerciantes.",
    ["Now why would you think that?"] = "¿Por qué piensas eso?",
    ["One of the shopkeepers told they were threatened by a man with a rake..."] = "Uno de los comerciantes dijo que fue amenazado por un hombre con un rastrillo...",
    ["Those people just don't want us to succeed. Don't listen to them!"] = "Esas personas simplemente no quieren que tengamos éxito. ¡No los escuches!",
    ["I wouldn't poke a mammoth in this heat, if I were you."] = "Si fuera tú, no empujaría a un mamut con este calor.",
    ["GRRR..|colour=#99FF99|bg=#0A1720}}"] = "GRRR..|color=#99FF99|bg=#0A1720}}",
    ["The flow has been interrupted! He is roused!|colour=#99FF99|bg=#0A1720}}"] = "¡Se ha interrumpido el flujo! ¡Está despertado!|color=#99FF99|bg=#0A1720}}",
    ["Do not let him absorb the shadow!"] = "¡No dejes que absorba la sombra!",
    ["GAH!!"] = "¡¡GAH!!",
    ["Raksha prepares to send out 5 waves of energy."] = "Raksha se prepara para enviar 5 ondas de energía.",
    ["Raksha begins to stamp the ground in anger. Watch out!"] = "Raksha comienza a patear el suelo con ira. ¡Cuidado!",
    ["You may think you hear it speaking. Ignore it and focus!"] = "Puedes creer que lo escuchas hablar. ¡Ignóralo y concéntrate!",
    ["THERE YOU ARE."] = "AQUÍ ESTÁS.",
    ["YOUR THOUGHTS BETRAY YOU."] = "TUS PENSAMIENTOS TE TRAICIONAN.",
    ["Raksha begins to poison your mind with shadow energy."] = "Raksha comienza a envenenar tu mente con energía de las sombras.",
    ["You must not let him poison your mind. It will kill you!"] = "No debes dejar que envenene tu mente. ¡Te matará!",
    ["You expel the poisonous shadow energy from your mind."] = "Expulsas la energía venenosa de la sombra de tu mente.",
    ["Raksha begins to bombard you with shadow bombs. Watch out!"] = "Raksha comienza a bombardearte con bombas de sombra. ¡Cuidado!",
    ["FLEE, INSECT."] = "FLEE, INSECTO.",
    ["SUCH A FRAIL CREATURE."] = "UNA CRIATURA TAN FRÁGIL.",
    ["The shadow grows thicker. You must defeat him quickly!"] = "La sombra se vuelve más espesa. ¡Debes derrotarlo rápidamente!",
    ["YOU ARE MY PREY."] = "Y ERES MI PRESA.",
    ["It's too dangerous. I'll open the gates. Lure him through!"] = "Es demasiado peligroso. Abriré las puertas. ¡Atraelo!",
    ["YOU ARE UNWISE TO FREE ME."] = "Y USTED ES IMPRUDENTE AL LIBERARME.",
    ["NO! RELEASE ME! RELEASE ME!"] = "NO! ¡LIBERAME! ¡LIBERAME!",
    ["You must finish him quickly. The secondary defences will not hold for long!"] = "Debes acabar con él rápidamente. ¡Las defensas secundarias no aguantarán por mucho tiempo!",
    ["I WILL DRAG YOU INTO EREBUS."] = "I TE ARRASTRARÁ A EREBUS.",
    ["Hide behind the posts!"] = "¡Escóndete detrás de los postes!",
    ["*(If the player interrupts the attack:)*"] = "*(Si el player interrumpe el ataque:)*",
    ["You interrupt Raksha's powerful attack before he could finish charging it."] = "Interrumpes el poderoso ataque de Raksha antes de que pueda terminar de cargarlo.",
    ["Collect that shadow!"] = "¡Recoge esa sombra!",
    ["The pain... subsides..."] = "El dolor... remite...",
    ["Well done. I will return Raksha to his confinement."] = "Bien hecho. Devolveré a Raksha a su confinamiento.",
    ["RRRROOOOOAARRR!"] = "RRRROOOOAARRR!",
    ["JOIN ME IN TORMENT."] = "ÚNETE A MÍ EN EL TORMENTO.",
    ["*(The following text is transcribed from the voice files. It is not verbatim.)*"] = "*(El siguiente texto está transcrito de los archivos de voz. No es palabra por palabra.)*",
    ["Be mindful of your surroundings.|colour=#99FF99|bg=#0A1720}}"] = "Sea consciente de su entorno.|color=#99FF99|bg=#0A1720}}",
    ["You must find opportunities to strike."] = "Debes encontrar oportunidades para atacar.",
    ["You must stay one step ahead of him to survive!"] = "¡Debes ir un paso por delante de él para sobrevivir!",
    ["Raksha is a predator, a perfect engine of your destruction!"] = "Raksha es un depredador, ¡un motor perfecto para tu destrucción!",
    ["When I battled Raksha, he was even MORE powerful!"] = "Cuando luché contra Raksha, ¡era aún MÁS poderoso!",
    ["The shadow energy is lethal. Watch out!"] = "La energía de las sombras es letal. ¡Cuidado!",
    ["Do not let it touch you!"] = "¡No dejes que te toque!",
    ["Containment is collapsing. You must fall back to the antechamber!"] = "La contención está colapsando. ¡Debes retroceder a la antecámara!",
    ["The oubliette is too damaged. We must fall back to the antechamber!"] = "La mazmorra está demasiado dañada. ¡Debemos retroceder a la antecámara!",
    ["Good. Now he's weakened, lure him into the antechamber."] = "Bien. Ahora que está debilitado, atráelo a la antecámara.",
    ["I SEE YOU.|colour=#99FF99|bg=#0A1720}}"] = "I NOS VEMOS.|color=#99FF99|bg=#0A1720}}",
    ["I WILL DEVOUR YOU."] = "I TE DEVORARÁ.",
    ["YOUR EYES WILL BE OPENED."] = "TUS OJOS SE ABRIRÁN.",
    ["RELEASE ME!"] = "¡LIBERAME!",
    ["NOTHING CAN CONTAIN MY HATRED!"] = "¡NADA PUEDE CONTENER MI ODIO!",
    ["NOTHING ON THIS WORLD CAN CHALLENGE ME!"] = "¡NADA EN ESTE MUNDO PUEDE DESAFÍARME!",
    ["THE SHADOW WILL CONSUME EVERYTHING."] = "LA SOMBRA LO CONSUMIRÁ TODO.",
    ["IT IS COMING."] = "IT ESTÁ VIENDO.",
    ["SOON!"] = "PRONTO!",
    ["DO YOU REALLY THINK YOU CAN SAVE THEM?"] = "¿DE VERDAD CREES QUE PUEDES SALVARLOS?",
    ["I have a special request for [breed]. Especially if it has the [Trait] trait!"] = "Tengo una solicitud especial para [breed]. ¡Especialmente si tiene el rasgo [Trait]!",
    ["I'm also after some Sheep, in fact I'll buy up to [number] more while I'm here."] = "También busco Sheep, de hecho compraré hasta [número] más mientras esté aquí.",
    ["Would you like to sell [name] for [number] beans?"] = "¿Le gustaría vender [name] por frijoles [número]?",
    ["Sell [name] for [number] beans?"] = "¿Vender [name] por frijoles [número]?",
    ["Your currency pouch is full of beans! You need to spend some beans before you can earn any more."] = "¡Tu bolsa de monedas está llena de frijoles! Necesitas gastar algunos frijoles antes de poder ganar más.",
    ["You can't hold anymore beans, I can't purchase this animal off you."] = "No puedes aguantar más frijoles, no puedo comprarte este animal.",
    ["This transaction would take you over the cap of one million beans. In doing so, you would lose out on [number] beans."] = "Esta transacción le llevaría por encima del límite de un millón de frijoles. Al hacerlo, perdería beans [número].",
    ["Complete transaction anyway?"] = "¿Completar la transacción de todos modos?",
    ["[number] beans added to your currency pouch."] = "Frijoles [número] agregados a su bolsa de divisas.",
    ["Let me check what animals I have which match your request."] = "Déjame comprobar qué animales tengo que coincidan con tu solicitud.",
    ["I've bought all the animals I need for now, catch you later!"] = "He comprado todos los animales que necesito por ahora, ¡nos vemos más tarde!",
    ["Are you sure you want me to take all the Sheep you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que tome todo el Sheep que tienes en la mano? No aceptaré ninguno de tus favoritos.",
    ["Sell all of your sheep?"] = "¿Vender todas tus ovejas?",
    ["Yes"] = "si",
    ["You don't have any animals to sell. Zero animals, Zero beans!"] = "No tienes animales para vender. ¡Cero animales, cero frijoles!",
    ["You've sold [number] animals for [number] total beans."] = "Has vendido animales [número] por un total de frijoles [número].",
    ["That one looks a little too violent to shear..."] = "Ese parece demasiado violento para cortarlo...",
    ["Can I 'elp you, monsieur?"] = "¿Puedo ayudarle, señor?",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["You've got an interesting accent!"] = "¡Tienes un acento interesante!",
    ["Oui, I 'ave perfected zis accent for when I worked for my father in Ardougne. He is a baker in ze market, and 'e believes ze customers will think ze bread of higher quality if it is made by a foreigner."] = "Sí, he perfeccionado este acento cuando trabajaba para mi padre en Ardougne. Es panadero en el mercado y cree que los clientes pensarán que el pan es de mayor calidad si lo elabora un extranjero.",
    ["And does that work?"] = "¿Y eso funciona?",
    ["Perhaps. I do not care for ze bread; it is ze fish zat shall be my future."] = "Quizás. No me gusta el pan; es el pescado que será mi futuro.",
    ["Good luck with that!"] = "¡Buena suerte con eso!",
    ["Why do you work in a fishing colony?"] = "¿Por qué trabajas en una colonia de pescadores?",
    ["Ahh, it is because I love ze sea. Ze rushing waters, ze endless horizon - it is beautiful! Also, I like ze fresh fish."] = "Ahh, es porque amo el mar. Las aguas que corren, el horizonte infinito: ¡es hermoso! Además, me gusta el pescado fresco.",
    ["It seems like rather hard work - can't you just get a beach house on Karamja?"] = "Parece un trabajo bastante duro. ¿No puedes simplemente conseguir una casa en la playa en Karamja?",
    ["Zat, I am afraid, is not for me an option. Besides, I 'ave read of ze island of Karamja - it is full of ze big green spiders, and I like zem not!"] = "Me temo que Zat no es una opción para mí. Además, he leído sobre la isla de Karamja: está llena de grandes arañas verdes, ¡y no me gustan!",
    ["Fair enough."] = "Muy bien.",
    ["No thanks, I'm alright."] = "No, gracias, estoy bien.",
    ["Ahh, farewell."] = "Ahh, adiós.",
    ["I 'ave ze puzzle for you to solve."] = "Tengo este rompecabezas para que lo resuelvas.",
    ["[Ramara has given you a puzzle box!]"] = "[¡Ramara te ha regalado una caja de rompecabezas!]",
    ["You can do better than zat!"] = "¡Puedes hacerlo mejor que zat!",
    ["[Ramara has given you another clue scroll!]"] = "[¡Ramara te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["Zat's wonderful!"] = "¡Zat es maravilloso!",
    ["Can you help me upgrade my pickaxe?"] = "¿Puedes ayudarme a mejorar mi pico?",
    ["[Ramarno thoroughly pats you down and ruffles through your backpack. He pauses to carefully hand-inspect anything you are carrying or wielding that's even remotely pickaxe-shaped.]"] = "[Ramarno te cachea minuciosamente y revuelve tu backpack. Hace una pausa para inspeccionar cuidadosamente cualquier cosa que lleves o empuñes y que tenga incluso remotamente forma de pico.]",
    ["You need an earth and song pickaxe if you want me to help you upgrade it."] = "Necesitas un pico de tierra y canción si quieres que te ayude a mejorarlo.",
    ["[You show your pickaxe of earth and song to Ramarno.]"] = "[Muestras tu pico de tierra y canción a Ramarno.]",
    ["[The blind dwarven sage runs his fingers over the head and handle. He grunts in appreciation.]"] = "[El sabio enano ciego pasa los dedos por la cabeza y el mango. Él gruñe en agradecimiento.]",
    ["Not bad. There is imcando dwarf-ufacturing here. But we can make it better."] = "No está mal. Aquí hay una fabricación enana imcando. Pero podemos mejorarlo.",
    ["You can make this pickaxe even more powerful? How?"] = "¿Puedes hacer que este pico sea aún más poderoso? ¿Cómo?",
    ["An ancient method, passed down by my grandfather, before he met his end."] = "Un método antiguo, transmitido por mi abuelo, antes de que encontrara su fin.",
    ["To make it, you must obtain a strange material from a dark and mysterious rock, known as 'black stone'."] = "Para hacerlo, debes obtener un material extraño de una roca oscura y misteriosa, conocida como 'piedra negra'.",
    ["I've heard of an island to the far south-east where such a rock may be located. It is likely still the domain of pirates and other horrors."] = "He oído hablar de una isla en el extremo sureste donde se puede ubicar una roca así. Probablemente siga siendo dominio de piratas y otros horrores.",
    ["I've got a fever, and the only prescription is more pirate quests."] = "Tengo fiebre y la única receta son más misiones piratas.",
    ["Black stone. Unspeakable horrors. Pirate island. Got it."] = "Piedra negra. Horrores indescriptibles. Isla Pirate. Entiendo.",
    ["I mined a mysterious black stone fragment from a stone slab on Mos Le'Harmless."] = "Extraje un misterioso fragmento de piedra negra de una losa de piedra en Mos Le'Harmless.",
    ["But I lost it."] = "Pero lo perdí.",
    ["[Ramarno cannot return your item, because your backpack is full.]"] = "[Ramarno no puede devolver su artículo porque su backpack está lleno.]",
    ["[Ramarno returns your lost item.]"] = "[Ramarno le devuelve su artículo perdido.]",
    ["You must obtain a moonstone imbued with the power of the underworld. I know nothing of such practice, but you must somehow attune your pickaxe with the moonstone."] = "Debes obtener una piedra lunar imbuida del poder del inframundo. No sé nada de esa práctica, pero de alguna manera debes armonizar tu pico con la piedra lunar.",
    ["If only I knew someone who could formally teach me how to craft moonstone jewellery..."] = "Si tan solo conociera a alguien que pudiera enseñarme formalmente cómo fabricar joyas con piedra lunar...",
    ["I know someone who knows how to work with moonstone. The former master crafter in the city of Um taught me how to craft moonstone jewellery."] = "Conozco a alguien que sabe trabajar con piedra lunar. El former master crafter del city of Um me enseñó a fabricar joyas de piedra lunar.",
    ["I ensouled a moonstone by performing a necromancy ritual."] = "Le di vida a una piedra lunar realizando un ritual de nigromancia.",
    ["I now need to feed the moonstone by mining with stone spirits."] = "Ahora necesito alimentar la piedra lunar extrayéndola con espíritus de piedra.",
    ["I mined until the ensouled moonstone's hunger for stone spirits was sated."] = "Miné hasta que el hambre de espíritus de piedra de la piedra lunar con alma fue saciada.",
    ["I now need to attune the moonstone to the spiritual frequency of my pickaxe of earth and song by mining tough rocks."] = "Ahora necesito sintonizar la piedra lunar con la frecuencia espiritual de mi pico de tierra y mi canción extrayendo rocas duras.",
    ["I attuned an ensouled moonstone to the spiritual frequency of my pickaxe."] = "Sintonicé una piedra lunar con alma con la frecuencia espiritual de mi pico.",
    ["Finally, you must obtain a metal fragment from the core of a meteorite."] = "Finalmente, deberás obtener un fragmento de metal del núcleo de un meteorito.",
    ["Hmm, perhaps I could find that in a shooting star."] = "Hmm, tal vez podría encontrar eso en una estrella fugaz.",
    ["I mined a metallic meteorite fragment from a shooting star."] = "Extraje un fragmento de meteorito metálico de una estrella fugaz.",
    ["[Ramarno rubs his grubby hands over the items be asked you to obtain, until he is satisfied.]"] = "[Ramarno frota sus manos sucias sobre los artículos que le piden que obtenga, hasta que queda satisfecho.]",
    ["Well done. Now, there are two more items I require..."] = "Bien hecho. Ahora, necesito dos elementos más...",
    ["Well, one million and one items, to be precise."] = "Bueno, un millón de artículos, para ser precisos.",
    ["Let me guess. A redberry pie and one million coins?"] = "Déjame adivinar. ¿ A pastel de frutos rojos y un millón de coins?",
    ["The sacred tradition of my people must be upheld."] = "Se debe mantener la sagrada tradición de mi pueblo.",
    ["Also, listening to you run all these errands has made me hungry."] = "Además, escucharte hacer todos esos recados me ha dado hambre.",
    ["[Ramarno licks his lips, hungrily waiting for you to line his pockets and his stomach.]"] = "[Ramarno se lame los labios, esperando con avidez que le llenes los bolsillos y el estómago.]",
    ["[You reluctantly give Ramarno one million coins and a redberry pie.]"] = "[De mala gana, le das a Ramarno un millón de coins y un pastel de frutos rojos.]",
    ["[Ramarno devours the redberry pie and greasily pockets his fee.]"] = "[Ramarno devora el pastel de frutos rojos y se embolsa grasientamente su tarifa.]",
    ["Let me guess. You want another million coins and a redberry pie?"] = "Déjame adivinar. ¿Quieres otro millón de coins y una tarta de frutos rojos?",
    ["What? No, you've already paid me once. You have all the items you require."] = "¿Qué? No, ya me pagaste una vez. Tienes todos los artículos que necesitas.",
    ["You may now use the sacred forge to upgrade your pickaxe."] = "Ahora puedes usar la forja sagrada para mejorar tu pico.",
    ["[Ramarno gives you one of the ingredients you need to forge a pickaxe of life and death.]"] = "[Ramarno te brinda uno de los ingredientes que necesitas para forjar un pico de vida o muerte.]",
    ["I hear you have another pickaxe of earth and song. Go ahead and use my sacred forge to upgrade it. No charge."] = "He oído que tienes otro pico de tierra y canción. Continúe y use mi forja sagrada para mejorarla. Sin cargo.",
    ["Can you help me upgrade my hatchet?"] = "¿Puedes ayudarme a mejorar mi hacha?",
    ["[Ramarno thoroughly pats you down and ruffles through your backpack. He pauses to carefully hand-inspect anything you are carrying or wielding that's even remotely hatchet-shaped.]"] = "[Ramarno te cachea minuciosamente y revuelve tu backpack. Hace una pausa para inspeccionar cuidadosamente cualquier cosa que lleves o empuñes y que tenga incluso remotamente forma de hacha.]",
    ["You need a hatchet of ember and glade if you want me to help you upgrade it."] = "Necesitas un hacha de brasas y claro si quieres que te ayude a mejorarla.",
    ["[You show your hatchet of ember and glade to Ramarno.]"] = "[Muestras tu hacha de brasas y claro a Ramarno.]",
    ["You can make this hatchet even more powerful? How?"] = "¿Puedes hacer que este hacha sea aún más poderosa? ¿Cómo?",
    ["To make it, you must obtain a sizeable chunk of witchwood."] = "Para hacerlo, debes obtener un trozo considerable de madera mágica.",
    ["That's going to be tricky, as witchwood trees are extinct."] = "Eso va a ser complicado, ya que los árboles de brujería están extintos.",
    ["I doubt 66.6...% Luke would be willing to part with any more of his better half, or that any fraction of Luke survived that swarm of 'rum'-pumped crabs."] = "Dudo en un 66,6%...% que Luke estuviera dispuesto a separarse de más de su media naranja, o que alguna fracción de Luke sobreviviera a ese enjambre de cangrejos bombeados con 'ron'.",
    ["But I did use Luke's leg to jam the hopper on the upper level of the Braindeath Island distillery. Maybe some witchwood survived the explosion."] = "Pero usé la pierna de Luke para bloquear la tolva en el nivel superior de la destilería de Braindeath Island. Quizás algo de brujería sobrevivió a la explosión.",
    ["I found a mysterious witchwood fragment on Braindeath Island."] = "Encontré un misterioso fragmento de madera mágica en Braindeath Island.",
    ["You must obtain a moonstone imbued with the power of the underworld. I know nothing of such practice, but you must somehow attune your tool with the moonstone."] = "Debes obtener una piedra lunar imbuida del poder del inframundo. No sé nada de esa práctica, pero de alguna manera debes armonizar tu herramienta con la piedra lunar.",
    ["The former master crafter in the city of Um taught me how to ensoul a moonstone at a necromancy ritual site."] = "El former master crafter en el city of Um me enseñó cómo animar una piedra lunar en un sitio ritual de nigromancia.",
    ["I now need to feed the moonstone by woodcutting with wood spirits."] = "Ahora necesito alimentar la piedra lunar cortando madera con alcoholes de madera.",
    ["I woodcut until the ensouled moonstone's hunger for wood spirits was sated."] = "Grabé en madera hasta que se saciara el hambre de espíritus de madera de la piedra lunar con alma.",
    ["I now need to attune the moonstone to the spiritual frequency of my hatchet of ember and glade by chopping tough trees."] = "Ahora necesito sintonizar la piedra lunar con la frecuencia espiritual de mi hacha de brasas y claro cortando árboles resistentes.",
    ["I attuned an ensouled moonstone to the spiritual frequency of my hatchet."] = "Sintonicé una piedra lunar con alma con la frecuencia espiritual de mi hacha.",
    ["Finally, you must obtain a tensile vine."] = "Finalmente, debes obtener una enredadera extensible.",
    ["Hmm, perhaps I could find that in an overgrown idol. They're covered with vines."] = "Hmm, tal vez podría encontrar eso en un ídolo demasiado grande. Están cubiertos de enredaderas.",
    ["I woodcut a tensile vine from an overgrown idol."] = "Grabé en madera una enredadera extensible de un ídolo demasiado grande.",
    ["You may now use the sacred forge to upgrade your hatchet."] = "Ahora puedes usar la forja sagrada para mejorar tu hacha.",
    ["I hear you have another hatchet of ember and glade. Go ahead and use my sacred forge to upgrade it. No charge."] = "He oído que tienes otro hacha de brasas y claro. Continúe y use mi forja sagrada para mejorarla. Sin cargo.",
    ["[Ramarno gives you one of the ingredients you need to upgrade your hatchet.]"] = "[Ramarno te brinda uno de los ingredientes que necesitas para mejorar tu hacha.]",
    ["[Ramarno gives you one of the ingredients you need to forge a upgrade your hatchet.]"] = "[Ramarno te brinda uno de los ingredientes que necesitas para mejorar tu hacha.]",
    ["(Talk about Defender of Varrock.)"] = "(Habla sobre el Defensor de Varrock.)",
    ["How did you fare in Varrock?"] = "¿Cómo te fue en Varrock?",
    ["We did it. We figured out how to defeat Zemouregal's army."] = "Lo logramos. Descubrimos cómo derrotar al ejército de Zemouregal.",
    ["Well done. I thought you had the sound of a hero about you."] = "Bien hecho. Pensé que tenías la voz de un héroe.",
    ["Farewell."] = "Adiós.",
    ["What is that divine smell? Could it be-?"] = "¿Qué es ese olor divino? ¿Podría ser-?",
    ["Redberry pie?"] = "¿Pastel de frutos rojos?",
    ["It really is! A legendary redberry pie. I don't suppose I could have some?"] = "¡Realmente lo es! Un pastel de frutos rojos legendario. ¿Supongo que no podría tener algunos?",
    ["Okay, here you go."] = "Bien, aquí tienes.",
    ["[Ramarno eats all of the pie.]"] = "[Ramarno se come todo el pastel.]",
    ["The reputation of the redberry pie is well deserved; that was absolutely amazing. Let me reward you for allowing me to experience such an exquisite taste sensation."] = "La reputación del pastel de frutos rojos es bien merecida; Eso fue absolutamente asombroso. Déjame recompensarte por permitirme experimentar una sensación de sabor tan exquisita.",
    ["Ramarno gives you knowledge of some Smithing techniques. You gain 1,000 smithing experience."] = "Ramarno le brinda conocimientos sobre algunas técnicas de Smithing. Obtienes 1000 de experiencia en herrería.",
    ["No, it's my pie."] = "No, es mi pastel.",
    ["A pity, but understandable. I wouldn't give away redberry pie if I had any, either."] = "Una lástima, pero comprensible. Tampoco regalaría pastel de frutos rojos si tuviera alguno.",
    ["I've given that dwarf quite enough pie."] = "Ya le he dado bastante pastel a ese enano.",
    ["Hang on. I'm not finished with you."] = "Espera. No he terminado contigo.",
    ["Mmmm?"] = "¿Mmmm?",
    ["Hello, I'm Player."] = "Hola, soy Player.",
    ["Skip the chit-chat, human."] = "Deja la charla, humano.",
    ["I'd like to ask you about yourself."] = "Me gustaría preguntarte sobre ti.",
    ["Alright."] = "Muy bien.",
    ["Who are you?"] = "¿Quién eres?",
    ["Your question is vague, and it has many answers. If you want to know my race, I am gorajo. If you want to know my class, I was born as a skinweaver. If you want to know my tribe, I serve no tribe, so I am called a ramokee. I am all those things, but they do not define who I am."] = "Tu pregunta es vaga y tiene muchas respuestas. Si quieres saber mi raza soy gorajo. Si quieres saber mi clase, nací como tejedora de pieles. Si quieres conocer mi tribu, no sirvo a ninguna tribu, por eso me llaman ramokee. Soy todas esas cosas, pero no definen quién soy.",
    ["Why are you here?"] = "¿Por qué estás aquí?",
    ["I am here because I wish to be here. But perhaps that is not what you meant to ask; I shall tell you more of my history. Among my race, skinweavers are rare. Almost as soon as we are born, the tribe expects us to undergo intensive training, learning to serve as healers. I had not asked to be a skinweaver; my class was a mere accident of fate, yet it set the course of my entire life. That is the gorajo way, and I rejected it. Once I had mastered my powers, I left the tribe, becoming a ramokee. Now I serve no-one, and my powers are mine to use as I wish."] = "Estoy aquí porque deseo estar aquí. Pero quizás eso no sea lo que querías preguntar; Les contaré más de mi historia. Entre mi raza, los tejedores de piel son raros. Casi tan pronto como nacemos, la tribu espera que pasemos por un entrenamiento intensivo, aprendiendo a servir como curanderos. No había pedido ser tejedor de pieles; Mi clase fue un mero accidente del destino, pero marcó el curso de toda mi vida. Ésa es la manera gorajo y la rechacé. Una vez que dominé mis poderes, dejé la tribu y me convertí en ramokee. Ahora no sirvo a nadie y mis poderes son míos para usarlos como quiera.",
    ["That was very selfish of you."] = "Eso fue muy egoísta de tu parte.",
    ["Human, I could dissolve your heart with a mere thought. Do not interrupt me."] = "Humano, podría disolver tu corazón con un simple pensamiento. No me interrumpas.",
    ["*(Continues below)*"] = "*(Continúa a continuación)*",
    ["I admire your independence."] = "Admiro tu independencia.",
    ["That is right and proper. I shall continue."] = "Eso es correcto y apropiado. Continuaré.",
    ["I'll leave you alone now."] = "Te dejaré en paz ahora.",
    ["Wandering alone, I came across a strange hole in the world, and passed through it into a land unlike any I had ever seen. Its winged inhabitants called it Zanaris."] = "Vagando solo, me encontré con un extraño agujero en el mundo y lo atravesé hasta llegar a una tierra como nunca antes había visto. Sus habitantes alados lo llamaron Zanaris.",
    ["Zanaris? Yes, I've been there."] = "¿Zanaris? Sí, he estado allí.",
    ["The hole, through which I had entered Zanaris, closed itself. The creatures of Zanaris said that it must have been an unstable portal; such things happen there. Although I could no longer return to my world, I had no desire to do so. There was nothing back there to interest me. Zanaris had rings of magical fungus through which I could travel from world to world. One such journey brought me to your world. As a skinweaver, I was fascinated by the fungus in those rings. It is a living organism, yet it contains magical power. I began to study fungi. I experimented on the fungi that were native to this damp cave, and I learned to imbue some of my own skinweaving powers into them. I could even weave the fungi around the native beasts, creating completely new creatures. They already had brute strength, but my fungus gave them magic. So now this cave is my home, where I can use my skinweaving powers to create whatever I wish. It is satisfactory."] = "El agujero por el que había entrado a Zanaris se cerró solo. Las criaturas de Zanaris dijeron que debió ser un portal inestable; cosas así suceden allí. Aunque ya no podía regresar a mi mundo, no tenía ningún deseo de hacerlo. Allí no había nada que me interesara. Zanaris tenía anillos de hongos mágicos a través de los cuales podía viajar de mundo en mundo. Uno de esos viajes me trajo a tu mundo. Como tejedora de pieles, me fascinaban los hongos que había en esos anillos. Es un organismo vivo, pero contiene poder mágico. Empecé a estudiar los hongos. Experimenté con los hongos nativos de esta cueva húmeda y aprendí a imbuirles algunos de mis propios poderes para tejer la piel. Incluso podría tejer los hongos alrededor de las bestias nativas, creando criaturas completamente nuevas. Ya tenían fuerza bruta, pero mi hongo les dio magia. Así que ahora esta cueva es mi hogar, donde puedo usar mis poderes de tejido de piel para crear lo que desee. Es satisfactorio.",
    ["Can I fight you?"] = "¿Puedo pelear contigo?",
    ["Human, I am a skinweaver. I can strip the flesh from your bones with a mere thought, then grow it into a more pleasing shape. Before you could strike me, you would find your intestines growing out through your nose."] = "Humano, soy un tejedor de pieles. Puedo arrancar la carne de tus huesos con un simple pensamiento y luego hacerla crecer hasta darle una forma más agradable. Antes de que pudieras golpearme, encontrarías que tus intestinos crecían a través de tu nariz.",
    ["I'll bear that in mind."] = "Lo tendré en cuenta.",
    ["Let's talk about something else."] = "Hablemos de otra cosa.",
    ["If you must."] = "Si es necesario.",
    ["I'd like to ask you about this place."] = "Me gustaría preguntarte sobre este lugar.",
    ["This place? It is my home. What about it?"] = "¿Este lugar? Es mi hogar. ¿Qué pasa con eso?",
    ["Why is the cave full of fungus?"] = "¿Por qué la cueva está llena de hongos?",
    ["Fungi are incredibly flexible life forms. I can imbue my powers into them, then grow them all over the beasts of the cave to make new kinds of creature. When I arrived here, the cave already contained fungi because this is a naturally damp region. I have simply encouraged the growth of these amazing organisms."] = "Los hongos son formas de vida increíblemente flexibles. Puedo imbuirles mis poderes y luego hacerlos crecer en todas las bestias de la cueva para crear nuevos tipos de criaturas. Cuando llegué aquí, la cueva ya contenía hongos porque esta es una región naturalmente húmeda. Simplemente he fomentado el crecimiento de estos asombrosos organismos.",
    ["I do whatever I wish! There is no tribe here to make demands of me. My powers are mine to use as I please. I have learned to imbue my skinweaving powers into the fungus of this cave. By growing it onto the native beasts, I have created new forms of life. I also make simple garments of mycelium. The merchant sells these upstairs. If you gather flakes of my fungus from my creatures, you can try to stitch the fungus to the mycelium garments to make protective armour imbued with my magical powers."] = "¡Hago lo que quiero! No hay ninguna tribu aquí que me exija nada. Mis poderes son míos para usarlos como quiera. He aprendido a imbuir mis poderes para tejer piel en el hongo de esta cueva. Al cultivarlo en las bestias nativas, he creado nuevas formas de vida. También hago prendas sencillas de micelio. El comerciante los vende arriba. Si recoges escamas de mi hongo de mis criaturas, puedes intentar unir el hongo a las prendas de micelio para hacer una armadura protectora imbuida de mis poderes mágicos.",
    ["I'd like to ask you about these creatures."] = "Me gustaría preguntarte sobre estas criaturas.",
    ["My creatures? Alright, go ahead."] = "¿Mis criaturas? Muy bien, adelante.",
    ["What are these creatures?"] = "¿Qué son estas criaturas?",
    ["When I first arrived here, they were mindless beasts lumbering around the cave, squatting in slime. They had brute strength, but nothing more. As I learned to imbue my powers into the native fungi, I was able to grow my fungi onto the creatures, and I adapted their bodies to receive it. In my creatures, I have achieved a perfect combination of the magical powers of the fungus with the strength and voracity of the beast."] = "Cuando llegué aquí por primera vez, eran bestias sin sentido que caminaban pesadamente por la cueva, en cuclillas en limo. Tenían fuerza bruta, pero nada más. Cuando aprendí a imbuir mis poderes en los hongos nativos, pude hacer crecer mis hongos en las criaturas y adapté sus cuerpos para recibirlos. En mis criaturas he conseguido una combinación perfecta de los poderes mágicos del hongo con la fuerza y ​​voracidad de the beast.",
    ["How should I fight them?"] = "¿Cómo debería luchar contra ellos?",
    ["When a human sees a strange creature, their instinct is to kill it. Your race is strange indeed! Nevertheless, you may try to cull them, if you dare; while I enjoy creating them, the fully-formed beasts are of no use to me. You will need skill, human. My fungus is powerful, and some of the creatures cannot even be harmed except by immensely skilled slayers. Furthermore, you should know that my fungus makes the creatures resilient to physical attacks. You may have more success using your magical powers. If you let the larger creatures touch you, their fungus will attempt to infest you. This will kill you very quickly, so keep your distance. The neem drupes that grow upstairs can be ground up to extract their oil. This is a natural fungicide. You can collect it in a jug. Splashing the neem oil on my creatures will weaken my fungus for a moment. If you daren't approach the creature to do this, get another human to do it for you. While the fungus is weakened, the creature will be confused, and it will be unable to cast magical attacks for a short time. Try not to die horribly."] = "Cuando un humano ve una criatura extraña, su instinto es matarla. ¡Tu raza es realmente extraña! Sin embargo, puedes intentar sacrificarlos si te atreves; Si bien disfruto creándolos, las bestias completamente formadas no me sirven de nada. Necesitarás habilidad, humano. Mi hongo es poderoso y algunas de las criaturas ni siquiera pueden ser dañadas excepto por cazadores inmensamente hábiles. Además, debes saber que mi hongo hace que las criaturas sean resistentes a los ataques físicos. Es posible que tengas más éxito usando tus poderes mágicos. Si dejas que las criaturas más grandes te toquen, sus hongos intentarán infestarte. Esto te matará muy rápidamente, así que mantén la distancia. Las drupas de neem que crecen arriba se pueden triturar para extraer su aceite. Este es un fungicida natural. Puedes recogerlo en una jarra. Salpicar aceite de neem sobre mis criaturas debilitará mis hongos por un momento. Si no te atreves a acercarte a la criatura para hacer esto, consigue que otro humano lo haga por ti. Mientras el hongo esté debilitado, la criatura quedará confundida y no podrá lanzar ataques mágicos durante un breve periodo de tiempo. Intenta no morir horriblemente.",
    ["What loot can I get from them?"] = "¿Qué botín puedo obtener de ellos?",
    ["Spores and flakes of fungus are fairly common. If you collect enough spores, you may be able to grow them on a polypore stick. Polypore sticks are found on the ganodermic beasts, the large ones. If you grow spores on a polypore stick, you can create a powerful magical staff. The flakes of fungus can be attached to mycelium garments that I make, turning them into magical armour. The merchant upstairs can sell you the garments. He is strange, even for a human, but he runs his little shop adequately. Apart from that I have created a special fungus that can be eaten by humans. I have named it the Gorajian Mushroom. It is imbued with my skinweaving powers. When you eat a gorajian mushroom, it will restore some of your health immediately, and you will benefit from a healing effect for a short period. The healing effect makes you take less damage when you are harmed by a human like yourself. You might even gain a little health if the damage was sufficiently slight. The effect is triggered by the spiritual conflict of the combatants. If you are fighting monsters, there will be no spiritual conflict, so the healing does nothing. Even if your foe is human, their origin may be too different from yours to trigger the healing effect."] = "Las esporas y escamas de hongos son bastante comunes. Si recolectas suficientes esporas, es posible que puedas cultivarlas en una varilla de poliporo. Las varillas de poliporo se encuentran en las bestias ganodermicas, las grandes. Si cultivas esporas en una barra de poliporo, puedes crear un poderoso y mágico staff. Las escamas de hongo se pueden adherir a prendas de micelio que hago, convirtiéndolas en armaduras mágicas. El comerciante de arriba puede venderte las prendas. Es extraño, incluso para un humano, pero dirige su pequeña tienda adecuadamente. Aparte de eso, he creado un hongo especial que los humanos pueden comer. Lo he llamado Hongo Gorajiano. Está imbuido de mis poderes para tejer piel. Cuando comes un hongo gorajian, restaurarás parte de tu salud inmediatamente y te beneficiarás de un efecto curativo durante un corto período. El efecto curativo hace que recibas menos daño cuando un humano como tú te lastima. Incluso podrías ganar un poco de salud si el daño fuera lo suficientemente leve. El efecto es provocado por el conflicto espiritual de los combatientes. Si estás luchando contra monstruos, no habrá conflicto espiritual, por lo que la curación no hace nada. Incluso si tu enemigo es humano, su origen puede ser demasiado diferente al tuyo como para desencadenar el efecto curativo.",
    ["The Ramokee Skinweaver is trying to explain that the healing effect only works in player-vs-player combat."] = "Ramokee Skinweaver está tratando de explicar que el efecto curativo solo funciona en el combate jugador contra jugador.",
    ["Okay, I'll keep an eye out for those things."] = "Está bien, estaré atento a esas cosas.",
    ["If they don't interest you, maybe you'll be able to sell them on."] = "Si no te interesan, tal vez puedas venderlos.",
    ["The Ramokee Skinweaver does not appear to care."] = "Al Ramokee Skinweaver no parece importarle.",
    ["Wow! look at this place, it's so colourful."] = "¡Guau! Mira este lugar, es tan colorido.",
    ["Why thank you. Can I help you with anything?"] = "Pues, gracias. ¿Puedo ayudarte con algo?",
    ["I take it by the clothes you are wearing and this room that you are in the dye trade?"] = "¿Supongo que por la ropa que llevas y esta habitación en la que estás en el comercio dye?",
    ["How observant of you."] = "Qué observador de tu parte.",
    ["Could you make some dye for me please?"] = "¿Podrías prepararme un poco de dye, por favor?",
    ["What colour dye do you want? I can make you blue, red or yellow dyes for you. If you bring me the correct raw materials."] = "¿Qué color de dye quieres? Puedo hacerte dyes azul, rojo o amarillo para ti. Si me traes las materias primas correctas.",
    ["What do you need to make red dye?"] = "¿Qué necesitas para hacer red dye?",
    ["Hmm... 3 lots of redberries should do the trick and 25 coins should cover any other costs."] = "Hmm... 3 lotes de redberries deberían ser suficientes y 25 coins deberían cubrir cualquier otro costo.",
    ["Okay, make me some red dye please."] = "Bien, hazme un poco de red dye, por favor.",
    ["You don't have enough berries to make the red dye."] = "No tienes suficiente berries para hacer el red dye.",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["You don't have enough coins to pay for the dye."] = "No tienes suficiente coins para pagar el dye.",
    ["You hand the redberries and some coins to Rana, who then rummages around some shelves, eventually finding a red bottle, which she then hands to you."] = "Le entregas el redberries y un poco de coins a Rana, quien luego hurga en algunos estantes y finalmente encuentra una botella roja, que luego te entrega.",
    ["I don't think I have all the ingredients yet."] = "Creo que todavía no tengo todos los ingredientes.",
    ["You know what you need to get, now come back when you have them. Goodbye for now."] = "Ya sabes lo que necesitas conseguir, ahora vuelve cuando los tengas. Adiós por ahora.",
    ["I can do without dye at that price."] = "Puedo prescindir de dye a ese precio.",
    ["Fair enough, I still think that the price is fairly reasonable considering that I'm the only source of dye this side of the Shantay Pass."] = "Es cierto, sigo pensando que el precio es bastante razonable teniendo en cuenta que soy la única fuente de dye de este lado del Shantay Pass.",
    ["Where would I find a redberry bush?"] = "¿Dónde puedo encontrar un arbusto de frutos rojos?",
    ["Well you could try growing them. They shouldn't be too hard to grow."] = "Bueno, podrías intentar cultivarlos. No deberían ser demasiado difíciles de cultivar.",
    ["If I didn't care to grow my own, where else could I get some?"] = "Si no me importara cultivar el mío, ¿dónde más podría conseguirlo?",
    ["Well I know for sure that the desert climate wouldn't suit them. I have mine picked for me in the woods south of Varrock."] = "Bueno, estoy seguro de que el clima desértico no les convendría. El mío lo recogí en el bosque al sur de Varrock.",
    ["What do you need to make yellow dye?"] = "¿Qué necesitas para hacer yellow dye?",
    ["Yellow is an awkward colour to recreate, I guess if you me 2 onions I could use their skins to make a warm yellow dye for you. Oh yes and lest I forget I'll need 25 coins to cover the cost of the glass ware and my wages."] = "El amarillo es un color difícil de recrear. Supongo que si me das 2 cebollas, podría usar sus pieles para preparar un yellow dye cálido para ti. Ah, sí, y para que no lo olvide, necesitaré 25 coins para cubrir el coste de la cristalería y mi salario.",
    ["Okay, make me some yellow dye please."] = "Bien, hazme un poco de yellow dye, por favor.",
    ["You don't have enough onions to make the yellow dye."] = "No tienes suficientes cebollas para hacer el yellow dye.",
    ["You hand two onions to Rana, who then rummages around some shelves, eventually finding a yellow bottle, which she then hands to you."] = "Le entregas dos cebollas a Rana, quien luego hurga en algunos estantes y finalmente encuentra una botella amarilla, que luego te entrega.",
    ["Where would I find some onions?"] = "¿Dónde puedo encontrar algunas cebollas?",
    ["Generally you would find onions in vegetable gardens, silly."] = "Generalmente encontrarás cebollas en los huertos, tonto.",
    ["Ok you have me there but is there anywhere around here where I could get my hands on some onions?"] = "Ok, ya me tienes allí, pero ¿hay algún lugar por aquí donde pueda conseguir algunas cebollas?",
    ["I really don't know. A friend of mine grows hers on a near Draynor village. But that's a little far from here to be useful."] = "Realmente no lo sé. Una amiga mía cultiva la suya en una planta cercana a Draynor village. Pero eso está un poco lejos de ser útil.",
    ["What do you need to make blue dye?"] = "¿Qué necesitas para hacer blue dye?",
    ["To make a bottle of blue dye I'll need 2 woad leaves and 25 coins from you."] = "Para hacer una botella de blue dye necesitaré 2 hojas de glasto y 25 coins de tu parte.",
    ["Okay, make me some blue dye please."] = "Bien, hazme un poco de blue dye, por favor.",
    ["You don't have enough woad leaves to make the blue dye."] = "No tienes suficientes hojas de glasto para hacer el blue dye.",
    ["You hand the woad leaves and some coins to Rana, who then rummages around some shelves, eventually finding a blue bottle, which she then hands to you."] = "Le entregas las hojas de glasto y un poco de coins a Rana, quien luego hurga en algunos estantes y finalmente encuentra una botella azul, que luego te entrega.",
    ["Where can I get some woad leaves?"] = "¿Dónde puedo conseguir algunas hojas de glasto?",
    ["Woad leaves are fairly fairly hard to find round here. My other customers tell me that there's a gardener in Falador who grows them."] = "Las hojas de glasto son bastante difíciles de encontrar por aquí. Mis otros clientes me dicen que hay un jardinero en Falador que los cultiva.",
    ["On second thoughts I don't really need any dye."] = "Pensándolo bien, realmente no necesito ningún dye.",
    ["On second thoughts, I don't think that I need some dye right now."] = "Pensándolo bien, no creo que necesite dye en este momento.",
    ["How did you get into the colour business?"] = "¿Cómo llegaste al negocio del color?",
    ["Well, it's quite simple really my mother was a drysalter and I learnt the trade from her."] = "Bueno, es bastante simple, realmente mi madre era saladora y aprendí el oficio de ella.",
    ["Umm, what's a drysalter, it isn't a medical condition is it?"] = "Umm, ¿qué es un drysalter? No es una condición médica, ¿verdad?",
    ["No silly, it's someone who deals with preservatives and dyes. I didn't really enjoy the preservatives side of the things so I've chosen to deal solely in dyeing."] = "No es tonto, es alguien que se ocupa de conservantes y dyes. Realmente no disfruté el lado de los conservantes, así que elegí dedicarme únicamente al teñido.",
    ["So how's business then?"] = "Entonces, ¿cómo va el negocio?",
    ["It's a dyeing trade! Oh gosh I'm sorry that was a truly dreadful joke."] = "¡Es un oficio de teñido! Oh Dios, lo siento, fue una broma verdaderamente espantosa.",
    ["Hmm yes, about the worst I've heard today at least."] = "Hmm, sí, al menos lo peor que he escuchado hoy.",
    ["Thanks. But really, it's not the best around here. nearly everyone in this town wears only white, which means I don't exactly do a roaring trade. Now is there anything I can get you?"] = "Gracias. Pero realmente, aquí no es lo mejor. Casi todo el mundo en esta ciudad viste sólo de blanco, lo que significa que no hago exactamente un gran negocio. ¿Hay algo que pueda conseguirte?",
    ["No thanks, I'm just having a look around."] = "No, gracias, solo estoy echando un vistazo.",
    ["Do you want to buy any armoured skirts? Designed especially for ladies who like to fight."] = "¿Quieres comprar faldas blindadas? Diseñado especialmente para mujeres a las que les gusta pelear.",
    ["Choose an option:"] = "Elige una opción:",
    ["Yes, please."] = "Sí, por favor.",
    ["No, thank you, that's not my scene."] = "No, gracias, ese no es mi lugar.",
    ["What do you think of Ali Morrisane?"] = "¿Qué opinas de Ali Morrisane?",
    ["He's a shifty man. Brought several men from his home town to try to set up shops here, or so he says. But if they're just setting up shop, why does he need to send them around to threaten us? One of them came here, waved his hammer around dangerously, and said things would be worse for us if we didn't join them!"] = "Es un hombre astuto. Trajo a varios hombres de su pueblo natal para intentar montar aquí tiendas, o eso dice. Pero si recién están estableciendo sus negocios, ¿por qué necesita enviarlos para amenazarnos? ¡Uno de ellos vino aquí, agitó su martillo peligrosamente y dijo que las cosas serían peores para nosotros si no nos uníamos a ellos!",
    ["What will you do about it?"] = "¿Qué harás al respecto?",
    ["I'm not going to let those thugs run me out of this town. So I'll just keep selling armoured skirts here. Would you like to buy any?"] = "No voy a permitir que esos matones me echen de esta ciudad. Así que seguiré vendiendo faldas blindadas aquí. ¿Quieres comprar alguno?",
    ["Hi. I have this money-off voucher."] = "Hola. Tengo este vale de descuento.",
    ["So I see. Unfortunately, it seems to have expired yesterday. Never mind."] = "Ya veo. Lamentablemente, parece haber caducado ayer. No importa.",
    ["But I only just got it!"] = "¡Pero acabo de recibirlo!",
    ["I'm sorry. There's nothing I can do. Goodbye."] = "Lo siento. No hay nada que pueda hacer. Adiós.",
    ["I've been told you need this."] = "Me han dicho que necesitas esto.",
    ["You need more inventory space to receive your clue casket."] = "Necesitas más espacio en el inventario para recibir tu cofre de pistas.",
    ["[You are handed a casket!]"] = "[¡Te entregan un ataúd!]",
    ["I hear voices in my head..."] = "Escucho voces en mi cabeza...",
    ["The voices..."] = "Las voces...",
    ["They council me..."] = "Me aconsejan...",
    ["They understand..."] = "Ellos entienden...",
    ["They talk to me."] = "Me hablan.",
    ["Welcome to my stall! Come and buy some tasty bread, freshly baked just 2 months ago!"] = "¡Bienvenido a mi puesto! ¡Ven a comprar un rico pan, recién horneado hace apenas 2 meses!",
    ["Sounds delicious!"] = "¡Suena delicioso!",
    ["I think I'll pass."] = "Creo que pasaré.",
    ["Greetings. I am your assistant for the ranged performance. For savety reasons I must now explain to you the rules of the performance."] = "Saludos. Soy su asistente para la actuación a distancia. Por razones de seguridad debo explicarles ahora las reglas de la actuación.",
    ["Do you understand the terms and conditions, and wish to continue with the Ranged performance?"] = "¿Entiendes los términos y condiciones y deseas continuar con la presentación de Ranged?",
    ["**Select an option**"] = "**Seleccione una opción**",
    ["Which weapon would you like to use?"] = "¿Qué arma te gustaría usar?",
    ["Bow and arrow"] = "Arco y flecha",
    ["Throwing knives"] = "arrojar cuchillos",
    ["Throwing axes"] = "arrojar hachas",
    ["Could you explain it to me again?"] = "¿Podrías explicármelo de nuevo?",
    ["Can you explain it to me again?"] = "¿Puedes explicármelo otra vez?",
    ["**Ranged assistant:** Please choose the target you wish to shoot at, either the bullseye or the popinjay, then the shooting spot from which you will attempt to hit the target. You can shoot from any shooting spot you like, regardless of your Ranged level, but you're more likely to score a hit if you have the recommended Ranged level. You may take 10 shots for the duration of your performance. 5 shots must be at the bullseye and the other 5 must be at the popinjay. Once 10 shots have been made, I will ask you to desist, and I will analyse and relay your score to you. You may also perform emotes during said performance to 'enliven' said performance. Participate at your leisure; the performance is not timed. Should you wish to terminate your performance early, speak to me. You may only do one performance at a time."] = "**Ranged assistant:** Elige el objetivo al que deseas disparar, ya sea la diana o el popinjay, y luego el punto de disparo desde el que intentarás alcanzar el objetivo. Puedes disparar desde cualquier punto de tiro que desees, independientemente de tu nivel Ranged, pero es más probable que aciertes si tienes el nivel Ranged recomendado. Puedes realizar 10 disparos durante la duración de tu actuación. 5 tiros deben ser a la diana y los otros 5 deben ser al popinjay. Una vez realizados 10 tiros, te pediré que desistas, analizaré y te transmitiré tu puntuación. También puede realizar emoticones durante dicha actuación para \"animar\" dicha actuación. Participa a tu gusto; la actuación no está cronometrada. Si desea finalizar su actuación antes de tiempo, hable conmigo. Sólo podrás realizar una actuación a la vez.",
    ["*Only one of the following options will appear, depending on which has been toggled previously:*"] = "*Solo aparecerá una de las siguientes opciones, dependiendo de cuál se haya activado anteriormente:*",
    ["Could you tell me how I'm doing?"] = "¿Podrías decirme cómo estoy?",
    ["Could you stop telling me how I'm doing?"] = "¿Podrías dejar de decirme cómo estoy?",
    ["Could you stop telling me what the audience thinks of my performance? It's distracting."] = "¿Podrías dejar de decirme qué piensa el público de mi actuación? Es una distracción.",
    ["Certainly. I cannot prevent them from talking, though. I'll simply stop telling you if they think your performance is repetitive or not. Do you still want me to stop telling you?"] = "Por supuesto. Sin embargo, no puedo evitar que hablen. Simplemente dejaré de decirte si creen que tu actuación es repetitiva o no. ¿Todavía quieres que deje de decírtelo?",
    ["Do you wish to terminate your performance early?"] = "¿Deseas finalizar tu actuación antes de tiempo?",
    ["*If the player scored points in their performance:*"] = "*Si el player anotó puntos en su actuación:*",
    ["Congratulations! You scored [amount] in your Ranged performance. You received [amount] experience points."] = "¡Felicitaciones! Obtuviste una puntuación de [amount] en tu actuación de Ranged. Recibiste puntos de experiencia [amount].",
    ["*If the player scored no points in their performance:*"] = "*Si el player no obtuvo puntos en su actuación:*",
    ["I'm sorry, but that performance just wasn't good enough for a reward. Try again next week."] = "Lo siento, pero esa actuación no fue lo suficientemente buena para recibir una recompensa. Vuelve a intentarlo la semana que viene.",
    ["Oh no! You didn't score anything in your Ranged performance. You received 0 experience points."] = "¡Ay no! No obtuviste nada en tu actuación de Ranged. Recibiste 0 puntos de experiencia.",
    ["You've already done your Ranged performance this week. You should speak to the ringmaster and see if there's anything else you can do."] = "Ya hiciste tu actuación de Ranged esta semana. Deberías hablar con el maestro de ceremonias y ver si hay algo más que puedas hacer.",
    ["Start 'Secrets of Amberfell'."] = "Inicia 'Secretos de Amberfell'.",
    ["Talk about something else."] = "Habla de otra cosa.",
    ["Apologies, adventurer. The bridge to Amberfell is out of commission."] = "Disculpas, aventurero. El puente a Amberfell está fuera de servicio.",
    ["What happened?"] = "¿Qué pasó?",
    ["Fell apart in the flooding last season. Probably for the best. Several of the folk who went travelling east recently never returned."] = "Se derrumbó durante las inundaciones de la temporada pasada. Probablemente lo mejor. Varias de las personas que viajaron hacia el este recientemente nunca regresaron.",
    ["Our cousins in Amberfell have been pleased to see us again."] = "Nuestros primos en Amberfell están encantados de vernos de nuevo.",
    ["Many thanks for reconnecting us again. We missed them."] = "Muchas gracias por reconectarnos nuevamente. Los extrañamos.",
    ["Hello there."] = "Hola.",
    ["Greetings. If you are an experienced archer, you may want to visit the guild here..."] = "Saludos. Si eres un arquero experimentado, quizás quieras visitar el gremio aquí...",
    ["*After getting at least 30 Chompy kills*"] = "*Después de conseguir al menos 30 muertes de Chompy*",
    ["Creature done good, cooking da chompy. Maybe you wants a free hatsie? Rantz got lots of hatsies for chompy shooters."] = "Criatura bien hecha, cocinando da chompy. ¿Quizás quieras un sombrero gratis? Rantz tiene muchos sombreros para tiradores mordaces.",
    ["What are these 'hatsies'?"] = "¿Qué son estos 'sombrero'?",
    ["Creature stupid? Hatsies to wear on head, make you look good. Huh huh huh."] = "¿Criatura estúpida? Hatsies para usar en la cabeza, te hacen lucir bien. Eh, eh, eh.",
    ["Ah, I see, you're offering me hats."] = "Ah, ya veo, me estás ofreciendo sombreros.",
    ["Dat's what Rantz said. You want hatsies or not?"] = "Eso es lo que dijo Rantz. ¿Quieres sombreros o no?",
    ["Okay, show me your 'hatsies'."] = "Está bien, muéstrame tus 'sombreros'.",
    ["*(same as below)*"] = "*(igual que a continuación)*",
    ["*(dialogue terminates)*"] = "*(termina el diálogo)*",
    ["You really should stop scratching. You'll get scars."] = "Deberías dejar de rascarte. Te saldrán cicatrices.",
    ["Wait, really? Scars are cool!"] = "Espera, ¿en serio? ¡Las cicatrices son geniales!",
    ["Now am scratching more! Thank you, stranger."] = "¡Ahora me estoy rascando más! Gracias, extraño.",
    ["Never mind, I'll leave you to it."] = "No importa, te dejo con eso.",
    ["Hello good sir."] = "Hola buen señor.",
    ["What do you want?"] = "¿Qué quieres?",
    ["I'm new in town and wanted to get to know the locals."] = "Soy nuevo en la ciudad y quería conocer a los lugareños.",
    ["What do you want to know?"] = "¿Qué quieres saber?",
    ["Tell me about yourself."] = "Háblame de ti.",
    ["That information is on a need to know basis and right now, you don't need to know."] = "Esa información es necesaria y, en este momento, no es necesario que la sepas.",
    ["Can I help you with anything else?"] = "¿Puedo ayudarte con algo más?",
    ["[Menu]: Select an Option"] = "[Menú]: Seleccione una opción",
    ["Yes I'd like to ask you about something else."] = "Sí, me gustaría preguntarte algo más.",
    ["Tell me about the other people in this town."] = "Cuéntame sobre las otras personas en esta ciudad.",
    ["Sheep, ready for the slau... hang on I shouldn't be saying... listen I don't want to talk about them."] = "Sheep, listo para el slau... espera, no debería decir... escucha, no quiero hablar de ellos.",
    ["Why did you have to go and ruin everything? We had a beautiful future ahead of us, the town would have been ours."] = "¿Por qué tuviste que ir y arruinarlo todo? Teníamos un hermoso futuro por delante, el pueblo habría sido nuestro.",
    ["Maybe I wanted to make it MY town!"] = "¡Tal vez quería convertirla en MI ciudad!",
    ["I see. I knew the power hunger would get to you eventually."] = "Ya veo. Sabía que el hambre de poder acabaría afectándote.",
    ["Evil megalomaniacs set on destruction should be opposed."] = "Debemos oponernos a los malvados megalómanos empeñados en la destrucción.",
    ["Really? I thought you were meant to follow those types blindly, with unquestioning loyalty."] = "¿En serio? Pensé que debías seguir a esos tipos ciegamente, con una lealtad incondicional.",
    ["Look Gielinor is full of power mad evil-doers. I'm sure another will come along soon enough."] = "Mira, Gielinor está lleno de malvados locos y poderosos. Estoy seguro de que pronto aparecerá otro.",
    ["No, it just wouldn't be the same, I think I'll just wallow in self pity for a while."] = "No, simplemente no sería lo mismo, creo que me hundiré en la autocompasión por un tiempo.",
    ["I'm sorry, I didn't mean to upset you. Can we still be friends?"] = "Lo siento, no quise molestarte. ¿Podemos seguir siendo amigos?",
    ["No, I think I'll just wallow in self pity for a while."] = "No, creo que me hundiré en la autocompasión por un tiempo.",
    ["I'm standing right here..."] = "Estoy parado aquí...",
    ["Following in the footsteps of Orcus, I see. And just what do you hope that this will achieve?"] = "Siguiendo los pasos de Orcus, ya veo. ¿Y qué espera que se logre con esto?",
    ["If I can find your tomb, I might find a way to stop you!"] = "¡Si puedo encontrar tu tumba, podría encontrar una manera de detenerte!",
    ["Would that be the tomb for my mortal remains? Remains decayed ages hence, in a tomb now utterly filled in with dirt? At least Orcus was timely..."] = "¿Esa sería la tumba de mis restos mortales? ¿Permanecerá desde hace siglos en descomposición, en una tumba ahora completamente llena de tierra? Al menos Orcus llegó a tiempo...",
    ["Fine, then tell me about Orcus."] = "Bien, entonces cuéntame sobre Orcus.",
    ["He sought me out to devour my remains. It's a chthonian thing; he sought to absorb my knowledge and power. Unfortunately for him, the reverse is what happened."] = "Me buscó para devorar mis restos. Es algo cthoniano; buscó absorber mi conocimiento y poder. Desafortunadamente para él, sucedió lo contrario.",
    ["I greeted him as a fellow necromancer, the first of our kind on this world after my own rise. He taught me of the primordial elements and of Erebus."] = "Lo saludé como a un compañero nigromante, el primero de nuestra especie en este mundo después de mi propio ascenso. Me enseñó de los elementos primordiales y del Erebus.",
    ["The revelation both scared and angered me. Scared for what this other realm would do to ours. Angered at Guthix for keeping such a dark secret from me!"] = "La revelación me asustó y enfureció al mismo tiempo. Asustado por lo que este otro reino le haría al nuestro. ¡Enfadado con Guthix por ocultarme un secreto tan oscuro!",
    ["If only Guthix had told me, I could have..."] = "Si Guthix me lo hubiera dicho, podría haber...",
    ["Could have what?"] = "¿Podría tener qué?",
    ["Ah, but that is a revelation for another time."] = "Ah, pero esa es una revelación para otro momento.",
    ["Fine, then what happened to Orcus?"] = "Bien, entonces ¿qué pasó con Orcus?",
    ["The same thing that happens to all necromancers who seek me out. I take them under my tutelage, build them up and set them loose on the world."] = "Lo mismo que les pasa a todos los nigromantes que me buscan. Los tomo bajo mi tutela, los edifico y los dejo sueltos por el mundo.",
    ["Then, once they have surpassed my own knowledge in some way, I wring out all of their secrets, then obliterate them."] = "Luego, una vez que han superado mi propio conocimiento de alguna manera, exprimo todos sus secretos y luego los borro.",
    ["And that's what you're doing with me? Just waiting for me to learn something you don't?"] = "¿Y eso es lo que estás haciendo conmigo? ¿Estás esperando que aprenda algo que tú no sabes?",
    ["In part. Do not worry; you have yet to learn anything I have not known for many lifetimes. And you will learn nothing of value here..."] = "En parte. No te preocupes; todavía tienes que aprender algo que yo no haya sabido en muchas vidas. Y aquí no aprenderás nada de valor...",
    ["...So do not disturb me like this again."] = "...Así que no me molestes así otra vez.",
    ["Congratulations! You have completed: 'Resting Lich Place' - Locate Rasial's tomb after 'Tomes of the Warlock'."] = "¡Felicidades! Has completado: 'Lugar de descanso del Lich': localiza la tumba de Rasial después de los 'Tomos del brujo'.",
    ["- \"Rasial!"] = "- \"¡Rasial!",
    ["- \"Perhaps you're not as ready as I thought."] = "- \"Quizás no estés tan preparado como pensaba\".",
    ["- \"Hahaha, you missed! My turn."] = "- \"¡Jajaja, te perdiste! Mi turno\".",
    ["Greetings friend. I am Rasolo, the famous merchant. Would you care to see my wares?"] = "Saludos amigo. Soy Rasolo, el famoso comerciante. ¿Le importaría ver mis productos?",
    ["No, not really."] = "No, en realidad no.",
    ["As you wish. I will travel wherever the business takes me."] = "Como desees. Viajaré a donde me lleve el negocio.",
    ["Many thanks for returning my heirloom to me, adventurer. Would you like to buy something?"] = "Muchas gracias por devolverme mi reliquia, aventurero. ¿Quieres comprar algo?",
    ["I lost that ring you gave me..."] = "Perdí ese anillo que me diste...",
    ["Then by all means, take another. Only a foolish merchant would give away his only stock!"] = "Entonces, por supuesto, toma otro. ¡Sólo un comerciante tonto regalaría sus únicas acciones!",
    ["Are you sure? I don't have it anymore..."] = "¿Estás seguro? ya no lo tengo...",
    ["Congratulations! You have completed: 'Ratbusters' - Attempt to catch a ghostly rat."] = "¡Felicitaciones! Has completado: 'Ratbusters': intenta atrapar una rata fantasmal.",
    ["The rat seems to phase right through your cat."] = "La rata parece atravesar a tu gato.",
    ["Do you want to try catching that ghostly rat over there?"] = "¿Quieres intentar atrapar esa rata fantasmal de allí?",
    ["Don't be ridiculous, that rat would phase right through me!"] = "¡No seas ridículo, esa rata me atravesaría!",
    ["An army of rats have arrived across the city."] = "Un ejército de ratas ha llegado a la ciudad.",
    ["5 souls fly over to power the vessel."] = "5 almas vuelan para impulsar el barco.",
    ["[Name], the ghost rat, has been recruited into your undead rat army!"] = "¡[Name], la rata fantasma, ha sido reclutada en tu ejército de ratas no muertas!",
    ["Finally! My ghost rat army is complete!"] = "¡Por fin! ¡Mi ejército de ratas fantasmas está completo!",
    ["About the Task System..."] = "Acerca del sistema de tareas...",
    ["I think I've finished all of the Easy Tasks in the Varrock set."] = "Creo que terminé todas las tareas fáciles del conjunto Varrock.",
    ["You have? Excellent! Well done."] = "¿Tienes? ¡Excelente! Bien hecho.",
    ["Thank you. Uh...can I have the reward?"] = "Gracias. Uh... ¿puedo tener la recompensa?",
    ["Reward? Ah, yes! Of course. Your reward: it's right here."] = "¿Recompensa? ¡Ah, sí! Por supuesto. Tu recompensa: está aquí mismo.",
    ["Now, this body armour is magically enhanced to help you with your Smithing and Mining. There is a furnace, not far from here, in Edgeville. Use this armour there and, when smelting ores up to and including steel, you will have a"] = "Ahora, esta armadura corporal está mejorada mágicamente para ayudarte con tu Smithing y Mining. Hay un horno, no lejos de aquí, en Edgeville. Utilice esta armadura allí y, al fundir minerales hasta acero inclusive, tendrá una",
    ["chance of making an extra bar every time. Also, when you mine with this armour on, you will have a chance of Mining extra ores from rocks up to and including coal."] = "posibilidad de hacer una barra extra cada vez. Además, cuando extraigas con esta armadura, tendrás la posibilidad de obtener Mining minerales adicionales, desde rocas hasta carbón incluido.",
    ["Oh, and it will also make you more likely to obtain parts of the spectre from the Stronghold of Security. And, when you assemble it, instead of 5 charges per day you'll get 10. Bear in mind that you'll need to be wearing the armour for any of these to work."] = "Ah, y también hará que sea más probable que obtengas partes del espectro de la Fortaleza de Seguridad. Y, cuando lo montes, en lugar de 5 cargas por día obtendrás 10. Ten en cuenta que necesitarás llevar puesta la armadura para que cualquiera de ellas funcione.",
    ["I can also change your Varrock Teleport spell so that it takes you to the Grand Exchange, if you'd find that more convenient."] = "También puedo cambiar tu hechizo de Teletransporte Varrock para que te lleve al Grand Exchange, si lo encuentras más conveniente.",
    ["As an extra reward, you can also have this old magical lamp to help with your skills. I was going to use it myself but I don't really need it."] = "Como recompensa adicional, también puedes tener esta antigua lámpara mágica para ayudarte con tus habilidades. Lo iba a usar yo mismo pero realmente no lo necesito.",
    ["Wow, thanks!"] = "¡Vaya, gracias!",
    ["If you should lose the armour, come back and see me for another set."] = "Si pierdes la armadura, vuelve a verme para otro juego.",
    ["Ah, hello there! How's the armour going for you?"] = "¡Ah, hola! ¿Cómo te va con la armadura?",
    ["I lost it."] = "Lo perdí.",
    ["Not a problem. I have a another one here that you can have."] = "No hay problema. Tengo otro aquí que puedes tener.",
    ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
    ["For completing the Varrock set, you are presented with some body armour."] = "Para completar el conjunto Varrock, se te presenta una armadura corporal.",
    ["This armour will become increasingly useful with each difficulty level of the set that you complete."] = "Esta armadura será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
    ["You need to complete all of the Tasks in the set of a particular difficulty, then you can claim your reward."] = "Debes completar todas las tareas del conjunto de una dificultad particular y luego podrás reclamar tu recompensa.",
    ["Most of the Varrock set's Tasks are straightforward, though you might find some require quests to be started, if not finished."] = "La mayoría de las tareas del conjunto Varrock son sencillas, aunque es posible que algunas requieran que se inicien, si no se terminan.",
    ["To claim your Varrock set reward, speak to Reldo in Varrock Library, Vannaka in Edgeville, or me."] = "Para reclamar la recompensa del conjunto Varrock, hable con Reldo en la biblioteca Varrock, con Vannaka en Edgeville o conmigo.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Varrock armour 1"] = "Armadura Varrock 1",
    ["Varrock armour 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "¿Armadura Varrock 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["Purchase another for 1,500 coins?"] = "¿Comprar otro por 1.500 coins?",
    ["[You're handed another Varrock armour 1.]"] = "[Te entregan otra armadura Varrock 1.]",
    ["Varrock armour 2"] = "Varrock armadura 2",
    ["Varrock armour 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "¿Armadura Varrock 2? Sí, pero me temo que te costaría 2500 coins.",
    ["Purchase another for 2,500 coins?"] = "¿Comprar otro por 2500 coins?",
    ["[You're handed another Varrock armour 2.]"] = "[Te entregan otra armadura Varrock 2.]",
    ["Varrock armour 3"] = "Varrock armadura 3",
    ["Varrock armour 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "¿Armadura Varrock 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["Purchase another for 7,500 coins?"] = "¿Comprar otro por 7.500 coins?",
    ["[You're handed another Varrock armour 3.]"] = "[Te entregan otra armadura Varrock 3.]",
    ["Varrock armour 4"] = "Varrock armadura 4",
    ["Varrock armour 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "¿Armadura Varrock 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["Purchase another for 15,000 coins?"] = "¿Comprar otro por 15.000 coins?",
    ["[You're handed another Varrock armour 4.]"] = "[Te entregan otra armadura Varrock 4.]",
    ["I'd like to change my teleport point."] = "Me gustaría cambiar mi punto de teletransporte.",
    ["I'd like to change my Varrock Teleport point."] = "Me gustaría cambiar mi punto de teletransporte Varrock.",
    ["Can I change my Varrock teleport point?"] = "¿Puedo cambiar mi punto de teletransporte Varrock?",
    ["Certainly. It's currently set to the [the fountain in the middle of Varrock/Grand Exchange/the altar in the north of Varrock]. Where would you prefer?"] = "Por supuesto. Actualmente está configurado en [the fountain in the middle of Varrock/Grand Exchange/the altar in the north of Varrock]. ¿Dónde preferirías?",
    ["Fountain in the middle of Varrock."] = "Fuente en medio de Varrock.",
    ["Okay, that's all done."] = "Bien, eso está todo hecho.",
    ["Your Varrock teleport will now teleport you to the middle of Varrock."] = "Tu teletransporte Varrock ahora te teletransportará al centro de Varrock.",
    ["Your Varrock teleport will now teleport you to the Grand Exchange."] = "Su teletransporte Varrock ahora lo teletransportará al Grand Exchange.",
    ["Altar in the north."] = "Altar en el norte.",
    ["Your Varrock teleport will now teleport you to the altar in the north of Varrock."] = "Tu teletransporte Varrock ahora te teletransportará al altar en el norte de Varrock.",
    ["Oh, hello. I'd love to chat right now, but I'm a bit busy. Perhaps you could come back and chat some other time?"] = "Oh, hola. Me encantaría charlar ahora mismo, pero estoy un poco ocupado. ¿Quizás podrías volver y charlar en otro momento?",
    ["Of course. Sorry to bother you!"] = "Por supuesto. ¡Lamento molestarlo!",
    ["Not at all! Farewell!"] = "¡Para nada! ¡Despedida!",
    ["You should speak with the ruler of this isle, King Gjuki Sorvott IV."] = "Deberías hablar con el gobernante de esta isla, el rey Gjuki Sorvott IV.",
    ["Is there anything else I can help you with?"] = "¿Hay algo más en lo que pueda ayudarte?",
    ["Can I have a look at your stock, please?"] = "¿Puedo echar un vistazo a su stock, por favor?",
    ["Can I have a look at your stock please?"] = "¿Puedo echar un vistazo a sus existencias, por favor?",
    ["No, nothing just now thanks."] = "No, nada ahora, gracias.",
    ["Oh, hello again. Want to buy some armour?"] = "Oh, hola de nuevo. ¿Quieres comprar algo de armadura?",
    ["I'll have a look."] = "Echaré un vistazo.",
    ["Not right now."] = "No en este momento.",
    ["It's rare that a visitor finds their way to my hut."] = "Es raro que un visitante encuentre el camino a mi cabaña.",
    ["You are welcome to stay as long as you'd like and immerse yourself in the tranquillity of the mountains."] = "Puedes quedarte todo el tiempo que quieras y sumergirte en la tranquilidad de las montañas.",
    ["I find that fishing is a great way to unwind and become one with nature. There's a wonderful spot beside my abode."] = "Creo que pescar es una excelente manera de relajarse y convertirse en uno con la naturaleza. Hay un lugar maravilloso al lado de mi morada.",
    ["Ah, it's you, how's it going?"] = "Ah, eres tú, ¿cómo te va?",
    ["Hey, I've laid a Shade to rest, can you tell me where the Shade lair is now?"] = "Oye, he dejado descansar a Shade, ¿puedes decirme dónde está ahora la guarida de Shade?",
    ["Yeah, great job putting that Shade to rest. The entrance to the Shade Lair is due North of my shop. Good hunting in the lair my friend!"] = "Sí, gran trabajo al dejar descansar a esa Sombra. La entrada a Shade Lair está al norte de mi tienda. ¡Buena caza en la guarida amigo!",
    ["Can you open a store for me?"] = "¿Puedes abrirme una tienda?",
    ["Sure, which store do you wanna see?"] = "Claro, ¿qué tienda quieres ver?",
    ["Can I see the general store please?"] = "¿Puedo ver el general store por favor?",
    ["Can I see the building store please?"] = "¿Puedo ver la tienda de construcción, por favor?",
    ["Ok, thanks."] = "Vale, gracias.",
    ["Ask about planks."] = "Pregunta por planks.",
    ["I hear that you have some planks for me?"] = "He oído que tienes algo de planks para mí.",
    ["Of course, which would you like?"] = "Por supuesto, ¿cuál te gustaría?",
    ["210 noted normal planks"] = "210 notó normal planks",
    ["Are you sure?"] = "¿Estás seguro?",
    ["[Razmire hands you some noted planks.]"] = "[Razmire te entrega algunos planks destacados.]",
    ["There you go. Come back in [X] days for some more."] = "Ahí lo tienes. Vuelve en [X] días por más.",
    ["140 noted oak planks"] = "140 roble notado planks",
    ["70 noted teak planks"] = "70 teca notada planks",
    ["Talk about something else"] = "hablar de otra cosa",
    ["Get out of it! You'se aint commin' in 'ere to get our's blood or's our food!"] = "¡Fuera de ahí! ¡No vendrás aquí a buscar nuestra sangre ni nuestra comida!",
    ["Huh! I'm Razvan. Ravaging after food is what I mostly do. Occasionally, I'll happen across a rat - and that's a good day - just like today!"] = "¡Eh! Soy Razvan. Devastar la comida es lo que más hago. De vez en cuando me cruzo con una rata, y que sea un buen día, ¡como hoy!",
    ["You don't have anything to hand in."] = "No tienes nada que entregar.",
    ["You hand in: [number] x Ectoplasm."] = "Entregas: [número] x Ectoplasma.",
    ["About time someone showed up to help. You see those ghosts? Get me their ectoplasm. Quick, now, before my bones fall apart again."] = "Ya era hora de que alguien apareciera para ayudar. ¿Ves esos fantasmas? Consígueme su ectoplasma. Rápido, ahora, antes de que mis huesos se desmoronen otra vez.",
    ["For completing this event you receive: 1 x Sack of wild rewards."] = "Por completar este evento recibirás: 1 x Saco de recompensas salvajes.",
    ["Citizens of West Ardougne! Who will join the Royal Army of Ardougne? It is a very noble cause. Fight alongside King Tyras, crusading in the darklands of the west!"] = "¡Ciudadanos de West Ardougne! ¿Quién se unirá al Ejército Real de Ardougne? Es una causa muy noble. ¡Lucha junto al rey Tyras en una cruzada en las tierras oscuras del oeste!",
    ["Plague bringer!"] = "¡Portador de plaga!",
    ["King Tyras is scum!"] = "¡El rey Tyras es escoria!",
    ["Tyras will be informed of these words of treason!"] = "¡Tyras será informado de estas palabras de traición!",
    ["Citizens of West Ardougne! Who will join the Royal Army of Ardougne? It is a very noble cause. Stand alongside King Thoros, ready to defend our land from new threats!"] = "¡Ciudadanos de West Ardougne! ¿Quién se unirá al Ejército Real de Ardougne? Es una causa muy noble. ¡Ponte junto al Rey Thoros, listo para defender nuestra tierra de nuevas amenazas!",
    ["Liar!"] = "¡Mentiroso!",
    ["Thoros is just as bad!"] = "¡Thoros es igual de malo!",
    ["King Thoros will be informed of these words of treason!"] = "¡El rey Thoros será informado de estas palabras de traición!",
    ["shadow=yes"] = "sombra=si",
    ["*(If the Red Revolution achievement hasn't been completed:)*"] = "*(Si el logro Revolución Roja no se ha completado:)*",
    ["Look lively! Let's see if you have what it takes to answer this question."] = "¡Luce animado! Veamos si tienes lo necesario para responder esta pregunta.",
    ["What question?"] = "¿Qué pregunta?",
    ["The one on this scroll."] = "El de este pergamino.",
    ["[The recruiter has given you a challenge scroll!]"] = "[¡El reclutador te ha dado un pergamino de desafío!]",
    ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
    ["Enter amount: [Input field]"] = "Ingrese la cantidad: [Input field]",
    ["Not even close!"] = "¡Ni siquiera cerca!",
    ["[The recruiter has given you another clue scroll!]"] = "[¡El reclutador te ha dado otro pergamino de pistas!]",
    ["Spot on!"] = "¡Acertado!",
    ["Don't bother me!"] = "¡No me molestes!",
    ["Mraaaawr!"] = "¡Mraaaawr!",
    ["Insolent dwarves! How dare they deny me my heritage? I am King Tiddles XIV, rightful king of all cats!"] = "¡Enanos insolentes! ¿Cómo se atreven a negarme mi herencia? ¡Soy el Rey Tiddles XIV, legítimo rey de todos los gatos!",
    ["There's a king of cats?"] = "¿Hay un rey de los gatos?",
    ["Can you not tell by my resplendent coat? Clearly I am a superior feline and deserve to rule."] = "¿No lo notas por mi abrigo resplandeciente? Claramente soy un felino superior y merezco gobernar.",
    ["Do you have any cat followers?"] = "¿Tienes algún gato seguidor?",
    ["Not yet, but only because these dwarves refuse to support me! If they would herd all the world's cats into my throne room as I have told them to, I would soon claim my rightful place!"] = "¡Todavía no, pero sólo porque estos enanos se niegan a apoyarme! Si arrearan a todos los gatos del mundo en mi salón del trono como les dije, ¡pronto reclamaría el lugar que me corresponde!",
    ["Can you tell me about the Red Axe?"] = "¿Puedes hablarme sobre el Hacha Roja?",
    ["Incompetent servants, whom I have discarded! Hreidmar's plans showed promise at first, but he let himself be foiled at every turn by a human adventurer!"] = "¡Siervos incompetentes, a quienes he descartado! Los planes de Hreidmar parecían prometedores al principio, ¡pero se dejó frustrar en todo momento por un aventurero humano!",
    ["After his first setback, he made a tactical retreat into smelly, dusty caves. Luckily he saw his error and built a more lavish home for me to live in."] = "Después de su primer revés, hizo una retirada táctica hacia cuevas polvorientas y malolientes. Afortunadamente, vio su error y construyó una casa más lujosa para que yo viviera.",
    ["When the dwarves in his company threatened to leave, he transformed them into chaos dwarves! He was right to punish them of course, but chaos dwarves are impolite and never gave me treats."] = "Cuando los enanos de su compañía amenazaron con irse, ¡los transformó en enanos del caos! Tenía razón al castigarlos, por supuesto, pero los enanos del caos son descorteses y nunca me dieron golosinas.",
    ["He kept on with his pointless experiments. First chaos dwogres, and then chaos giants, although he ever learned to control them. He did keep them away from the palace though, no doubt out of respect for me."] = "Continuó con sus experimentos inútiles. Primero los dwogres del caos y luego los gigantes del caos, aunque alguna vez aprendió a controlarlos. Sin embargo, los mantuvo alejados del palacio, sin duda por respeto hacia mí.",
    ["In the end he abandoned his quest to make me king of cats, and gave up!"] = "¡Al final abandonó su búsqueda de convertirme en rey de los gatos y se rindió!",
    ["Eventually the Black Guard attacked the palace and rescued me so I could pursue my destiny. Their only mistake was to assign this imbecile as a servant rather than someone competent!"] = "Finalmente, Black Guard atacó el palacio y me rescató para que pudiera perseguir mi destino. ¡Su único error fue asignar a este imbécil como un sirviente en lugar de alguien competente!",
    ["Goodbye."] = "Adiós.",
    ["Arr, Matey!"] = "¡Arriba, amigo!",
    ["**Select an Option**"] = "**Seleccione una opción**",
    ["I'm in search of treasure."] = "Estoy en busca de un tesoro.",
    ["Arr!"] = "¡Arr!",
    ["Do you have anything for trade?"] = "¿Tienes algo para intercambiar?",
    ["Nothin' at the moment, but then again the Customs Agents are on the warpath right now."] = "Nada por el momento, pero claro, los agentes de aduanas están en pie de guerra en este momento.",
    ["Speak about Pieces of Hate"] = "Habla de Piezas de Odio",
    ["Arrr ye really left me out of all that?"] = "¿De verdad me dejaste fuera de todo eso?",
    ["Did ye not be thinking I would have liked to take me knife to Rabid Jack's throat?"] = "¿No estabas pensando que me hubiera gustado poner mi cuchillo en la garganta de Rabid Jack?",
    ["Sorry, I forgot."] = "Lo siento, lo olvidé.",
    ["Aye I be forgotten about a lot these days."] = "Sí, me han olvidado de muchas cosas estos días.",
    ["We already had enough people."] = "Ya teníamos suficiente gente.",
    ["Bah, first rule of be'in a pirate, always bring more than ye need."] = "Bah, la primera regla para ser un pirata es llevar siempre más de lo que necesitas.",
    ["It wasn't my fault!"] = "¡No fue mi culpa!",
    ["Aye, but ye didn't say anything about it did ye?"] = "Sí, pero no dijiste nada al respecto, ¿verdad?",
    ["I mean I literally had no choice."] = "Quiero decir, literalmente no tuve otra opción.",
    ["Bah!"] = "¡Bah!",
    ["Blame Raven"] = "Culpar al cuervo",
    ["What do ye think I am? An idiot? If I blame him he'll put me on his list!"] = "¿Qué crees que soy? ¿Un idiota? ¡Si lo culpo, me pondrá en su lista!",
    ["Oh gods!"] = "¡Oh dioses!",
    ["I'm too ginger to die!"] = "¡Soy demasiado pelirrojo para morir!",
    ["**Redbeard Frank:** Arrr but there be no point in holding a grudge o'er this."] = "**Redbeard Frank:** Arrr, pero no tiene sentido guardar rencor por esto.",
    ["Was it at least a glorious battle?"] = "¿Fue al menos una batalla gloriosa?",
    ["It was very strange, there was 'rum' involved and kittens all over the place."] = "Fue muy extraño, había 'ron' involucrado y gatitos por todos lados.",
    ["Kittens?"] = "¿Gatitos?",
    ["Yeah I'm not sure I get it either."] = "Sí, tampoco estoy seguro de entenderlo.",
    ["Strange tales indeed."] = "Cuentos realmente extraños.",
    ["Go on, be off with ya. I've got pirating to be doing."] = "Continúa, vete. Tengo que dedicarme a la piratería.",
    ["See you around cap'n."] = "Nos vemos cerca, capitán.",
    ["I've come for my reward."] = "He venido por mi recompensa.",
    ["So, you've finished, well done! I believe congratulations are in order."] = "Entonces, ya terminaste, ¡bien hecho! Creo que las felicitaciones son necesarias.",
    ["I believe rewards are in order."] = "Creo que las recompensas están en orden.",
    ["Right you are."] = "Tienes razón.",
    ["This is the first stage of the Falador shield: a buckler. It grants you access to a Prayer restore ability and an emote."] = "Esta es la primera etapa del escudo Falador: un escudo. Te otorga acceso a la capacidad de restauración de Prayer y a un emote.",
    ["Each of these features can be triggered while wielding the shield. The Prayer restore can also be activated from your inventory."] = "Cada una de estas funciones se puede activar mientras se empuña el escudo. La restauración de Prayer también se puede activar desde su inventario.",
    ["The Prayer restore ability can only be used once per day, and gives you back a quarter of your Prayer points."] = "La capacidad de restauración de Prayer solo se puede usar una vez al día y te devuelve una cuarta parte de tus puntos Prayer.",
    ["As well as all of these features, the shield is pretty handy in combat, and gives you a small Prayer boost."] = "Además de todas estas características, el escudo es bastante útil en combate y te brinda un pequeño impulso de Prayer.",
    ["I've even thrown in a bit of booty I found on my travels."] = "Incluso agregué un poco del botín que encontré en mis viajes.",
    ["If you should lose your shield, come back and see me for another one."] = "Si pierdes tu escudo, regresa y busca otro.",
    ["I've lost my shield."] = "He perdido mi escudo.",
    ["What? That was valuable equipment!"] = "¿Qué? ¡Ese era un equipo valioso!",
    ["Luckily, I have a spare. Take better care of it this time."] = "Por suerte, tengo uno de repuesto. Cuídalo mejor esta vez.",
    ["Arr! The Achievement System be a load o 'challenges ta do while adventuring 'round the world."] = "¡Arr! El Sistema de Logros será una gran cantidad de desafíos que enfrentar mientras viajas por el mundo.",
    ["Ye can earn plunder for completin' certain achievements - either booty or pieces o' eight - which ye can get from Explorer Jack in Lumbridge."] = "Puedes ganar botín al completar ciertos logros, ya sea botín o piezas de ocho, que puedes obtener de Explorer Jack en Lumbridge.",
    ["Most o' them, if ye do enough in an area, gets ye a powerful item which can be claimed from someone in the area, such as meself."] = "La mayoría de ellos, si haces lo suficiente en un área, obtienes un objeto poderoso que puedes reclamar de alguien en el área, como yo.",
    ["Yer reward here in Falador be a shield, matey, and a better one each time ye finishes a difficulty level."] = "Tu recompensa aquí en Falador será un escudo, un compañero y uno mejor cada vez que termines un nivel de dificultad.",
    ["We'll let ye know what it does when we gives it to ye."] = "Te informaremos qué hace cuando te lo entreguemos.",
    ["You need to complete all of the tasks in a set of a particular difficulty, then you can claim your reward."] = "Debes completar todas las tareas en un conjunto de una dificultad particular, luego podrás reclamar tu recompensa.",
    ["Some of the Falador set's tasks are simple, some will require certain skill levels, and some might require quests to be started or completed."] = "Algunas de las tareas del conjunto Falador son simples, algunas requerirán cierto skill levels y otras pueden requerir que se inicien o completen misiones.",
    ["Ta claim yer Falador set rewards, have a chinwag with the chemist in Rimmington, Sir Vyvin's squire in the White Knights' Castle, or meself."] = "Para reclamar las recompensas del conjunto Falador, charlar con el químico de Rimmington, el escudero de Sir Vyvin en el Castillo de los Caballeros Blancos o conmigo mismo.",
    ["Falador shield 1"] = "Escudo Falador 1",
    ["Falador shield 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "¿Escudo Falador 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["[You're handed another Falador shield 1.]"] = "[Te entregan otro escudo Falador 1.]",
    ["Falador shield 2"] = "Escudo Falador 2",
    ["Falador shield 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "¿Escudo Falador 2? Sí, pero me temo que te costaría 2500 coins.",
    ["[You're handed another Falador shield 2.]"] = "[Te entregan otro escudo Falador 2.]",
    ["Falador shield 3"] = "Escudo Falador 3",
    ["Falador shield 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "¿Escudo Falador 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["[You're handed another Falador shield 3.]"] = "[Te entregan otro escudo Falador 3.]",
    ["Falador shield 4"] = "Escudo Falador 4",
    ["Falador shield 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "¿Escudo Falador 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["[You're handed another Falador shield 4.]"] = "[Te entregan otro escudo Falador 4.]",
    ["Arr yourself! Say Frank, what's the deal with that chest over there?"] = "¡Arréglate! Di Frank, ¿qué pasa con ese cofre de ahí?",
    ["That be a treasure chest of One-Eyed Hector, me ol' captain."] = "Ese será un cofre del tesoro de Héctor el Tuerto, mi viejo capitán.",
    ["It recently washed up and considerin' all them celebrations and gift-givings lately, I thought I'd hand out its riches to the people of Gielinor."] = "Recientemente se lavó y considerando todas las celebraciones y regalos de los últimos tiempos, pensé en entregar sus riquezas a la gente de Gielinor.",
    ["Ye know, to right some past wrongs and such."] = "Ya sabes, para corregir algunos errores del pasado y cosas así.",
    ["That's great! Can I have some?"] = "¡Eso es genial! ¿Puedo tener algunos?",
    ["Arr, well, ye know..."] = "Arr, bueno, ya sabes...",
    ["...I may not have the key for it."] = "...Puede que no tenga la clave.",
    ["But that be where ye come in! For every 4 pirate's keys ye bring me, I'll give ye one piece of treasure once the chest's open."] = "¡Pero ahí es donde entras tú! Por cada 4 llaves de pirata que me traigas, te daré un tesoro una vez que esté abierto el cofre.",
    ["Until January 31st, ye'll be able to find keys every day when you arrive in Gielinor, and hourly while ye're out and about."] = "Hasta el 31 de enero, podrás encontrar las llaves todos los días cuando llegues a Gielinor y cada hora mientras estés fuera de casa.",
    ["However, ye won't be findin' more than 12 keys a week I reckon."] = "Sin embargo, creo que no encontrarás más de 12 llaves por semana.",
    ["A pirate's week always begins on Wednesday, so that's when more pirate's keys will surely appear."] = "La semana de un pirata siempre comienza el miércoles, así que es cuando seguramente aparecerán más llaves de piratas.",
    ["Sounds like a deal! But what if the fitting key is rusting away at the bottom of the sea?"] = "¡Suena como un trato! ¿Pero qué pasa si la llave de montaje se está oxidando en el fondo del mar?",
    ["Arr, that be quite likely. I was hopin' to avoid keelhauling Hector's memory like this, but..."] = "Arr, eso es bastante probable. Esperaba evitar arrastrar la memoria de Héctor de esta manera, pero...",
    ["...if it's still shut on February 1st, I'll just blast it open."] = "...si todavía está cerrado el 1 de febrero, lo abriré de golpe.",
    ["Either way, if ye come to me once the chest is open, I'll wait for another four weeks for ye to claim yer share, until February 28th."] = "De cualquier manera, si vienes a verme una vez que el cofre esté abierto, esperaré otras cuatro semanas para que reclames tu parte, hasta el 28 de febrero.",
    ["Speak about Frank's Free Chest"] = "Habla sobre el cofre gratuito de Frank",
    ["For every 4 pirate's keys ye bring me, I'll give ye one piece of treasure once the chest's open."] = "Por cada 4 llaves de pirata que me traigas, te daré un tesoro una vez que el cofre esté abierto.",
    ["Ye'll be able to find keys every day when you arrive in Gielinor, and hourly while ye're out and about."] = "Podrás encontrar las llaves todos los días cuando llegues a Gielinor y cada hora mientras estés fuera de casa.",
    ["A pirate's week always begins on Wednesday, so that's when ye'll be able to find more keys."] = "La semana de un pirata siempre comienza el miércoles, así que ahí es cuando podrás encontrar más llaves.",
    ["Ye can bring me keys until January 31st."] = "Podéis traerme las llaves hasta el 31 de enero.",
    ["After that, I'll wait until February 28th for ye to claim yer share."] = "Después de eso, esperaré hasta el 28 de febrero para que reclames tu parte.",
    ["I'm currently handing out its riches to the people of Gielinor."] = "Actualmente estoy repartiendo sus riquezas a la gente de Gielinor.",
    ["Go on and take yer share!"] = "¡Continúa y toma tu parte!",
    ["Arr there! I see you've dredged up another chest from the depths of the sea?"] = "¡Llega ahí! ¿Veo que has sacado otro cofre de las profundidades del mar?",
    ["Aye! Hector's humid hoard be provin' quite lucrative."] = "¡Sí! El húmedo tesoro de Héctor está resultando bastante lucrativo.",
    ["That's great to hear! Any chance I can get some loot in exchange for keys again?"] = "¡Es genial escucharlo! ¿Alguna posibilidad de volver a conseguir algo de botín a cambio de llaves?",
    ["I hope there's no toads in there this time..."] = "Espero que no haya sapos ahí esta vez...",
    ["I actually found the key fer this one meself!"] = "¡De hecho, encontré la clave de este yo mismo!",
    ["Took a peek in it earlier. Lots o' piratey attire an' pets, powerful items, an' not one toad!"] = "Le eché un vistazo antes. ¡Muchos atuendos piratas y mascotas, objetos poderosos y ni un solo sapo!",
    ["But how can I earn some loot if you don't need me to bring you keys?"] = "¿Pero cómo puedo ganar algo de botín si no necesitas que te traiga las llaves?",
    ["Ye can pay me for it, in bits of eight!"] = "¡Puedes pagarme por ello, en trozos de ocho!",
    ["Until the end of May 2nd, ye'll be able to find those every day when ye arrive in Gielinor, an' hourly while ye're out an' about."] = "Hasta finales del 2 de mayo, podrás encontrarlos todos los días cuando llegues a Gielinor, y cada hora mientras estés fuera.",
    ["There be a cap of 16 a week, which resets every Wednesday."] = "Habrá un límite de 16 por semana, que se reinicia todos los miércoles.",
    ["For every 4 bits of eight ye bring me, I'll reserve a piece o' treasure for ye."] = "Por cada 4 bits de ocho que me traigas, te reservaré un tesoro.",
    ["Every 8 bits of eight, that piece will be from a special pool."] = "Cada 8 bits de ocho, esa pieza será de un grupo especial.",
    ["That means roughly half yer loot will be piratey spoils and powerful items!"] = "¡Eso significa que aproximadamente la mitad de tu botín será botín pirata y objetos poderosos!",
    ["On top o' that, I've instructed me crew to deliver ye some extra pirate plunder for every 16 bits of eight ye find."] = "Además de eso, le he ordenado a mi tripulación que les entregue un botín pirata adicional por cada 16 bits de ocho que encuentren.",
    ["Each pirate plunder has a piece of loot from this here chest as well as a title and some clothing worthy of a pirate."] = "Cada botín pirata tiene un botín de este cofre, así como un título y algo de ropa digna de un pirata.",
    ["Ye can come claim yer earned loot from May 3rd until the end of May 31st."] = "Puedes venir a reclamar el botín ganado desde el 3 de mayo hasta el final del 31 de mayo.",
    ["pieces of eight."] = "piezas de a ocho.",
    ["About Frank's Free Chest"] = "Acerca del cofre gratuito de Frank",
    ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
    ["About Bits of Eight"] = "Acerca de Bits de ocho",
    ["Since me rum reserves be runnin' out fast, I be handing out loot in exchange for bits of eight this time."] = "Dado que mis reservas de ron se están agotando rápidamente, esta vez repartiré botín a cambio de trozos de ocho.",
    ["About Chest Loot"] = "Acerca del botín del cofre",
    ["About Pirate Plunder"] = "Acerca del saqueo de Pirate",
    ["I've instructed me crew to deliver ye some extra pirate plunder for every 16 bits of eight ye find."] = "Le he ordenado a mi tripulación que les entregue un botín pirata adicional por cada 16 bits de ocho que encuentren.",
    ["If ye've got enough bits of eight, ye can now claim a share of the loot."] = "Si tienes suficientes piezas de ocho, ahora puedes reclamar una parte del botín.",
    ["It be one piece of treasure for every 4 bits of eight. Roughly half of the treasure be piratey attire an' pets, or powerful items!"] = "Será un tesoro por cada 4 bits de ocho. ¡Aproximadamente la mitad del tesoro son vestimentas piratas, mascotas o objetos poderosos!",
    ["Why aren't you cutting the trees with the others?"] = "¿Por qué no cortas los árboles con los demás?",
    ["Do you see da faces on da trees? They always watching us..."] = "¿Ves las caras en los árboles? Siempre nos miran...",
    ["They're just trees. They don't have eyes."] = "Son solo árboles. No tienen ojos.",
    ["Maybe not now, but once maybe. I can feel them on me."] = "Quizás no ahora, pero quizás una vez. Puedo sentirlos en mí.",
    ["That why I not chopping them anymore. Feels wrong."] = "Por eso ya no los corto. Se siente mal.",
    ["And how can I be a woodcutter if I not cut wood?"] = "¿Y cómo puedo ser leñador si no corto madera?",
    ["So just rethinking whole life."] = "Así que repensar toda la vida.",
    ["Please do not disturb me, outerlander. I have much to do."] = "Por favor, no me molestes, extranjero. Tengo mucho que hacer.",
    ["Sorry, [Fremennik name], I must get on with my work."] = "Lo siento, [Fremennik name], debo continuar con mi trabajo.",
    ["Greetings, [Sir/Madam]."] = "Saludos, [Sir/Madam].",
    ["Tell me about the shotput area."] = "Cuéntame sobre el área de lanzamiento de peso.",
    ["Of course [Sir/Madam]. There are two different weights of shot..."] = "Por supuesto [Sir/Madam]. Hay dos pesos diferentes de tiro...",
    ["Shot?"] = "¿Disparo?",
    ["Yes [Sir/Madam]. Shot. The iron spheres that are propelled by the chemical energy stored in your body."] = "Sí [Sir/Madam]. Disparo. Las esferas de hierro que son impulsadas por la energía química almacenada en tu cuerpo.",
    ["The... what?"] = "¿El... qué?",
    ["Your strength [Sir/Madam]. The stronger you are, the further you can throw the shot, but there are other factors of course, like your technique."] = "Tu fuerza [Sir/Madam]. Cuanto más fuerte seas, más lejos podrás lanzar el tiro, pero, por supuesto, hay otros factores, como tu técnica.",
    ["What's that then?"] = "¿Qué es eso entonces?",
    ["The style of the shot [Sir/Madam]."] = "El estilo de la toma [Sir/Madam].",
    ["Iron has style??"] = "¿El hierro tiene estilo?",
    ["The referee sighs, rolls his eyes and continues...."] = "El árbitro suspira, pone los ojos en blanco y continúa....",
    ["[Sir/madam], the style in which you throw the shot, not the style of the iron."] = "[Sir/madam], el estilo con el que lanzas el tiro, no el estilo del hierro.",
    ["Oh! You mean the spinny round thing or the chuck it straight?"] = "¡Oh! ¿Te refieres a la cosa redonda que gira o a tirarla recta?",
    ["Crudely put, [Sir/Madam], but yes. Some are more difficult than others. Experiment and see which you prefer."] = "En pocas palabras, [Sir/Madam], pero sí. Algunas son más difíciles que otras. Experimente y vea cuál prefiere.",
    ["Thanks for the help!"] = "¡Gracias por la ayuda!",
    ["You are welcome, [Sir/Madam]."] = "De nada, [Sir/Madam].",
    ["Do you have any tips for me?"] = "¿Tienes algún consejo para mí?",
    ["Tips, [Sir/Madam]?"] = "¿Consejos, [Sir/Madam]?",
    ["Yes, like how can I do better than everyone else."] = "Sí, ¿cómo puedo hacerlo mejor que los demás?",
    ["[sir/Madam] may find that a fine powder applied to the hands may give one an advantage when putting the shot."] = "[sir/Madam] puede descubrir que un polvo fino aplicado en las manos puede darle una ventaja al realizar el tiro.",
    ["You mean if I grind something up and put dust on my hands I'll chuck the ball further?"] = "¿Quieres decir que si muelo algo y me pongo polvo en las manos, arrojaré la pelota más lejos?",
    ["Yes, [Sir/Madam]."] = "Sí, [Sir/Madam].",
    ["Bye!"] = "¡Adiós!",
    ["Good luck [Sir/Madam]."] = "Buena suerte [Sir/Madam].",
    ["Hey! You can't take that, it's guild property. Take one from the pile."] = "¡Oye! No puedes tomar eso, es propiedad del gremio. Toma uno del montón.",
    ["Pace yourself!"] = "¡Controla tu ritmo!",
    ["Hey, slow down!"] = "¡Oye, más despacio!",
    ["Just a moment, I dropped my hanky."] = "Un momento, se me cayó el pañuelo.",
    ["Wait a moment, I'm nearly ready."] = "Espera un momento, ya casi estoy listo.",
    ["Welcome, adventurer. Have you come to have a look at my fine wares?"] = "Bienvenido, aventurero. ¿Has venido a echar un vistazo a mis finos productos?",
    ["Yes, I want to see what you're selling."] = "Sí, quiero ver lo que estás vendiendo.",
    ["No, I have some questions."] = "No, tengo algunas preguntas.",
    ["What currency are you trading in?"] = "¿En qué moneda está operando?",
    ["What currency are you trading in? It doesn't seem to be regular coins."] = "¿En qué moneda opera? No parece ser un coins normal.",
    ["You are absolutely right, my friend. I exchange my goods for so called Fist of Guthix tokens."] = "Tienes toda la razón, amigo mío. Cambio mis productos por las llamadas fichas del Puño de Guthix.",
    ["How can I get hold of these tokens?"] = "¿Cómo puedo hacerme con estos tokens?",
    ["We run a little business here, together with Fiara. You see, this is a holy site of Guthix and there is great power emanating from that cave over there. We're not quite sure what it is yet, but it has to do with Guthix itself."] = "Tenemos un pequeño negocio aquí, junto con Fiara. Verás, este es un lugar sagrado de Guthix y hay un gran poder que emana de esa cueva de allí. No estamos muy seguros de qué es todavía, pero tiene que ver con el propio Guthix.",
    ["We try to store as much as we can, so that we're ready to use it once we know what it's for."] = "Intentamos almacenar todo lo que podemos para estar listos para usarlo una vez que sepamos para qué sirve.",
    ["And what does that have to do with the tokens?"] = "¿Y eso qué tiene que ver con los tokens?",
    ["Oh yes, the tokens. Everyone is free to enter the contest we're running here, and the winners are rewarded with tokens which you can then trade in for goods. If you want to know more, you should speak to Fiara."] = "Ah, sí, las fichas. Todo el mundo es libre de participar en el concurso que organizamos aquí y los ganadores son recompensados ​​con fichas que luego pueden canjear por productos. Si quieres saber más, debes hablar con Fiara.",
    ["I want to see what you're trading first."] = "Primero quiero ver qué estás negociando.",
    ["I have more questions that I want answered."] = "Tengo más preguntas que quiero respuestas.",
    ["Alright, I will do that."] = "Muy bien, lo haré.",
    ["What are Fist of Guthix tokens?"] = "¿Qué son las fichas de Fist of Guthix?",
    ["Oh, they're nothing special in themselves. They are just tokens we use as currency."] = "Oh, no son nada especiales en sí mismos. Son sólo tokens que utilizamos como moneda.",
    ["What are you selling?"] = "¿Qué estás vendiendo?",
    ["I have another question."] = "Tengo otra pregunta.",
    ["I have to go now."] = "Tengo que irme ahora.",
    ["Can you recharge my items?"] = "¿Pueden recargar mis artículos?",
    ["By items, I assume you mean items originally acquired from me. If so, the answer is yes, my friend. I gladly spread the power of Guthix, if I am able to."] = "Por artículos, asumo que te refieres a artículos que adquirí originalmente de mí. Si es así, la respuesta es sí, amigo. Con mucho gusto difundo el poder de Guthix, si puedo.",
    ["That's great."] = "Eso es genial.",
    ["It certainly is. The power of Guthix does not come cheaply, though. So, I'm afraid I will have to charge you some tokens for it. And I can only recharge items that have been completely depleted of their magical energy."] = "Ciertamente lo es. Sin embargo, el poder de Guthix no es barato. Entonces, me temo que tendré que cobrarte algunas fichas por ello. Y sólo puedo recargar elementos cuya energía mágica se haya agotado por completo.",
    ["Sounds fair. So, how do I go about doing this?"] = "Suena justo. Entonces, ¿cómo hago para hacer esto?",
    ["Just hand me the item you want recharged and I'll see what I can do."] = "Sólo pásame el artículo que deseas recargar y veré qué puedo hacer.",
    ["I want to see what you're selling first."] = "Primero quiero ver qué estás vendiendo.",
    ["I still have more questions."] = "Todavía tengo más preguntas.",
    ["Okay, I'll do that."] = "Está bien, lo haré.",
    ["Can you uncharge my items?"] = "¿Pueden descargar mis artículos?",
    ["Can you uncharge my items for me?"] = "¿Pueden descargar mis artículos por mí?",
    ["You don't want to keep the power of Guthix? That's strange. But yes, of course I can do this for you. Please be aware that you won't get anything in return, except the degraded item, and it will cost you tokens to have it charged again."] = "¿No quieres conservar el poder de Guthix? Eso es extraño. Pero sí, por supuesto que puedo hacer esto por ti. Tenga en cuenta que no recibirá nada a cambio, excepto el artículo degradado, y le costará tokens cargarlo nuevamente.",
    ["Yes, I will keep that in mind."] = "Sí, lo tendré en cuenta.",
    ["Good. In that case, just hand me the item from which you want the charge removed."] = "Bien. En ese caso, simplemente entrégueme el artículo del que desea eliminar el cargo.",
    ["Why do all of your wares degrade?"] = "¿Por qué todos sus productos se degradan?",
    ["Why do all of your wares degrade? I have seen plenty of similar items in my days, but they all seem to last a lot longer than yours."] = "¿Por qué se degradan todos tus productos? He visto muchos artículos similares en mis días, pero todos parecen durar mucho más que los tuyos.",
    ["A most accurate observation, my friend. But the other items you've come across in your travels most certainly have not been directly infused with the power emanating from the Fist of Guthix."] = "Una observación muy precisa, amigo mío. Pero los otros elementos con los que te has topado en tus viajes seguramente no han sido infundidos directamente con el poder que emana del Puño de Guthix.",
    ["Umm...I suppose not. But wouldn't the power of Guthix have made the items stronger?"] = "Umm... Supongo que no. ¿Pero el poder de Guthix no habría hecho que los objetos fueran más fuertes?",
    ["Why, yes, they have. Keeping a shop so close to the source of this power has resulted in the items being infused with energy. This makes them stronger than they normally would have been, but, unfortunately, they are"] = "Vaya, sí, lo han hecho. Mantener una tienda tan cerca de la fuente de este poder ha resultado en que los artículos se infundan de energía. Esto los hace más fuertes de lo que normalmente habrían sido, pero, desafortunadamente, son",
    ["hardly suitable vessels for such divine power. As they are being used, the power will be spent, and all that will remain is an empty, weakened shell. When this happens, just come back to me and I will gladly recharge them for you."] = "Vasijas difícilmente adecuadas para tal poder divino. A medida que se utilicen, la energía se gastará y todo lo que quedará será un caparazón vacío y debilitado. Cuando esto suceda, simplemente regresa conmigo y con gusto los recargaré por ti.",
    ["...For a small fee."] = "...Por una pequeña tarifa.",
    ["Haha. Yes, my friend, for a small fee. The power of a god does not come cheaply, not even in small doses. If we were to give it out for free, we would run out of resources in an instant. Balance must be maintained."] = "Jaja. Sí, amigo mío, por una pequeña tarifa. El poder de un dios no es barato, ni siquiera en pequeñas dosis. Si lo diéramos gratis, nos quedaríamos sin recursos en un instante. Se debe mantener el equilibrio.",
    ["Okay, I will keep that in mind. Thank you."] = "Está bien, lo tendré en cuenta. Gracias.",
    ["Now, is there anything else I can help you with?"] = "Ahora, ¿hay algo más en lo que pueda ayudarte?",
    ["I have to leave now."] = "Tengo que irme ahora.",
    ["Sorry, I have to leave now. Goodbye."] = "Lo siento, tengo que irme ahora. Adiós.",
    ["No, I'm just passing by."] = "No, solo estoy de paso.",
    ["Greetings! I see you are a new arrival to the world of Gielinor. My job is to welcome all new visitors to this land. So, welcome! You've already learned the first thing needed to succeed in this world: talking to other people!"] = "¡Saludos! Veo que eres un recién llegado al mundo de Gielinor. Mi trabajo es dar la bienvenida a todos los nuevos visitantes a esta tierra. Entonces, ¡bienvenido! Ya has aprendido lo primero que se necesita para triunfar en este mundo: ¡hablar con otras personas!",
    ["Getting around is easy. Just . a destination to walk there. a door to open it. to see all options."] = "Moverse es fácil. Sólo . un destino para caminar hasta allí. una puerta para abrirla. para ver todas las opciones.",
    ["To continue, open that door over there."] = "Para continuar, abre esa puerta de allí.",
    ["Now go outside and talk to the Survival Expert."] = "Ahora sal y habla con el experto en supervivencia.",
    ["You've already learned the first thing needed to succeed in this world: talking to other people! You will find many inhabitants of the world of Gielinor have useful things to say to you."] = "Ya has aprendido lo primero que se necesita para triunfar en este mundo: ¡hablar con otras personas! Encontrarás que muchos habitantes del mundo de Gielinor tienen cosas útiles que decirte.",
    ["Getting around is easy. Just . a destination to walk there. a door to open it. Now go outside and talk to the Survival Expert."] = "Moverse es fácil. Sólo . un destino para caminar hasta allí. una puerta para abrirla. Ahora sal y habla con el experto en supervivencia.",
    ["**Reinald** Welcome to my home. I have a fine selection of home- made arm guards, as well as fine clothes imported from Thessalia in Varrock, if you're interested."] = "**Reinald** Bienvenido a mi casa. Tengo una excelente selección de protectores para brazos hechos en casa, así como ropa fina importada de Thessalia en Varrock, si estás interesado.",
    ["**Reinald** You're not able to try on my clothes with all that armour. Take it off and then speak to me again."] = "**Reinald** No puedes probarte mi ropa con toda esa armadura. Quítatelo y luego vuelve a hablarme.",
    ["What would you like to do?"] = "¿Qué te gustaría hacer?",
    ["Ask about their request."] = "Pregunta sobre su solicitud.",
    ["What're you requesting today?"] = "¿Qué pides hoy?",
    ["I've been working on my own farm recently and need a few items to bolster my productivity!"] = "¡He estado trabajando en mi propia granja recientemente y necesito algunos artículos para aumentar mi productividad!",
    ["I'm trying to get some extra crops going, so I'll need : [Seed] x [number]"] = "Estoy intentando conseguir algunos cultivos adicionales, así que necesitaré: [Seed] x [número]",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal].",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal], o [Animal].",
    ["I'm also looking for some produce, so I'll need : [Produce] x [number]"] = "También estoy buscando algunos productos, así que necesitaré: [Produce] x [número]",
    ["If you complete this, I'll give you : Light animica stone spirit x 10. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Espíritu de piedra animica ligera x 10. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] days, [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido!, solo estoy aquí por [número] días, [número] horas y [número] minutos. Para ser exactos.",
    ["Give them the items & animals for their request"] = "Dales los artículos y animales que soliciten.",
    ["You don't have enough items to fulfil my request. I won't take favourited animals."] = "No tienes suficientes artículos para cumplir con mi solicitud. No aceptaré animales favoritos.",
    ["For completing this request you've received Brassica primer x 1."] = "Por completar esta solicitud, recibió 1 imprimación para Brassica.",
    ["[You've received : Light animica stone spirit x 10 And 5,500 farming reputation.]"] = "[Has recibido: Espíritu de piedra animica ligera x 10 Y 5500 reputación agrícola.]",
    ["Thank you for your help!"] = "¡Gracias por tu ayuda!",
    ["A new request will be available in [time]"] = "Una nueva solicitud estará disponible en [time]",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal], or [Animal"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal], o [Animal",
    ["Which animal would you like to hand in?"] = "¿Qué animal te gustaría entregar?",
    ["You've already completed this request, there will be a new bi-daily request in [time]"] = "Ya has completado esta solicitud, habrá una nueva solicitud bidiaria en [time]",
    ["Do you want to buy some leather armour?"] = "¿Quieres comprar una armadura de cuero?",
    ["Yes please."] = "Sí, por favor.",
    ["Have a good day!"] = "¡Que tengas un buen día!",
    ["Hello there. How can I help you today?"] = "Hola. ¿Cómo puedo ayudarte hoy?",
    ["Me? What do you want to know?"] = "¿Yo? ¿Qué quieres saber?",
    ["What do you do?"] = "¿Qué haces?",
    ["I am the palace librarian."] = "Soy el bibliotecario del palacio.",
    ["Ah. That's why you're in the library, then."] = "Ah. Entonces por eso estás en la biblioteca.",
    ["Although I would probably be in here even if I didn't work here. I like reading."] = "Aunque probablemente estaría aquí incluso si no trabajara aquí. Me gusta leer.",
    ["Some day, I hope to catalogue all of the information stored in these books, so all may read it."] = "Algún día espero catalogar toda la información almacenada en estos libros, para que todos puedan leerla.",
    ["Do you have anything to trade?"] = "¿Tienes algo para intercambiar?",
    ["Only knowledge."] = "Sólo conocimiento.",
    ["How much do you want for that, then?"] = "¿Cuánto quieres entonces por eso?",
    ["No, sorry, that was just my little joke. I'm not the trading type."] = "No, lo siento, esa fue solo mi pequeña broma. No soy del tipo comercial.",
    ["Oh, well."] = "Oh, bueno.",
    ["Do you know any heroic stories?"] = "¿Conoces alguna historia heroica?",
    ["Yes, I do."] = "Sí, lo hago.",
    ["Years ago, a terrible creature slew King Roald's betrothed and terrorized the people. Varrock sent an embassy to Morytania to open a dialogue with Drakan about it."] = "Hace años, una criatura terrible mató al prometido de King Roald y aterrorizó a la gente. Varrock envió una embajada a Morytania para abrir un diálogo con Drakan al respecto.",
    ["It didn't end happily. Poor Gar'rth, we didn't know he was... Well, it would be unfair for me to say. That's his secret, not mine."] = "No terminó felizmente. Pobre Gar'rth, no sabíamos que lo era... Bueno, sería injusto de mi parte decirlo. Ese es su secreto, no el mío.",
    ["What about the terrible creature?"] = "¿Qué pasa con la terrible criatura?",
    ["It was brought to justice, but not before claiming many innocents."] = "Fue llevado ante la justicia, no sin antes cobrarse muchos inocentes.",
    ["Go on, tell me about Gar'rth."] = "Continúa, cuéntame sobre Gar'rth.",
    ["Another time, perhaps? I have work to do."] = "¿En otro momento, tal vez? Tengo trabajo que hacer.",
    ["Hmpf!"] = "¡Hmpf!",
    ["That's enough about you."] = "Ya es suficiente sobre ti.",
    ["I've finished all the Medium Tasks in the Varrock set."] = "Terminé todas las tareas medianas del conjunto Varrock.",
    ["Really? How extraordinary! Well, that certainly is a worthy achievement indeed."] = "¿En serio? ¡Qué extraordinario! Bueno, ciertamente es un logro digno de mención.",
    ["Thanks. Was there a reward?"] = "Gracias. ¿Hubo recompensa?",
    ["A reward? Well, yes, I suppose I can help you there."] = "¿Una recompensa? Bueno, sí, supongo que puedo ayudarte en eso.",
    ["Reldo takes the Varrock armour and attaches some more plate metal to it, filling it out to look like a proper suit of armour. He etches some words into the armour, which glows slightly before fading."] = "Reldo toma la armadura Varrock y le coloca un poco más de placa de metal, llenándola para que parezca una armadura adecuada. Graba algunas palabras en la armadura, que brilla ligeramente antes de desvanecerse.",
    ["I have enhanced your body armour with a spell. You now have a chance to double your bars when smelting, ores when mining and progress when smithing mithril and adamant. I can also change your Varrock Teleport spell so that it takes you to the Grand Exchange, if you'd find that more convenient. As an extra reward, I have also given you a magical lamp to help with your skills."] = "He mejorado tu armadura con un hechizo. Ahora tienes la oportunidad de duplicar tus lingotes al fundir, minerales al extraer y progresar al forjar mithril y adamant. También puedo cambiar tu hechizo de Teletransporte Varrock para que te lleve al Grand Exchange, si lo encuentras más conveniente. Como recompensa adicional, también te he dado una lámpara mágica para ayudarte con tus habilidades.",
    ["Wow, thanks! What if I lose the armour?"] = "¡Vaya, gracias! ¿Qué pasa si pierdo la armadura?",
    ["Oh, that's not a problem. You can come back to see me and I'll get you another set."] = "Oh, eso no es un problema. Puedes volver a verme y te conseguiré otro juego.",
    ["Don't tell me you lost the armour I gave you?"] = "¿No me digas que perdiste la armadura que te di?",
    ["Yes, sorry about that. I don't know what happened to it."] = "Sí, lo siento. No sé qué pasó con eso.",
    ["Oh, well, no harm done. Fortunately, I have another set here - we get quite a lot of Varrock explorers these days, you know."] = "Oh, bueno, no ha pasado nada. Afortunadamente, tengo otro conjunto aquí: tenemos muchos exploradores Varrock en estos días, ¿sabes?",
    ["You need to complete all Tasks within a particular difficulty set, then you can claim your reward. Most of the Varrock set's Tasks are straightforward, though you might find some require quests to be started, if not finished."] = "Debes completar todas las tareas dentro de un conjunto de dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Varrock son sencillas, aunque es posible que algunas requieran que se inicien, si no se terminan.",
    ["To claim your Varrock set reward, speak to Rat Burgiss south of Varrock, Vannaka in Edgeville Dungeon, or me."] = "Para reclamar la recompensa del conjunto Varrock, habla con Rat Burgiss al sur de Varrock, con Vannaka en Edgeville Dungeon o conmigo.",
    ["You're handed another Varrock armour 2."] = "Te entregan otra armadura Varrock 2.",
    ["Varrock armour 4? Yes, but I'm afraid it would cost you 15,00 coins."] = "¿Armadura Varrock 4? Sí, pero me temo que te costaría 15,00 coins.",
    ["Certainly. It's currently set to [the altar in the north of Varrock/the fountain in the middle of Varrock/the Grand Exchange]. Where would you prefer?"] = "Por supuesto. Actualmente está configurado en [the altar in the north of Varrock/the fountain in the middle of Varrock/the Grand Exchange]. ¿Dónde preferirías?",
    ["I have a question about the TzHaar language."] = "Tengo una pregunta sobre el idioma TzHaar.",
    ["Hello, Reldo. Could you remind me where I could find that book on the TzHaar language?"] = "Hola, Reldo. ¿Podrías recordarme dónde puedo encontrar ese libro sobre el idioma TzHaar?",
    ["Of course. It's the TzHaar Tourist Guide. It should be somewhere in the library. I'm not sure exactly where, but if you have a look around, I'm sure you will find it."] = "Por supuesto. Es la Guía Turística de TzHaar. Debería estar en algún lugar de la biblioteca. No estoy seguro de dónde exactamente, pero si echas un vistazo a tu alrededor, estoy seguro de que lo encontrarás.",
    ["Alright, thank you."] = "Muy bien, gracias.",
    ["I'd like to talk about a pyramid."] = "Me gustaría hablar de una pirámide.",
    ["How goes the matter of the mummy's personality?"] = "¿Cómo va el asunto de la personalidad de la momia?",
    ["She is reunited with knowledge of her personality now - so overall a happy ending."] = "Ahora se reencuentra con el conocimiento de su personalidad, por lo que, en general, es un final feliz.",
    ["Excellent, all too rare to see a good end to matters these days."] = "Excelente, es muy raro ver un buen final en estos días.",
    ["Before we get to business, I hear you have access to the Everlight Dig Site. I wonder if you might retrieve a certain artefact from there for me..."] = "Antes de entrar en materia, escuché que tienes acceso al sitio de excavación Everlight. Me pregunto si podrías recuperar cierto artefacto de allí para mí...",
    ["If you would bring me a restored Dominarian device, I have a magical relic I would give you as payment. It might help you, er, 'fund' future endeavours."] = "Si me trajeras un dispositivo Dominariano restaurado, tengo una reliquia mágica que te daría como pago. Podría ayudarle, digamos, a \"financiar\" proyectos futuros.",
    ["Why do you need a Dominarian device."] = "¿Por qué necesitas un dispositivo Dominarian?",
    ["Oh, come now, you know I like to tinker. The idea of some ahead-of-its-time technology from my old stomping grounds is too intriguing a mystery to pass up!"] = "Oh, vamos, sabes que me gusta jugar. ¡La idea de alguna tecnología adelantada a su tiempo procedente de mi antiguo territorio es un misterio demasiado intrigante como para dejarlo pasar!",
    ["As it so happens, I have just that thing on me right now!"] = "Da la casualidad de que ¡tengo justo eso encima ahora mismo!",
    ["Give Dominarian device to Reldo?"] = "¿Darle dispositivo Dominarian a Reldo?",
    ["And in return...this is Andvaranaut. This ring will help mask you from people you are picking the pockets of. That's not really my style."] = "Y a cambio... este es Andvaranaut. Este anillo te ayudará a enmascararte de las personas a las que les estás robando los bolsillos. Ese no es realmente mi estilo.",
    ["One of your own creation, I take? You have a knack for creating rings that manipulate people into parting with their money."] = "¿Uno de tu propia creación, supongo? Tienes una habilidad especial para crear anillos que manipulan a las personas para que se deshagan de su dinero.",
    ["What can I say? My gift is my curse."] = "¿Qué puedo decir? Mi regalo es mi maldición.",
    ["And you say picking pockets isn't your style?"] = "¿Y dices que robar carteras no es tu estilo?",
    ["Of course not! Why go through all the effort of stealing from individuals, when the payoff is so much greater if you just broaden your horizons a little."] = "¡Por supuesto que no! ¿Por qué pasar por todo el esfuerzo de robar a individuos, cuando la recompensa es mucho mayor si simplemente amplías un poco tus horizontes?",
    ["I hope you'll reconsider. I need it for my research."] = "Espero que lo reconsideres. Lo necesito para mi investigación.",
    ["I'll keep you in mind."] = "Te tendré en cuenta.",
    ["[Inside the reliquary are some ancient fragments of bone, and a jewelled cithara. You feel a sense of awe as you approach the instrument, as if a holy power watches over it.]"] = "[Dentro del relicario hay algunos fragmentos antiguos de hueso y una cítara enjoyada. Sientes una sensación de asombro cuando te acercas al instrumento, como si un poder sagrado lo vigilara.]",
    ["Attempt to take the cithara."] = "Intenta tomar la cítara.",
    ["An invisible force gently but firmly moves your hand away from the cithara."] = "Una fuerza invisible aleja suave pero firmemente tu mano de la cítara.",
    ["O holy rapture! That mine eyes, long dead, should even now behold a living saint! Please, pilgrim, take my blessed instrument, and play and sing to Saradomin's praise."] = "¡Oh santo éxtasis! ¡Que mis ojos, muertos hace mucho tiempo, vean ahora a un santo vivo! Por favor, peregrino, toma mi bendito instrumento, toca y canta para alabar a Saradomin.",
    ["[Saint Elspeth allows you to take the cithara.]"] = "[Santa Elspeth te permite llevar la cítara.]",
    ["You are so close to worthy, but fall short. You may return in time, to try again."] = "Estás muy cerca de ser digno, pero te quedas corto. Quizás regreses en el tiempo para volver a intentarlo.",
    ["The spirit prevents you from taking the cithara."] = "El espíritu te impide tomar la cítara.",
    ["Leave the cithara where it is."] = "Deja la cítara donde está.",
    ["Inside the reliquary is nothing but some ancient fragments of bone."] = "Dentro del relicario no hay más que algunos fragmentos de huesos antiguos.",
    ["You look rather out of place..."] = "Te ves bastante fuera de lugar...",
    ["That I may do, but so do you! I suggest you speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance for a lesson. Brugsen will give an interesting lesson on the Grand Exchange and the Tutor will give a smaller, plain lesson."] = "Eso puedo hacerlo yo, ¡pero tú también! Te sugiero que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada para recibir una lección. Brugsen dará una lección interesante sobre Grand Exchange y el Tutor dará una lección más breve y sencilla.",
    ["Not so fast! I suggest you speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance for a lesson. Brugsen will give an interesting lesson on the Grand Exchange and the Tutor will give a smaller, plain lesson."] = "¡No tan rápido! Te sugiero que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada para recibir una lección. Brugsen dará una lección interesante sobre Grand Exchange y el Tutor dará una lección más breve y sencilla.",
    ["Hey there."] = "Hola.",
    ["Why, hell to you too, my friend."] = "Vaya, al diablo contigo también, amigo mío.",
    ["You look like you've travelled a fair distance."] = "Parece que has viajado una distancia considerable.",
    ["What gave me away?"] = "¿Qué me delató?",
    ["I don't mean to be rude, but the face paint and hair, for starters."] = "No quiero ser grosero, pero the face pinta y peina, para empezar.",
    ["Ah, yes. I'm from Shilo Village on Karamja, it's a style I've had since I was little."] = "Ah, sí. Soy de Shilo Village en Karamja, es un estilo que tengo desde pequeña.",
    ["Then tell me, why are you so far from home?"] = "Entonces dime, ¿por qué estás tan lejos de casa?",
    ["This Grand Exchange! Isn't it marvellous! I've never seen anything like it in my life. My people were not pleased to see me break traditions to visit such a place, but I hope to make some serious profit. Then they'll see I was right!"] = "¡Este Grand Exchange! ¿No es maravilloso? Nunca he visto nada parecido en mi vida. A mi gente no le agradó verme romper las tradiciones para visitar un lugar así, pero espero obtener importantes beneficios. ¡Entonces verán que tenía razón!",
    ["So, what are you selling?"] = "Entonces, ¿qué estás vendiendo?",
    ["Logs! Of all kinds! That's my plan, at least. Nature is one thing my people understand very well."] = "Logs! ¡De todo tipo! Ese es mi plan, al menos. La naturaleza es algo que mi gente entiende muy bien.",
    ["I'm trying to find the prices for logs."] = "Estoy intentando encontrar los precios de logs.",
    ["Then you've come to the right person."] = "Entonces has llegado a la persona adecuada.",
    ["Sorry, I need to make tracks."] = "Lo siento, necesito hacer pistas.",
    ["Okay, nice talking to you!"] = "¡Está bien, un placer hablar contigo!",
    ["Hello. I am Relomia, the emissary of Sliske, here to teach everyone about him. If you wish to declare support for Sliske, I may have some work for you."] = "Hola. Soy Relomia, la emisaria de Sliske, aquí para enseñarles a todos sobre él. Si desea declarar su apoyo a Sliske, es posible que tenga algo de trabajo para usted.",
    ["*Who are you?*"] = "*¿Quién eres?*",
    ["I was... am Relomia. I was a humble maid, working in Ardougne, long ago, until I was lost in the shadow realm. There was no great event or magic that I could see. I simply turned a corner one day...and was lost. It was there that I first saw Sliske, the master of shadows. He would weave in and out at will - such skill he has! When I was released from the shadow, I knew it was up to me to spread the word, and to gather those who would listen to our side. I am the emissary of Sliske! If you wish to declare support for Sliske, I may have some work for you."] = "Yo era... soy Relomia. Yo era una humilde sirvienta que trabajaba en Ardougne hace mucho tiempo, hasta que me perdí en el reino de las sombras. No hubo ningún gran evento o magia que pudiera ver. Simplemente un día doblé una esquina... y me perdí. Fue allí donde vi por primera vez a Sliske, el maestro de las sombras. Él entraba y salía a voluntad: ¡qué habilidad tiene! Cuando fui liberado de la sombra, supe que dependía de mí correr la voz y reunir a aquellos que escucharan nuestro lado. ¡Soy el emisario de Sliske! Si desea declarar su apoyo a Sliske, es posible que tenga algo de trabajo para usted.",
    ["How were you released?"] = "¿Cómo te liberaron?",
    ["I don't know. I was trapped there for a long time - staring only at shades and patterns in the gloom. Eventually, I saw things...things that I'm not certain I'll ever be able to understand. All I know is that the one who brought me there was named Sliske; that he is lord of shadow and secrets and lost things; and that it was only because he willed it that I returned."] = "No lo sé. Estuve atrapado allí durante mucho tiempo, mirando sólo sombras y patrones en la penumbra. Con el tiempo, vi cosas... cosas que no estoy seguro de poder entender alguna vez. Lo único que sé es que quien me trajo allí se llamaba Sliske; que es señor de la sombra y de los secretos y de las cosas perdidas; y que fue sólo porque él lo quiso que regresé.",
    ["*Can you tell me about Sliske?*"] = "*¿Puedes contarme sobre Sliske?*",
    ["Can you tell me about Sliske?"] = "¿Puedes hablarme de Sliske?",
    ["What do you want to know about Sliske?"] = "¿Qué quieres saber sobre Sliske?",
    ["*Who is Sliske?*"] = "*¿Quién es Sliske?*",
    ["Who is Sliske?"] = "¿Quién es Sliske?",
    ["Sliske is the youngest of the gods; only recently has he achieved the power. Before that, he was a Mahjarrat, serving Zaros. He is the god of shadows and darkness; devious, mysterious and dangerous."] = "Sliske es el más joven de los dioses; sólo recientemente ha alcanzado el poder. Antes de eso, fue un Mahjarrat, al servicio de Zaros. Él es el dios de las sombras y las tinieblas; tortuoso, misterioso y peligroso.",
    ["*Why should I follow Sliske?*"] = "*¿Por qué debería seguir a Sliske?*",
    ["Why should I follow Sliske?"] = "¿Por qué debería seguir a Sliske?",
    ["Sliske is the god of the future. He may be new to his power, but I am sure that he will be the centre of much to come! In these dark times, when shadows lie over the world, then Sliske will know the way."] = "Sliske es el dios del futuro. Puede que sea nuevo en su poder, ¡pero estoy seguro de que será el centro de mucho de lo que vendrá! En estos tiempos oscuros, cuando las sombras cubren el mundo, entonces Sliske sabrá el camino.",
    ["*What does Sliske want?*"] = "*¿Qué quiere Sliske?*",
    ["What does Sliske want?"] = "¿Qué quiere Sliske?",
    ["Only Sliske himself knows for certain. What I do know is that he sees all - he sees the truth that lies beneath the world's veneer...and he laughs. A war is coming, and when it begins I will stand alongside Sliske at the very heart of the storm."] = "Solo el propio Sliske lo sabe con certeza. Lo que sí sé es que él lo ve todo: ve la verdad que se esconde bajo el barniz del mundo... y se ríe. Se avecina una guerra y, cuando comience, estaré junto a Sliske en el corazón mismo de la tormenta.",
    ["*Is Sliske really a god?*"] = "*¿Sliske es realmente un dios?*",
    ["Is Sliske really a god?"] = "¿Es Sliske realmente un dios?",
    ["Of course he is! He's powerful - he defeated Guthix! Like Zamorak, he must have reached godhood. Although I have to confess... I have no proof of his godliness."] = "¡Por supuesto que lo es! Es poderoso: ¡derrotó a Guthix! Al igual que Zamorak, debe haber alcanzado la divinidad. Aunque tengo que confesar... no tengo pruebas de su piedad.",
    ["*I want to declare my support for Sliske!*"] = "*¡Quiero declarar mi apoyo a Sliske!*",
    ["That's wonderful! On behalf of Sliske's followers, I welcome you. Please, take this banner to show your support. I have a gift for you: a book of stories regarding the gods and their followers. Please, read it and learn wisdom. It will show you that even the gods walk in darkness, and that only Sliske knows the way. The book is not yet complete, however. When you complete some jobs I will give you more pages."] = "¡Eso es maravilloso! En nombre de los seguidores de Sliske, les doy la bienvenida. Por favor, lleve este banner para mostrar su apoyo. Tengo un regalo para ti: un libro de historias sobre los dioses y sus seguidores. Por favor, léelo y aprende sabiduría. Te mostrará que incluso los dioses caminan en la oscuridad y que sólo Sliske conoce el camino. Sin embargo, el libro aún no está completo. Cuando completes algunos trabajos te daré más páginas.",
    ["Category:God Emissaries"] = "Categoría:God Emissaries",
    ["Well done, well done. Not many find their way in here."] = "Bien hecho, bien hecho. No muchos encuentran su camino aquí.",
    ["I'm Remsai, a tree gnome. We live in this maze for our protection. Have a look around and enjoy."] = "Soy Remsai, un gnomo de árbol. Vivimos en este laberinto para nuestra protección. Echa un vistazo y disfruta.",
    ["Hi there traveller. You're a legend around these parts."] = "Hola viajero. Eres una leyenda por estos lares.",
    ["Thanks Remsai."] = "Gracias Remsai.",
    ["*(One of the following is shown every 30 seconds:)*"] = "*(Se muestra uno de los siguientes cada 30 segundos:)*",
    ["Oh hello there! Exciting times are approaching... or possibly approached."] = "¡Hola! Se acercan tiempos emocionantes... o posiblemente se acercan.",
    ["The museum has finally obtained the funding to start digging into the history of Gielinor. Quite literally."] = "El museo finalmente obtuvo la financiación para comenzar a profundizar en la historia de Gielinor. Literalmente.",
    ["Soon the guild will be opening at the Varrock Dig Site and the door to the past will be flung wide open!"] = "¡Pronto el gremio se abrirá en el sitio de excavación Varrock y la puerta al pasado se abrirá de par en par!",
    ["You should give it a look yourself. An accomplished adventurer like you, why I bet you'll be a natural!"] = "Deberías echarle un vistazo tú mismo. Un aventurero consumado como tú, ¡apuesto a que serás natural!",
    ["You'll need quite the skill to dig deep into the earth and uncover the ancient secrets."] = "Necesitarás bastante habilidad para cavar profundamente en la tierra y descubrir los secretos antiguos.",
    ["And I bet there'll be plenty of strange and wonderful discoveries you could make to enhance your adventuring!"] = "¡Y apuesto a que habrá muchos descubrimientos extraños y maravillosos que podrías hacer para mejorar tus aventuras!",
    ["Give it a look, the Archaeology Guild will be coming to the Varrock Dig Site soon!"] = "Échale un vistazo, ¡el gremio Archaeology llegará pronto al sitio de excavación Varrock!",
    ["Hello there. What are you doing here?"] = "Hola. ¿Qué estás haciendo aquí?",
    ["Just looking around at the moment."] = "Solo estoy mirando a mi alrededor en este momento.",
    ["Well, feel free to talk to me should you come across anything you can't figure out."] = "Bueno, no dudes en hablar conmigo si encuentras algo que no puedas resolver.",
    ["Hello there! I heard all about your big find; well done!"] = "¡Hola! Escuché todo sobre tu gran hallazgo; ¡bien hecho!",
    ["Can you tell me more about the tools an archaeologist uses?"] = "¿Puedes contarme más sobre las herramientas que utiliza un arqueólogo?",
    ["Of course! Let's see now..."] = "¡Por supuesto! Veamos ahora...",
    ["Trowels are vital for fine digging work, so you can be careful to not damage or disturb any artefacts."] = "Las paletas son vitales para los trabajos de excavación finos, por lo que debes tener cuidado de no dañar ni alterar ningún artefacto.",
    ["Rock picks are for splitting rocks or scraping away soil."] = "Los picos de rocas sirven para partir rocas o raspar la tierra.",
    ["What about specimen jars and brushes?"] = "¿Qué pasa con los cepillos y los frascos de muestras?",
    ["Those are essential for carefully cleaning and storing smaller samples."] = "Son esenciales para limpiar y almacenar cuidadosamente muestras más pequeñas.",
    ["Where can I get any of these things?"] = "¿Dónde puedo conseguir cualquiera de estas cosas?",
    ["Well, we've come into a bit more funding of late, so there should be a stock of each of them in the Exam Centre's tools cupboard."] = "Bueno, últimamente hemos recibido un poco más de financiación, por lo que debería haber un stock de cada uno de ellos en el armario de herramientas del Centro de exámenes.",
    ["We also hand out relevant tools as students complete each level of their Earth Sciences exams."] = "También entregamos herramientas relevantes a medida que los estudiantes completan cada nivel de sus exámenes de Ciencias de la Tierra.",
    ["Anything else?"] = "¿Algo más?",
    ["If you need something identified or are not sure about something, give it to Terry. He's the archaeological expert in the next room."] = "Si necesita identificar algo o no está seguro de algo, dáselo a Terry. Él es el experto en arqueología en la habitación de al lado.",
    ["Ah, okay, thanks."] = "Ah, está bien, gracias.",
    ["Thank you!"] = "¡Gracias!",
    ["Hello, ghost, how are you?"] = "Hola fantasma, ¿cómo estás?",
    ["Wooo wooo wooooo!"] = "¡Guau, guau, guau!",
    ["Sorry, I don't speak ghost."] = "Lo siento, no hablo fantasmas.",
    ["Woo woo?"] = "¿Guau, guau?",
    ["Nope, still don't understand you."] = "No, todavía no te entiendo.",
    ["Woooooo!"] = "¡Guauoooo!",
    ["Never mind."] = "No importa.",
    ["Ooh, that's interesting."] = "Oh, eso es interesante.",
    ["Wooo wooo. Woooooooooooooooooo!"] = "Guau, guau. ¡Woooooooooooooooo!",
    ["Did he really?"] = "¿Lo hizo realmente?",
    ["My brother had exactly the same problem."] = "Mi hermano tuvo exactamente el mismo problema.",
    ["Woo wooooo!"] = "¡Guau, guau!",
    ["Wooooo woo woo woo!"] = "¡Guau, guau, guau, guau!",
    ["Goodbye. Thanks for the chat."] = "Adiós. Gracias por la charla.",
    ["Wooo wooo."] = "Guau, guau.",
    ["You'll have to give me the recipe some time."] = "Tendrás que darme la receta en algún momento.",
    ["Wooooooo woo woooooooo."] = "Woooooo woooooooo.",
    ["Hmm, I'm not sure about that."] = "Mmm, no estoy seguro de eso.",
    ["Wooo woo?"] = "¿Guau, guau?",
    ["Well, if you insist."] = "Bueno, si insistes.",
    ["Wooooooooo!"] = "¡Guauoooooo!",
    ["Ah, well, better be off now."] = "Ah, bueno, será mejor que nos vayamos ahora.",
    ["Bye."] = "Adiós.",
    ["Yeah, that's what I thought."] = "Sí, eso es lo que pensé.",
    ["Wooo woooooooooooooo…"] = "Wooooooooooooooo…",
    ["Any hints as to where I can find some treasure?"] = "¿Alguna pista sobre dónde puedo encontrar algún tesoro?",
    ["Wooooooo woo! Wooooo woo wooooo woowoowoo woo <center>Woo</center> wooo. Wooooo woo woo? Woooooooooooooooooo!"] = "¡Guauuuuuuuuu! Wooooo woooooo woowoowoo woo <center>Woo</center> wooo. ¿Guauuuuuuuuu? ¡Woooooooooooooooo!",
    ["Thank you. You've been very helpful."] = "Gracias. Has sido de mucha ayuda.",
    ["Wooooooo."] = "Woooooo.",
    ["I don't suppose ye know a guy called 'Malignius'?"] = "¿Supongo que no conoces a un tipo llamado 'Malignius'?",
    ["Malignius? He's the one helping me with my necromancer studies."] = "¿Maligno? Él es quien me ayuda con mis estudios de nigromante.",
    ["That would explain what he's doing here."] = "Eso explicaría lo que está haciendo aquí.",
    ["He came up to have a look around the garden, so I offered him some of our freshly-grown salad."] = "Vino a echar un vistazo al jardín, así que le ofrecí un poco de nuestra ensalada recién cultivada.",
    ["Poor fella was just about to have a bite, but as soon as I mentioned it had morchella mushrooms in it, he ran off!"] = "El pobre tipo estaba a punto de comer algo, pero tan pronto como mencioné que tenía hongos morchella, ¡se escapó!",
    ["Ah, well, he does have a deadly mushroom allergy."] = "Ah, bueno, tiene una alergia mortal a los hongos.",
    ["He does seem to have a strange obsession with them, though, so I'm surprised he ran off."] = "Sin embargo, parece tener una extraña obsesión con ellos, así que me sorprende que se haya escapado.",
    ["Keep yer enemies close, but not too close, I guess!"] = "¡Mantén a tus enemigos cerca, pero no demasiado, supongo!",
    ["Oi! Haven't you heard of knocking?"] = "¡Oye! ¿No has oído hablar de tocar la puerta?",
    ["Sorry, I thought your shop was open."] = "Lo siento, pensé que tu tienda estaba abierta.",
    ["A new face? Don't see many of those round these parts."] = "¿Una cara nueva? No veo muchos de esos por estos lares.",
    ["I should be the one apologising. Shouldn't 'ave shouted at you like that. Just got a lot going on, you know?"] = "Debería ser yo quien se disculpe. No debería haberte gritado así. Están pasando muchas cosas, ¿sabes?",
    ["What's the matter?"] = "¿Qué pasa?",
    ["It's my kid, Tali."] = "Es mi hijo, Tali.",
    ["She went wandering off yesterday. Never came home. I'm worried something fierce."] = "Ella se fue ayer. Nunca volví a casa. Me preocupa algo feroz.",
    ["She's a good kid. Got her 'ead screwed on right, and she's nearly fully grown. Doesn't feel right reprimanding her for wanting some independence."] = "Es una buena niña. Tiene la cabeza bien atornillada y casi ha crecido por completo. No se siente bien reprenderla por querer algo de independencia.",
    ["But she shouldn't be camping out in the Highweald forest on her own. It's not safe."] = "Pero no debería acampar sola en el bosque de Highweald. No es seguro.",
    ["Why haven't you gone looking for her?"] = "¿Por qué no has ido a buscarla?",
    ["It's a difficult time for us. Have a feeling I'm the last person she'd want to see right now."] = "Es un momento difícil para nosotros. Tengo la sensación de que soy la última persona a la que querría ver en este momento.",
    ["Last time she went hiking through the Highweald alone Adam practically chewed her ear off. Don't need 'im getting involved again either."] = "La última vez que fue de excursión sola por Highweald, Adam prácticamente le arrancó la oreja de un mordisco. Tampoco es necesario que vuelva a involucrarse.",
    ["She said she was going to explore the ruined watchtower by the passage into the mountains. If you're 'eaded that way, would you mind keeping an eye out?"] = "Ella dijo que iba a explorar la torre de vigilancia en ruinas junto al pasaje hacia las montañas. Si te dirigen en esa dirección, ¿te importaría estar atento?",
    ["I'll let you know if I find her."] = "Te avisaré si la encuentro.",
    ["Thanks, mate. Appreciate it."] = "Gracias, amigo. Se lo agradezco.",
    ["Have you found Tali? I can't rest easy knowing she's still out there."] = "¿Has encontrado Tali? No puedo estar tranquilo sabiendo que ella todavía está ahí afuera.",
    ["What were you doing out there? Are you hurt? Why didn't you come home?"] = "¿Qué estabas haciendo ahí fuera? ¿Estás herido? ¿Por qué no volviste a casa?",
    ["I'm-"] = "Yo-",
    ["I'm sorry, papa. I only wanted to go somewhere I could remember the good times. Away from all of this...misery. But I lost my equipment, and..."] = "Lo siento, papá. Sólo quería ir a algún lugar donde pudiera recordar los buenos tiempos. Lejos de todo esto... miseria. Pero perdí mi equipo y...",
    ["I understand. I do. But it's not safe wandering around the forest on your own. Even Adam wouldn't-"] = "Lo entiendo. Sí. Pero no es seguro deambular solo por el bosque. Incluso Adam no lo haría-",
    ["I know!"] = "¡Lo sé!",
    ["I know..."] = "Lo sé...",
    ["Listen. I can't force you to stay here. If you want to explore the ruins out east or wherever 'ave you, it's not my place to stop you."] = "Escucha. No puedo obligarte a quedarte aquí. Si quieres explorar las ruinas del este o donde sea que estés, no me corresponde a mí detenerte.",
    ["This is my home, and you're my family. I'd never want to leave for good."] = "Este es mi hogar y ustedes son mi familia. Nunca quisiera irme para siempre.",
    ["But it would be wonderful to see the archaeology guild again. To follow in father's footsteps and go on on proper expeditions!"] = "Pero sería maravilloso volver a ver el gremio de arqueología. ¡Seguir los pasos de mi padre y realizar expediciones adecuadas!",
    ["You're welcome to join me some time, if you'd like."] = "Puedes unirte a mí en algún momento, si quieres.",
    ["I'd love to!"] = "¡Me encantaría!",
    ["Just take care of yourself, alright? I couldn't bear to lose you too."] = "Solo cuídate, ¿de acuerdo? No podría soportar perderte a ti también.",
    ["I will. I promise."] = "Lo haré. Prometo.",
    ["Thank you for all your help, friend. If you need any hides tanned, come see me, you 'ear? It's on the house."] = "Gracias por toda tu ayuda, amigo. Si necesitas curtir pieles, ven a verme, ¿entiendes? Va por cuenta de la casa.",
    ["Hey there, mate. If you need hides tanned, I'm your man."] = "Hola, amigo. Si necesitas pieles curtidas, soy tu hombre.",
    ["I made Zeke's armour, you know. My finest work, if I do say so myself."] = "Yo hice la armadura de Zeke, ¿sabes? Mi mejor trabajo, si lo digo yo mismo.",
    ["I'll think about it."] = "Lo pensaré.",
    ["Good to see you again [player]."] = "Me alegro de verte de nuevo [player].",
    ["You too. I'm not intruding, am I?"] = "Tú también. No estoy entrometiendo, ¿verdad?",
    ["You're good. I was just about to share a tale my grandfather used to tell me about this 'ere tower. You can stay and listen, if you'd like."] = "Eres bueno. Estaba a punto de compartir una historia que mi abuelo solía contarme sobre esta torre. Puedes quedarte y escuchar, si quieres.",
    ["I'm all ears."] = "Soy todo oídos.",
    ["Your grandfather told you stories about this place?"] = "¿Tu abuelo te contó historias sobre este lugar?",
    ["He went on a journey across Havenhythe, when he came of age. Said our ancestors found this tower when they arrived and repurposed it for their needs."] = "Se fue de viaje a través de Havenhythe cuando alcanzó la mayoría de edad. Dijeron que nuestros antepasados ​​encontraron esta torre cuando llegaron y la reutilizaron para sus necesidades.",
    ["It started as a watchtower but became a place of worship. Those who followed the God of Order gathered 'ere all hush hush."] = "Comenzó como una torre de vigilancia pero se convirtió en un lugar de culto. Aquellos que siguieron al Dios del Orden se reunieron aquí en silencio.",
    ["That explains all the stars of Saradomin."] = "Eso explica todas las estrellas de Saradomin.",
    ["People started gossiping about the rites they performed here. Suspicion let to fear. Followers of a rival god came in the dead of night and set the tower ablaze."] = "La gente empezó a chismorrear sobre los ritos que realizaban aquí. La sospecha deja paso al miedo. Los seguidores de un dios rival llegaron en plena noche y prendieron fuego a la torre.",
    ["History doesn't repeat, but it often rhymes."] = "La historia no se repite, pero a menudo rima.",
    ["We've always been a small community. That sort of division would 'ave been the end of us."] = "Siempre hemos sido una comunidad pequeña. Ese tipo de división habría sido nuestro fin.",
    ["They tore down every shrine, but one. A small altar on the outskirts of town. One where all gods and their followers would have equal standing."] = "Derribaron todos los santuarios, menos uno. Un pequeño altar a las afueras del pueblo. Uno en el que todos los dioses y sus seguidores tuvieran la misma posición.",
    ["Still stands today, at the shrine to Inanna."] = "Sigue en pie hoy, en el santuario de Inanna.",
    ["Did your grandfather tell you a lot of stories about the history of Havenhythe?"] = "¿Tu abuelo te contó muchas historias sobre la historia de Havenhythe?",
    ["Oh, he had a tale for just about everything!"] = "¡Oh, tenía una historia para casi todo!",
    ["Not unlike your father."] = "No muy diferente a tu padre.",
    ["I miss him. I miss him so much."] = "Lo extraño. Lo extraño mucho.",
    ["Yeah, I do too."] = "Sí, yo también.",
    ["Thank you for the story. Take care, both of you."] = "Gracias por la historia. Cuídense los dos.",
    ["Hi."] = "Hola.",
    ["Greetings. What wisdom do you seek?"] = "Saludos. ¿Qué sabiduría buscas?",
    ["Me? I'm here to grant you rewards for any of the Pizazz Points you may have earned in this training arena. Like my fellow guardians I am part of the arena and live to ensure its safe running."] = "¿Yo? Estoy aquí para otorgarte recompensas por cualquiera de los puntos Pizazz que hayas obtenido en este campo de entrenamiento. Al igual que mis compañeros guardianes, soy parte de la arena y vivo para garantizar su funcionamiento seguro.",
    ["I see."] = "Ya veo.",
    ["Can I trade my Pizazz Points, please?"] = "¿Puedo canjear mis puntos Pizazz, por favor?",
    ["Why, of course."] = "Por qué, por supuesto.",
    ["Sorry, you must be carrying a Pizazz Progress Hat so I can check what points you have. If you haven't got one, talk to my fellow guardian downstairs."] = "Lo siento, debes llevar un sombrero de progreso Pizazz para que pueda comprobar qué puntos tienes. Si no tienes uno, habla con mi compañero guardián de abajo.",
    ["Got anything else I can buy?"] = "¿Tienes algo más que pueda comprar?",
    ["Well, we do stock a special book that you may be interested in, which provides a comprehensive guide to this training arena. It costs 200gp; would you like one?"] = "Bueno, tenemos un libro especial que puede interesarle y que proporciona una guía completa sobre este campo de capacitación. Cuesta 200 po; ¿te gustaría uno?",
    ["No thanks, I already have one."] = "No gracias, ya tengo uno.",
    ["Let me know if you lose it."] = "Avísame si lo pierdes.",
    ["That sounds useful. Yes please."] = "Eso suena útil. Sí, por favor.",
    ["Very good, that'll be 200gp please."] = "Muy bien, serán 200 po, por favor.",
    ["Sorry, I don't have enough money."] = "Lo siento, no tengo suficiente dinero.",
    ["Thank you."] = "Gracias.",
    ["I don't want some dusty old book."] = "No quiero un libro viejo y polvoriento.",
    ["It's not old and it certainly isn't dusty, but suit yourself."] = "No es viejo y ciertamente no tiene polvo, pero haz lo que quieras.",
    ["Thanks, bye!"] = "¡Gracias, adiós!",
    ["Use what you've learned, young one."] = "Usa lo que has aprendido, joven.",
    ["If you've worked hard towards your cause, perhaps you'd be interested in some rewards?"] = "Si has trabajado duro por tu causa, ¿tal vez te interesarían algunas recompensas?",
    ["Show me the rewards, please."] = "Muéstrame las recompensas, por favor.",
    ["Tell me about the rewards."] = "Cuéntame sobre las recompensas.",
    ["By helping your team gather sacred clay, you earn points that you can spend on rewards here. There are two types of reward: tools and equipment. All the rewards are made from the same sacred clay that your team works so hard to harvest, which gives them some rather special properties."] = "Al ayudar a tu equipo a recolectar arcilla sagrada, ganas puntos que puedes gastar en recompensas aquí. Hay dos tipos de recompensa: herramientas y equipos. Todas las recompensas están hechas de la misma arcilla sagrada que tu equipo trabaja tan duro para cosechar, lo que les confiere algunas propiedades bastante especiales.",
    ["Tell me more about tool rewards."] = "Cuéntame más sobre las recompensas de herramientas.",
    ["These hallowed tools are made from sacred clay, and can be transformed into a pickaxe, woodcutting hatchet, harpoon, butterfly net, fletching knife, hammer or needle. The morphic tool allows you to decide which tool it will transform into. As you use the tool, you'll get extra experience in that skill. The volatile tool is made of more powerful clay, but is more unstable, so although you get more bonus experience, you have no control over which tool it becomes. Eventually, either type of tool will run out of sacred power and stop working. You can always come back here and buy more charges for it with points from the primordial realm."] = "Estas herramientas sagradas están hechas de arcilla sagrada y se pueden transformar en un pico, un hacha de cortar madera, un arpón, un cazamariposas, un cuchillo para emplumar, un martillo o una aguja. La herramienta mórfica le permite decidir en qué herramienta se transformará. A medida que utilices la herramienta, obtendrás experiencia adicional en esa habilidad. La herramienta volátil está hecha de arcilla más poderosa, pero es más inestable, por lo que aunque obtienes más experiencia adicional, no tienes control sobre en qué herramienta se convierte. Con el tiempo, cualquier tipo de herramienta se quedará sin poder sagrado y dejará de funcionar. Siempre puedes volver aquí y comprar más cargos con puntos del reino primordial.",
    ["Tell me more about equipment rewards."] = "Cuéntame más sobre las recompensas de equipo.",
    ["Ah, now these rewards truly reveal the power of the sacred clay. The morphic armour and weapon can adapt to your fighting style. When you operate a piece of the morphic armour and choose a new combat style, all currently equipped morphic armour and weapons will change to that style of combat. While you are using the equipment, you will gain extra experience in whichever combat skills you are training. Eventually, the armour will run out of sacred energy, but you can always come back and earn more charges for it."] = "Ah, ahora estas recompensas realmente revelan el poder de la arcilla sagrada. La armadura y el arma mórficas pueden adaptarse a tu estilo de lucha. Cuando operas una pieza de la armadura mórfica y eliges un nuevo estilo de combate, todas las armaduras y armas mórficas actualmente equipadas cambiarán a ese estilo de combate. Mientras usas el equipo, obtendrás experiencia adicional en cualquier habilidad de combate que estés entrenando. Con el tiempo, la armadura se quedará sin energía sagrada, pero siempre podrás regresar y ganar más cargas por ella.",
    ["Thanks."] = "Gracias.",
    ["Welcome to the lovely Sunlight Sands!"] = "¡Bienvenido a la hermosa Sunlight Sands!",
    ["Thank you! It's very hot here."] = "¡Gracias! Hace mucho calor aquí.",
    ["Of course, we're in the Land of Sunlight, what else could you expect?"] = "Por supuesto, estamos en la Tierra de la Luz del Sol, ¿qué más se puede esperar?",
    ["What's the giant creature in the crater?"] = "¿Cuál es la criatura gigante en el cráter?",
    ["Oh, that's Clawdia!"] = "¡Oh, ese es Clawdia!",
    ["We have a bit of history with her us at the beach in Lumbridge crater."] = "Tenemos un poco de historia con ella en la playa del cráter Lumbridge.",
    ["Turns out, this is where she lives, so now we are paying her a visit."] = "Resulta que aquí es donde vive, así que ahora le haremos una visita.",
    ["What can I do on the beach?"] = "¿Qué puedo hacer en la playa?",
    ["There are many skilling opportunities, try building a sandcastle, do a spot of cooking or fishing, gather some coconuts or hook some ducks."] = "Hay muchas oportunidades para desarrollar habilidades, intenta construir un castillo de arena, cocinar o pescar, recoger algunos cocos o enganchar algunos patos.",
    ["Clawdia like to pop out of the pool in the centre of the island at 45 minutes past every hour. She brings the rain with her and causes a bit of chaos."] = "A Clawdia le gusta salir de la piscina en el centro de la isla cada hora 45 minutos después. Trae la lluvia consigo y provoca un poco de caos.",
    ["When that happens a bit of a brawl ensues, but she calms down quickly after and the rain disappears."] = "Cuando eso sucede, se produce una pequeña pelea, pero ella se calma rápidamente y la lluvia desaparece.",
    ["Are there any rewards I can earn while on the beach?"] = "¿Hay alguna recompensa que pueda ganar mientras estoy en la playa?",
    ["Oh yes! Lots of rewards to be earned! Why, just by skilling on the beach you'll get Sandy sand which you can exchange for some fabulous summer items in Gill and Sheldon's shops."] = "¡Oh, sí! ¡Muchas recompensas por ganar! Vaya, con solo practicar en la playa obtendrás arena Sandy que podrás cambiar por fabulosos artículos de verano en las tiendas de Gill y Sheldon.",
    ["There are also various titles you can earn by completing tasks."] = "También hay varios títulos que puedes ganar completando tareas.",
    ["What titles can I unlock?"] = "¿Qué títulos puedo desbloquear?",
    ["Something else."] = "Algo más.",
    ["the Beachbum"] = "el vagabundo de la playa",
    ["Successfully hit 5 coconuts in a row on the coconut shy."] = "Golpea con éxito 5 cocos seguidos en el coco tímido.",
    ["Beachcomber"] = "vagabundo",
    ["Play the coconut shy - Take part in the strongman activity - Catch a tropical trout - Prepare some food at the cooking station - Harvest and drop off a coconut - Help build a sandcastle"] = "Juega al tímido coco - Participa en la actividad del hombre fuerte - Atrapa una trucha tropical - Prepara algo de comida en la estación de cocina - Cosecha y deja un coco - Ayuda a construir un castillo de arena",
    ["the Bronzed"] = "el bronceado",
    ["Obtain from Sheldon's Store."] = "Consíguelo en la tienda de Sheldon.",
    ["the Chilled"] = "el enfriado",
    ["Eat 10 ice creams."] = "Come 10 helados.",
    ["the Lifeguard"] = "el Lifeguard",
    ["Kill Clawdia 15 times."] = "Mata a Clawdia 15 veces.",
    ["the Quackers"] = "los charlatanes",
    ["Catch 250 ducks on the hook-a-duck game."] = "Atrapa 250 patos en el juego del gancho del pato.",
    ["the Totally Quackers"] = "los totalmente charlatanes",
    ["Catch 1000 ducks on the hook-a-duck game."] = "Atrapa 1000 patos en el juego del gancho del pato.",
    ["the Sunburned"] = "el quemado por el sol",
    ["the Beachy Keen"] = "el entusiasta playero",
    ["Successfully catch 5 ducks in a row on the hook-a-duck game."] = "Atrapa con éxito 5 patos seguidos en el juego de enganchar un pato.",
    ["the Feathered"] = "el emplumado",
    ["Catch 100 ducks on the hook-a-duck game."] = "Atrapa 100 patos en el juego del gancho del pato.",
    ["the Sunkissed"] = "el besado por el sol",
    ["Find and listen to a large shell 10 times."] = "Encuentra y escucha una concha grande 10 veces.",
    ["the Sun-sational"] = "el sol-sacional",
    ["Play hook-a-duck"] = "Jugar al gancho del pato",
    ["King/Queen of the Sandcastle"] = "Rey/Reina del Castillo de Arena",
    ["Unlock the following titles: - The Beachbum - the Bronzed - Beachcomber - the Chilled - the Lifeguard - the Quackers - the Sunburned"] = "Desbloquea los siguientes títulos: - The Beachbum - the Bronzed - Beachcomber - the Chilled - the Lifeguard - the Quackers - the Sunburned",
    ["Emperor/Empress of the Sandcastle"] = "Emperador/Emperatriz del Castillo de Arena",
    ["the Beachy Keen - the Feathered - the Sunkissed - the Sun-sational"] = "el Beachy Keen - el Feathered - el Sunkissed - el Sun-sational",
    ["the Completesunist"] = "el unista completo",
    ["Unlock the Deckchair resting animation by resting in a red, green and blue deckchair 10 times each - Unlock the rainbow kite by talking to Reyna, Nigel, Palmer, Sarah and Wellington - Unlock the Beach Towel cape override by resting on the beach 10 times with a beach rest animation active - Unlock the Beach Swimming outfit from Sheldon's Store. - Unlock the Beach Summer Fun outfit from Sheldon's Store."] = "Desbloquea la animación de descanso de la tumbona descansando en una tumbona roja, verde y azul 10 veces cada una - Desbloquea la cometa arcoíris hablando con Reyna, Nigel, Palmer, Sarah y Wellington - Desbloquea la capa de toalla de playa descansando en la playa 10 veces con una animación de descanso en la playa activa - Desbloquea el traje de natación de playa de la tienda de Sheldon. - Desbloquear el conjunto Beach Summer Fun de Sheldon's Store.",
    ["Oh it's a scorcher! The temperature scale is so hot it's stopped working so you can carry on with your beach activities regardless of the current heat!"] = "¡Oh, es abrasador! ¡La escala de temperatura está tan alta que dejó de funcionar para que puedas continuar con tus actividades en la playa independientemente del calor actual!",
    ["Quite the beast isn't she? I believe that we may have had a hand in her being here."] = "Bastante the beast, ¿no? Creo que es posible que hayamos contribuido a que ella estuviera aquí.",
    ["In what way?"] = "¿De qué manera?",
    ["There was an adorable little creature in one of the buckets of sand that was handed in for the beach, little dot of a thing."] = "Había una criaturita adorable en uno de los cubos de arena que se entregaron para la playa, un pequeño punto.",
    ["It looks like she grew up!"] = "¡Parece que creció!",
    ["I have sent word to the wizards at the Wizards' Tower and they believe that the little tyke is the land retaliating for the battles in the area. That Gielinor is, well, unhappy, and has used the Anima Mundi to create a defender."] = "He avisado a los magos de Wizards' Tower y creen que el pequeño es la tierra que toma represalias por las batallas en la zona. Ese Gielinor está, bueno, descontento y ha utilizado Anima Mundi para crear un defensor.",
    ["I'm not sure if I believe that though, the wizards are reluctant to come and see her for themselves. But it is hard to deny that the little thing has grown rather large."] = "No estoy seguro de creerlo, pero los magos se muestran reacios a venir a verla por sí mismos. Pero es difícil negar que la pequeña cosa se ha vuelto bastante grande.",
    ["I just wish she didn't bring the rain with her."] = "Ojalá no hubiera traído la lluvia con ella.",
    ["There are lots of lovely activities and shops. What would you like to know about?"] = "Hay muchas actividades y tiendas encantadoras. ¿Qué te gustaría saber sobre?",
    ["Skilling activities."] = "Actividades de capacitación.",
    ["There are many skilling opportunities, try building a sandcastle, do a spot of cooking or fishing, gather some coconuts or try to knock down the odd coconut."] = "Hay muchas oportunidades para desarrollar habilidades, intenta construir un castillo de arena, cocinar o pescar, recoger algunos cocos o intentar derribar algún coco.",
    ["Have a look around and ask the people in charge of the activities for more information."] = "Echa un vistazo y pide más información a los responsables de las actividades.",
    ["Vendors."] = "Vendedores.",
    ["Sheldon has gathered up all the old items the vendors used to sell here in previous years and is offering them all up!"] = "¡Sheldon ha reunido todos los artículos antiguos que los vendedores solían vender aquí en años anteriores y los está ofreciendo todos!",
    ["I hear that there aren't many left, so after this year, I suspect they will be gone for good."] = "He oído que no quedan muchos, así que después de este año, sospecho que desaparecerán para siempre.",
    ["Flo on the other hand, is still adamant that newer is better, so she's got a bunch of new items ready to sell!"] = "Flo, por otro lado, sigue insistiendo en que lo nuevo es mejor, ¡así que tiene un montón de artículos nuevos listos para vender!",
    ["I'm planning on getting myself a little crab pet to follow me around. It's so adorable that he just carries that bucked around on his back."] = "Estoy pensando en conseguirme un pequeño cangrejo como mascota para que me siga. Es tan adorable que simplemente lleva ese corcovado en su espalda.",
    ["The creature."] = "La criatura.",
    ["The creature seems to pop out of the crater every hour. She brings the rain with her. We have found though, that if we can beat her she will go and hide again and we get the lovely sunshine back."] = "La criatura parece salir del cráter cada hora. Ella trae la lluvia con ella. Sin embargo, hemos descubierto que si podemos vencerla, ella se esconderá nuevamente y recuperaremos el hermoso sol.",
    ["The portals."] = "Los portales.",
    ["There are portals in the beach that can take you directly to lots of fun activities, and a lifeguard who will let you know when to go, so you don't have to waste a minute of tanning time."] = "Hay portales en la playa que pueden llevarte directamente a muchas actividades divertidas y un salvavidas que te avisará cuándo ir, para que no tengas que perder ni un minuto bronceándote.",
    ["[There are portals to take you to the following D&Ds: Sinkholes, Big Chinchompa, Guthixian Cache, Evil Tree, Shooting Star, Fish Flingers and Familiarisation.]"] = "[Hay portales que te llevarán a los siguientes D&D: Sumideros, Gran Chinchompa, Guthixian Cache, Evil Tree, Shooting Star, Fish Flingers y Familiarización.]",
    ["[The portals will open when the games are about to start.]"] = "[Los portales se abrirán cuando los juegos estén por comenzar.]",
    ["There are also a few portals to take you to some other useful locations around Gielinor, though why you'd leave the beach is beyond me!"] = "También hay algunos portales que te llevarán a otros lugares útiles alrededor de Gielinor, ¡aunque no entiendo por qué abandonarías la playa!",
    ["[These include the recently unearthed ancient city of Senntisten, and a little something to help you along with Archaeology.]"] = "[Estos incluyen la antigua ciudad recientemente desenterrada de Senntisten y algo que te ayudará junto con Archaeology.]",
    ["Oh yes! Lots of rewards to be earned! Why, just by skilling on the beach you can occasionally discover tokens for some fabulous summer items - outfits, weapons, pets and more!"] = "¡Oh, sí! ¡Muchas recompensas por ganar! Bueno, con solo practicar en la playa, ocasionalmente puedes descubrir fichas para algunos artículos fabulosos de verano: trajes, armas, mascotas y más.",
    ["There are also various titles you can earn should you stick around long enough."] = "También hay varios títulos que puedes ganar si te quedas el tiempo suficiente.",
    ["What will happen to the sand at the end of the party?"] = "¿Qué pasará con la arena al final de la fiesta?",
    ["There is a plan to put it all back in the desert, of course there is."] = "Hay un plan para devolverlo todo al desierto, por supuesto que lo hay.",
    ["And the plan is?"] = "¿Y el plan es?",
    ["It's a secret! I wouldn't want people ambushing the sand as it goes back now. Not sure why they'd want to though..."] = "¡Es un secreto! No me gustaría que la gente tendiera emboscadas a la arena tal como está ahora. Aunque no estoy seguro de por qué querrían hacerlo...",
    ["How am I doing?"] = "¿Cómo estoy?",
    ["Let's have a look..."] = "Echemos un vistazo...",
    ["You don't have space in your inventory for a clue scroll."] = "No tienes espacio en tu inventario para un pergamino de pistas.",
    ["Here, I've got a sandy clue scroll for you."] = "Aquí tengo un pergamino de pistas arenosas para ti.",
    ["After this clue scroll you have [amount] additional clue scroll[s]."] = "Después de este desplazamiento de pistas, tienes [amount] desplazamiento de pistas adicionales [s].",
    ["You can't receive another clue until you've completed or destroyed your previous one."] = "No podrás recibir otra pista hasta que hayas completado o destruido la anterior.",
    ["You've received all the clue scrolls you can for now. Come back tomorrow for more."] = "Has recibido todos los pergaminos de pistas que has podido por ahora. Vuelve mañana por más.",
    ["You've completed all the beach clue scrolls you can this year. Well done!"] = "Has completado todos los pergaminos de pistas de playa que has podido este año. ¡Bien hecho!",
    ["Reach maximum temperature 10 times."] = "Alcance la temperatura máxima 10 veces.",
    ["Kill Clawdia 50 times."] = "Mata a Clawdia 50 veces.",
    ["Find 10 hidden rubber ducks on the beach using a spade. Get digging!"] = "Encuentra 10 patos de goma escondidos en la playa usando una pala. ¡Empieza a cavar!",
    ["A bonus title which can be obtained by unlocking the 'Quackers' title and the 'Mega ducklings' boss pet."] = "Un título extra que se puede obtener desbloqueando el título 'Quackers' y la mascota jefe 'Mega patitos'.",
    ["Reach maximum temperature 25 times."] = "Alcanza la temperatura máxima 25 veces.",
    ["Play hook-a-duck - Enter the Dungeoneering hole"] = "Juega gancho-a-pato - Ingresa al hoyo Dungeoneering",
    ["Unlock the Deckchair resting animation by resting in a red, green and blue deckchair 10 times each - Unlock the rainbow kite by talking to Reyna, Nigel, Palmer, Sarah and Wellington - Unlock the Beach Towel cape override by resting on the beach 10 times with a beach rest animation active - Unlock the Beach Swimming outfit by reaching maximum temperature 50 times. - Unlock the Beach Summer Fun outfit by reaching maximum temperature 100 times."] = "Desbloquea la animación de descanso de la tumbona descansando en una tumbona roja, verde y azul 10 veces cada una - Desbloquea la cometa arcoíris hablando con Reyna, Nigel, Palmer, Sarah y Wellington - Desbloquea la capa de toalla de playa descansando en la playa 10 veces con una animación de descanso en la playa activa - Desbloquea el traje de natación de playa alcanzando la temperatura máxima 50 veces. - Desbloquea el conjunto Beach Summer Fun alcanzando la temperatura máxima 100 veces.",
    ["*(During a heatwave:)*"] = "*(Durante una ola de calor:)*",
    ["*(Continues below.)*"] = "*(Continúa a continuación.)*",
    ["*(Only if not selected last, and only in 2020:)*"] = "*(Solo si no fue seleccionado el último, y solo en 2020:)*",
    ["What's new?"] = "¿Qué hay de nuevo?",
    ["I was approached by this strange character... I think he said his name was Mark? Mate? Morn? Something like that..."] = "Se me acercó este extraño personaje... Creo que dijo que se llamaba Mark. ¿Compañero? ¿Morn? Algo así...",
    ["He was desperate to get this hole dug in the area. Said that people would really enjoy jumping into it to train their Dungeoneering."] = "Estaba desesperado por cavar este hoyo en el área. Dijo que a la gente le gustaría mucho saltar a él para entrenar su Dungeoneering.",
    ["He reassured me that he had no nefarious reasons for it. So that's good!"] = "Me aseguró que no tenía motivos nefastos para ello. ¡Eso es bueno!",
    ["Now that I mention it, it does seem a little weird that he would say that without me questioning him..."] = "Ahora que lo menciono, parece un poco extraño que dijera eso sin que yo lo cuestionara...",
    ["But he seemed like an alright chap! So I'm sure everything will be ok!"] = "¡Pero parecía un buen tipo! ¡Así que estoy seguro de que todo estará bien!",
    ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
    ["*(Only if not selected last:)*"] = "*(Sólo si no fue seleccionado en último lugar:)*",
    ["Skilling activities"] = "Actividades de capacitación",
    ["There are many skilling opportunities, try building a sandcastle, do a spot of cooking or fishing, gather some coconuts, chase a beachball or try to knock down the odd coconut."] = "Hay muchas oportunidades para desarrollar habilidades, intenta construir un castillo de arena, cocinar o pescar, recoger algunos cocos, perseguir una pelota de playa o intentar derribar algún que otro coco.",
    ["Vendors"] = "Vendedores",
    ["The creature"] = "la criatura",
    ["The portals"] = "los portales",
    ["There are portals to take you to the following D&Ds: Sinkholes, Big Chinchompa, Guthixian Cache, Evil Tree, Shooting Star, Fish Flingers and Familiarisation."] = "Hay portales que te llevarán a los siguientes D&D: Sumideros, Gran Chinchompa, Guthixian Cache, Evil Tree, Shooting Star, Fish Flingers y Familiarización.",
    ["The portals will open when the games are about to start."] = "Los portales se abrirán cuando los juegos estén por comenzar.",
    ["These include Anachronia and a little something to help you along with Archaeology."] = "Estos incluyen Anacronia y algo que te ayudará junto con Archaeology.",
    ["*(Only after asking something else:)*"] = "*(Solo después de preguntar algo más :)*",
    ["Something else"] = "algo mas",
    ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
    ["*(With titles left to unlock:)*"] = "*(Quedan títulos por desbloquear:)*",
    ["*(With all titles unlocked:)*"] = "*(Con todos los títulos desbloqueados:)*",
    ["It looks like you already have all the titles available for doing things on the beach!"] = "¡Parece que ya tienes todos los títulos disponibles para hacer cosas en la playa!",
    ["Be sure to check out Sheldon's store for some other titles from previous years!"] = "¡Asegúrate de visitar la tienda de Sheldon para ver otros títulos de años anteriores!",
    ["*(If the player has more scrolls in store:)*"] = "*(Si el player tiene más pergaminos almacenados:)*",
    ["Oh it's a scorcher! The temperature scale is so hot it's stopped working so you can carry on with your beach activities regardless!"] = "¡Oh, es abrasador! ¡La escala de temperatura está tan alta que dejó de funcionar, por lo que puedes continuar con tus actividades en la playa de todos modos!",
    ["This year's beach has all new peep boards!"] = "¡La playa de este año tiene nuevos mirillas!",
    ["Pop your head in the hole and have your picture taken, while looking like a god. A souvenir for all time."] = "Mete la cabeza en el agujero y tómate una foto mientras pareces un dios. Un recuerdo para todos los tiempos.",
    ["They are dotted around the beach. Have a go and have a chuckle."] = "Están repartidos por la playa. Pruébalo y ríete.",
    ["The beach has attracted a couple of vendors, and they have outfit pieces, lots of lovely hats, and also fun items for sale."] = "La playa ha atraído a un par de vendedores que tienen prendas de vestir, muchos sombreros encantadores y también artículos divertidos a la venta.",
    ["My personal favourite is the throwing disk."] = "Mi favorito personal es el disco arrojadizo.",
    ["Don't forget, there are a few portals to take you to some other useful locations around Gielinor, though why you'd leave the beach is beyond me!"] = "No lo olvides, hay algunos portales que te llevarán a otras ubicaciones útiles alrededor de Gielinor, ¡aunque no entiendo por qué abandonarías la playa!",
    ["These include; Menaphos, deep sea fishing and Aminishi."] = "Estos incluyen; Menaphos, pesca de altura y Aminishi.",
    ["Terrorbird racing"] = "carreras de pájaros terroríficos",
    ["This year's beach has the old favourite, the terrorbird racecourse."] = "La playa de este año tiene el viejo favorito: el hipódromo del terrorbird.",
    ["It should be even more manic this year - I just love running around with that banana mount on so much!"] = "Debería ser aún más maníaco este año. ¡Me encanta correr con esa montura tipo banana puesta!",
    ["It starts in the same place as last year, so talk to Doctor Oddenstein by the terrorbird racing gate to find out all about how the racing works."] = "Comienza en el mismo lugar que el año pasado, así que habla con Doctor Oddenstein junto a la puerta de carreras de terrorbird para descubrir todo sobre cómo funcionan las carreras.",
    ["Secret for now, wouldn't want people ambushing the sand as it goes back now. Yep, that's the reason."] = "Secreto por ahora, no querría que la gente tendiera emboscadas en la arena a medida que regresa. Sí, esa es la razón.",
    ["*During Happy Hour*"] = "*Durante la hora feliz*",
    ["What year would you like to check?"] = "¿Qué año le gustaría consultar?",
    ["*(Only if not asked last, and without the period only as first question:)*"] = "*(Solo si no se hizo la última pregunta y sin el punto solo como primera pregunta:)*",
    ["2017 titles[.]"] = "Títulos de 2017[.]",
    ["You have unlocked all 2017 titles."] = "Has desbloqueado todos los títulos de 2017.",
    ["2016 titles[.]"] = "Títulos de 2016[.]",
    ["You have unlocked all 2016 titles."] = "Has desbloqueado todos los títulos de 2016.",
    ["2015 titles[.]"] = "Títulos de 2015[.]",
    ["You have unlocked all 2015 titles."] = "Has desbloqueado todos los títulos de 2015.",
    ["*(Only after selecting another option:)*"] = "*(Solo después de seleccionar otra opción:)*",
    ["None."] = "Ninguno.",
    ["Enjoy your time on the beach."] = "Disfruta de tu tiempo en la playa.",
    ["*(Only after asking about finishing the beach:)*"] = "*(Solo después de preguntar sobre terminar la playa :)*",
    ["Build-a-beach"] = "construir una playa",
    ["*(Dialogue from Build-a-Beach occurs.)*"] = "*(Se produce un diálogo de Build-a-Beach.)*",
    ["This year's beach has a new longer terrorbird racecourse."] = "La playa de este año tiene un nuevo hipódromo de terrorbird más largo.",
    ["It should be even more manic this year - I just love running around with that mount on so much!"] = "Debería ser aún más maníaco este año. ¡Me encanta correr con esa montura!",
    ["It starts in the same place as last year, so talk to Xuan by the terrorbird racing gate to find out all about how the racing works."] = "Comienza en el mismo lugar que el año pasado, así que habla con Xuan junto a la puerta de carreras de terrorbird para descubrir todo sobre cómo funcionan las carreras.",
    ["So you got the beach finished"] = "Así que terminaste la playa.",
    ["Absolutely, and how glorious it is. I could not have done it without all of the help I had from so many splendid people."] = "Absolutamente, y qué glorioso es. No podría haberlo hecho sin toda la ayuda que recibí de tanta gente maravillosa.",
    ["Thanks for helping me with the beach this year. Lets party!"] = "Gracias por ayudarme con la playa este año. ¡Vamos a la fiesta !",
    ["Lets have a look..."] = "Vamos a a echar un vistazo...",
    ["*(If the title isn't unlocked yet:)*"] = "*(Si el título aún no está desbloqueado:)*",
    ["Looks like you've not done all the beach content for this year yet. Speak to a lifeguard for more info."] = "Parece que aún no has hecho todo el contenido de playa para este año. Habla con un salvavidas para obtener más información.",
    ["*(The missing of the following are shown:)*"] = "*(Se muestran los siguientes que faltan:)*",
    ["You haven't unlocked the Octopus pet yet."] = "Aún no has desbloqueado la mascota Pulpo.",
    ["*(If the title is already unlocked:)*"] = "*(Si el título ya está desbloqueado:)*",
    ["You've already got the title from this year's event."] = "Ya tienes el título del evento de este año.",
    ["*(If there is beach sand to hand in:)*"] = "*(Si hay arena de playa para entregar:)*",
    ["*(Dialogue from handing in beach sand occurs, then continues below.)*"] = "*(Se produce un diálogo entre la entrega de arena de la playa y luego continúa a continuación.)*",
    ["Hello friend, are you here to help with Build-a-beach?"] = "Hola amigo, ¿estás aquí para ayudar con Build-a-beach?",
    ["I'm Reyna, and I love a good beach party."] = "Soy Reyna y me encanta una buena fiesta en la playa.",
    ["So where is it then?"] = "Entonces, ¿dónde está?",
    ["Well I have to keep rebuilding it ready for the party every year."] = "Bueno, tengo que seguir reconstruyéndolo para la fiesta todos los años.",
    ["Some Guy keeps interfering and moving all my sand back to the desert."] = "Algunos Guy siguen interfiriendo y moviendo toda mi arena de regreso al desierto.",
    ["Any idea who it was?"] = "¿Alguna idea de quién fue?",
    ["Nope, but if I ever catch him, I'll show him what for-ks!"] = "No, pero si alguna vez lo atrapo, ¡le mostraré qué tenedores!",
    ["What was that other event in the crater?"] = "¿Cuál fue ese otro evento en el cráter?",
    ["Some people moved in and brought all kinds of fluff with them!"] = "¡Algunas personas se mudaron y trajeron todo tipo de tonterías!",
    ["I told them there'd be Helter pay for if they didn't."] = "Les dije que Helter pagaría si no lo hacían.",
    ["Well given that it's now free again, I guess you're having another party?"] = "Bueno, dado que ahora es gratis nuevamente, ¿supongo que vas a celebrar otra fiesta?",
    ["I sure am!"] = "¡Claro que sí!",
    ["How can I help?"] = "¿Cómo puedo ayudar?",
    ["Well, you can help with the Build-a-beach in a couple of ways..."] = "Bueno, puedes ayudar con Build-a-beach de varias maneras...",
    ["You can gather sand whilst on going about your daily business and bring it to me."] = "Puedes recolectar arena mientras realizas tus actividades diarias y tráemela.",
    ["Ordinary sand won't do, but you can find this stuff everywhere. It always gets in the cracks."] = "La arena común y corriente no sirve, pero puedes encontrarla en todas partes. Siempre se queda en las grietas.",
    ["And the other?"] = "¿Y el otro?",
    ["You can help deliver the sand from this pile here next to me, to one of ones in the crater."] = "Puedes ayudar a llevar la arena de este montón aquí a mi lado, a uno de los que están en el cráter.",
    ["Watch out for the quick sand, and those sandstorms though."] = "Cuidado con la arena movediza y con las tormentas de arena.",
    ["If you drop it all before you get to the piles, just come back here and get some more."] = "Si lo dejas todo antes de llegar a las pilas, vuelve aquí y consigue un poco más.",
    ["I've also got some rewards including an outfit and a little magic ring I made for you if you help out."] = "También tengo algunas recompensas que incluyen un atuendo y un pequeño anillo mágico que hice para ti si ayudas.",
    ["Okay, got it."] = "Está bien, lo tengo.",
    ["What was with the sand pits?"] = "¿Qué pasó con los pozos de arena?",
    ["Ah yes, well erm I was trying to teleport the sand from the desert straight to the crater but something went a bit wrong."] = "Ah, sí, bueno, estaba tratando de teletransportar la arena del desierto directamente al cráter, pero algo salió un poco mal.",
    ["At least it's all sorted now."] = "Al menos ya está todo arreglado.",
    ["Lovely weather..."] = "Buen tiempo...",
    ["Yes well, that seems to be an unfortunate side effect from when I tried to teleport the sand here."] = "Sí, bueno, eso parece ser un efecto secundario desafortunado de cuando intenté teletransportar la arena aquí.",
    ["Take care around the sandstorms for now, they'll give you a bit of a whirl if you get too close, though only whilst carrying sand it seems."] = "Ten cuidado con las tormentas de arena por ahora, te darán un pequeño remolino si te acercas demasiado, aunque parece que solo mientras transportas arena.",
    ["Got it."] = "Entendido.",
    ["Hopefully they'll blow out soon enough before we start the party."] = "Con suerte, se apagarán pronto antes de que comencemos la fiesta.",
    ["What is The Beach Party?"] = "¿Qué es La Fiesta en la Playa?",
    ["Why it's only the best event of the year, that takes place in the summer near Lumbridge castle, previously where some Gods fought!"] = "¡Por qué es solo el mejor evento del año, que se lleva a cabo en el verano cerca del castillo Lumbridge, donde anteriormente lucharon algunos dioses!",
    ["Unrivalled then. What can we do?"] = "Entonces, incomparable. ¿Qué podemos hacer?",
    ["Well, there are plenty of activities to do, loads of skilling opportunities and portals that take you to other fun activities."] = "Bueno, hay muchas actividades para hacer, muchas oportunidades de habilidades y portales que te llevan a otras actividades divertidas.",
    ["As well as shops with outfits and items for sale, and lots more!"] = "Además de tiendas con trajes y artículos a la venta, ¡y mucho más!",
    ["I can't wait!"] = "¡No puedo esperar!",
    ["You do not have anything to hand in."] = "No tienes nada que entregar.",
    ["Handing in event currency will increase your progress for this event unlocking unique rewards. This will remove currency up to the amount that is required to complete the event."] = "Entregar la moneda del evento aumentará tu progreso en este evento y desbloqueará recompensas únicas. Esto eliminará moneda hasta la cantidad necesaria para completar el evento.",
    ["Do you wish to continue?"] = "¿Quieres continuar?",
    ["*(If not all the rewards are unlocked:)*"] = "*(Si no todas las recompensas están desbloqueadas:)*",
    ["You hand in [X] Beach sand. You need to hand in [Y] more to complete the event."] = "Entregas [X] Arena de playa. Debes entregar [Y] más para completar el evento.",
    ["*(Dialogue from claiming rewards occurs.)*"] = "*(Se produce un diálogo para reclamar recompensas.)*",
    ["*(If all the rewards are unlocked:)*"] = "*(Si todas las recompensas están desbloqueadas:)*",
    ["You have completed the event!"] = "¡Has completado el evento!",
    ["You have unlocked all of the rewards available for this event. You can convert any remaining currency into consumable rewards."] = "Has desbloqueado todas las recompensas disponibles para este evento. Puedes convertir cualquier moneda restante en recompensas consumibles.",
    ["There you are!"] = "¡Ahí estás!",
    ["Congratulations, you have unlocked [reward]."] = "Felicitaciones, has desbloqueado [reward].",
    ["You have unlocked [X]/7 of the rewards for the Beach Buildup event."] = "Has desbloqueado [X]/7 de las recompensas del evento Beach Buildup.",
    ["You have more rewards to unlock. Collect more sand to get them."] = "Tienes más recompensas para desbloquear. Recoge más arena para conseguirlos.",
    ["What are the new activities?"] = "¿Cuáles son las nuevas actividades?",
    ["We have two new exciting activities for this year's beach - hook a duck and terrorbird racing. They're both really fun, although the racing is my favourite - I love running around with that mount on! Sarah by the hook a duck stall will give you information about that, and talk to Xuan by the terrorbird racing gate to find out all about how the racing works."] = "Tenemos dos nuevas y emocionantes actividades para la playa de este año: enganchar un pato y correr pájaros terroríficos. Ambos son muy divertidos, aunque las carreras son mis favoritas. ¡Me encanta correr con esa montura! Sarah junto al gancho, un puesto de patos, le brindará información al respecto y hablará con Xuan junto a la puerta de carreras de terrorbird para descubrir todo sobre cómo funcionan las carreras.",
    ["Absolutely, and how glorious it is. I could not have done it without all the help I had from so many splendid people."] = "Absolutamente, y qué glorioso es. No podría haberlo hecho sin toda la ayuda que tuve de tanta gente maravillosa.",
    ["There was an adorable little creature in one of the buckets of sand that was handed in for the beach, little dot of a thing. It looks like she grew up! I have sent word to the wizards at the Wizards' Tower and they believe that the little tyke is the land retaliating for the battles in the area. That Gielinor is, well, unhappy, and has used the Anima Mundi to create a defender. I'm not sure if I believe that though, the wizards are reluctant to come and see her for themselves. But it is hard to deny that the little thing has grown rather large. I just wish she didn't bring the rain with her."] = "Había una criaturita adorable en uno de los cubos de arena que se entregaron para la playa, un pequeño punto. ¡Parece que creció! He avisado a los magos del Wizards' Tower y creen que el pequeño es la tierra que toma represalias por las batallas en la zona. Ese Gielinor está, bueno, descontento y ha utilizado Anima Mundi para crear un defensor. Sin embargo, no estoy seguro de creer eso, los magos se muestran reacios a venir a verla por sí mismos. Pero es difícil negar que la pequeña cosa se ha vuelto bastante grande. Sólo desearía que no trajera la lluvia con ella.",
    ["There are many skilling opportunities, try building a sandcastle, do a spot of cooking or fishing, gather some coconuts, chase a beachball or try to knock down the odd coconut. Have a look around and ask the people in charge of the activities for more information."] = "Hay muchas oportunidades para desarrollar habilidades, intenta construir un castillo de arena, cocinar o pescar, recoger algunos cocos, perseguir una pelota de playa o intentar derribar algún que otro coco. Echa un vistazo y pide más información a los responsables de las actividades.",
    ["The beach has attracted a couple of vendors, and they have outfit pieces, lots of lovely hats, and also fun items for sale. My personal favourite is the throwing disk."] = "La playa ha atraído a un par de vendedores que tienen prendas de vestir, muchos sombreros encantadores y también artículos divertidos a la venta. Mi favorito personal es el disco arrojadizo.",
    ["Oh hey Reyna, what are you still doing here?"] = "Oh, hola Reyna, ¿qué sigues haciendo aquí?",
    ["It's all gone... My poor beach, it's ruined!"] = "Se acabó todo... ¡Mi pobre playa, está arruinada!",
    ["Urm, Reyna are you okay?"] = "Urm, Reyna, ¿estás bien?",
    ["I'll be off now then... Enjoy doing whatever it is that you're doing with that bit of sand."] = "Entonces me voy... Disfruta haciendo lo que sea que estés haciendo con ese pedacito de arena.",
    ["What do you do around here?"] = "¿Qué haces por aquí?",
    ["I wheel, I deal, I keep the money moving by offering prizes for hard earned spooky tokens."] = "Yo manejo, trato y mantengo el dinero en movimiento ofreciendo premios por tokens espeluznantes ganados con tanto esfuerzo.",
    ["What sort of stuff do you sell?"] = "¿Qué tipo de cosas vendes?",
    ["Hmmph. Costumes, weapons, prizes. Even some legitimate clan confections if you've got enough tokens."] = "Hmmph. Disfraces, armas, premios. Incluso algunos dulces legítimos del clan si tienes suficientes fichas.",
    ["Can I see your wares?"] = "¿Puedo ver tus productos?",
    ["Yeah, yeah."] = "Sí, sí.",
    ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
    ["I want [number] [items] for that."] = "Quiero [número] [items] para eso.",
    ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
    ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
    ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
    ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
    ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
    ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
    ["There is no need for me to look after that poison ivy."] = "No es necesario que cuide esa hiedra venenosa.",
    ["Really?"] = "¿En serio?",
    ["Yes, poison ivy is pretty hardy stuff, and most animals will avoid eating it."] = "Sí, la hiedra venenosa es un material bastante resistente y la mayoría de los animales evitarán comerla.",
    ["Hence, there is no reason to worry about it."] = "Por lo tanto, no hay razón para preocuparse por eso.",
    ["Great."] = "Genial.",
    ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
    ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
    ["If you like, but I want [number] [item] for that."] = "Si quieres, pero quiero [número] [item] para eso.",
    ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
    ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
    ["Okay, it's a deal."] = "Está bien, es un trato.",
    ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["No, that's too much."] = "No, eso es demasiado.",
    ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
    ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
    ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
    ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
    ["Can you sell me something?"] = "¿Puedes venderme algo?",
    ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["Some plant cure."] = "Alguna cura vegetal.",
    ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
    ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
    ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
    ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
    ["A bucket of compost."] = "Un balde de abono.",
    ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
    ["A rake."] = "Un rastrillo.",
    ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See more items)"] = "(Ver más artículos)",
    ["A watering can"] = "una regadera",
    ["A watering can."] = "Una regadera.",
    ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
    ["A gardening trowel"] = "Una paleta de jardinería",
    ["A gardening trowel."] = "Una paleta de jardinería.",
    ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["A seed dibber"] = "Un zambullidor de semillas",
    ["A seed dibber."] = "Un arrancador de semillas.",
    ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See previous items)"] = "(Ver artículos anteriores)",
    ["Forget it."] = "Olvídalo.",
    ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
    ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
    ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    ["If you complete this, I'll give you : A Rock-shell, Spined, or Skeletal armour piece x 1. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Una pieza de armadura de caparazón de roca, de espinas o de esqueleto x 1. ¡Estoy seguro de que también ganarás algo de reputación en el gremio de agricultores!",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal] o [Animal].",
    ["You've received : [Reward] x 1 And 5,500 Farming reputation."] = "Has recibido: [Reward] x 1 Y 5500 reputación Farming.",
    ["You've received : [Reward] x 1 And 5,500 farming reputation."] = "Has recibido: [Reward] x 1 Y 5500 reputación agrícola.",
    ["You've already completed this request, there will be a new tri-daily request in [time]"] = "Ya has completado esta solicitud, habrá una nueva solicitud tridiaria en [time]",
    ["The Tower of Voices is a wonderful place to do business, enrapt with the Voice of Seren as we are."] = "La Torre de las Voces es un lugar maravilloso para hacer negocios, cautivados por la Voz de Seren como estamos.",
    ["My specialty is anything related to herbs and potions. Can I help you with anything?"] = "Mi especialidad es todo lo relacionado con hierbas y pociones. ¿Puedo ayudarte con algo?",
    ["Can you decant some potions for me?"] = "¿Puedes decantarme algunas pociones?",
    ["Can you help me out with the prices for herbs?"] = "¿Me pueden ayudar con los precios de las hierbas?",
    ["I'd be happy to!"] = "¡Estaría encantado de hacerlo!",
    ["How much do you charge for decanting potions?"] = "¿Cuanto cobran por decantar pociones?",
    ["If you want potions decanted into 4, 3, 2 or 1 dose versions, I charge 2 coins for each normal vial, 2 coins for each juju vial and 15 coins for each powerburst vial."] = "Si quieres pociones decantadas en versiones de 4, 3, 2 o 1 dosis, cobro 2 coins por cada vial normal, 2 coins por cada vial de juju y 15 coins por cada vial de powerburst.",
    ["Sorry, I've got to go."] = "Lo siento, tengo que irme.",
    ["Okay, I'll be here if you ever need me, mesmerised by the lady's voice."] = "Está bien, estaré aquí si alguna vez me necesitas, hipnotizado por la voz de la dama.",
    ["Decant vials"] = "Decantar viales",
    ["How many doses do you want to decant into?"] = "¿En cuántas dosis quieres decantar?",
    ["One dose"] = "una dosis",
    ["There you go, chum."] = "Ahí lo tienes, amigo.",
    ["Sorry, I don't know how to decant anything that you're carrying."] = "Lo siento, no sé cómo decantar nada de lo que llevas.",
    ["Sorry, you don't have enough money to pay for enough empty vials."] = "Lo sentimos, no tienes suficiente dinero para pagar suficientes viales vacíos.",
    ["Your inventory's a bit too full for me to do anything for you."] = "Tu inventario está demasiado lleno para que pueda hacer algo por ti.",
    ["Two doses"] = "Dos dosis",
    ["Three doses"] = "Tres dosis",
    ["Four doses"] = "Cuatro dosis",
    ["Decant flasks"] = "Decantar matraces",
    ["Sorry, you don't seem to have anything I can use. Make sure you have 2 flasks that aren't completely full!"] = "Lo siento, parece que no tienes nada que pueda usar. ¡Asegúrate de tener 2 matraces que no estén completamente llenos!",
    ["Let's see what you have. I will decant your potion flasks back into 6 dosed flasks. I can make use of the flasks, so I'll take those as payment."] = "Veamos qué tienes. Decantaré sus frascos de poción nuevamente en 6 frascos dosificados. Puedo hacer uso de los frascos, así que los aceptaré como pago.",
    ["Here you go. That's the best I can do! If the flasks don't look too different, I gave them a clean"] = "Aquí tienes. ¡Eso es lo mejor que puedo hacer! Si los matraces no se ven muy diferentes, los limpié.",
    ["Convert vials to flasks"] = "Convertir viales en matraces",
    ["You'll need to supply the empty flasks yourself; they're not cheap. You can bring them to me noted or unnoted."] = "Tendrás que proporcionar los frascos vacíos tú mismo; no son baratos. Puedes traérmelos anotados o sin anotaciones.",
    ["Let's see what you have. I will decant potion vials and all flasks up to 4 doses into 6 dose flasks. You'll need to supply the empty flasks yourself; they're not cheap."] = "Veamos qué tienes. Decantaré los viales de poción y todos los frascos hasta 4 dosis en frascos de 6 dosis. Tendrás que proporcionar los matraces vacíos tú mismo; no son baratos.",
    ["Here you go. That's the best I can do!"] = "Aquí tienes. ¡Eso es lo mejor que puedo hacer!",
    ["Sorry you don't seem to have anything I can help you with! Make sure you have the correct potions and some free space in your inventory and I can try again."] = "¡Lo siento, parece que no tienes nada en lo que pueda ayudarte! Asegúrate de tener las pociones correctas y algo de espacio libre en tu inventario y podré intentarlo de nuevo.",
    ["Convert flasks to vials"] = "Convertir matraces en viales",
    ["Sorry, you don't seem to have anything I can use. Make sure you have at least 1 flask!"] = "Lo siento, parece que no tienes nada que pueda usar. ¡Asegúrate de tener al menos 1 matraz!",
    ["Certainly. I think I can make use of the flasks, so I'll give you the vials for free."] = "Por supuesto. Creo que puedo utilizar los matraces, así que te daré los viales gratis.",
    ["There you go, that's the best I can do!"] = "Ahí lo tienes, ¡eso es lo mejor que puedo hacer!",
    ["Cancel"] = "Cancelar",
    ["Hello there! I've not seen anyone arriving here for ages. I'm Rhod."] = "¡Hola! Hace tiempo que no veo a nadie llegar aquí. Soy Rhod.",
    ["Player. The is struggling with this Sanguine threat."] = "Player. El está luchando contra esta amenaza sanguínea.",
    ["That what you're calling whatever has happened to the folks over in Berylbrook?"] = "¿Así llamas a lo que le pasó a la gente de Berylbrook?",
    ["Yes - it's some kind of blood affliction."] = "Sí, es una especie de aflicción de la sangre.",
    ["Like we didn't already have one of those to deal with... You know, what with being werewolves."] = "Como si aún no tuviéramos uno de esos con el que lidiar... Ya sabes, lo de ser hombres lobo.",
    ["Still, those 'sanguine werewolves', like you say - they don't cross over to us, so you're safe here."] = "Aún así, esos 'hombres lobo sanguíneos', como dices, no cruzan hacia nosotros, así que estás a salvo aquí.",
    ["Unless one of US chooses to eat you..."] = "A menos que uno de nosotros decida comerte...",
    ["What?"] = "¿Qué?",
    ["Kidding. I use dark humour to hide my unease. Enjoy your visit!"] = "Es broma. Utilizo el humor negro para ocultar mi malestar. ¡Disfruta tu visita!",
    ["[You find something, but without room in your backpack you're unable to collect it.]"] = "[Encuentras algo, pero sin espacio en tu backpack no puedes recogerlo.]",
    ["[You find an old tablet, its writings still legible.]"] = "[Encuentras una tablilla vieja, cuyas escrituras aún son legibles.]",
    ["You only find some lint and some jerky in Rhod's pockets. You put it all pack."] = "En los bolsillos de Rhod sólo encuentras pelusa y algo de cecina. Lo pones todo empacado.",
    ["Welcome to the Max Guild! I'm always happy to see other talented individuals here. My specialty is potions, although I've got some skill with crystal singing too. Can I help you with anything?"] = "¡Bienvenido al gremio Max! Siempre estoy feliz de ver a otras personas talentosas aquí. Mi especialidad son las pociones, aunque también tengo cierta habilidad con el canto de cristales. ¿Puedo ayudarte con algo?",
    ["I am Rhodri of the Dail family. I am a ward of the Clan Meilyr, although I have spent much time with all the clans. We should always aspire to broaden our skills. How else do we achieve greatness?"] = "Soy Rhodri de la familia Dail. Estoy bajo la tutela del clan Meilyr, aunque he pasado mucho tiempo con todos los clanes. Siempre debemos aspirar a ampliar nuestras habilidades. ¿De qué otra manera alcanzamos la grandeza?",
    ["Are you related to Rhobert in the Tower of Voices?"] = "¿Estás relacionado con Rhobert en la Torre de las Voces?",
    ["I am his brother, but he does not admit to that. He is jealous of my position here in the Max Guild. I hope one day he will discover his own talents are broader than just herblore, but for now he has ears only for the Voice."] = "Soy su hermano, pero él no lo admite. Está celoso de mi posición aquí en el Gremio Max. Espero que algún día descubra que sus propios talentos van más allá de la simple literatura, pero por ahora sólo tiene oídos para la Voz.",
    ["*Back to previous options*"] = "*Volver a opciones anteriores*",
    ["Can you decant things for me?"] = "¿Puedes decantar las cosas por mí?",
    ["Sure, 4-dose versions are simple enough. If you want potions decanted into 3-, 2- or 1-dose versions, I can do that too. I charge 2 coins for each normal vial and 2 coins for each juju vial I have to supply. Would you like to decant them into 1-, 2-, 3- or 4-dose potions?"] = "Claro, las versiones de 4 dosis son bastante simples. Si quieres que las pociones se decanten en versiones de 3, 2 o 1 dosis, también puedo hacerlo. Cobro 2 coins por cada vial normal y 2 coins por cada vial de juju que tengo que suministrar. ¿Te gustaría decantarlos en pociones de 1, 2, 3 o 4 dosis?",
    ["*Enter 1, 2, 3 or 4:*"] = "*Ingrese 1, 2, 3 o 4:*",
    ["*Searching*"] = "*Buscando*",
    ["*If you have potions that can be decanted they will be decanted*"] = "*Si tienes pociones que se pueden decantar, serán decantadas*",
    ["There you go."] = "Ahí lo tienes.",
    ["*If you don't have potions that can be decanted:*"] = "*Si no tienes pociones que se puedan decantar:*",
    ["*Ends dialogue*"] = "*Termina el diálogo*",
    ["Can you convert my flasks into normal vials for me?"] = "¿Pueden convertir mis matraces en viales normales para mí?",
    ["*If you have flasks to be converted:*"] = "*Si tiene matraces para convertir:*",
    ["*If you don't have flasks to be converted:*"] = "*Si no tienes matraces para convertir:*",
    ["Sorry, I couldn't really help you out there."] = "Lo siento, realmente no pude ayudarte.",
    ["Can you enchant my crystals for me?"] = "¿Puedes encantar mis cristales por mí?",
    ["Show me a crystal seed or crystal item, and I'll see what I can do with it."] = "Muéstrame una semilla de cristal o un objeto de cristal y veré qué puedo hacer con él.",
    ["Okay, I'll be here if you need me."] = "Está bien, estaré aquí si me necesitas.",
    ["I swear the master blacksmith is going crazy. He thinks someone keeps breaking in and making off with our anvils, yet they're still here."] = "Juro que el maestro herrero se está volviendo loco. Cree que alguien sigue entrando y llevándose nuestros yunques, pero todavía están aquí.",
    ["Please, spare an ounce of your time to help an apprentice?"] = "Por favor, ¿dedicas un poco de tu tiempo a ayudar a un aprendiz?",
    ["Would you like to help?"] = "¿Quieres ayudar?",
    ["Thank you so much."] = "Muchas gracias.",
    ["Oh, what will I do?"] = "Oh, ¿qué haré?",
    ["The magnificent Crondis has been angered by [monster]. She requires a blood sacrifice and a tribute."] = "El magnífico Crondis se ha enfadado con [monster]. Requiere un sacrificio de sangre y un tributo.",
    ["First, go and kill [number] [monster]."] = "Primero, ve y mata a [número] [monster].",
    ["What have the [monster] done to anger the almighty Crondis?"] = "¿Qué han hecho los [monster] para enojar al todopoderoso Crondis?",
    ["You don't need to know. Will you go to kill them?"] = "No necesitas saberlo. ¿Irás a matarlos?",
    ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
    ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
    ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
    ["Talk about your current task."] = "Hable sobre su tarea actual.",
    ["Have you vanquished the [number] [monster] for Lady Crondis? ([number] remaining)"] = "¿Has vencido al [número] [monster] para Lady Crondis? ([número] restantes)",
    ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
    ["Yes, I have slaughtered the [monster]."] = "Sí, he masacrado al [monster].",
    ["Praise be to Crondis!"] = "¡Alabado sea Crondis!",
    ["Now the pitiful wretches have paid for their transgressions, we require a burnt offering."] = "Ahora que los miserables han pagado por sus transgresiones, requerimos un holocausto.",
    ["The next things I need are [item]."] = "Lo siguiente que necesito es [item].",
    ["Right. Why [item]?"] = "Correcto. ¿Por qué [item]?",
    ["The first step towards appeasing Crondis is traditionally a burnt offering of [item]."] = "El primer paso para apaciguar a Crondis es tradicionalmente una ofrenda quemada de [item].",
    ["So please go and get [number] [item]."] = "Así que ve y consigue [número] [item].",
    ["Sure thing."] = "Claro.",
    ["No, sorry."] = "No, lo siento.",
    ["Do you have the tribute for Crondis? She grows impatient. I need [number] [item]. ([number] remaining)"] = "¿Tienes el tributo a Crondis? Ella se impacienta. Necesito [número] [item]. ([número] restantes)",
    ["Number of [item] given to Rhotep ([number]/[number])"] = "Número de [item] dado a Rhotep ([número]/[número])",
    ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
    ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
    ["Great. Thank you."] = "Genial. Gracias.",
    ["Yes, I have the [item]."] = "Sí, tengo el [item].",
    ["May the great crocodile smile upon you!"] = "¡Que el gran cocodrilo te sonría!",
    ["Finally, as per tradition, Crondis requires a liquid offering to be poured into the Elid."] = "Finalmente, según la tradición, Crondis requiere que se vierta una ofrenda líquida en el Elid.",
    ["A liquid offering?"] = "¿Una oferta líquida?",
    ["Yes, gather [number] [item] for me and I will have workers liquidise them."] = "Sí, reúne [número] [item] para mí y haré que los trabajadores los liquiden.",
    ["Nope."] = "No.",
    ["Have you gathered the [number] [item]? We need to appease Crondis as soon as possible! ([number] remaining)"] = "¿Has reunido el [número] [item]? ¡Necesitamos apaciguar a Crondis lo antes posible! ([número] restantes)",
    ["Aren't you industrious! Good job."] = "¿No eres trabajador? Buen trabajo.",
    ["Thank you so much for helping me!"] = "¡Muchas gracias por ayudarme!",
    ["Hello there, you interested in trading in your bonus experience?"] = "Hola, ¿estás interesado en intercambiar tu experiencia de bonificación?",
    ["I am a trader of sorts. I can take your bonus experience and offer you compensation in the form of various rare objects."] = "Soy una especie de comerciante. Puedo aprovechar tu experiencia adicional y ofrecerte una compensación en forma de varios objetos raros.",
    ["Does it hurt?"] = "¿Te duele?",
    ["Not at all! I get your bonus experience and you can get experience of your choice in return - or, if you prefer, you could have some rare items."] = "¡Para nada! Obtengo tu experiencia adicional y tú puedes obtener la experiencia que elijas a cambio o, si lo prefieres, puedes tener algunos artículos raros.",
    ["How does it work? What are you doing with the experience your take?"] = "¿Cómo funciona? ¿Qué estás haciendo con la experiencia que llevas?",
    ["That's not for you to know. I'm not going to be around forever, so make good use of the offer while I'm in the area!"] = "Eso no debes saberlo tú. No estaré aquí para siempre, ¡así que aprovecha la oferta mientras esté en la zona!",
    ["I would like to trade in some bonus experience."] = "Me gustaría intercambiar alguna experiencia adicional.",
    ["*(Skill selection interface opens.)*"] = "*(Se abre la interfaz de selección de habilidades.)*",
    ["I would like to buy something."] = "Me gustaría comprar algo.",
    ["*(Vic's Store interface opens.)*"] = "*(Se abre la interfaz de la Tienda de Vic.)*",
    ["Hello there, are you interested in buying items with your credits?"] = "Hola, ¿estás interesado en comprar artículos con tus créditos?",
    ["I am no longer trading, but you can still spend the credits you have earned."] = "Ya no hago transacciones, pero aún puedes gastar los créditos que has ganado.",
    ["Ah, No! Anything but that!"] = "¡Ah, no! ¡Cualquier cosa menos eso!",
    ["You'll have to absorb the experience from that yourself, before trading it with me!"] = "¡Tendrás que absorber la experiencia tú mismo antes de intercambiarla conmigo!",
    ["Ah, yes! I vant! I vant a yummy biscuit!"] = "¡Ah, sí! ¡Quiero! ¡Quiero una rica galleta!",
    ["Well hello there, Player!"] = "¡Bueno, hola, Player!",
    ["How do you know my name?"] = "¿Cómo sabes mi nombre?",
    ["Oh, I hear word of all the adventurers who come to visit our wonderful Burrow. Have you come to marvel at the wonders of carrot boats?"] = "Oh, me he enterado de todos los aventureros que vienen a visitar nuestra maravillosa Madriguera. ¿Has venido a maravillarte con las maravillas de los barcos zanahoria?",
    ["I think so?"] = "¿Creo que sí?",
    ["Good day, Player! Come to take my carrot boats for a spin?"] = "¡Buenos días, Player! ¿Vienes a dar una vuelta con mis botes de zanahoria?",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["I've come down to visit my dear old brother for the springtime season, and thought this would be the most fabulous opportunity in which to test out my latest creation - carrot boats!"] = "He venido a visitar a mi querido hermano mayor durante la temporada de primavera y pensé que esta sería la oportunidad más fabulosa para probar mi última creación: ¡los botes de zanahorias!",
    ["The ultra-nutritious soil here allows for quick iterations of new models, and the swathes of bushy-eyed adventurers make for ripe test sailors."] = "El suelo ultranutritivo aquí permite iteraciones rápidas de nuevos modelos, y las franjas de aventureros de ojos tupidos son marineros de prueba maduros.",
    ["Hold on - test sailors? Boats made out of rot-able vegetables? I'm not sure I'm on board with this."] = "Espera, ¿marineros de prueba? ¿Barcos hechos con vegetales podridos? No estoy seguro de estar de acuerdo con esto.",
    ["Oh, Player! There really is little to worry about. My team have done plenty of rigorous durability and safety tests earlier on in development. I'd never promote anything I wouldn't use myself!"] = "¡Oh, Player! Realmente hay poco de qué preocuparse. Mi equipo ha realizado muchas pruebas rigurosas de durabilidad y seguridad al principio del desarrollo. ¡Nunca promocionaría nada que no usaría yo mismo!",
    ["Alright, that was enough to convince me. Sign me up!"] = "Muy bien, eso fue suficiente para convencerme. ¡Inscríbeme!",
    ["Wonderful!"] = "¡Maravilloso!",
    ["Tell me more about boating."] = "Cuéntame más sobre la navegación.",
    ["So, what does boating involve?"] = "Entonces, ¿qué implica navegar?",
    ["For starters, my team and I have gone to the effort of placing some obstacles around the lake. There are hoops, slaloms, ramps, and half-pipes, all of which you can train Agility on."] = "Para empezar, mi equipo y yo nos hemos esforzado en colocar algunos obstáculos alrededor del lago. Hay aros, slaloms, rampas y halfpipes, en todos los cuales puedes entrenar a Agility.",
    ["But that's not all! Every 30 minutes, you can also take part in the Blooming Burrow race. I start setting these up on the hour and half past the hour, with the races properly kicking off at five minutes later."] = "¡Pero eso no es todo! Cada 30 minutos, también podrás participar en la carrera Blooming Burrow. Empiezo a configurarlos a la hora y media, y las carreras comienzan correctamente cinco minutos más tarde.",
    ["What can I get in return?"] = "¿Qué puedo obtener a cambio?",
    ["What can I get in return? I'd rather not be a lab bunny in one of your carrot boats for free."] = "¿Qué puedo obtener a cambio? Preferiría no ser un conejito de laboratorio en uno de tus carros zanahoria gratis.",
    ["Oh, dear Player! I would never ask you for free labour!"] = "¡Oh, querido Player! ¡Nunca te pediría mano de obra gratis!",
    ["In addition to Agility experience, I will personally make sure that you're paid in spring tokens for your endeavors."] = "Además de la experiencia Agility, personalmente me aseguraré de que te paguen en fichas de primavera por tus esfuerzos.",
    ["I've also commissioned some unique golden, silver, and bronze titles, and skins for your carrot boat, should you finish a boat race in good time."] = "También he encargado algunos títulos únicos de oro, plata y bronce, y diseños para tu bote zanahoria, en caso de que termines una regata a tiempo.",
    ["Can I customise my boat?"] = "¿Puedo personalizar mi barco?",
    ["Of course! You can be the most stylish carrot boater around with my custom-made boat decorations."] = "¡Por supuesto! Puedes ser el navegante de zanahorias más elegante que existe con mis decoraciones para barcos hechas a medida.",
    ["I'll be off now."] = "Me voy ahora.",
    ["Good day, Player."] = "Buenos días, Player.",
    ["Hello. How can I help you?"] = "Hola. ¿Le puedo ayudar en algo?",
    ["Can you give me any farming advice?"] = "¿Puedes darme algún consejo agrícola?",
    ["Yes - ask a gardener."] = "Sí, pregúntale a un jardinero.",
    ["I'm okay, thank you."] = "Estoy bien, gracias.",
    ["Hello there! Are you interested in buying one of my special team capes?"] = "¡Hola! ¿Estás interesado en comprar una de mis capas especiales del equipo?",
    ["What do team capes do?"] = "¿Qué hacen las capas del equipo?",
    ["If you and your friends all wear the same team cape, you'll be less likely to attack your friends by accident, and you'll find it easier to attack everyone else."] = "Si tú y tus amigos usan la misma capa del equipo, será menos probable que ataques a tus amigos por accidente y te resultará más fácil atacar a todos los demás.",
    ["They're very useful in Clan Wars and other player-vs-player combat areas where you might come across friends you don't want to harm."] = "Son muy útiles en Guerras de Clanes y otras áreas de combate jugador contra jugador donde puedes encontrarte con amigos a los que no quieres hacer daño.",
    ["So would you like to buy one?"] = "Entonces, ¿te gustaría comprar uno?",
    ["Yes please!"] = "¡Sí, por favor!",
    ["*Redirected to Richard's Wilderness Cape Shop*"] = "*Redirigido a la tienda del cabo Wilderness de Richard*",
    ["You have no coins to give away."] = "No tienes coins para regalar.",
    ["The magpie ignores you."] = "La urraca te ignora.",
    ["The magpie takes a small interest in your coins, but continues to ignore you."] = "La urraca se interesa un poco por tu coins, pero sigue ignorándote.",
    ["Good day there! That's quite a shiny looking set of coins you have there."] = "¡Buenos días! El conjunto de coins que tienes ahí tiene un aspecto bastante brillante.",
    ["Are you eyeing up my coins?"] = "¿Estás mirando mi coins?",
    ["[You hold your coins out in front of you.]"] = "[Mantienes tu coins frente a ti.]",
    ["These are my hard earned coins. I've been on many adventures you see."] = "Estos son mis coins ganados con tanto esfuerzo. He estado en muchas aventuras, ya ves.",
    ["Would you be so kind and share some with me?"] = "¿Serías tan amable de compartir algunos conmigo?",
    ["Good day Player. It's great to see you again."] = "Buenos días Player. Es genial verte de nuevo.",
    ["Are you here to share more of your wealth?"] = "¿Estás aquí para compartir más de tu riqueza?",
    ["How many coins would you like to give away? You have helped Richie accumulate a total wealth of [number]. (0-[100,000,000 minus the already donated amount]) [input field]"] = "¿Cuántos coins te gustaría regalar? Has ayudado a Richie a acumular una riqueza total de [número]. (0-[100,000,000 minus the already donated amount]) [input field]",
    ["You are about to give away [number] coins. Do you wish to continue?"] = "Estás a punto de regalar [número] coins. ¿Quieres continuar?",
    ["CANCEL"] = "CANCELAR",
    ["OK"] = "bien",
    ["Player, you have helped me accumulate a total wealth of [number]!"] = "Player, ¡me has ayudado a acumular una riqueza total de [número]!",
    ["As you clearly know how to increase your wealth, I have decided to join you on your adventures!"] = "Como sabes claramente cómo aumentar tu riqueza, ¡he decidido unirme a ti en tus aventuras!",
    ["You have unlocked the pet: 'Richie'."] = "Has desbloqueado la mascota: 'Richie'.",
    ["You can activate this via the 'Pets' tab in the 'Customisations' interface."] = "Puedes activar esto a través de la pestaña 'Mascotas' en la interfaz 'Personalizaciones'.",
    ["Congratulations! You have completed: 'Richie' - Unlock the Richie pet from helping Richie accumulate wealth at the Grand Exchange. (100,000,000/100,000,000)"] = "¡Felicitaciones! Has completado: 'Richie': desbloquea la mascota Richie para que pueda ayudar a Richie a acumular riqueza en Grand Exchange. (100.000.000/100.000.000)",
    ["Stand and deliver?"] = "¿Estar de pie y cumplir?",
    ["I used to roam the lands robbing travellers and giving the loot to anyone I liked. It was such a happy life, and I didn't really do much harm."] = "Solía vagar por las tierras robando a los viajeros y dándole el botín a quien quisiera. Era una vida muy feliz y realmente no hice mucho daño.",
    ["Suddenly they've decided that wealth redistribution is a crime, so they've stuck me in here with a stupid mugger. We even have to take turns using the bed!"] = "De repente decidieron que la redistribución de la riqueza es un delito, así que me encerraron aquí con un estúpido atracador. ¡Incluso tenemos que turnarnos para usar la cama!",
    ["I still shout 'Stand and deliver' at people, but it doesn't really work so well from in here."] = "Todavía le grito a la gente 'Stand and Delivery', pero en realidad no funciona tan bien desde aquí.",
    ["That's really sad."] = "Eso es realmente triste.",
    ["You could cheer me up by shooting the mugger. I like it when people shoot the mugger. I like it when people shoot the mugger, even though he always comes back."] = "Podrías animarme disparándole al atracador. Me gusta cuando la gente dispara al atracador. Me gusta cuando la gente dispara al atracador, aunque siempre regresa.",
    ["Hahaha, you're locked up."] = "Jajaja, estás encerrado.",
    ["No need to rub it in!"] = "¡No es necesario frotarlo!",
    ["I'm leaving now."] = "Me voy ahora.",
    ["I guess I'll be here next time you come by."] = "Supongo que estaré aquí la próxima vez que vengas.",
    ["Allo mate! Got a job going? Only [number] coins!"] = "¡Hola amigo! ¿Tienes un trabajo en marcha? ¡Solo [número] coins!",
    ["What can you do?"] = "¿Qué puedes hacer?",
    ["I'm a great cook, me! I used to work with a rat-catcher, I used to cook for him. There's a dozen different ways you can cook a rat!"] = "¡Soy un gran cocinero, yo! Solía ​​trabajar con un cazador de ratas, solía cocinar para él. ¡Hay docenas de formas diferentes de cocinar una rata!",
    ["Tell me about your previous jobs"] = "Cuéntame sobre tus trabajos anteriores.",
    ["Tell me about your previous jobs."] = "Cuéntame sobre tus trabajos anteriores.",
    ["Well, city warder Bravek once threw a chair at me and yelled at me to get him a hangover cure. So I made it and I think it worked, 'cause then he threw another chair at me and that one hit!"] = "Bueno, el guardia de la ciudad Bravek una vez me arrojó una silla y me gritó que le consiguiera una cura para la resaca. Así que lo hice y creo que funcionó, porque luego me arrojó otra silla y ¡ésa me golpeó!",
    ["So you've been in West Ardougne?"] = "¿Entonces has estado en West Ardougne?",
    ["Yeah, but I ain't got the plague or nuthin'! Honest, guv!"] = "Sí, ¡pero no tengo la peste ni nada por el estilo! ¡Honesto, jefe!",
    ["You're hired!"] = "¡Estás contratado!",
    ["Sorry mate, but we've been advised not to take on any work until them wizard's are done tinkerin'. It's a safety 'azard!"] = "Lo siento amigo, pero nos han aconsejado que no realicemos ningún trabajo hasta que los magos hayan terminado de retocar. ¡Es un peligro para la seguridad!",
    ["Cheers, mate! Look forward to working with you!"] = "¡Salud, amigo! ¡Esperamos trabajar con usted!",
    ["You already have a servant."] = "Ya tienes un sirviente.",
    ["If you answer my fiendish riddle correctly, I'll give you a treasure of my people!"] = "¡Si respondes correctamente a mi acertijo diabólico, te daré un tesoro de mi pueblo!",
    ["Alright then, shoot."] = "Muy bien, entonces dispara.",
    ["I'm carrying two swords and eight spears, and dressed in a cow-leather tunic. I peek through a hole in the door. What am I?"] = "Llevo dos espadas y ocho lanzas, y estoy vestido con una túnica de cuero de vaca. Miro por un agujero en la puerta. ¿Qué soy yo?",
    ["A maniac."] = "Un maníaco.",
    ["Wrong!"] = "¡Mal!",
    ["A spy."] = "Un espía.",
    ["A master at arms."] = "Un maestro de las armas.",
    ["A crab."] = "Un cangrejo.",
    ["Correct! Here is your shiny prize!"] = "¡Correcto! ¡Aquí está tu brillante premio!",
    ["A man."] = "Un hombre.",
    ["Hello there, master of riddles."] = "Hola, maestro de los acertijos.",
    ["Come on, Jessie. Giddyup! YEEEHAW! <!-- happy -->"] = "Vamos, Jessie. ¡Arrepiéntete! ¡SÍ! <!-- happy -->",
    ["Get back up on that mount. It ain't gonna ride itself! <!-- happy -->"] = "Vuelve a subir a esa montura. ¡No se montará solo! <!-- happy -->",
    ["I see you eyeing up my mount. away from Jessie! <!-- angry -->"] = "Te veo mirando mi montura. lejos de Jessie! <!-- angry -->",
    ["Riding isn't just my job. It's my passion! <!-- friendly -->"] = "Montar no es sólo mi trabajo. ¡Es mi pasión! <!-- friendly -->",
    ["What do you call a steed with money in the bank? Financially stable! <!-- laughing loudly -->"] = "¿Cómo se llama un corcel con dinero en el banco? ¡Financieramente estable! <!-- laughing loudly -->",
    ["We gotta saddle our differences! <!-- laughing loudly -->"] = "¡Tenemos que resolver nuestras diferencias! <!-- laughing loudly -->",
    ["You're doing a lot of talking and not a lot of riding! <!-- annoyed -->"] = "¡Estás hablando mucho y no montando mucho! <!-- annoyed -->",
    ["There is a ball in play, get back in there!"] = "Hay una pelota en juego, ¡vuelve allí!",
    ["I've nothing to say!"] = "¡No tengo nada que decir!",
    ["That's a point for us! # : #"] = "¡Ese es un punto para nosotros! # : #",
    ["Oh no! Let me know when you want me to start the next round."] = "¡Ay no! Avísame cuando quieres que comience la siguiente ronda.",
    ["Hello there, what are you doing here?"] = "Hola, ¿qué haces aquí?",
    ["I... am the sculptor's associate."] = "Yo... soy el asociado del escultor.",
    ["His associate? What does that mean?"] = "¿Su socio? ¿Qué significa eso?",
    ["Are you going to say anything meaningful at all?"] = "¿Vas a decir algo significativo?",
    ["No, apparently not."] = "No, aparentemente no.",
    ["I'm glad I don't have to talk to you anymore!"] = "¡Me alegro de no tener que hablar más contigo!",
    ["Oh, I have a puzzle for you to solve."] = "Oh, tengo un rompecabezas que debes resolver.",
    ["[Riki has given you a puzzle box!]"] = "[¡Riki te ha regalado una caja de rompecabezas!]",
    ["That isn't right, keep trying."] = "Eso no está bien, sigue intentándolo.",
    ["[Riki has given you another clue scroll!]"] = "[¡Riki te ha dado otro pergamino de pistas!]",
    ["Oh, you made it. That's a surprise."] = "Oh, lo lograste. Eso es una sorpresa.",
    ["Welcome to the clothes store. How might I help you?"] = "Bienvenido a la tienda de ropa. ¿Cómo puedo ayudarte?",
    ["What can you sell me?"] = "¿Qué puedes venderme?",
    ["Do you have any use for suqah teeth or hides?"] = "¿Tiene algún uso para los dientes o las pieles de suqah?",
    ["Most certainly! The hides are great for making clothes and the teeth are particularly useful for broaches, necklaces and the like. I'll trade you any you can find for pure essence if you like."] = "¡Sin duda! Las pieles son excelentes para confeccionar ropa y los dientes son particularmente útiles para broches, collares y cosas similares. Te cambio cualquiera que encuentres por esencia pura si quieres.",
    ["Trade your hides and teeth for [number] pure essence?"] = "¿Cambiar tus pieles y dientes por esencia pura [número]?",
    ["There you go!"] = "¡Ahí lo tienes!",
    ["Fair enough, come back anytime if you do."] = "Es justo, vuelve en cualquier momento si lo haces.",
    ["That's good to know. I don't have any with me at the moment, but at least I know where to come when I do!"] = "Es bueno saberlo. No tengo ninguno conmigo en este momento, ¡pero al menos sé dónde ir cuando lo tenga!",
    ["Most certainly! I'm only happy to let you exchange 28 each day though. Otherwise I'm swamped with teeth and hides that I can't use. You've reached that limit."] = "¡Sin duda! Sin embargo, solo me complace permitirte intercambiar 28 cada día. De lo contrario, estoy inundado de dientes y pieles que no puedo usar. Has llegado a ese límite.",
    ["You need to complete the Fremennik elite tasks to unlock this facility."] = "Debes completar las tareas de élite de Fremennik para desbloquear esta instalación.",
    ["It's a very interesting island you have here."] = "Es una isla muy interesante la que tienes aquí.",
    ["Why thank you. It's been our haven for a great many generations."] = "Pues, gracias. Ha sido nuestro refugio durante muchas generaciones.",
    ["Everything seems to have a magical feel to it."] = "Todo parece tener una sensación mágica.",
    ["Of course. We integrate magic into all areas of our lives. It is a part of everyone, so why deny it? It's best to make the most of this innate gift we have all been given."] = "Por supuesto. Integramos la magia en todos los ámbitos de nuestra vida. Es parte de todos, entonces ¿por qué negarlo? Lo mejor es aprovechar al máximo este don innato que todos hemos recibido.",
    ["What sort of things do you use your magic for?"] = "¿Para qué tipo de cosas usas tu magia?",
    ["Take a look around. We use it in our day to day lives, from making a cup of tea, to travelling around the island. You see our ancestors were the ones that found the first rune essence and put it to use! The various factions were"] = "Echa un vistazo a tu alrededor. Lo utilizamos en nuestro día a día, desde preparar una taza de té, hasta viajar por la isla. ¡Verás, nuestros antepasados ​​fueron los que encontraron la primera esencia rúnica y la pusieron en uso! Las diversas facciones fueron",
    ["eventually created, with people having different ideas on how the essence should be used (or not in some cases!)"] = "finalmente se creó, y las personas tenían diferentes ideas sobre cómo se debe usar la esencia (¡o no en algunos casos!)",
    ["What has kept you so secluded on this island?"] = "¿Qué te ha mantenido tan aislado en esta isla?",
    ["It may be a bit beyond you, but although magic comes from within, we are all very strongly linked to the moon and the effects it has on us cannot be denied!"] = "Puede que esté un poco fuera de tu alcance, pero aunque la magia viene de dentro, todos estamos muy fuertemente vinculados a la luna y ¡no se pueden negar los efectos que tiene en nosotros!",
    ["It can't?"] = "¿No puede?",
    ["Of course not. This very island has a great link to our moon, which helps us understand ourselves - especially our dreams, which is the path to understanding magic."] = "Por supuesto que no. Esta misma isla tiene un gran vínculo con nuestra luna, lo que nos ayuda a comprendernos a nosotros mismos, especialmente a nuestros sueños, que es el camino para comprender la magia.",
    ["I think I will just have to take your word on that."] = "Creo que tendré que confiar en tu palabra al respecto.",
    ["I'm good thanks, bye."] = "Estoy bien, gracias, adiós.",
    ["Come to visit my garden then, have you, human?"] = "Entonces vienes a visitar mi jardín, ¿verdad, humano?",
    ["This is your garden?"] = "¿Este es tu jardín?",
    ["No no, not quite. But I do look after it. It's the palace garden, you see. I keep it tidy, keep it living."] = "No, no, no del todo. Pero lo cuido. Es el jardín del palacio, ¿ves? Lo mantengo ordenado, lo mantengo vivo.",
    ["It's hard to grow much on these hard rocks deep beneath these mountains, you know."] = "Es difícil crecer mucho en estas rocas duras en lo profundo de estas montañas, ¿sabes?",
    ["I can imagine. Where do you get all your food from? Or even the soil for this garden?"] = "Me lo imagino. ¿De dónde sacas toda tu comida? ¿O incluso la tierra para este jardín?",
    ["We can grow a little food underground, but most of it comes from the extensive steamcart network that runs beneath the earth."] = "Podemos cultivar un poco de comida bajo tierra, pero la mayor parte proviene de la extensa red de carros de vapor que corre bajo tierra.",
    ["In the Era of Kings, many centuries ago, it was harder of course. Our steam technology was not developed as far yet and getting fresh supplies of food was always a problem."] = "En la Era de los Reyes, hace muchos siglos, era más difícil, por supuesto. Nuestra tecnología de vapor aún no estaba tan desarrollada y conseguir alimentos frescos siempre fue un problema.",
    ["Oh, I'm not boring you, am I?"] = "Oh, no te estoy aburriendo, ¿verdad?",
    ["Not at all!"] = "¡En absoluto!",
    ["Not at all! Please, go on!"] = "¡Para nada! ¡Por favor, continúa!",
    ["Oh yes, as I was saying, it was difficult to make a decent living here. I'm afraid this garden was rather neglected during that time."] = "Ah, sí, como decía, era difícil ganarse la vida dignamente aquí. Me temo que este jardín estuvo bastante descuidado durante ese tiempo.",
    ["Why did you dwarves stay so deep under ground, then? Why not simply go above ground?"] = "Entonces, ¿por qué ustedes, enanos, permanecieron tan profundamente bajo tierra? ¿Por qué no simplemente ir a la superficie?",
    ["What, with the wars raging up there?"] = "¿Qué, con las guerras que arrasan allí?",
    ["We dwarves went underground a long time ago, see. For a while the city of Keldagrim was completely cut off from the surface, simply waiting out the wars of the humans and the gods."] = "Nosotros, los enanos, pasamos a la clandestinidad hace mucho tiempo, ¿ves? Durante un tiempo, la ciudad de Keldagrim estuvo completamente aislada de la superficie, simplemente esperando a que pasaran las guerras de los humanos y los dioses.",
    ["This made it hard, though, to determine when the wars above the ground were over. Perhaps Keldagrim had remained hidden for far too long."] = "Sin embargo, esto hizo que fuera difícil determinar cuándo terminaron las guerras en la superficie. Quizás Keldagrim había permanecido oculto durante demasiado tiempo.",
    ["Only when King Alvis heroically defended the city against an invasion of trolls did we dare to venture out and see how much the world had changed."] = "Sólo cuando el rey Alvis defendió heroicamente la ciudad contra una invasión de trolls nos atrevimos a aventurarnos y ver cuánto había cambiado el mundo.",
    ["Of course, after that..."] = "Por supuesto, después de eso...",
    ["Ah well, enough history lessons I should say. I must really get back to my gardening."] = "Ah, bueno, ya basta de lecciones de historia, debería decir. Realmente debo volver a mi jardinería.",
    ["Thanks for the info!"] = "¡Gracias por la información!",
    ["A little, yes."] = "Un poco, sí.",
    ["A little, yes. I don't really know what all this has to do with anything."] = "Un poco, sí. Realmente no sé qué tiene que ver todo esto con nada.",
    ["I suppose it doesn't, really, it's just the mumblings of an old dwarf."] = "Supongo que no, en realidad, son solo los murmullos de un viejo enano.",
    ["Not really, no."] = "En realidad no, no.",
    ["Oh, alright then."] = "Oh, está bien entonces.",
    ["I'm also looking for a new animal, I'm currently after A [animal]"] = "También estoy buscando un nuevo animal, actualmente estoy buscando A [animal]",
    ["If you complete this, I'll give you : Luminite stone spirit x 10. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Espíritu de piedra de luminita x 10. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido! Solo estoy aquí por [número] horas y [número] minutos. Para ser exactos.",
    ["[You've received : Luminite stone spirit x 10 And 2,750 farming reputation.]"] = "[Has recibido: espíritu de piedra de luminita x 10 y 2750 de reputación agrícola.]",
    ["A new request will be available in [time].."] = "Una nueva solicitud estará disponible en [time].",
    ["You've already completed this request, there will be a new daily request in [time].."] = "Ya has completado esta solicitud, habrá una nueva solicitud diaria en [time].",
    ["Ah, a new face. Could you be our new performer?"] = "Ah, una cara nueva. ¿Podrías ser nuestro nuevo intérprete?",
    ["Yes, I am."] = "Sí, lo soy.",
    ["WONDERFUL! Wonderful. But you're human? Well, beggars can't be choosers."] = "¡MARAVILLOSO! Maravilloso. ¿Pero eres humano? Bueno, los mendigos no pueden elegir.",
    ["What's wrong with-"] = "¿Qué pasa con-?",
    ["Now, we have several acts that need a performer. What act would you like to perform in?"] = "Ahora, tenemos varios actos que necesitan un artista. ¿En qué acto te gustaría actuar?",
    ["Err, no. I was just having a look around."] = "Eh, no. Estaba simplemente echando un vistazo a mi alrededor.",
    ["Ah, very well. I suppose not all are meant for the spotlight."] = "Ah, muy bien. Supongo que no todos están destinados a ser el centro de atención.",
    ["Ah, my little performer. What can I do for you?"] = "Ah, mi pequeño intérprete. ¿Qué puedo hacer por ti?",
    ["Could you tell me about..."] = "¿Podrías hablarme de...?",
    ["The performances"] = "las actuaciones",
    ["What performances have I done?"] = "¿Qué actuaciones he hecho?",
    ["You have done your _____ performance."] = "Has hecho tu _____ actuación.",
    ["You have done all your performances for this week. What dedication you have."] = "Has hecho todas tus actuaciones de esta semana. Que dedicación tienes.",
    ["Ah, this is a truly fearsome act! You must walk the tightrope and perform daring feats of agility. Flips, twirls, juggling chinchompas; it is truly only for the brave."] = "¡Ah, este es un acto verdaderamente temible! Debes caminar por la cuerda floja y realizar atrevidas hazañas de agilidad. Volteretas, giros, malabarismos con chinchompas; Realmente es sólo para los valientes.",
    ["Chinchompas? Juggling?"] = "¿Chinchompas? ¿Malabarismo?",
    ["We shall provide you with a costume; simply go to the changing tent by the ladder. You will change there and be taken to the platform. You can either get started straight away, or speak to the assistant on the platform at the top of the ladder who will explain the details to you."] = "Te proporcionaremos un disfraz; simplemente diríjase a la tienda para cambiarse junto a la escalera. Te cambiarás allí y te llevarán a la plataforma. Puede comenzar de inmediato o hablar con el asistente en la plataforma en la parte superior de la escalera, quien le explicará los detalles.",
    ["What's in it for me?"] = "¿Qué gano yo con esto?",
    ["How do I leave the circus?"] = "¿Cómo salgo del circo?",
    ["Ah, an ancient practice, ideal for the spotlight. Dazzle the audience with your displays of impossible feats. You won't need any runes. Speak to the fairy in the wizard's outfit and she'll explain the details to you, or if you feel you're already ready you can just get stuck in!"] = "Ah, una práctica antigua, ideal para ser el centro de atención. Deslumbra al público con tus demostraciones de hazañas imposibles. No necesitarás ninguna runa. Habla con el hada vestida de mago y ella te explicará los detalles, o si sientes que ya estás listo, ¡puedes quedarte atrapado!",
    ["A perfect place to put your shooting ability to the test. You must successfully hit 10 targets from a distance of your choice. Don't kill your assistant, though, as fairies are expensive to import. We shall provide you with equipment, so there is no cost to you. Either speak to the fairy in the green outfit near the bullseye to get more information, or get started straight away."] = "Un lugar perfecto para poner a prueba tu habilidad de tiro. Debes alcanzar con éxito 10 objetivos desde la distancia que elijas. Pero no mates a tu asistente, ya que importar hadas es caro. Nosotros te proporcionaremos el equipo, por lo que no habrá ningún coste para ti. Habla con el hada del traje verde cerca de la diana para obtener más información o comienza de inmediato.",
    ["More."] = "Más.",
    ["Certainly! Which would you like to know about?"] = "¡Por supuesto! ¿Cuál te gustaría saber sobre?",
    ["Fire poi"] = "poi de fuego",
    ["Ah, be careful with that one! You must successfully perform 6 flaming poi tricks! Be careful not to ignite anything... we don't want that happening again."] = "¡Ah, ten cuidado con ese! ¡Debes realizar con éxito 6 trucos de poi en llamas! Tenga cuidado de no encender nada... no queremos que eso vuelva a suceder.",
    ["Again?"] = "¿Otra vez?",
    ["Never mind that, my little performer! Speak to Emmett over in the firemakers' area and he will explain the details to you, or you can start straight away by taking your place on the star near him."] = "¡No importa eso, mi pequeño artista! Habla con Emmett en el área de los fogoneros y él te explicará los detalles, o puedes comenzar de inmediato tomando tu lugar en la estrella cerca de él.",
    ["Fire-breathing"] = "escupe fuego",
    ["A daring, colourful event indeed! You must successfully breath fires 6 times, in a multitude of colours!"] = "¡Un evento atrevido y colorido! ¡Debes escupir fuego con éxito 6 veces, en multitud de colores!",
    ["Speak to Sera over in the firemakers' area and she will explain the details to you, or you can start straight away by taking your place on the star near her."] = "Habla con Sera en el área de los fogoneros y ella te explicará los detalles, o puedes comenzar de inmediato tomando tu lugar en la estrella cerca de ella.",
    ["Want to put your skills at sleight of hand to the test, eh? In a world filled with impossible feats, often the most simple are the most amazing."] = "¿Quieres poner a prueba tus habilidades de prestidigitación, verdad? En un mundo lleno de hazañas imposibles, a menudo las más simples son las más sorprendentes.",
    ["You can speak to Teddy, the polar bear, to get more details, or you can start straight away by taking your position on the star near him."] = "Puedes hablar con Teddy, el oso polar, para obtener más detalles, o puedes comenzar de inmediato tomando tu posición en la estrella cercana a él.",
    ["Back"] = "Atrás",
    ["Improving my performance"] = "Mejorando mi desempeño",
    ["Ah, there is so much that goes into being a true virtuoso! The audience is key to any great performance. You must listen to what they want and appease them. They love seeing their requests performed. They also hate repetition, so don't keep doing the same safe move. Be dangerous! Try more difficult moves and who knows, you might succeed. Everything you can do here is rated by difficulty in relation to your skill levels, but they're only recommended levels. You're welcome to attempt anything you like, you're just more likely to succeed if you have the relevant skill level."] = "¡Ah, hay tantas cosas que implica ser un verdadero virtuoso! El público es clave para cualquier gran actuación. Debes escuchar lo que quieren y apaciguarlos. Les encanta ver realizados sus pedidos. También odian la repetición, así que no sigas haciendo el mismo movimiento seguro. ¡Sé peligroso! Prueba movimientos más difíciles y quién sabe, tal vez lo consigas. Todo lo que puedes hacer aquí está clasificado por dificultad en relación a tu skill levels, pero solo son niveles recomendados. Eres bienvenido a intentar lo que quieras, pero es más probable que tengas éxito si tienes el skill level correspondiente.",
    ["What if I can't do more difficult moves? I can't help repeating!"] = "¿Qué pasa si no puedo hacer movimientos más difíciles? ¡No puedo evitar repetir!",
    ["Then perform an emote in between moves! That will make the audience happy; however, don't repeat them. Our audiences are very fickle and HATE repetition. Also, we only give you a point bonus for the first 10 that you perform."] = "¡Entonces realiza un gesto entre movimientos! Eso hará feliz al público; sin embargo, no los repita. Nuestras audiencias son muy volubles y ODIAN la repetición. Además, sólo te damos un bono de puntos por los primeros 10 que realices.",
    ["Isn't there an easier way to improve my performance? The audience can be so demanding."] = "¿No existe una forma más sencilla de mejorar mi rendimiento? El público puede ser muy exigente.",
    ["Certainly. Wear crazy costumes - the crazier the better! I will not tell you which clothes to wear, as it is to the taste of the performer, but do experiment. See what works best for you. For safety reasons, you can only wear the costume we provide for the Agility performance. Also, keep an eye on where the ticket vendor moves to, and who populates our audience. Different locations have different preferences, and that will give you a bonus."] = "Por supuesto. Usa disfraces locos: ¡cuanto más locos, mejor! No te diré qué ropa usar, ya que es del gusto del artista, pero experimenta. Vea qué funciona mejor para usted. Por razones de seguridad, solo puedes usar el disfraz que te proporcionamos para la presentación de Agility. Además, esté atento a dónde se mueve el vendedor de entradas y quiénes forman parte de nuestra audiencia. Diferentes ubicaciones tienen diferentes preferencias y eso te dará una ventaja.",
    ["Thanks for the advice!"] = "¡Gracias por el consejo!",
    ["Would you like to know about anything else?"] = "¿Le gustaría saber algo más?",
    ["[Menu]: Tell me about..."] = "[Menú]: Háblame de...",
    ["The rewards"] = "Las recompensas",
    ["The circus"] = "El circo",
    ["Never mind"] = "No importa",
    ["I want to retrieve a costume."] = "Quiero recuperar un disfraz.",
    ["I want to know more about the rewards."] = "Quiero saber más sobre las recompensas.",
    ["Not that performing isn't great in itself, but what do I get for doing it? You can't expect me to work for free."] = "No es que actuar no sea genial en sí mismo, pero ¿qué gano por hacerlo? No puedes esperar que trabaje gratis.",
    ["What happened to the days when the thrill of performing was enough? Of course I reward my performers, but I work on a performance-related pay method. The better you do, the better I reward you. Your performance itself is a reward, because you gain more experience than you normally would in the skill you perform in. At the end of your performance, I review how well you did and I will reward you with extra experience and a part of a costume."] = "¿Qué pasó con los días en que la emoción de actuar era suficiente? Por supuesto, recompenso a mis artistas, pero trabajo con un método de pago relacionado con el desempeño. Cuanto mejor lo hagas, mejor te recompensaré. Tu actuación en sí es una recompensa, porque obtienes más experiencia de la que normalmente obtendrías en la habilidad que desempeñas. Al final de tu actuación, reviso qué tan bien lo hiciste y te recompensaré con experiencia extra y una parte de un disfraz.",
    ["What costume?"] = "¿Qué disfraz?",
    ["Not just one, but several! For those that simply...put in the minimum effort, I reward them with peasant costume pieces and the occasional giant hand. For those that increasingly put in effort, they get performance costumes. I give out pieces for an acrobat costume, a clown costume and, for those that are truly amazing (like myself), I give out a ringmaster costume!"] = "¡No solo uno, sino varios! Para aquellos que simplemente... ponen el mínimo esfuerzo, los premio con piezas de disfraces de campesinos y alguna que otra mano gigante. Para aquellos que se esfuerzan cada vez más, consiguen trajes de actuación. Reparto piezas para un disfraz de acróbata, un disfraz de payaso y, para aquellos que son realmente increíbles (como yo), ¡reparto un disfraz de maestro de ceremonias!",
    ["That's not too bad, I suppose. I hope mine fits better than yours does."] = "Eso no está tan mal, supongo. Espero que el mío encaje mejor que el tuyo.",
    ["I'd like to see you find a tailor who can make size 115 trousers!"] = "¡Me gustaría verte encontrar un sastre que pueda hacer pantalones talla 115!",
    ["Tell me about the circus. It's a little odd."] = "Háblame del circo. Es un poco extraño.",
    ["It's a circus. It's *supposed* to be odd. What would you like to know?"] = "Es un circo. *Se supone* que es extraño. ¿Qué te gustaría saber?",
    ["Why are there so few people here?"] = "¿Por qué hay tan poca gente aquí?",
    ["Why is there hardly any one here? And why am I your only performer?"] = "¿Por qué casi no hay nadie aquí? ¿Y por qué soy tu único intérprete?",
    ["We are but a new business, and haven't attracted many customers yet. That is why there are so few people in the stands. But with a performer as good as you, we hope to attract more customers and more performers."] = "No somos más que un negocio nuevo y aún no hemos atraído a muchos clientes. Por eso hay tan poca gente en las gradas. Pero con un artista tan bueno como usted, esperamos atraer más clientes y más artistas.",
    ["Where are we?"] = "¿Dónde estamos?",
    ["Ah, we exist within the ticket vendor. We fold space in on itself to fit in something smaller than the space we take up. It's all very complex, but the fairies tell me it's quite easy."] = "Ah, existimos dentro del vendedor de boletos. Doblamos el espacio sobre sí mismo para que quepa algo más pequeño que el espacio que ocupamos. Es todo muy complejo, pero las hadas me dicen que es bastante fácil.",
    ["So, I'm currently folded in space? Is it going to hurt to unfold?"] = "Entonces, ¿actualmente estoy plegado en el espacio? ¿Va a doler desplegarse?",
    ["No, of course not. It's no different to teleporting normally."] = "No, por supuesto que no. No es diferente a teletransportarse normalmente.",
    ["How do I leave the circus? All of the exits are roped off."] = "¿Cómo salgo del circo? Todas las salidas están acordonadas.",
    ["Silly little performer, you were given a golden ticket when you entered Balthazar Beauregard's Big Top Bonanza, yes?"] = "Pequeño artista tonto, te dieron un boleto dorado cuando entraste al Big Top Bonanza de Balthazar Beauregard, ¿no?",
    ["Yes, I did."] = "Sí, lo hice.",
    ["Well, read it! It says you just need to tear it to leave the circus. Tear the ticket and 'POOF', you are gone. Simple as that."] = "Bueno, ¡léelo! Dice que sólo necesitas romperlo para salir del circo. Rompe el billete y 'POOF', te has ido. Así de simple.",
    ["Ah, little performer. Have you lost one of your rewards?"] = "Ah, pequeño artista. ¿Has perdido una de tus recompensas?",
    ["Very well, let's get you some replacements."] = "Muy bien, vamos a conseguirte algunos reemplazos.",
    ["Ahh, you haven't had a ticket. Roll up! Roll up! Get your ticket while it's hot!"] = "Ahh, no has tenido multa. ¡Arremangar! ¡Arremangar! ¡Consigue tu entrada mientras hace calor!",
    ["You receive a free ticket for the raffle."] = "Recibes un boleto gratis para el sorteo.",
    ["What's all this about a raffle?"] = "¿Qué es todo esto de una rifa?",
    ["Roll up! Roll up! Enter my raffle! Win prizes!"] = "¡Enróllate! ¡Arremangar! ¡Participa en mi sorteo! ¡Gana premios!",
    ["Speak to me daily and I'll give you one ticket. You can get another one from Gilly Willikers the clown once a day or from doing a daily challenge."] = "Hablame diariamente y te daré un boleto. Puedes conseguir otro del payaso Gilly Willikers una vez al día o realizando un desafío diario.",
    ["If you've missed a ticket or two, you can use a bond to gain the ability to claim any that you've missed! And any that you might miss in the future!"] = "Si te perdiste uno o dos boletos, ¡puedes usar un bono para poder reclamar los que te perdiste! ¡Y cualquiera que te puedas perder en el futuro!",
    ["Enter your tickets straight away or save them up - there will be one raffle draw daily!"] = "Ingresa tus boletos de inmediato o guárdalos: ¡habrá un sorteo diario!",
    ["Where is Gilly Willikers now?"] = "¿Dónde está Gilly Willikers ahora?",
    ["*(Continues with the hint.)*"] = "*(Continúa con la pista.)*",
    ["I'd like to enter today's raffle."] = "Me gustaría participar en el sorteo de hoy.",
    ["What are the rewards for the raffle?"] = "¿Cuáles son las recompensas del sorteo?",
    ["The prizes for the raffle change each day. If you're interested in something specific then you'll want to come back and enter on that day."] = "Los premios del sorteo cambian cada día. Si está interesado en algo específico, querrá regresar e ingresar ese día.",
    ["Make sure you roll up each day so I can give you your ticket!"] = "¡Asegúrate de llegar todos los días para que pueda darte tu boleto!",
    ["How many tickets have been entered in today's raffle so far?"] = "¿Cuántas entradas han entrado hasta el momento en el sorteo de hoy?",
    ["A total of [number] tickets have been entered today with [number] total prizes available. You haven't entered today's draw. Would you like to?"] = "Hoy se ingresaron un total de boletos [número] con premios totales [número] disponibles. No has participado en el sorteo de hoy. ¿Le gustaría?",
    ["I'd like to enter the raffle."] = "Me gustaría participar en el sorteo.",
    ["You have entered [number] [ticket/tickets] in today's raffle and there have been a total of [number] tickets entered today with [number] total prizes available."] = "Has participado en [número] [ticket/tickets] en el sorteo de hoy y ha habido un total de boletos [número] ingresados hoy con premios totales [número] disponibles.",
    ["Goodbye"] = "Adiós",
    ["Come back soon!"] = "¡Vuelve pronto!",
    ["What's that there? They look like fakes! Give me those!"] = "¿Qué es eso ahí? ¡Parecen falsificaciones! ¡Dame esos!",
    ["Where is Gilly Willikers at the moment?"] = "¿Dónde está Gilly Willikers en este momento?",
    ["It seems he was last seen in Al Kharid."] = "Parece que fue visto por última vez en Al Kharid.",
    ["I believe he's currently visiting Draynor."] = "Creo que actualmente está visitando Draynor.",
    ["He is up in Edgeville apparently."] = "Aparentemente está en Edgeville.",
    ["Hmm, he was seen wandering around Falador's front gate recently."] = "Hmm, recientemente lo vieron deambulando por la puerta principal de Falador.",
    ["He was exploring Lumbridge castle not long ago."] = "No hace mucho estaba explorando el castillo Lumbridge.",
    ["He was spotted around Taverley not long ago."] = "Fue visto en Taverley no hace mucho.",
    ["I'm hearing reports that he is in Varrock."] = "He escuchado informes de que está en Varrock.",
    ["I'm sorry the RuneScape raffle has ended."] = "Lamento que el sorteo de RuneScape haya terminado.",
    ["I'm just here to hand out the last few prizes."] = "Sólo estoy aquí para repartir los últimos premios.",
    ["Do you have a prize for me?"] = "¿Tienes un premio para mí?",
    ["No, nothing for you. Move along."] = "No, nada para ti. Avanzar.",
    ["Unfortunately, the raffle has since been and gone. Try your luck next time."] = "Desafortunadamente, la rifa ya no existe. Prueba suerte la próxima vez.",
    ["The raffle has now ended."] = "El sorteo ya ha finalizado.",
    ["The main part of the raffle is not running at the moment, so Gilly is no longer handing out tickets."] = "La parte principal del sorteo no se realiza en este momento, por lo que Gilly ya no repartirá boletos.",
    ["Hello there...thanks for helping out Trufitus commune with the gods Bwana. We've been able to return to the village thanks to your help."] = "Hola... gracias por ayudar a Trufitus a comunicarse con los dioses Bwana. Hemos podido regresar al pueblo gracias a vuestra ayuda.",
    ["Well, it's funny you should ask that actually, I run the local parcel service to the mainland."] = "Bueno, es curioso que preguntes que, en realidad, dirijo el servicio de paquetería local al continente.",
    ["Parcel service?"] = "¿Servicio de paquetería?",
    ["Yes, we sometimes get asked to send items back to the mainland. We can send items to individuals' bank accounts, for a small fee of course."] = "Sí, a veces nos piden que enviemos artículos al continente. Podemos enviar artículos a cuentas bancarias de particulares, por una pequeña tarifa, por supuesto.",
    ["How much does it cost?"] = "¿Cuánto cuesta?",
    ["It costs 10 trading sticks per item, unfortunately, even stackable items cost the same."] = "Cuesta 10 barras comerciales por artículo; desafortunadamente, incluso los artículos apilables cuestan lo mismo.",
    ["What are trading sticks and how do I get some?"] = "¿Qué son los palos comerciales y cómo los consigo?",
    ["Trading sticks are our local currency, you could perhaps earn some trading sticks by doing some work around the village."] = "Los bastones comerciales son nuestra moneda local. Quizás puedas ganar algunos bastones comerciales trabajando un poco en la aldea.",
    ["Have a chat with Murcaily, I think he was looking for someone to help him, he works near the hardwood grove to the east of Trufitus' hut."] = "Charla con Murcaily, creo que estaba buscando a alguien que lo ayudara, trabaja cerca del bosquecillo de madera al este de la cabaña de Trufitus.",
    ["Can I send a parcel please?"] = "¿Puedo enviar un paquete por favor?",
    ["It costs at least 10 trading sticks to use this service. Sorry but you don't have enough."] = "Cuesta al menos 10 unidades comerciales utilizar este servicio. Lo siento pero no tienes suficiente.",
    ["Of course...which items would you like to send to your bank?"] = "Por supuesto... ¿qué artículos te gustaría enviar a tu banco?",
    ["Is there anything interesting to do here?"] = "¿Hay algo interesante que hacer aquí?",
    ["Is there anything interesting to do around here?"] = "¿Hay algo interesante que hacer por aquí?",
    ["Well, I think that there's some work to be done...perhaps Murcaily can help you. He usually tends to the hardwood grove to the east of Trufitus' hut."] = "Bueno, creo que hay trabajo por hacer... tal vez Murcaily pueda ayudarte. Por lo general, atiende el bosquecillo de madera al este de la cabaña de Trufitus.",
    ["I've been doing some work around the village."] = "He estado trabajando en el pueblo.",
    ["Hey, I've seen you working around the village. You've been doing a lot of good work around here for us. Let me give you something for your trouble."] = "Oye, te he visto trabajando en el pueblo. Has estado haciendo un muy buen trabajo aquí para nosotros. Déjame darte algo por tu molestia.",
    ["I've already given you some trading sticks and I don't have any more on me at the moment. Why not go and talk to some of the other villagers and get some contributions?"] = "Ya te he dado algunos palitos de intercambio y no tengo ninguno más en este momento. ¿Por qué no vas y hablas con algunos de los otros aldeanos y consigues algunas contribuciones?",
    ["You get [number] trading sticks. Your remaining favour totals [percentage]."] = "Obtienes palos comerciales [número]. El favor restante asciende a [percentage].",
    ["Ahhhhhhhh - Get away from me you beast!"] = "Ahhhhhhhh - ¡Aléjate de mí, bestia!",
    ["Ahhhhhhhh!"] = "¡Ahhhhhhhh!",
    ["Ahhhhhhhh - It's a monster!"] = "Ahhhhhhhh - ¡Es un monstruo!",
    ["Waahhhhh! - It's da evil broodoo beast come ta eat my very soul!"] = "¡Waahhhhh! - ¡Es una bestia malvada que viene a comerse mi alma!",
    ["What's the problem... oh, I'm wearing this big scary mask! I'd better take it off before I start talking to the natives."] = "¿Cuál es el problema? ¡Oh, estoy usando esta gran máscara aterradora! Será mejor que me lo quite antes de empezar a hablar con los nativos.",
    ["I'm Rixie, one of the vendors here at the fayre, so you can buy yourself a lovely souvenir to take home with you."] = "Soy Rixie, uno de los vendedores aquí en la feria, así que puedes comprarte un bonito recuerdo para llevártelo a casa.",
    ["How do the portals work?"] = "¿Cómo funcionan los portales?",
    ["They're amazing, aren't they? We had them made by a wizard, a long time ago now. They're splendid things, never had a problem with them."] = "Son increíbles, ¿no? Los hicimos hacer un mago, hace mucho tiempo. Son cosas espléndidas, nunca tuve ningún problema con ellas.",
    ["We simply set them up in the new location for the fayre and they calibrate themselves. It's quite incredible to watch."] = "Simplemente los configuramos en la nueva ubicación de la feria y se calibran solos. Es bastante increíble de ver.",
    ["They seem to know where the most useful places in the near vicinity are and set themselves up to point to there."] = "Parecen saber dónde están los lugares más útiles en las inmediaciones y se disponen a señalarlos.",
    ["It's just my job to work out how many we need. When they stop glowing, were all done."] = "Mi trabajo es calcular cuántos necesitamos. Cuando dejan de brillar, estamos listo.",
    ["How are things going?"] = "¿Cómo van las cosas?",
    ["It's a noisy life, living and working at the fayre, but I wouldn't change it for the world."] = "Es una vida ruidosa, vivir y trabajar en la feria, pero no lo cambiaría por nada del mundo.",
    ["Would you like to buy some Fishing equipment or sell some fish?"] = "¿Te gustaría comprar algún equipo Fishing o vender pescado?",
    ["*(Fishing Guild Store opens)*"] = "*(Se abre la tienda del gremio Fishing)*",
    ["No, thank you."] = "No, gracias.",
    ["*(Dialogue ends)*"] = "*(Termina el diálogo)*",
    ["**Roamin' Rains** Barooooooooo!"] = "**Roamin' Rains** ¡Baroooooooo!",
    ["You have just finished your current Yak Track task: Wandering Yak. Open the Yak Track interface to claim your rewards."] = "Acabas de terminar tu tarea actual de Yak Track: Wandering Yak. Abre la interfaz de Yak Track para reclamar tus recompensas.",
    ["Greetings traveller. Welcome to 'The Hair Of the Dog' Tavern. What can I do you for?"] = "Saludos viajero. Bienvenidos a la Taberna 'El Pelo del Perro'. ¿Para qué puedo hacerte?",
    ["Can I buy a beer?"] = "¿Puedo comprar una cerveza?",
    ["Well that's my speciality! The local brew's named 'Moonlight Mead' and will set you back 5 gold. Whaddya say? Fancy a pint?"] = "¡Bueno, esa es mi especialidad! La cerveza local se llama 'Moonlight Mead' y te costará 5 de oro. ¿Qué dices? ¿Te apetece una pinta?",
    ["Here ya go pal. Enjoy!"] = "Aquí tienes, amigo. ¡Disfrutar!",
    ["I don't have the money on me right now though... can I start a tab?"] = "Aunque no tengo el dinero encima en este momento... ¿puedo iniciar una cuenta?",
    ["You see that sign behind me there?"] = "¿Ves ese cartel detrás de mí?",
    ["The one that says; 'Please Do Not Ask For Credit As Being Attacked By A Large Angry Werewolf Inn Keeper Often Offends'?"] = "El que dice; '¿Por favor, no pida crédito porque ser atacado por un gran hombre lobo enojado Inn Keeper a menudo ofende'?",
    ["Actually, no thanks."] = "En realidad, no, gracias.",
    ["Eh, suit yourself. You're missing out on a genuine taste experience."] = "Eh, haz lo que quieras. Te estás perdiendo una experiencia de sabor genuina.",
    ["Can I hear some gossip?"] = "¿Puedo escuchar algunos chismes?",
    ["Well, I dunno... The village is kind of on the fringe out here, I dunno how up to date the stuff I hear about is..."] = "Bueno, no sé... El pueblo está un poco al margen aquí, no sé qué tan actualizadas están las cosas que escucho...",
    ["Tell me about this village."] = "Háblame de este pueblo.",
    ["You want to know about Canifis? I dunno why, not a lot happens here. We're just your typical everyday down at earth werewolf folk, after all..."] = "¿Quieres saber más sobre Canifis? No sé por qué, aquí no pasan muchas cosas. Después de todo, somos el típico hombre lobo con los pies en la tierra...",
    ["So... everyone here is a werewolf?"] = "Entonces... ¿todos aquí son hombres lobo?",
    ["Yep. We are as Zamorak made us!"] = "Sí. ¡Somos como nos hizo Zamorak!",
    ["You mentioned Zamorak..."] = "Mencionaste a Zamorak...",
    ["Yeah, he's great, isn't he? Every year we hold a big festival to give thanks to Zamorak for keeping us well fed and happy."] = "Sí, es genial, ¿no? Cada año celebramos un gran festival para agradecer a Zamorak por mantenernos bien alimentados y felices.",
    ["I hear over in the west, they worship Saradomin. I don't know why! What's he ever done to help us werewolves, huh?"] = "He oído que en el oeste adoran a Saradomin. ¡No sé por qué! ¿Qué ha hecho para ayudarnos a los hombres lobo, eh?",
    ["His followers say crazy things like 'we shouldn't kill people and eat them'! What's up with that?"] = "¡Sus seguidores dicen cosas locas como '¡no deberíamos matar gente y comérnosla'! ¿Qué pasa con eso?",
    ["...So, when is this festival?"] = "... Entonces, ¿cuándo es este festival?",
    ["Ah, not for a good few months. Come and ask me again nearer the time. I'll keep some meat and mead back from the rest for you, pal."] = "Ah, no hasta dentro de unos meses. Ven y pregúntame de nuevo cuando se acerque el momento. Te guardaré un poco de carne e hidromiel del resto, amigo.",
    ["Yeah, the great god Zamorak! That is another crime to add to Saradomin's slate."] = "¡Sí, el gran dios Zamorak! Ése es otro crimen que añadir a la lista de Saradomin.",
    ["Not long ago, Saradomin defeated Zamorak in a great battle near a place called Lumbridge."] = "No hace mucho, Saradomin derrotó a Zamorak en una gran batalla cerca de un lugar llamado Lumbridge.",
    ["First he poisons our river, then he banishes our god! He really is an evil god!"] = "¡Primero envenena nuestro río y luego destierra a nuestro dios! ¡Él realmente es un dios malvado!",
    ["And he has all these crazy followers who say things like we shouldn't kill people and eat them! What's up with that?"] = "¡Y tiene todos estos seguidores locos que dicen cosas como que no deberíamos matar gente y comérnosla! ¿Qué pasa con eso?",
    ["Anyway, every year we hold a big festival to give thanks to Zamorak for keeping us well fed and happy here."] = "De todos modos, cada año celebramos un gran festival para agradecer a Zamorak por mantenernos bien alimentados y felices aquí.",
    ["...So when is this festival?"] = "... Entonces, ¿cuándo es este festival?",
    ["Aaaah, not for a good few months yet. Come and ask me nearer to time, I'll keep some extra meat and mead from the rest for ya pal."] = "Aaaah, todavía no hasta dentro de unos meses. Ven y pregúntame más cerca del momento, te guardaré un poco de carne e hidromiel del resto, amigo.",
    ["Yeah, he's right there fighting for our rights even now, by somewhere called Lumbridge."] = "Sí, él está ahí luchando por nuestros derechos incluso ahora, en algún lugar llamado Lumbridge.",
    ["I hear that Saradomin is back too. He's truly evil - he poisoned the river to the west!"] = "He oído que Saradomin también ha vuelto. Es realmente malvado: ¡envenenó el río del oeste!",
    ["But Zamorak should put him in place. Zamorak is great, isn't he!"] = "Pero Zamorak debería ponerlo en su lugar. Zamorak es genial, ¿no?",
    ["Every year we hold a big festival to give thanks to Zamorak for keeping us well fed and happy here."] = "Cada año celebramos un gran festival para agradecer a Zamorak por mantenernos bien alimentados y felices aquí.",
    ["Tell me about the land of Morytania."] = "Háblame de la tierra de Morytania.",
    ["Well, I don't know what to tell you really. This village is called Canifis and lies on the border between Morytania and Misthalin. So, we're kind of on the front line if those Saradominists to the west ever decide to attack us."] = "Bueno, no sé qué decirte la verdad. Este pueblo se llama Canifis y se encuentra en el límite entre Morytania y Misthalin. Entonces, estamos en la primera línea si esos saradoministas del oeste alguna vez deciden atacarnos.",
    ["South East of here is the castle of Lord Drakan, our master."] = "Al sureste de aquí se encuentra el castillo de Lord Drakan, nuestro maestro.",
    ["Lord Drakan? Who is that?"] = "¿Señor Drakan? ¿Quién es ese?",
    ["Ahhh... you must be new to these parts if you haven't heard of Lord Drakan! He's the lord of the land, and we all pledge allegiance to him."] = "Ahhh... ¡debes ser nuevo en estos lugares si no has oído hablar de Lord Drakan! Él es el señor de la tierra y todos le juramos lealtad.",
    ["In return for our allegiance, and the tithe of course, he keeps our land safe from any invaders and the Saradominists who want to kill us all."] = "A cambio de nuestra lealtad y el diezmo, por supuesto, él mantiene nuestra tierra a salvo de cualquier invasor y de los saradoministas que quieren matarnos a todos.",
    ["Tithe? What do you mean?"] = "¿Diezmo? ¿Qué quieres decir?",
    ["Ah, well, in return for his protection, we have to give Lord Drakan a share of blood every week. If we don't have any to spare from our hunts, then we need to pick a member of the village to give their life in return for the blood so"] = "Ah, bueno, a cambio de su protección, tenemos que darle a Lord Drakan una porción de sangre cada semana. Si no nos sobra nadie en nuestras cacerías, entonces tendremos que elegir a un miembro de la aldea para que dé su vida a cambio de su sangre.",
    ["that the tithe is fulfilled."] = "que se cumpla el diezmo.",
    ["You mean you kill someone you know in order to meet the tithe?"] = "¿Quieres decir que matas a alguien que conoces para poder pagar el diezmo?",
    ["That's right, but only if we haven't managed to get enough spare blood from our hunts. It's kind of severe if you look at it that way, but frankly, I think the price is fair in return for his protection and his tolerance of our"] = "Así es, pero sólo si no hemos logrado obtener suficiente sangre extra de nuestras cacerías. Es un poco grave si lo miras de esa manera, pero, francamente, creo que el precio es justo a cambio de su protección y su tolerancia hacia nuestra",
    ["village. He could probably kill us all if he wanted us gone, so keeping on his good side is worth the sacrifice to us. Lucky we're not human really!"] = "pueblo. Probablemente podría matarnos a todos si quisiera que nos fuéramos, por lo que mantener su lado bueno vale el sacrificio para nosotros. ¡Qué suerte que en realidad no somos humanos!",
    ["Why's that?"] = "¿Por qué?",
    ["He hates humans! Apparently his brother Draynor is trapped in Misthalin, and adventurous little human wannabe-heroes keep trying to kill him!"] = "¡Odia a los humanos! Aparentemente su hermano Draynor está atrapado en Misthalin, ¡y pequeños aspirantes a héroes humanos aventureros siguen intentando matarlo!",
    ["He hates humans! Apparently long ago his brother Draynor was trapped in Misthalin and lost much of his powers, and was recently killed by some human!"] = "¡Odia a los humanos! Aparentemente hace mucho tiempo su hermano Draynor quedó atrapado en Misthalin y perdió gran parte de sus poderes, ¡y recientemente fue asesinado por un humano!",
    ["Man, I'd hate to be a human around here, that's for sure. Drakan would really enjoy hunting them down and killing them!"] = "Hombre, odiaría ser un humano por aquí, eso es seguro. ¡A Drakan realmente le encantaría cazarlos y matarlos!",
    ["Uh... thanks for the info..."] = "Eh... gracias por la información...",
    ["Tell me about the shopkeepers here."] = "Háblame de los comerciantes de aquí.",
    ["Hmmm? Why, who did you want to hear the gossip about?"] = "¿Mmmm? ¿De quién querías oír los chismes?",
    ["Sbott the Tanner."] = "Sbott o Tanner.",
    ["Tell me what you know about Sbott the Tanner."] = "Cuéntame lo que sabes sobre Sbott y Tanner.",
    ["Hey, I won't hear a word said bad about that guy! He's an honest and hard-working wolf if I ever met one! He charges a lot for his job, but he's one of the best tanners I've ever seen - and I'm over four hundred years old! You"] = "¡Oye, no escucharé ni una palabra mala sobre ese tipo! ¡Es un lobo honesto y trabajador si alguna vez conocí uno! Cobra mucho por su trabajo, pero es uno de los mejores bronceadores que he visto en mi vida... ¡y tengo más de cuatrocientos años! tu",
    ["need stuff tanning, I recommend him!"] = "Necesito cosas para broncearme, ¡lo recomiendo!",
    ["Rufus the food seller."] = "Rufus el vendedor de comida.",
    ["Know anything interesting about Rufus the food seller?"] = "¿Sabes algo interesante sobre Rufus, el vendedor de comida?",
    ["Ah yeah... good old Rufus... He's kind of getting on in years and doesn't like to come out of his wolf form so often, but let me tell you this: that guy is a hunter through and through. You seen how much food he catches in a day? That"] = "Ah, sí... el bueno de Rufus... Está envejeciendo y no le gusta salir de su forma de lobo tan a menudo, pero déjame decirte esto: ese tipo es un cazador de pies a cabeza. ¿Has visto cuánta comida pesca en un día? eso",
    ["takes real dedication! Some of the young pups think that just because a wolf has a bit of grey in his fur then he's past it, but I've seen him put those pups to shame in a hunt! He's a real inspiration to us all!"] = "¡requiere verdadera dedicación! Algunos de los cachorros jóvenes piensan que solo porque un lobo tiene un poco de gris en su pelaje ya lo ha superado, ¡pero lo he visto avergonzar a esos cachorros en una cacería! ¡Es una verdadera inspiración para todos nosotros!",
    ["Barker the clothes seller."] = "Barker el vendedor de ropa.",
    ["Got anything to share about Barker the clothes seller?"] = "¿Tienes algo que compartir sobre Barker, el vendedor de ropa?",
    ["Eh, I don't like the guy much, but you can't knock the quality of his stock. They're some fine quality threads that you can get yourself there."] = "Eh, no me gusta mucho el tipo, pero no se puede reducir la calidad de sus acciones. Son algunos hilos de buena calidad que puedes conseguir tú mismo allí.",
    ["What's wrong with him?"] = "¿Qué le pasa?",
    ["Eh... I can't really tell you to be honest. Something about the guy just gets my hackles up everything he opens his yap, know what I mean?"] = "Eh... Realmente no puedo decírtelo para ser honesto. Hay algo en el tipo que me pone los pelos de punta cada vez que abre su ladrido, ¿sabes a qué me refiero?",
    ["Lucky for you. I can't really explain it, I just don't like the guy. Does great clothes though, you got to give him that."] = "Por suerte para ti. Realmente no puedo explicarlo, simplemente no me gusta el chico. Aunque hace muy buena ropa, tienes que concedérselo.",
    ["Fidelio the general store owner."] = "Fidelio el propietario de general store.",
    ["I bet you have some juicy gossip about Fidelio the general store owner."] = "Apuesto a que tienes algún chisme jugoso sobre Fidelio, el propietario de general store.",
    ["That nut job? Oh sure, we all know about him. He was a real firebrand daredevil when he was much younger, always taking risks to make himself a quick buck... he got himself caught up in the smuggling trade, sneaking over the"] = "¿Ese loco? Oh, claro, todos sabemos sobre él. Era un verdadero temerario cuando era mucho más joven, siempre arriesgándose para ganar dinero rápido... quedó atrapado en el negocio del contrabando, escabulléndose por las calles.",
    ["border into Misthalin and pretending to be a human so he could buy exotic items to sell."] = "bordea Misthalin y finge ser un humano para poder comprar artículos exóticos para vender.",
    ["Exotic items? From Misthalin? Like what?"] = "¿Artículos exóticos? ¿De Misthalin? ¿Cómo qué?",
    ["Oh man, you name it! Flour... buckets... tinderboxes... chisels... he could get the lot! He's been doing it so long now though, his nerves are shot."] = "¡Oh hombre, lo que sea! Harina... cubos... yesqueros... cinceles... ¡podría conseguirlo todo! Pero ya lleva tanto tiempo haciéndolo que tiene los nervios destrozados.",
    ["Nowadays he's a disgrace, he can barely string a sentence together and jumps at his own shadow. Makes you feel ashamed to be a werewolf."] = "Hoy en día es una vergüenza, apenas puede articular una frase y salta hacia su propia sombra. Te da vergüenza ser un hombre lobo.",
    ["Tell me about the temple to the West."] = "Háblame del templo de Occidente.",
    ["Tell me about the temple to the west."] = "Háblame del templo del oeste.",
    ["Well, I'm not old enough to remember the full story behind it, but it was a terrible day for our kingdom when it was built there."] = "Bueno, no tengo edad suficiente para recordar la historia completa detrás de esto, pero fue un día terrible para nuestro reino cuando se construyó allí.",
    ["Apparently Morytania had a once strong kingdom, with lands spreading far further west than they do today, and south into the desert, until the day when a sneak attack by the hated human forces who worship Saradomin burned"] = "Aparentemente, Morytania alguna vez tuvo un reino fuerte, con tierras que se extendían mucho más al oeste de lo que lo hacen hoy, y al sur hacia el desierto, hasta el día en que un ataque furtivo de las odiadas fuerzas humanas que adoran a Saradomin ardió.",
    ["our villages and slaughtered our peoples in mass."] = "nuestras aldeas y masacraron a nuestros pueblos en masa.",
    ["They then cursed the river, so that it would burn our kind should we touch it! Can you imagine? To make an entire river poisonous to us?"] = "¡Luego maldijeron el río para que quemara a los de nuestra especie si lo tocáramos! ¿Te imaginas? ¿Hacer que todo un río sea venenoso para nosotros?",
    ["Luckily they seem to have calmed down somewhat recently, and tend to stay on their side of the river... but the wrong they have done my people will never be forgotten, and will never be forgiven. What is worse is"] = "Afortunadamente parecen haberse calmado un poco recientemente y tienden a permanecer en su lado del río... pero el mal que le han hecho a mi gente nunca será olvidado y nunca será perdonado. Lo que es peor es",
    ["that they then had the nerve to build that gigantic statue on the river mouth to mock the slaughter of our people and the poisoning of our river! I can understand Lord Drakan's hatred for them even if I do not share it to his"] = "¡Que luego tuvieron el descaro de construir esa gigantesca estatua en la desembocadura del río para burlarse de la masacre de nuestra gente y el envenenamiento de nuestro río! Puedo entender el odio de Lord Drakan hacia ellos incluso si no lo comparto con sus",
    ["extent."] = "extensión.",
    ["Luckily, though, the curse has been lifted and we're free to travel into Misthalin for food. Most of us are too afraid of those evil humans, though, so we don't risk it."] = "Afortunadamente, la maldición se ha levantado y podemos viajar a Misthalin en busca de comida. Sin embargo, la mayoría de nosotros tenemos demasiado miedo de esos malvados humanos, así que no nos arriesgamos.",
    ["So you hate humans too?"] = "¿Entonces también odias a los humanos?",
    ["Absolutely! If I ever met one I would gobble him up where he stands! And then chew the bones for dessert!"] = "¡Absolutamente! ¡Si alguna vez conociera a uno, lo devoraría allí mismo! ¡Y luego mastica los huesos como postre!",
    ["Um, okay, thanks, bye."] = "Um, está bien, gracias, adiós.",
    ["Can I hear a story?"] = "¿Puedo escuchar una historia?",
    ["A story? Heh, well the only one I can think of right now is the one my dear old mammy told me as a pup..."] = "¿Una historia? Je, bueno, el único que se me ocurre ahora mismo es el que me dijo mi querida mami cuando era cachorro...",
    ["Now how did it go... Ah yes!"] = "Ahora, ¿cómo te fue? ¡Ah, sí!",
    ["Once upon a time a brave young wolf was walking through a forest, when he came upon a human dressed all in red. 'Aha!' he thought to himself, 'Here's a nice easy meal!' But the human talked to him, and he was always taught to"] = "Érase una vez un joven lobo valiente que caminaba por un bosque, cuando se encontró con un humano vestido todo de rojo. '¡Ajá!' pensó para sí mismo: '¡Aquí tienes una comida fácil y agradable!' Pero el humano habló con él, y siempre le enseñaron a",
    ["be a polite wolf, he spoke back to it."] = "sé un lobo educado, le respondió.",
    ["Well, this cunning human told him that there was a better meal that would not run away in the house in the woods. As the brave young wolf could see that this human was not fully grown, he figured maybe he'd better get a better"] = "Bueno, este astuto humano le dijo que había una comida mejor que la que no se escaparía en la casa del bosque. Cuando el valiente joven lobo pudo ver que este humano no había crecido completamente, pensó que tal vez sería mejor conseguir un mejor",
    ["meal at this house, so he ran as fast as his paws could carry him to the house the human told him about... inside he found an old human lying in bed, and although she was a little tough, as the human was older than he"] = "comida en esta casa, así que corrió tan rápido como sus patas pudieron llevarlo a la casa de la que le habló el humano... dentro encontró a una humana vieja acostada en la cama, y aunque era un poco dura, ya que el humano era mayor que él.",
    ["thought, he had a good meal and decided to sleep it off in the house for awhile. He had not been asleep long though, when he was woken by a knocking at the door. The human in red had followed him to the house! Suspecting a human"] = "pensó, comió bien y decidió dormir un rato en la casa. No llevaba mucho tiempo dormido cuando lo despertaron unos golpes en la puerta. ¡El humano de rojo lo había seguido hasta la casa! Sospechar de un humano",
    ["trap, the brave young wolf put on the old humans clothes and jumped into the bed, so that he could pretend to be human and escape from this terrible trap! Well now, this human dressed in red came into the house, and pretended"] = "trampa, el valiente joven lobo se puso la ropa de los viejos humanos y saltó a la cama, para poder fingir ser humano y escapar de esta terrible trampa. Bueno, este humano vestido de rojo entró en la casa y fingió",
    ["to believe the brave wolf was really a human, and began to talk to him. But then the human started asking strange questions of the wolf, because the human knew that it was not a human at all! The brave young wolf decided to"] = "creyó que el valiente lobo era realmente un humano, y comenzó a hablar con él. Pero entonces el humano empezó a hacerle preguntas extrañas al lobo, ¡porque sabía que no era un humano en absoluto! El joven y valiente lobo decidió",
    ["try and escape, for it was only a young human, and not very strong, so the brave young wolf said he would eat the human if they did not let him escape! As he said this however, the human in red shouted at him: 'Aha! You"] = "intenta escapar, porque era solo un humano joven y no muy fuerte, ¡así que el joven lobo valiente dijo que se comería al humano si no lo dejaban escapar! Sin embargo, mientras decía esto, el humano de rojo le gritó: '¡Ajá! tu",
    ["are a wolf!' and as the human shouted this another bigger human ran into the room from outside! This bigger human was much stronger and was carrying an axe, and the poor young wolf died in this terrible trap made for him by the"] = "¡Eres un lobo!' ¡Y cuando el humano gritó esto, otro humano más grande entró corriendo a la habitación desde afuera! Este humano más grande era mucho más fuerte y llevaba un hacha, y el pobre joven lobo murió en esta terrible trampa que le tendió el",
    ["humans."] = "humanos.",
    ["And do you know what the moral of this story is?"] = "¿Y sabes cuál es la moraleja de esta historia?",
    ["Um... no, not really."] = "Um... no, en realidad no.",
    ["It's 'Never trust humans' of course! My dear old mammy told me that story when I was a pup, and I'm still alive and well to tell it you today!"] = "¡Es 'Nunca confíes en los humanos', por supuesto! Mi querida mami me contó esa historia cuando era un cachorro, ¡y todavía estoy viva y bien para contártela hoy!",
    ["Pretty good story huh?"] = "Bastante buena historia, ¿eh?",
    ["Um... yeah. It was great. Really."] = "Um... sí. Fue genial. En realidad.",
    ["Nothing thanks."] = "Nada, gracias.",
    ["...I don't know why you talked to me if you don't want anything then..."] = "...No sé para qué me hablaste si no quieres nada entonces...",
    ["Here you go!"] = "¡Aquí tienes!",
    ["[Roavar has given you another clue scroll!]"] = "[¡Roavar te ha dado otro pergamino de pistas!]",
    ["Welcome to the Magic Guild Store. Would you like to buy some magic supplies?"] = "Bienvenido a la tienda del gremio Magic. ¿Te gustaría comprar algunos suministros mágicos?",
    ["Can I buy a skillcape of Magic?"] = "¿Puedo comprar un skillcape de Magic?",
    ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins por este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
    ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
    ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
    ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
    ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar algo de espacio en backpack antes de que pueda venderte uno.",
    ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
    ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
    ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
    ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
    ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
    ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
    ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
    ["You say you're a master. Stand straight, let me take a look at you..."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo...",
    ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Magic master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Magic master cape.",
    ["Buy Magic master cape for 120,000 coins?"] = "¿Comprar Magic master cape por 120.000 coins?",
    ["You do not have enough room in your backpack. Please come back when you have some more."] = "No tienes suficiente espacio en tu backpack. Por favor regresa cuando tengas más.",
    ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
    ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
    ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
    ["It looks like you're currently using the old model for your Magic skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Magic skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes elegir usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
    ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
    ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
    ["I would just like to change the Magic skillcape."] = "Solo me gustaría cambiar el Magic skillcape.",
    ["No problem, you will now use the [older/newer] model for your Magic skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Magic skillcape.",
    ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
    ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
    ["I've changed my mind!"] = "¡He cambiado de opinión!",
    ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
    ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
    ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
    ["No, thanks."] = "No, gracias.",
    ["No thank you."] = "No, gracias.",
    ["Hey, can you help me out? I excavated the cave to the south while digging for artefacts. It contains a rare and precious type of clay, but I lack the expertise and equipment to mine the porcelain myself."] = "Oye, ¿puedes ayudarme? Excavé la cueva hacia el sur mientras buscaba artefactos. Contiene un tipo de arcilla raro y precioso, pero carezco de la experiencia y el equipo para extraer la porcelana yo mismo.",
    ["Thanks a ton for helping me out - you're the best! I hope you have a blast reading the book."] = "Muchas gracias por ayudarme, ¡eres el mejor! Espero que te lo pases genial leyendo el libro.",
    ["cond=Before obtaining On the Origin of Centaurs:"] = "cond=Antes de obtener Sobre el origen de los centauros:",
    ["I found a book in the cave when I first discovered it. I'll trade it for 100 porcelain, soft or dry."] = "Encontré un libro en la cueva cuando lo descubrí por primera vez. Lo cambio por 100 de porcelana, blanda o seca.",
    ["[pic=On the Origin of Centaurs detail.png]"] = "[pic=Sobre el origen de los centauros detail.png]",
    ["Tell me about this cave."] = "Háblame de esta cueva.",
    ["Two streams of water flow through the cave, which is rich in porcelain clay deposits. The clay closest to water is softer."] = "Dos corrientes de agua fluyen a través de la cueva, que es rica en depósitos de arcilla porcelánica. La arcilla más cercana al agua es más blanda.",
    ["Everlight's water has special mineral properties which over time have made the clay stronger - both to mine and to work."] = "El agua de Everlight tiene propiedades minerales especiales que con el tiempo han hecho que la arcilla sea más fuerte, tanto para extraer como para trabajar.",
    ["Porcelain could make strong and beautiful pottery, but it requires a skilled hand and strong pickaxe to extract."] = "La porcelana puede producir cerámica fuerte y hermosa, pero requiere una mano experta y un pico fuerte para extraerla.",
    ["cond=With porcelain clay in backpack:"] = "cond=Con arcilla porcelánica en backpack:",
    ["Wow! [number] is impressive! Can you bring me 100 porcelain clay? I'll give you my book in exchange."] = "¡Guau! ¡[número] es impresionante! ¿Puedes traerme 100 de arcilla porcelana? Te daré mi libro a cambio.",
    ["Wow! [number] is impressive!"] = "¡Guau! ¡[número] es impresionante!",
    ["You can have the book I found in exchange for 100 porcelain clay."] = "Puedes quedarte con el libro que encontré a cambio de 100 arcilla de porcelana.",
    ["However, you need a free space in your backpack, so I can give you the book."] = "Sin embargo, necesitas un espacio libre en tu backpack para poder darte el libro.",
    ["[number] porcelain clay is impressive! I don't have anything else to give you in exchange, though."] = "¡La arcilla para porcelana [número] es impresionante! Aunque no tengo nada más que darte a cambio.",
    ["You'll need to be a particularly proficient Miner to gather porcelain clay in that cave."] = "Tendrás que ser un minero particularmente competente para recolectar arcilla de porcelana en esa cueva.",
    ["*(If the player doesn't own a Yak Track Task List:)*"] = "*(Si el player no posee una lista de tareas de Yak Track:)*",
    ["*(Only on first time:)*"] = "*(Sólo la primera vez:)*",
    ["Ho ho barooooooooooooooo."] = "Ho ho baroooooooooooooo.",
    ["Ahhh! It's a talking Reindeer!"] = "¡Ahhh! ¡Es un reno que habla!",
    ["Actually, 'it' is a talking Yak. A Christmas Yak with a big red nose. The best kind of Yak."] = "En realidad, \"eso\" es un yak parlante. Un Yak navideño con una gran nariz roja. El mejor tipo de Yak.",
    ["Ahhh!"] = "¡Ahhh!",
    ["Merry Christmas to you too, Player."] = "Feliz Navidad para ti también, Player.",
    ["How do you know my name!?"] = "¿¡Cómo sabes mi nombre!?",
    ["Santa isn't the only one with a naughty list you know."] = "Santa no es el único con una lista traviesa, ¿sabes?",
    ["So what is a talking Reindeer doing here anyway?"] = "Entonces, ¿qué hace aquí un reno parlante?",
    ["Well, Player. I've been asked to deliver you all a Christmas themed Yak Track of course! To make things extra festive, you'll be tasked with Present Hunts throughout the track."] = "Bueno, Player. ¡Me pidieron que les entregara a todos un Yak Track con temática navideña, por supuesto! Para hacer las cosas más festivas, se te asignará la tarea Present Hunts a lo largo de la pista.",
    ["*(After the first time:)*"] = "*(Después de la primera vez:)*",
    ["Hello again, Player. How can I help you?"] = "Hola de nuevo, Player. ¿Le puedo ayudar en algo?",
    ["How does the Yak Track work?"] = "¿Cómo funciona Yak Track?",
    ["You get to go on an adventure and earn rewards along the way. You can complete tasks to progress along the track."] = "Puedes embarcarte en una aventura y ganar recompensas a lo largo del camino. Puedes completar tareas para progresar a lo largo de la pista.",
    ["You will be given a choice between two tasks at a time, but you only need to complete one of them to progress. If you don't feel like doing either of them then you can use a task skip to move on. As you progress along the track you will earn rewards; Premier Club members and those who have purchased a Premier Pass will earn additional premium rewards. If you purchase a Premier Pass you will receive any premium rewards you would have been eligible for."] = "Podrás elegir entre dos tareas a la vez, pero solo necesitarás completar una de ellas para progresar. Si no tiene ganas de hacer ninguna de las dos, puede saltar tareas para seguir adelante. A medida que avances en la pista, ganarás recompensas; Los miembros de Premier Club y aquellos que hayan comprado un Premier Pass obtendrán recompensas premium adicionales. Si compra un Premier Pass, recibirá todas las recompensas premium para las que hubiera sido elegible.",
    ["Sounds great!"] = "¡Suena genial!",
    ["Is there anything else I can help you with, Player?"] = "¿Hay algo más en lo que pueda ayudarte, Player?",
    ["How do Present Hunt tasks work?"] = "¿Cómo funcionan las tareas de Present Hunt?",
    ["**Robin:** During Present Hunt tasks, you'll find presents scattered all over Gielinor. I've added an extra touch of Christmas magic, so you may find that presents relocate from time to time, just to make things a little different. Each present you collect will bag you a festive goodie, and will progress your active Present Hunt task."] = "**Robin:** Durante las tareas de búsqueda de regalos, encontrarás regalos repartidos por todo Gielinor. He añadido un toque extra de magia navideña, por lo que es posible que descubras que los regalos se reubican de vez en cuando, solo para hacer las cosas un poco diferentes. Cada regalo que recolectes te otorgará un obsequio festivo y avanzará en tu tarea activa de búsqueda de regalos.",
    ["Sounds great! So how do I find these presents?"] = "¡Suena genial! Entonces, ¿cómo encuentro estos regalos?",
    ["Why using a set of Magical jingle bells of course! The bells can be used to obtain location clues for each present. You can also ring the bells, causing them to glow. This will alert you of any nearby presents for the next minute."] = "¿Por qué usar un juego de cascabeles mágicos, por supuesto? Las campanas se pueden utilizar para obtener pistas de ubicación para cada regalo. También puedes tocar las campanas para que brillen. Esto le avisará de cualquier regalo cercano durante el próximo minuto.",
    ["*(If the player doesn't have magical jingle bells:)*"] = "*(Si el player no tiene cascabeles mágicos:)*",
    ["Here, Player, I actually have a set right here for you."] = "Toma, Player, de hecho tengo un juego aquí para ti.",
    ["Robin hands you a set of Magical jingle bells. You can use these to assist you with Present Hunt tasks."] = "Robin te entrega un juego de cascabeles mágicos. Puede utilizarlos para ayudarle con las tareas de Present Hunt.",
    ["Thanks Robin!"] = "¡Gracias Robin!",
    ["Bye, Player. Merry baroooooooooooooooooooo."] = "Adiós, Player. Feliz baroooooooooooooooooo.",
    ["It's nice to see another human face around here."] = "Es agradable ver otro rostro humano por aquí.",
    ["Leave me be, peasant - I am relaxing."] = "Déjame en paz, campesino, me estoy relajando.",
    ["Well, that's nice!"] = "Bueno, ¡eso es genial!",
    ["Do you know who I am?"] = "¿Sabes quién soy?",
    ["I'm sorry, I haven't had the privilege."] = "Lo siento, no he tenido el privilegio.",
    ["I, peasant, am Robin, Master Bowman. I am very famous you know."] = "Yo, campesino, soy Robin, Maestro Bowman. Soy muy famoso, ¿sabes?",
    ["Oh, Robin, Master Bowman, I see."] = "Oh, Robin, Maestro Bowman, ya veo.",
    ["So have you heard of me?"] = "¿Has oído hablar de mí?",
    ["Would you do me a favour? I appear to have run out of bed linen. Can you run along to the innkeeper and get me a clean bedsheet?"] = "¿Me harías un favor? Parece que se me acabó la ropa de cama. ¿Puedes ir corriendo donde el posadero y traerme una sábana limpia?",
    ["Anything for a famous person such as yourself."] = "Cualquier cosa para una persona famosa como tú.",
    ["Now that sounds more like it. Run along now, get me my sheet."] = "Ahora eso suena más parecido. Vete ahora, tráeme mi sábana.",
    ["Go and get it yourself."] = "Ve y consíguelo tú mismo.",
    ["Oh charming. You just can't get the staff these days."] = "Oh, encantador. Simplemente no puedes conseguir el staff en estos días.",
    ["I've brought you a clean bedsheet, Robin."] = "Te he traído una sábana limpia, Robin.",
    ["Well it's about time. Run along now, I need some Robin time."] = "Bueno, ya era hora. Corre ahora, necesito algo de tiempo Robin.",
    ["I've completed all of the Medium Tasks in the Morytania set."] = "He completado todas las tareas medianas del conjunto Morytania.",
    ["So you have. I have some special leggings kept aside for you."] = "Así que sí. Tengo unos leggings especiales reservados para ti.",
    ["[Robin hands you a pair of leggings and a lamp.]"] = "[Robin te entrega un par de mallas y una lámpara.]",
    ["There you go. They're a bit odd, though. I'm not sure I like the way they fit; they feel rather slimy, but at least you can have a ball at the forge in town. Oh, and someone gave me this lamp, but it's not really any use to me."] = "Ahí lo tienes. Aunque son un poco extraños. No estoy seguro de que me guste cómo me quedan; se sienten bastante viscosos, pero al menos puedes divertirte en la fragua de la ciudad. Ah, y alguien me regaló esta lámpara, pero en realidad no me sirve para nada.",
    ["By the way, Lyra says she'll pop down and look after your mushroom patch, and Razmire has been in touch about some planks and more doses to his olive oil. I've also...acquired some of that slime you adventurers"] = "Por cierto, Lyra dice que vendrá y cuidará tu huerto de hongos, y Razmire se ha puesto en contacto para pedir más planks y más dosis de su aceite de oliva. También... adquirí algo de esa baba, aventureros.",
    ["seem to like, and I'll swap you bones for bonemeal as I, uh, made a deal with someone and seem to have rather a lot."] = "Parece que me gusta, y te cambiaré los huesos por harina de huesos, ya que hice un trato con alguien y parece que tengo bastante.",
    ["On top of that there are some storage chests in Mort'ton, near the funeral pyres. You'll be allowed to stockpile any one type of pyre log type in them from now on."] = "Además de eso, hay algunos cofres de almacenamiento en Mort'ton, cerca de las piras funerarias. A partir de ahora, podrás almacenar cualquier tipo de tronco de pira en ellos.",
    ["Ah, the leggings wearer! How are you finding them?"] = "¡Ah, el que usa calzas! ¿Cómo los estás encontrando?",
    ["I lost them."] = "Los perdí.",
    ["Oh, no!"] = "¡Oh, no!",
    ["Never mind, I have another pair. Here..."] = "No importa, tengo otro par. Aquí...",
    ["[Robin hands you a pair of leggings.]"] = "[Robin te entrega un par de leggings.]",
    ["For completing the Morytania set, you are presented with some leggings."] = "Para completar el conjunto Morytania, se te presentan unos leggings.",
    ["These leggings will become increasingly useful as you complete greater difficulties of task sets."] = "Estos leggings serán cada vez más útiles a medida que completes conjuntos de tareas de mayor dificultad.",
    ["You need to complete all Tasks within a particular difficulty set, then you can claim your reward."] = "Debes completar todas las tareas dentro de un conjunto de dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Morytania set's Tasks are simple, some require certain skill levels, and others require quests to be started or completed."] = "Algunas de las tareas del conjunto Morytania son simples, algunas requieren cierto skill levels y otras requieren que se inicien o completen misiones.",
    ["To claim your Morytania set rewards, speak to Hiylik Myna just east of Paterdomus, the Strange Old Man at the Barrows, Old Man Ral in Meiyerditch or myself."] = "Para reclamar las recompensas del conjunto Morytania, habla con Hiylik Myna justo al este de Paterdomus, con Strange Old Man en Barrows, con Old Man Ral en Meiyerditch o conmigo mismo.",
    ["Morytania legs 1"] = "Morytania piernas 1",
    ["Morytania legs 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "Morytania piernas 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["[You're handed another Morytania legs 1.]"] = "[Te entregan otras piernas Morytania 1.]",
    ["Morytania legs 2"] = "Morytania piernas 2",
    ["Morytania legs 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "Morytania piernas 2? Sí, pero me temo que te costaría 2500 coins.",
    ["[You're handed another Morytania legs 2.]"] = "[Te entregan otras piernas Morytania 2.]",
    ["Morytania legs 3"] = "Morytania piernas 3",
    ["Morytania legs 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "Morytania piernas 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["[You're handed another Morytania legs 3.]"] = "[Te entregan otras piernas Morytania 3.]",
    ["Morytania legs 4"] = "Morytania piernas 4",
    ["Morytania legs 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "Morytania piernas 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["[You're handed another Morytania legs 4.]"] = "[Te entregan otras patas Morytania 4.]",
    ["Ask for bonemeal and slime."] = "Pide harina de huesos y baba.",
    ["You said something about slime and bonemeal when you gave me the Morytania legs..."] = "Dijiste algo sobre baba y harina de huesos cuando me diste las piernas de Morytania...",
    ["Oh, so I did. I have [13/26/39] buckets of slime left. Simply give me the bones you wish to exchange."] = "Oh, así lo hice. Me quedan [13/26/39] cubos de baba. Simplemente dame los huesos que deseas intercambiar.",
    ["Ask for information on bonemeal and slime."] = "Pide información sobre harina de huesos y babas.",
    ["You said something about slime and bonemeal when you gave me the Morytania legs. Can you tell me more?"] = "Dijiste algo sobre baba y harina de huesos cuando me diste las piernas de Morytania. ¿Puedes contarme más?",
    ["I suppose so. I will exchange bones you bring me for ground bonemeal, and an equivalent number of buckets of slime."] = "Supongo que sí. Cambiaré los huesos que me traigas por harina de huesos molida y una cantidad equivalente de cubos de baba.",
    ["I've also begun to accept noted bones recently. The bonemeal and buckets of slime I give you in return will also be noted."] = "Recientemente también comencé a aceptar huesos notables. También se anotarán la harina de huesos y los cubos de baba que te daré a cambio.",
    ["So, if I bring you 2 wyvern bones and 3 noted dragon bones, you'll give me 2 lots of wyvern bonemeal and 3 lots of noted dragon bonemeal?"] = "Entonces, si te traigo 2 huesos de wyvern y 3 huesos de dragón famosos, ¿me darás 2 lotes de harina de huesos de wyvern y 3 lotes de harina de huesos de dragón famoso?",
    ["That's right, and don't forget the five free buckets of slime. You can exchange up to 13/26/39 bones daily. Don't forget you'll need free space for the buckets of slime though!"] = "Así es, y no olvides los cinco cubos de limo gratis. Puedes intercambiar hasta 26/13/39 huesos diariamente. ¡No olvides que necesitarás espacio libre para los cubos de baba!",
    ["So, still here then."] = "Entonces, todavía aquí.",
    ["Do you want another game of Runedraw?"] = "¿Quieres otro juego de Runedraw?",
    ["You have a serious gambling problem, you know."] = "Tienes un problema grave con el juego, ¿sabes?",
    ["Go away peasant, you don't have enough free bag space for that!"] = "¡Vete, campesino, no tienes suficiente espacio libre en la bolsa para eso!",
    ["colour=#f00"] = "color=#f00",
    ["What did you really expect to happen?"] = "¿Qué esperabas realmente que sucediera?",
    ["colour=#0f0}}"] = "color=#0f0}}",
    ["colour=#0f0"] = "color=#0f0",
    ["Greetings! I am Roddeck. What can I do for you today?"] = "¡Saludos! Soy Roddeck. ¿Qué puedo hacer por ti hoy?",
    ["Ah, Player, how nice to see you again. What brings you to my humble home?"] = "Ah, Player, que gusto verte de nuevo. ¿Qué te trae a mi humilde hogar?",
    ["My name is Roddeck. I'm just an elderly gentleman of Lumbridge, and this is my house."] = "Mi nombre es Roddeck. Sólo soy un señor mayor de Lumbridge, y esta es mi casa.",
    ["Now, was there anything else you needed?"] = "Ahora, ¿necesitabas algo más?",
    ["About the dragon in your cellar..."] = "Sobre el dragón en tu sótano...",
    ["Oh yes, my pet dragon. Poor thing, it was so sweet when I first hatched it, but it grew completely out of control. That was when I sent the White Knights a message to ask for their help."] = "Oh, sí, mi dragón mascota. Pobrecito, era muy dulce cuando lo nací por primera vez, pero se salió completamente de control. Fue entonces cuando envié un mensaje a los Caballeros Blancos para pedirles ayuda.",
    ["That was really cruel."] = "Eso fue realmente cruel.",
    ["I'm sorry, I had no choice! It had me completely trapped in my own cupboard. Now, was there anything else you wanted?"] = "Lo siento, ¡no tuve otra opción! Me tenía completamente atrapado en mi propio armario. Ahora, ¿había algo más que quisieras?",
    ["Can you offer me any advice?"] = "¿Puedes ofrecerme algún consejo?",
    ["Nothing, thanks."] = "Nada, gracias.",
    ["That was a fun adventure!"] = "¡Fue una aventura divertida!",
    ["Oh? Well, I'm glad you enjoyed yourself. I personally found it somewhat terrifying to be trapped in my own cupboard by a fire-breathing dragon."] = "¿Ah? Bueno, me alegro que hayas disfrutado. Personalmente, me resultó algo aterrador quedar atrapado en mi propio armario por un dragón que escupe fuego.",
    ["Now, was there anything else you wanted?"] = "Ahora, ¿había algo más que quisieras?",
    ["Advice? Certainly, certainly! Use the Task System to help you find your feet, that's my advice."] = "¿Consejo? ¡Ciertamente, ciertamente! Utiliza el sistema de tareas para ayudarte a encontrar tu lugar, ese es mi consejo.",
    ["This kitchen is truly blessed by some divine force!"] = "¡Esta cocina está verdaderamente bendecida por una fuerza divina!",
    ["My knives never seem to dull and I am constantly filled with culinary inspiration!"] = "¡Parece que mis cuchillos nunca se desafilan y estoy constantemente lleno de inspiración culinaria!",
    ["At tier 1, you will gain access to a range, bank and sink in the kitchen. Your knives will also be sharpened and allow you to never fail cutting through spider webs."] = "En el nivel 1, obtendrá acceso a una estufa, un banco y un fregadero en la cocina. Tus cuchillos también estarán afilados y te permitirán cortar nunca las telas de araña.",
    ["At tier 2, you will gain access to a shop stocked with useful items for cooking. You will also have a reduced chance to burn food cooked within the kitchen by 3%."] = "En el nivel 2, obtendrás acceso a una tienda repleta de artículos útiles para cocinar. También tendrá una probabilidad reducida de quemar alimentos cocinados en la cocina en un 3%.",
    ["At tier 3, you will gain access to a soup creation station, benefiting from any workshop XP upgrades in your Player Owned Port. You will also gain 5% additional experience for cooking in the fort kitchen."] = "En el nivel 3, obtendrás acceso a una estación de creación de sopa y te beneficiarás de cualquier mejora de XP del taller en tu puerto propiedad de Player. También obtendrás un 5% de experiencia adicional por cocinar en la cocina del fuerte.",
    ["What happened to that cabbage that was here anyway?"] = "¿Qué pasó con ese repollo que estaba aquí de todos modos?",
    ["It made a fantastic soup!"] = "¡Hizo una sopa fantástica!",
    ["I'm afraid I don't have any surplus stock to sell off."] = "Me temo que no tengo stock excedente para vender.",
    ["Rodney's shop will unlock when you have a tier 2 kitchen."] = "La tienda de Rodney se desbloqueará cuando tengas una cocina de nivel 2.",
    ["The attack."] = "El ataque.",
    ["The nightstick."] = "La porra.",
    ["The face mask."] = "Máscara The face.",
    ["That's all, for now."] = "Eso es todo, por ahora.",
    ["Mr. Murray, I'd like to talk to you about the attack."] = "Sr. Murray, me gustaría hablar con usted sobre el ataque.",
    ["Mr. Murray, I'd like to talk to you about the nightstick."] = "Sr. Murray, me gustaría hablarle sobre la porra.",
    ["Mr. Murray, I'd like to talk to you about the face mask worn by the Defendant."] = "Sr. Murray, me gustaría hablarle sobre la máscara the face que usa el acusado.",
    ["You can positively say that the man in this court is the one that attacked you?"] = "¿Puede decir con seguridad que el hombre de este tribunal es el que le atacó?",
    ["That's all, for now. Thank you."] = "Eso es todo, por ahora. Gracias.",
    ["No problem, guv'nor. I'd just won a pocketful of cash from betting on some ferret racing. As I was counting it, walking down a street in Edgeville, a guy in a mask beat me and took all my cash.So, you reported this terrible attack to the local authorities and identified this man as the attacker?"] = "No hay problema, jefe. Acababa de ganar un montón de dinero apostando en unas carreras de hurones. Mientras lo contaba, caminando por una calle en Edgeville, un tipo enmascarado me golpeó y se llevó todo mi dinero en efectivo. Entonces, ¿denunciaste este terrible ataque a las autoridades locales e identificaste a este hombre como el atacante?",
    ["I sure did. There was no mistaking him."] = "Seguro que sí. No había forma de confundirlo.",
    ["Had you provoked the attacker in any way?"] = "¿Había provocado al atacante de alguna manera?",
    ["Only by holding the cash in my hands, in plain sight. That was enough for the Defendant to jump me, it seems. I didn't even get to have a victory beer."] = "Sólo manteniendo el efectivo en mis manos, a plena vista. Al parecer, eso fue suficiente para que el acusado me atacara. Ni siquiera pude tomar una cerveza de la victoria.",
    ["Can you positively identify this as the weapon used by the Defendant to attack you?"] = "¿Puede identificar positivamente esto como el arma utilizada por el acusado para atacarlo?",
    ["Yes, yes I can. It even matches one of my bruises; the arresting officer checked."] = "Sí, sí puedo. Incluso coincide con uno de mis moretones; comprobó el oficial que lo arrestó.",
    ["Yes, I can. I mean, the mask makes it hard to say for 100%, but I'm definitely 80% sure it's him. Yeah, completely, 80% sure."] = "Sí, puedo. Quiero decir, la máscara hace que sea difícil decirlo al 100%, pero definitivamente estoy 80% seguro de que es él. Sí, completamente, 80% seguro.",
    ["Er, you mean you have never seen his face?"] = "Er, ¿quieres decir que nunca has visto su cara?",
    ["Well, no, not entirely. But black masks aren't all THAT common. So, I'm definitively, positively, 80% sure it's him."] = "Bueno, no, no del todo. Pero las máscaras negras no son TAN comunes. Entonces, estoy definitiva y positivamente, 80% seguro de que es él.",
    ["Have you come to bust me out of here?"] = "¿Has venido a sacarme de aquí?",
    ["Why are you locked up here?"] = "¿Por qué estás encerrado aquí?",
    ["I used to be a part of the group of rogues here, until they accused me of having stolen the gold we had stolen from people who had previously stolen it from someone else."] = "Solía ser parte del grupo de pícaros aquí, hasta que me acusaron de haber robado el oro que le habíamos robado a personas que previamente se lo habían robado a otra persona.",
    ["So they locked you up?"] = "¿Entonces te encerraron?",
    ["Yeah, I kept telling them I didn't steal nothing, but they just refused to believe me."] = "Sí, seguí diciéndoles que no robé nada, pero simplemente se negaron a creerme.",
    ["So, did you steal it?"] = "Entonces, ¿lo robaste?",
    ["That's not the point! What's important is that I said I didn't."] = "¡Ese no es el punto! Lo importante es que dije que no.",
    ["Eh...I see."] = "Eh... ya veo.",
    ["So, have you come to release me or what?"] = "Entonces, ¿has venido a liberarme o qué?",
    ["Yes, I have."] = "Sí, lo tengo.",
    ["No, I haven't."] = "No, no lo he hecho.",
    ["Yes, I have. The doors were locked but I used this magical ring to travel into a parallel realm where all recent changes are opposite to the other side. So by closing the doors there, I opened the doors he-"] = "Sí, lo he hecho. Las puertas estaban cerradas pero usé este anillo mágico para viajar a un reino paralelo donde todos los cambios recientes son opuestos al otro lado. Entonces, al cerrar las puertas allí, abrí las puertas que él-",
    ["Man, did you break the doors open using your head, or what? Regardless, I appreciate the help, man. If you ever need anything, come see me at my place in Varrock. I've got a business you might be interested in."] = "Hombre, ¿rompiste las puertas con la cabeza o qué? De todos modos, agradezco la ayuda, hombre. Si alguna vez necesitas algo, ven a verme a mi casa en Varrock. Tengo un negocio que podría interesarte.",
    ["Whereabouts in Varrock?"] = "¿Dónde está Varrock?",
    ["Assuming it hasn't been occupied by any of the muggers, I've got a place in the not-so-nice parts of town, right behind the archery store. Come and see me there. Anyway, I've got to run now before my so-called companions realise what you and your thick head have done."] = "Suponiendo que no haya sido ocupado por ninguno de los atracadores, tengo un lugar en las partes no tan agradables de la ciudad, justo detrás de la tienda de tiro con arco. Ven a verme allí. De todos modos, tengo que correr ahora antes de que mis supuestos compañeros se den cuenta de lo que tú y tu cabeza dura habéis hecho.",
    ["The prisoner sneaks out of the castle and heads south towards Varrock."] = "El prisionero se escapa del castillo y se dirige al sur hacia Varrock.",
    ["No, I haven't. I'm just here to make sure you haven't gotten your hands on anything to eat."] = "No, no lo he hecho. Sólo estoy aquí para asegurarme de que no hayas conseguido nada para comer.",
    ["Aw, man, I keep telling you, I didn't steal the gold. Just let me out."] = "Oh, hombre, te lo sigo diciendo, yo no robé el oro. Sólo déjame salir.",
    ["Uh...no."] = "Eh...no.",
    ["Welcome to my humble abode. What can I do for you?"] = "Bienvenido a mi humilde morada. ¿Qué puedo hacer por ti?",
    ["You mentioned a business."] = "Mencionaste un negocio.",
    ["Up at the Rogues' Castle, you mentioned a business. What was that about?"] = "Arriba en el Castillo de los Pícaros, mencionaste un negocio. ¿Qué fue eso?",
    ["Ah, yes, I run...what do you call it? Something of a little jewellery business. So, if you happen to come across any unenchanted gold jewellery, I'll gladly take it off your hands for a decent sum of coins."] = "Ah, sí, corro... ¿cómo se llama? Algo así como un pequeño negocio de joyería. Entonces, si te encuentras con alguna joya de oro no encantada, con mucho gusto te la quitaré por una suma decente de coins.",
    ["Only gold jewellery?"] = "¿Solo joyas de oro?",
    ["Correct. I'm not buying anything that isn't beautiful, bright gold. My...eh...clients are picky about that."] = "Correcto. No compraré nada que no sea dorado hermoso y brillante. Mis... eh... los clientes son exigentes con eso.",
    ["I have some right here."] = "Tengo algunos aquí.",
    ["Good, good, just hand it over and I'll see what I can give for it."] = "Bien, bien, solo entrégalo y veré qué puedo dar por él.",
    ["Alright, I'll remember that."] = "Muy bien, lo recordaré.",
    ["Nothing."] = "Nada.",
    ["Sorry, but I don't deal with those. I only trade unenchanted gold jewellery, nothing else. Bring notes if you like, but I prefer the real deal."] = "Lo siento, pero no me ocupo de eso. Sólo vendo joyas de oro no encantadas, nada más. Trae notas si quieres, pero prefiero el trato real.",
    ["I'll give you [price] coins for that [item]. Do we have a deal?"] = "Te daré [price] coins por ese [item]. ¿Tenemos un trato?",
    ["Yes, we do."] = "Sí, lo hacemos.",
    ["It was a pleasure doing business with you. Come back if you have more jewellery to sell."] = "Fue un placer hacer negocios contigo. Vuelve si tienes más joyas para vender.",
    ["No, we do not."] = "No, no lo hacemos.",
    ["Whoa, that's quite a bit of jewellery you've got there! Please try to keep it in amounts smaller than 10,000. Big numbers make my head hurt."] = "¡Vaya, qué joyas tienes ahí! Intente mantenerlo en cantidades inferiores a 10.000. Los grandes números me duelen la cabeza.",
    ["That's a nice [item] you've got there. I'll give you [price] for the bunch. Do we have a deal?"] = "Qué buen [item] tienes ahí. Te daré [price] por el grupo. ¿Tenemos un trato?",
    ["You've got enough money as it is. It usually doesn't bother me, but now you're just being absurd."] = "Ya tienes suficiente dinero. Normalmente no me molesta, pero ahora estás siendo absurdo.",
    ["Hello there, youngster."] = "Hola, jovencito.",
    ["Who are you calling youngster??"] = "¿A quién llamas joven?",
    ["Why you. Unless you have seen the small village of Falador grow into a heaving city like I have of course!"] = "¿Por qué tú? ¡A menos que hayas visto el pequeño pueblo de Falador convertirse en una ciudad bulliciosa como yo, por supuesto!",
    ["Err… no…"] = "Err... no...",
    ["Well then! Enjoy your stay in our mountain home."] = "¡Pues bien! Disfrute de su estancia en nuestra casa de montaña.",
    ["Hello again, youngster."] = "Hola de nuevo, jovencito.",
    ["About your son..."] = "Sobre tu hijo...",
    ["How's your son getting on, now that I've rescued him from the time bubble and the culinaromancer?"] = "¿Cómo le va a tu hijo ahora que lo rescaté de la burbuja del tiempo y del culinaromante?",
    ["My son's fine. I'm not so sure about you, though. Maybe you should lay down in a dark room until the babbling stops."] = "Mi hijo está bien. Aunque no estoy tan seguro de ti. Tal vez deberías acostarte en una habitación oscura hasta que deje de balbucear.",
    ["Can I have another rock cake?"] = "¿Puedo comer otro pastel de roca?",
    ["Aye, I've still got enough ingredients from before, but I'll want 100 coins."] = "Sí, todavía tengo suficientes ingredientes de antes, pero quiero 100 coins.",
    ["Okay, 100 coins will be fine."] = "Bien, 100 coins estarán bien.",
    ["[You hand over 100 gold and Rohak bakes you a rock cake.]"] = "[Entregas 100 de oro y Rohak te hornea un pastel de piedra.]",
    ["I'm not doing it for less, even for a mate."] = "No lo hago por menos, ni siquiera por un compañero.",
    ["Come one, come all, buy my amazing choc ice invention here! Chocolate on the outside. Iced cream on the inside. Oh I also have some chocolate left over from making choc ices which I'm selling too."] = "¡Vengan uno, vengan todos, compren aquí mi increíble invento de helado de chocolate! Chocolate por fuera. Crema helada por dentro. Ah, también me sobró un poco de chocolate de hacer helados de chocolate que también estoy vendiendo.",
    ["Cool, I'd like to buy some."] = "Genial, me gustaría comprar algunos.",
    ["No thanks, I'm not interested."] = "No, gracias, no me interesa.",
    ["How do you stop your icy snacks melting?"] = "¿Cómo evitas que tus bocadillos helados se derritan?",
    ["How do you stop your icy snacks melting? The middle of the desert is the last place I'd expect to see ice."] = "¿Cómo evitas que tus bocadillos helados se derritan? El medio del desierto es el último lugar donde esperaría ver hielo.",
    ["It's quite a surprise, isn't it, my friend? I actually have this special magic box of ice, which I bought for a princely sum from a strange man while adventuring in lands far away. He said it is imbued with some sort of powerful ice"] = "Es toda una sorpresa, ¿no, amigo mío? De hecho, tengo esta caja mágica especial de hielo, que le compré por una suma principesca a un hombre extraño mientras me aventuraba en tierras lejanas. Dijo que está imbuido de una especie de hielo poderoso.",
    ["magic which keeps it cold all the time. I had never seen any ice magic before. It's clearly very rare and powerful, so I felt I had to buy it."] = "magia que lo mantiene frío todo el tiempo. Nunca antes había visto magia de hielo. Es claramente muy raro y poderoso, así que sentí que tenía que comprarlo.",
    ["*(After Crocodile Tears)* Do you sell croc ices?"] = "*(Después de Crocodile Tears)* ¿Venden helados de cocodrilo?",
    ["Do you sell croc ices?"] = "¿Venden helados de cocodrilo?",
    ["Why, yes I do! I've just recently started stocking some for a customer near Menaphos."] = "¡Pues sí! Recientemente comencé a almacenar algunos para un cliente cerca de Menaphos.",
    ["I have to warn you, though - they are VERY moreish. They are so delicious, it's hard to stop at just eating one."] = "Pero tengo que advertirte que son MUY deliciosos. Son tan deliciosos que es difícil limitarse a comer solo uno.",
    ["Though, you should be aware you'll have to deliver them by foot. Any sort of magical interference and they'll melt."] = "Sin embargo, debes tener en cuenta que tendrás que entregarlos a pie. Cualquier tipo de interferencia mágica y se derretirán.",
    ["How's business, now that the curse has gone?"] = "¿Cómo va el negocio ahora que la maldición se ha ido?",
    ["Ohh as good as ever. The people of Nardah seem to have taken well to the taste of chocolate and iced cream combined and, with the curse gone, all my friends are much happier too, so it's all good."] = "Ohh, tan bueno como siempre. La gente de Nardah parece haber acogido bien el sabor del chocolate y el helado combinados y, una vez eliminada la maldición, todos mis amigos también están mucho más felices, así que todo está bien.",
    ["*(After Do No Evil)* Made any more chimp ices?"] = "*(Después de Do No Evil)* ¿Hiciste más helados de chimpancé?",
    ["Made any more chimp ices?"] = "¿Hiciste más helados de chimpancé?",
    ["Ah, no. I sold the intellectual property rights to a group of desert monkeys: non-rectangular shapes are more of a headache than they're worth."] = "Ah, no. Vendí los derechos de propiedad intelectual a un grupo de monos del desierto: las formas no rectangulares causan más dolor de cabeza que valor.",
    ["Can you leave me alone please? I'm trying to study."] = "¿Puedes dejarme en paz, por favor? Estoy intentando estudiar.",
    ["Hey there, fancy taking a trip out to the deep sea fishing hub? Don't worry if you don't have the fishing level required to enter the guild, I know another way in!"] = "Hola, ¿te apetece hacer un viaje al centro de pesca en alta mar? No te preocupes si no tienes el nivel de pesca requerido para ingresar al gremio, ¡conozco otra forma de ingresar!",
    ["What's there to do at the fishing hub?"] = "¿Qué se puede hacer en el centro pesquero?",
    ["Lots of fishing of course! Captain Groggy found such a great location in the deep sea, that he setup shop there. Lots of interesting sea creatures turn up now and then. The hub is also full of fish I've never seen before."] = "¡Mucha pesca, por supuesto! El Capitán Groggy encontró una ubicación tan excelente en las profundidades del mar que instaló su tienda allí. De vez en cuando aparecen muchas criaturas marinas interesantes. El centro también está lleno de peces que nunca antes había visto.",
    ["What are you doing here?"] = "¿Qué haces aquí?",
    ["You see, my brother Goomah lives inside the fishing guild, providing access to the deep sea to all players who can gain access to the guild. I just happened to be in town to visit for a few days and thought, why not provide access to everyone? After all, I do know of a secret passage to the deep sea. Just make sure you don't tell my brother! He won't be best pleased."] = "Verás, mi hermano Goomah vive dentro del gremio de pescadores, brindando acceso a las profundidades del mar a todos los jugadores que pueden acceder al gremio. Casualmente estuve en la ciudad de visita por unos días y pensé: ¿por qué no brindar acceso a todos? Después de todo, conozco un pasaje secreto a las profundidades del mar. ¡Solo asegúrate de no decírselo a mi hermano! No estará muy contento.",
    ["Sure, let's go!"] = "¡Claro, vamos!",
    ["Welcome to deep sea fishing! Feel free to explore, and when you are ready, follow the breadcrumb trail to the swarm fishing area, which you can fish at any level."] = "¡Bienvenidos a la pesca en alta mar! Siéntete libre de explorar y, cuando estés listo, sigue el sendero hasta la zona de pesca enjambre, en la que puedes pescar en cualquier nivel.",
    ["Don't forget, access to the area is time limited, and once the weekend is over, your access will be revoked unless you meet the 68 fishing level requirement."] = "No olvides que el acceso al área es por tiempo limitado y una vez finalizado el fin de semana, tu acceso será revocado a menos que cumplas con el requisito de nivel de pesca 68.",
    ["Hello!"] = "¡Hola!",
    ["Do you have my pie?"] = "¿Tienes mi pastel?",
    ["No, I don't have your pie."] = "No, no tengo tu pastel.",
    ["This is intolerable! I already have plenty to drink, so why would they send a serving [lad/lass] up to see me without my food!"] = "¡Esto es intolerable! Ya tengo mucho para beber, así que ¿por qué enviarían una porción [lad/lass] a verme sin mi comida?",
    ["I don't work here, and even if I did, I'm not a serving [lad/lass]."] = "No trabajo aquí, e incluso si lo hiciera, no soy un [lad/lass] al servicio.",
    ["Such impertinence! Inform the head of this establishment that I want you to be dismissed immediately!"] = "¡Qué impertinencia! ¡Informe al jefe de este establecimiento que quiero que lo despidan inmediatamente!",
    ["But...I don't work here."] = "Pero... No trabajo aquí.",
    ["What's that? You won't do it? Egad, do you not know who you are dealing with, whelp? I'll tan your hide!"] = "¿Qué es eso? ¿No lo harás? Dios mío, ¿no sabes con quién estás tratando, cachorro? ¡Te broncearé la piel!",
    ["Hilarious as it would be to see you try, I still don't work here."] = "Por muy gracioso que sería verte intentarlo, todavía no trabajo aquí.",
    ["By the gods, you're a fiery one! Never have I been so insulted by a lowly servant..."] = "¡Por los dioses, eres ardiente! Nunca me había sentido tan insultado por un humilde sirviente...",
    ["Repeat after me..."] = "Repite conmigo...",
    ["I...don't...work...here."] = "Yo... no... trabajo... aquí.",
    ["I...Don't... Dash it all, you scoundrel! Why didn't you tell me you didn't work here?"] = "Yo... No... ¡Mátalo todo, sinvergüenza! ¿Por qué no me dijiste que no trabajabas aquí?",
    ["I did...several times."] = "Lo hice... varias veces.",
    ["Fetch the head of this establishment! I will have your job for embarrassing me!"] = "¡Trae al director de este establecimiento! ¡Me quitaré tu trabajo por avergonzarme!",
    ["It's like watching a highly obese dog chasing its pudgy tail."] = "Es como ver a un perro muy obeso persiguiendo su cola regordeta.",
    ["No, no, no! I ordered a pie, the best and most expensive pie the cook could make!"] = "¡No, no, no! Pedí un pastel, ¡el mejor y más caro pastel que el cocinero pudo hacer!",
    ["How dare you prod me with that filthy, lower-class trash!"] = "¡Cómo te atreves a pincharme con esa basura sucia de clase baja!",
    ["Sorry. I just slipped."] = "Lo siento. Simplemente resbalé.",
    ["Slipped? Slipped? What kind of excuse is that, you rapscallion?"] = "¿Se resbaló? ¿Resbaló? ¿Qué clase de excusa es esa, bribón?",
    ["A pretty good one, in my opinion."] = "Uno bastante bueno, en mi opinión.",
    ["Begone, before I have you thrashed for your impudence!"] = "¡Vete, antes de que te golpee por tu descaro!",
    ["A lovestruck Romeo sings a street suss serenade..."] = "Un Romeo enamorado canta una serenata callejera...",
    ["That song sounds familiar."] = "Esa canción me suena familiar.",
    ["I've been down here since 2010 and I still haven't gotten used to it."] = "Llevo aquí desde 2010 y todavía no me he acostumbrado.",
    ["Gotten used to what?"] = "¿Acostumbrado a qué?",
    ["All the references."] = "Todas las referencias.",
    ["Up in Gielinor there are loads of references all the time, but no one ever talks about it."] = "Arriba en Gielinor hay un montón de referencias todo el tiempo, pero nadie habla de ello.",
    ["Oh yeah, didn't they remove you from the game because you were too blatant a reference?"] = "Ah, sí, ¿no te sacaron del juego porque eras una referencia demasiado descarada?",
    ["Yes!"] = "¡Sí!",
    ["Down here though it's all pop culture all the time."] = "Aunque aquí abajo todo es cultura pop todo el tiempo.",
    ["Why do you think there are so many references in the game?"] = "¿Por qué crees que hay tantas referencias en el juego?",
    ["There's two good reasons and one bad one, I reckon."] = "Creo que hay dos buenas razones y una mala.",
    ["Good reason one is to show respect for a source of inspiration."] = "Una buena razón es mostrar respeto por una fuente de inspiración.",
    ["All art is imitative, and a well-placed reference acknowledges that fact without disrupting the flow of the work."] = "Todo arte es imitativo y una referencia bien ubicada reconoce ese hecho sin interrumpir el flujo de la obra.",
    ["Oh, like homages?"] = "Oh, ¿te gustan los homenajes?",
    ["Yes, exactly. Good reason two is to create a sense of camaraderie with the audience."] = "Sí, exactamente. La segunda buena razón es crear un sentido de camaradería con la audiencia.",
    ["Including a reference signals to the audience that the author shares their life experiences and loves all the same things."] = "Incluir una referencia le indica a la audiencia que el autor comparte sus experiencias de vida y ama todas las mismas cosas.",
    ["What's the bad reason?"] = "¿Cuál es la mala razón?",
    ["When it's used as a substitute for actual content. Using a lazy reference because you couldn't think of a line yourself is as bad as using a cliche."] = "Cuando se utiliza como sustituto del contenido real. Usar una referencia vaga porque no puedes pensar en una línea por ti mismo es tan malo como usar un cliché.",
    ["One other important thing is, the perfect reference is visible to those who get it, but invisible to those who don't."] = "Otra cosa importante es que la referencia perfecta es visible para quienes la entienden, pero invisible para quienes no.",
    ["Hm?"] = "¿Hm?",
    ["If it's obvious that it's a reference but you don't know what it's referencing, that makes you feel excluded from an in-joke."] = "Si es obvio que es una referencia pero no sabes a qué hace referencia, eso te hace sentir excluido de una broma interna.",
    ["You must hate this quest then?"] = "¿Entonces debes odiar esta misión?",
    ["Yeah..."] = "Sí...",
    ["You've put a lot of thought into this."] = "Has pensado mucho en esto.",
    ["Surprising, isn't it? I'll be honest though, on any other subject I'm still the same randy old dog as always."] = "Sorprendente, ¿no? Seré sincero, en cualquier otro tema sigo siendo el mismo perro cachondo de siempre.",
    ["I heard Juliet had died. Terrible business."] = "Escuché que Juliet había muerto. Pésimo negocio.",
    ["Her cousin and I are getting on well though. Thanks for your help."] = "Aunque su prima y yo nos llevamos bien. Gracias por tu ayuda.",
    ["Hello, traveller. Have a look at my latest range of gnome fashion. Rometti is the ultimate label in gnome high-society."] = "Hola viajero. Echa un vistazo a mi última gama de moda de gnomos. Rometti es el sello definitivo de la alta sociedad gnome.",
    ["Really."] = "De verdad.",
    ["Pastels are all the rage this season."] = "Los pasteles están de moda esta temporada.",
    ["I've no time for fashion."] = "No tengo tiempo para la moda.",
    ["Hmm...I did wonder."] = "Hmm... Me preguntaba.",
    ["Okay then, let's have a look."] = "Bien, entonces echemos un vistazo.",
    ["Hello and welcome to my pie shop, how can I help you?"] = "Hola y bienvenido a mi pastelería, ¿en qué puedo ayudarte?",
    ["I'd like to buy some pies."] = "Me gustaría comprar algunas tartas.",
    ["Do you need any help?"] = "¿Necesitas ayuda?",
    ["Actually I could, you see I'm running out of stock and I don't have time to bake any more pies. Would you be willing to bake me some pies? I'll pay you well for them."] = "En realidad podría, verás, me estoy quedando sin existencias y no tengo tiempo para hornear más pasteles. ¿Estarías dispuesto a hornearme algunos pasteles? Te pagaré bien por ellos.",
    ["Sure, what do you need?"] = "Claro, ¿qué necesitas?",
    ["Great, can you bake me [number] [type of pie] please."] = "Genial, ¿puedes hornearme [número] [type of pie] por favor?",
    ["Sorry, I can't help you."] = "Lo siento, no puedo ayudarte.",
    ["I've got those pies you wanted."] = "Tengo esos pasteles que querías.",
    ["Doesn't look like you have any of the [number] [type of pie] I requested."] = "No parece que tengas ninguno de los [número] [type of pie] que solicité.",
    ["Thank you, if you could bring me the other [remaining number] that'd be great!"] = "Gracias, si pudieras traerme el otro [remaining number], ¡sería genial!",
    ["Thank you very much!"] = "¡Muchas gracias!",
    ["I'm good thanks."] = "Estoy bien, gracias.",
    ["Hello and welcome to my pie shop. My word! That's a nice smelling pie you have. Is it for me?"] = "Hola y bienvenido a mi pastelería. ¡Mi palabra! Qué pastel huele muy bien el que tienes. ¿Es para mí?",
    ["Yes, it is."] = "Sí, lo es.",
    ["Oh, how splendid! Let me take that from you then."] = "¡Oh, qué espléndido! Déjame quitarte eso entonces.",
    ["No, it's for...someone else."] = "No, es para... alguien más.",
    ["Oh, I see. Was there something else you needed?"] = "Oh, ya veo. ¿Había algo más que necesitabas?",
    ["Would you like to buy some Crafting equipment?"] = "¿Te gustaría comprar algún equipo Crafting?",
    ["Let's see what you've got then."] = "Veamos qué tienes entonces.",
    ["No thanks, I've got all the crafting equipment I need."] = "No, gracias. Tengo todo el equipo de artesanía que necesito.",
    ["Okay. Fare well on your travels."] = "Está bien. Que te vaya bien en tus viajes.",
    ["I've come about this treasure trail."] = "He venido por este sendero del tesoro.",
    ["Fair enough. Answer my question and you can continue."] = "Bastante bien. Responde mi pregunta y podrás continuar.",
    ["[Rommik has given you a challenge scroll!]"] = "[¡Rommik te ha dado un pergamino de desafío!]",
    ["Are you sure about that?"] = "¿Estás seguro de eso?",
    ["[Rommik has given you another clue scroll!]"] = "[¡Rommik te ha dado otro pergamino de pistas!]",
    ["Bang on!"] = "¡Adelante!",
    ["Want to buy some supplies for your ship? You'll need supplies to travel on your ship. The greater the distance, the more supplies you'll need."] = "¿Quieres comprar algunos suministros para tu barco? Necesitarás suministros para viajar en tu barco. Cuanto mayor sea la distancia, más suministros necesitarás.",
    ["You have purchased the maximum of [X]/[X] supplies."] = "Ha comprado el máximo de consumibles [X]/[X].",
    ["Supplies: [X]/[X]. How many supplies do you want to purchase? ([X] chimes each)"] = "Suministros: [X]/[X]. ¿Cuántos suministros desea comprar? (campanas [X] cada una)",
    ["Enter a number larger than zero."] = "Introduzca un número mayor que cero.",
    ["You purchased [X] [supply/supplies] for [X] chimes."] = "Compró [X] [supply/supplies] para timbres [X].",
    ["You now have [X]/[X] supplies."] = "Ahora tiene consumibles [X]/[X].",
    ["Confirm purchase: Are you sure you want to purchase [X] [supply/supplies] with [X] chimes?"] = "Confirmar compra: ¿Estás seguro de que deseas comprar [X] [supply/supplies] con timbres [X]?",
    ["Rosie attempts to give you Heartments and a Lovely gift box, but you don't have inventory space."] = "Rosie intenta darte corazones y una preciosa caja de regalo, pero no tienes espacio en el inventario.",
    ["You receive 250 Heartments and a Lovely gift box from Rosie!"] = "¡Recibes 250 corazones y una preciosa caja de regalo de Rosie!",
    ["Get OUT of my WAY!"] = "¡Fuera de mi camino!",
    ["Hey you! Human person thing! I've got a lil' task for you!"] = "¡Hola, tú! ¡Cosa de persona humana! ¡Tengo una pequeña tarea para ti!",
    ["What can I do for you then?"] = "¿Qué puedo hacer por ti entonces?",
    ["Oooo, I want ehm... What did I want again?"] = "Oooo, quiero ehm... ¿Qué quería otra vez?",
    ["You tell me."] = "Dime tú.",
    ["I want... a [item]! What do you mean, what am I going to do with a [item]? That's my business it is!"] = "Quiero... ¡un [item]! ¿Qué quieres decir con qué voy a hacer con un [item]? ¡Ese es mi negocio!",
    ["I didn't say anything..."] = "No dije nada...",
    ["Good, good... now get me a [item] within [number] minutes, and I'll have ehm... I don't know, I'll have something for you!"] = "Bien, bien... ahora tráeme un [item] en [número] minutos, y tendré ehm... No sé, ¡tendré algo para ti!",
    ["Stay away from me!"] = "¡Aléjate de mí!",
    ["Awww, you're just a worthless human, stop wasting my time!"] = "Awww, eres simplemente un humano inútil, ¡deja de hacerme perder el tiempo!",
    ["Got my ehm, ehm... got whatever I asked you to get yet, human?"] = "Ya tengo mi ehm, ehm... ¿Ya tienes lo que te pedí que consiguieras, humano?",
    ["No, and I can't be bothered anymore."] = "No, y ya no me molestan más.",
    ["Bah, you're just a no good lousy human."] = "Bah, no eres más que un pésimo humano.",
    ["No, not yet, what was it again?"] = "No, todavía no, ¿qué fue?",
    ["Sorry, no, not yet... What was it again anyway?"] = "Lo siento, no, todavía no... ¿Qué fue de todos modos?",
    ["Lemme think... ehm... yeah, I want you to get a [item], no questions asked!"] = "Déjame pensar... ehm... sí, quiero que consigas un [item], ¡sin hacer preguntas!",
    ["Look, I've got what you asked me to get!"] = "¡Mira, tengo lo que me pediste!",
    ["Did you now, did you? Ehm."] = "¿Lo hiciste ahora, verdad? Ehm.",
    ["What did I ask you to get again?"] = "¿Qué te pedí que compraras de nuevo?",
    ["You wanted me to get a [item], remember? Well, here you go!"] = "Querías que consiguiera un [item], ¿recuerdas? Bueno, ¡aquí tienes!",
    ["Ooo, that'sh great! Let me get your reward... here, some coins for you."] = "¡Oh, eso es genial! Déjame conseguir tu recompensa... aquí, algo de coins para ti.",
    ["[number]/14 owls tracked"] = "[número]/14 búhos rastreados",
    ["Congratulations! You have completed: 'Birds of Prey' - Track all of the owls for Deryn."] = "¡Felicitaciones! Has completado: 'Aves de presa': rastrea todos los búhos para Deryn.",
    ["You have unlocked the title: 'Player,"] = "Has desbloqueado el título: 'Player,",
    ["You can activate this via the 'Titles' tab in the Customisations interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz de Personalizaciones.",
    ["This is the perfect spot to get a sniff of the freshly baked deathday cakes."] = "Este es el lugar perfecto para oler los pasteles recién horneados del día de la muerte.",
    ["Nice to meet you!"] = "¡Encantado de conocerte!",
    ["Ah, I visited with her Royal Highness for the Diamond Jubilee, and I liked it so much I never left! However, I find myself without an income. Care to hire me, for only [number] coins?"] = "¡Ah, visité a Su Alteza Real para el Jubileo de Diamante y me gustó tanto que nunca me fui! Sin embargo, me encuentro sin ingresos. ¿Quieres contratarme solo por [número] coins?",
    ["I have some experience cooking, and I'm happy to take items to and from the bank."] = "Tengo algo de experiencia cocinando y estaré encantado de llevar artículos hacia y desde el banco.",
    ["I've worked in the Queen's service, almost since I was a lad. A high quality of service expected there, let me tell you!"] = "He trabajado al servicio de la Reina, casi desde que era un muchacho. Allí se espera una alta calidad de servicio, ¡déjame decirte!",
    ["My dear sir, we've been discouraged from taking on more work for now."] = "Mi querido señor, nos han disuadido de realizar más trabajo por ahora.",
    ["What can I do for you?"] = "¿Qué puedo hacer por ti?",
    ["Go the bank/sawmill..."] = "Ir al banco/aserradero...",
    ["Take something to the bank"] = "llevar algo al banco",
    ["Can you take something to the bank for me?"] = "¿Puedes llevarme algo al banco?",
    ["Such tasks seem rather below a guard of the Queen's service, but I will do it. Give the item to me."] = "Esas tareas parecen bastante inferiores a las de una guardia al servicio de la Reina, pero lo haré. Dame el artículo.",
    ["Bring something from the bank"] = "Trae algo del banco",
    ["Here you go. Service worthy of a monarch, I must say."] = "Aquí tienes. Servicio digno de un monarca, debo decir.",
    ["You don't have any of those in your bank."] = "No tienes ninguno de esos en tu banco.",
    ["Take something to the sawmill"] = "Lleva algo al aserradero.",
    ["I'm afraid I can't go to the sawmill; I'd need extra insurance you see."] = "Me temo que no puedo ir al aserradero; Necesitaría un seguro adicional, ya ves.",
    ["Misc..."] = "Varios...",
    ["Make Tea"] = "hacer té",
    ["A most excellent choice! One cuppa, coming up."] = "¡Una excelente elección! Una taza de té, próximamente.",
    ["Do you take milk with your tea?"] = "¿Tomas leche con tu té?",
    ["Yes please"] = "si por favor",
    ["No thanks"] = "No gracias",
    ["Actually I don't want any"] = "En realidad no quiero ninguno",
    ["Actually I don't want any."] = "En realidad no quiero ninguno.",
    ["Serve dinner"] = "servir la cena",
    ["Certainly."] = "Por supuesto.",
    ["Serve drinks"] = "servir bebidas",
    ["Serve drinks please."] = "Sirva bebidas, por favor.",
    ["As long as everything is kept in order."] = "Siempre y cuando todo se mantenga en orden.",
    ["Can I offer you a drink?"] = "¿Puedo ofrecerles una bebida?",
    ["Do enjoy it."] = "Disfrútalo.",
    ["Greet guests"] = "Saludar a los invitados",
    ["Stay at the entrance and greet guests."] = "Quédese en la entrada y salude a los invitados.",
    ["If you like. I am highly trained in greeting etiquette, after all."] = "Si quieres. Después de todo, estoy altamente capacitado en etiqueta de saludo.",
    ["Stop following me"] = "deja de seguirme",
    ["You're fired"] = "estas despedido",
    ["Do you really want to fire your servant?"] = "¿De verdad quieres despedir a tu sirviente?",
    ["You're fired!"] = "¡Estás despedido!",
    ["I shall return to my monarch. It has been a pleasure."] = "Volveré con mi monarca. Ha sido un placer.",
    ["As a member of the Queen's Guard, I cannot be seen handling such... objects."] = "Como miembro de la Guardia de la Reina, no se me puede ver manipulando tales... objetos.",
    ["Excuse me mate, I don't work for free! If you want me to keep working for you, you'll need to pay me 500 coins."] = "Disculpe amigo, ¡no trabajo gratis! Si quieres que siga trabajando para ti, tendrás que pagarme 500 coins.",
    ["Pay servant 500 coins."] = "Pague al servidor 500 coins.",
    ["Pay servant 500 coins and don't ask again."] = "Pague al servidor 500 coins y no vuelva a preguntar.",
    ["Don't Pay."] = "No pagues.",
    ["Fire servant."] = "Servidor de bomberos.",
    ["Excuse me mate, I don't work for free! If you want me to keep working for you, you'll need to pay me 375 coins."] = "Disculpe amigo, ¡no trabajo gratis! Si quieres que siga trabajando para ti, tendrás que pagarme 375 coins.",
    ["*(The following message is seen occasionally:)*"] = "*(El siguiente mensaje se ve ocasionalmente :)*",
    ["Player, I'm glad I found you. King Roald has requested your audience at the dig site to the east of Varrock."] = "Player, me alegro de haberte encontrado. King Roald ha solicitado audiencia en el sitio de excavación al este de Varrock.",
    ["What for?"] = "¿Para qué?",
    ["You're to lead an expedition north-east to a recently discovered land mass."] = "Debes liderar una expedición al noreste hacia una masa de tierra recientemente descubierta.",
    ["He was quite keen for it to be you, you've made quite the impression."] = "Él tenía muchas ganas de que fueras tú, has causado una gran impresión.",
    ["Would you like me to escort you right there?"] = "¿Quieres que te acompañe hasta allí?",
    ["Travel to the Varrock Dig Site?"] = "¿Viaja al sitio de excavación Varrock?",
    ["Let's go."] = "Vamos.",
    ["That's alright. I get it. You don't want my company. Please make your own way there."] = "Está bien. Lo entiendo. No quieres mi compañía. Por favor, dirígete hasta allí.",
    ["*(If the player isn't holding a royal message and has space in backpack:)*"] = "*(Si el player no tiene un mensaje real y tiene espacio en backpack:)*",
    ["You ssshould not be down here..."] = "No deberías estar aquí abajo...",
    ["My name isss unimportant... I live only to ssserve my massster."] = "Mi nombre no tiene importancia... Vivo sólo para servir a mi amo.",
    ["Um... Okay then."] = "Um... Está bien, entonces.",
    ["Why are you down here?"] = "¿Por qué estás aquí abajo?",
    ["Thisss isss where I belong... Beingsss sssuch as myssself cannot abide in the light... It is in the darknesss where we find our homesss..."] = "Aquí es donde pertenezco... Seres como yo no pueden habitar en la luz... Es en la oscuridad donde encontramos nuestros hogares...",
    ["Uh... Okay then."] = "Eh... Está bien, entonces.",
    ["Can I use your anvil?"] = "¿Puedo usar tu yunque?",
    ["Of courssse you may... I have very little ussse for it nowadaysss..."] = "Por supuesto que puedes... Tengo muy poco uso para ello hoy en día...",
    ["Uh... Thanks, I guess."] = "Uh... Gracias, supongo.",
    ["I have no ussse for that..."] = "No tengo ussse para eso...",
    ["Can I ride on your head? I enjoy adventures. I'm hungry!"] = "¿Puedo montar en tu cabeza? Disfruto de las aventuras. ¡Tengo hambre!",
    ["I am happy to exist! Life is wonderful! Also, my nose is red! Wheee!"] = "¡Estoy feliz de existir! ¡La vida es maravillosa! Además, ¡tengo la nariz roja! ¡Vaya!",
    ["I have no idea what's happening. This is the best day ever. I like you!"] = "No tengo idea de lo que está pasando. Este es el mejor día de todos. ¡Me gustas!",
    ["I liked the fire flap creature. Am I a fire flap creature too? Life is an adventure. I like life."] = "Me gustó la criatura con alas de fuego. ¿Soy yo también una criatura con alas de fuego? La vida es una aventura. Me gusta la vida.",
    ["What's this? What's this? There's colour everywhere!"] = "¿Qué es esto? ¿Qué es esto? ¡Hay color por todas partes!",
    ["What's this? There's white things in the air!"] = "¿Qué es esto? ¡Hay cosas blancas en el aire!",
    ["Sorry if I startled you. I'm just trying to impress the parrot inside the ship."] = "Perdón si te asusté. Sólo intento impresionar al loro dentro del barco.",
    ["Hi!"] = "¡Hola!",
    ["Grrreetings frrriend! Welcome to my worrrld famous food emporrrium! All my meats are so frrresh you'd swear you killed them yourrrself!"] = "¡Buenas reuniones amigo! ¡Bienvenido a mi emporrrio gastronómico mundialmente famoso! ¡Todas mis carnes son tan frescas que jurarías que las mataste tú mismo!",
    ["Why do you only sell meats?"] = "¿Por qué solo vendes carnes?",
    ["What? Why, what else would you want to eat? What kind of lycanthrrrope are you anyway?"] = "¿Qué? ¿Qué más te gustaría comer? ¿Qué clase de licántropo eres de todos modos?",
    ["...A vegetarian one?"] = "...¿Uno vegetariano?",
    ["Vegetarrrian...?"] = "¿Vegetariano...?",
    ["Do you sell cooked food?"] = "¿Venden comida cocinada?",
    ["Cooked food? Who would want that? You lose all the flavourrr of the meat when you can't taste the blood!"] = "¿Comida cocinada? ¿Quién querría eso? ¡Se pierde todo el sabor de la carne cuando no se puede saborear la sangre!",
    ["Can I buy some food?"] = "¿Puedo comprar algo de comida?",
    ["Cerrrtainly!"] = "¡Ciertamente!",
    ["Ook. Ah Uh Ah! Ah Uh Ah! Ook Ah Ook!"] = "Bueno. ¡Ah, ah, ah! ¡Ah, ah, ah! ¡Ok, ah, ook!",
    ["You cannot understand what he is saying."] = "No puedes entender lo que está diciendo.",
    ["Perhaps I can be of use?"] = "¿Quizás pueda ser de utilidad?",
    ["Not unless you speak Monkey."] = "No, a menos que hables mono.",
    ["*(One of the following conversations will play:)*"] = "*(Se reproducirá una de las siguientes conversaciones:)*",
    ["*Dialogue 1:*"] = "*Diálogo 1:*",
    ["Ook! Akk! Oookawwwaaa!"] = "¡Ok! ¡Akk! ¡Oookawwwaaa!",
    ["The monkey seems to understand him."] = "El mono parece entenderlo.",
    ["*Dialogue 2:*"] = "*Diálogo 2:*",
    ["Oook! Akkk! Awwwwakkaa!"] = "¡Oook! ¡Akkk! ¡Awwwwakkaa!",
    ["The monkey gives you a banana."] = "El mono te da un plátano.",
    ["Ah, I am a little rusty, it seems. Ook! Akk! Oookawwwaaa!"] = "Ah, parece que estoy un poco oxidado. ¡Ok! ¡Akk! ¡Oookawwwaaa!",
    ["Welcome to Chimpish Airways: the premium monkey carpet station for a monkey in a hurry."] = "Bienvenido a Chimpish Airways: la estación premium de alfombras para monos para monos con prisa.",
    ["I'd like to travel."] = "Me gustaría viajar.",
    ["Of course, all travel is free for you from this hub. Where would you like to go?"] = "Por supuesto, todos los viajes son gratuitos para usted desde este centro. ¿Adónde te gustaría ir?",
    ["What does Ali Morrisane think of this set up?"] = "¿Qué piensa Ali Morrisane de esta configuración?",
    ["He came here, with a monkeyspeak amulet, and accused us of stealing his carpets. He was pretty angry at first, but, with a bit of heavy-handed negotiation, we made a deal."] = "Vino aquí con un amuleto de lengua de mono y nos acusó de robar sus alfombras. Al principio estaba bastante enojado, pero, con un poco de negociación dura, llegamos a un acuerdo.",
    ["A deal?"] = "¿Un trato?",
    ["He collects money on carpets flying to us, and we collect money on the carpets flying towards his stations. Win-win."] = "Él recauda dinero en las alfombras que vuelan hacia nosotros y nosotros recolectamos dinero en las alfombras que vuelan hacia sus estaciones. Todos ganan.",
    ["What's up with your assistant?"] = "¿Qué pasa con tu asistente?",
    ["Oh yeah, he's a bit miserable, isn't he? Last time we ever hire someone by post. I thought humans were supposed to be cutesy and full of energy; if anything, he's driving away business."] = "Oh, sí, es un poco miserable, ¿no? La última vez que contratamos a alguien por correo. Pensé que se suponía que los humanos eran cursis y llenos de energía; en todo caso, está alejando el negocio.",
    ["I'd like to see what's lost and found."] = "Me gustaría ver qué se ha perdido y encontrado.",
    ["Yes, I have found many things that have not been claimed. They fall from people's packs as the carpets fly up. Here, have one. Come back tomorrow for more!"] = "Sí, he encontrado muchas cosas que no han sido reclamadas. Se caen de las mochilas de la gente cuando las alfombras se levantan. Toma, toma uno. ¡Vuelve mañana por más!",
    ["Sorry, I haven't found anything yet. Come back tomorrow."] = "Lo siento, todavía no he encontrado nada. Vuelve mañana.",
    ["I've got to go."] = "Tengo que irme.",
    ["On behalf of Chimpish Airways, we hope to see you soon."] = "En nombre de Chimpish Airways, esperamos verlo pronto.",
    ["Greetings, desert traveller. Do you require the services of Ali Morrisane's flying carpet fleet?"] = "Saludos, viajero del desierto. ¿Necesita los servicios de la flota de alfombras voladoras de Ali Morrisane?",
    ["Tell me about Ali Morrisane."] = "Háblame de Ali Morrisane.",
    ["**Player:** Tell me about Ali Morrisane."] = "**Player:** Háblame de Ali Morrisane.",
    ["What? You haven't heard of Ali Morrisane? Possibly the greatest salesman in all the Kharidian Desert, if not all RuneScape?"] = "¿Qué? ¿No has oído hablar de Ali Morrisane? ¿Posiblemente el mayor vendedor de todo Kharidian Desert, si no de todo RuneScape?",
    ["I can't say that I have, but he must be the ambitious type to set up his own airline."] = "No puedo decir que sí, pero debe ser del tipo ambicioso como para montar su propia aerolínea.",
    ["I reckon that he's trying to take on those gnomes at their own game, and I'd bet good money that he'll probably win."] = "Creo que está intentando enfrentarse a esos gnomos en su propio juego, y apostaría una buena cantidad de dinero a que probablemente ganará.",
    ["Huh? You've lost me."] = "¿Eh? Me has perdido.",
    ["You know, the little guys...the ones that aren't dwarves."] = "Ya sabes, los pequeños... los que no son enanos.",
    ["Yeah, gnomes - I'm with you that far."] = "Sí, gnomos, hasta ahí estoy con vosotros.",
    ["Well, they have already established Gnome Air..."] = "Bueno, ya han establecido Gnome Air...",
    ["Go on."] = "Continúa.",
    ["Anyway, I think Ali M's setup here will prove really successful, and maybe once we're properly established we could compete with those gnomes."] = "De todos modos, creo que la configuración de Ali M aquí resultará realmente exitosa, y tal vez una vez que estemos establecidos adecuadamente podamos competir con esos gnomos.",
    ["I'll watch this space."] = "Vigilaré este espacio.",
    ["Ah, yes, I remember him now. I went on a wild goose chase looking for his nephew."] = "Ah, sí, ahora lo recuerdo. Me embarqué en una búsqueda inútil buscando a su sobrino.",
    ["Ha! No doubt old Ali M instigated the whole thing."] = "¡Ja! Sin duda el viejo Ali M. instigó todo el asunto.",
    ["I had a bit of fun, though. The whole job was quite diverting."] = "Aunque me divertí un poco. Todo el trabajo fue bastante divertido.",
    ["There's never a dull moment around that man. He's always looking for a way to make a quick coin or two."] = "Nunca hay un momento aburrido con ese hombre. Siempre está buscando una manera de ganar una moneda o dos rápidamente.",
    ["Tell me about Ali Morrisane?"] = "¿Cuéntame sobre Ali Morrisane?",
    ["Tell me about this magic carpet fleet?"] = "¿Cuéntame sobre esta flota de alfombras mágicas?",
    ["I want to travel by magic carpet."] = "Quiero viajar en alfombra mágica.",
    ["I have some other questions."] = "Tengo algunas otras preguntas.",
    ["Tell me about this magic carpet fleet."] = "Háblame de esta flota de alfombras mágicas.",
    ["**Player:** Tell me about this magic carpet fleet."] = "**Player:** Háblame de esta flota de alfombras mágicas.",
    ["The latest idea from the great Ali Morrisane. Desert travel will never be the same again."] = "La última idea del gran Ali Morrisane. Los viajes al desierto nunca volverán a ser los mismos.",
    ["So how does it work?"] = "Entonces, ¿cómo funciona?",
    ["The carpet or the whole enterprise?"] = "¿La alfombra o toda la empresa?",
    ["The carpet."] = "La alfombra.",
    ["Tell me about how the carpet works."] = "Cuéntame cómo funciona la alfombra.",
    ["I'm not really too sure; it's just an enchanted rug really, made out of special Ugthanki hair. It flies to whatever destination its owner commands."] = "No estoy muy seguro; En realidad, es solo una alfombra encantada, hecha de cabello especial Ugthanki. Vuela a cualquier destino que le ordene su dueño.",
    ["Are they for sale then?"] = "¿Están a la venta entonces?",
    ["Do you think I'm mad? Do you think that Ali Morrisane would throw his magic carpet monopoly away?"] = "¿Crees que estoy enojado? ¿Crees que Ali Morrisane tiraría por la borda su monopolio de la alfombra mágica?",
    ["Well, perhaps if I offered the right price."] = "Bueno, tal vez si ofreciera el precio correcto.",
    ["Not a hope. Could you imagine the mess there'd be if people were constantly zooming through Al Kharid and Pollnivneach? It would be chaos. This way, we can keep the carpet traffic outside towns and other busy places."] = "No es una esperanza. ¿Te imaginas el desorden que habría si la gente estuviera constantemente revisando Al Kharid y Pollnivneach? Sería un caos. De esta manera podemos mantener el tráfico de alfombras fuera de las ciudades y otros lugares concurridos.",
    ["I suppose getting stuck in a carpet jam could get a bit tiresome."] = "Supongo que quedar atrapado en un atasco de alfombras puede resultar un poco aburrido.",
    ["Just think of the friction burns you would get if you were in a carpet crash."] = "Solo piense en las quemaduras por fricción que sufriría si tuviera un accidente con una alfombra.",
    ["The enterprise."] = "La empresa.",
    ["Tell me about the enterprise."] = "Cuéntame sobre la empresa.",
    ["It's quite simple really. Ali Morrisane has hired myself and a few others to set up carpet stations at some of the desert's more populated places and run flights between the stations."] = "En realidad, es bastante simple. Ali Morrisane nos contrató a mí y a algunas otras personas para instalar estaciones de alfombras en algunos de los lugares más poblados del desierto y realizar vuelos entre las estaciones.",
    ["So why has he limited the service to just the desert."] = "Entonces, ¿por qué ha limitado el servicio solo al desierto?",
    ["I don't think Ali is prepared to take on Gnome Air just yet. Their gliders are much faster than our carpets. Besides that, I think we are in the short-haul business, something that would only work in harsh conditions like the desert."] = "No creo que Ali esté preparado para enfrentarse a Gnome Air todavía. Sus planeadores son mucho más rápidos que nuestras alfombras. Además de eso, creo que estamos en el negocio de las distancias cortas, algo que sólo funcionaría en condiciones duras como el desierto.",
    ["Why is that?"] = "¿Por qué?",
    ["I suppose because people would just walk. Getting lost isn't too much of a problem generally, but it's a different matter when you're in the middle of the Kharidian Desert with a dry waterskin and no idea which direction to go in."] = "Supongo que porque la gente simplemente caminaba. Perderse no es un gran problema en general, pero es diferente cuando estás en medio del Kharidian Desert con un odre de agua seco y sin idea de qué dirección tomar.",
    ["You're right, I guess. How's the business going?"] = "Tienes razón, supongo. ¿Cómo va el negocio?",
    ["Not too bad. The hubs are generally quite busy, but the stations in Uzer and the Bedabin Camp could do with a bit more traffic."] = "No está tan mal. Los centros de conexión suelen estar bastante concurridos, pero a las estaciones de Uzer y Bedabin Camp les vendría bien un poco más de tráfico.",
    ["A growth market, I guess."] = "Un mercado en crecimiento, supongo.",
    ["No, but I had some questions."] = "No, pero tenía algunas preguntas.",
    ["**Player:** I have some other questions."] = "**Player:** Tengo algunas otras preguntas.",
    ["I'll help you as much as I can."] = "Te ayudaré tanto como pueda.",
    ["Well, this is a good position for desert traffic. Shantay seems to have a nice little money-spinner setup, but I reckon this could turn out even better."] = "Bueno, esta es una buena posición para el tráfico del desierto. Shantay parece tener una pequeña y agradable configuración para generar dinero, pero creo que esto podría resultar aún mejor.",
    ["Besides the obvious of me looking after this station? I'm trying to figure out how these Tentis manage to cultivate such delicious pineapples."] = "¿Además de lo obvio de que yo cuide esta estación? Estoy tratando de descubrir cómo estos Tentis logran cultivar piñas tan deliciosas.",
    ["You might not realise it, but this is quite a busy station."] = "Puede que no te des cuenta, pero ésta es una estación bastante concurrida.",
    ["Who would want to come here?"] = "¿Quién querría venir aquí?",
    ["Well, you for one, and besides that we get quite a few archaeologists passing through to examine the golem."] = "Bueno, tú por ejemplo, y además de eso, tenemos bastantes arqueólogos que pasan para examinar el golem.",
    ["Well, Pollnivneach is the ideal location for setting up a carpet station."] = "Bueno, Pollnivneach es el lugar ideal para instalar una estación de alfombras.",
    ["It's located halfway between Al Kharid and the Menaphite cities, and close to Nardah too, so we get more than enough traffic to keep the business running."] = "Está ubicado a medio camino entre Al Kharid y las ciudades menafitas, y también cerca de Nardah, por lo que tenemos tráfico más que suficiente para mantener el negocio en funcionamiento.",
    ["I work here renting out magic carpets. I'm from Pollnivneach, so it is a handy job. I don't have to commute too far to work every day."] = "Trabajo aquí alquilando alfombras mágicas. Soy de Pollnivneach, por lo que es un trabajo útil. No tengo que viajar demasiado para ir a trabajar todos los días.",
    ["What's your name then?"] = "¿Cómo te llamas entonces?",
    ["Malak. Not the most remarkable of names, not that it matters, you see everyone in town knows me as Flash."] = "Malak. No es el nombre más notable, no es que importe, verás, todos en la ciudad me conocen como Flash.",
    ["Right."] = "Correcto.",
    ["I'd prefer to be running one of the carpet stations at a hub such as Pollnivneach. I was a bit slow off the mark to get that gig, though. Still, business in Nardah isn't bad for a terminal. At least people come here for the bank and to see the herbalist."] = "Preferiría administrar una de las estaciones de alfombras en un centro como Pollnivneach. Sin embargo, tardé un poco en conseguir ese trabajo. Aún así, el negocio en Nardah no está mal para un terminal. Al menos la gente viene aquí por el banco y por el herbolario.",
    ["Until recently I was looking after one of the busiest carpet stations, but that all changed once Menaphos closed its gates. Right now I have to fill my day trying to come up with reasons why Ali M should keep this place open."] = "Hasta hace poco estaba cuidando una de las estaciones de alfombras más concurridas, pero todo eso cambió una vez que Menaphos cerró sus puertas. Ahora tengo que ocupar mi día tratando de encontrar razones por las que Ali M debería mantener este lugar abierto.",
    ["Have you come up with any good ideas?"] = "¿Se te ha ocurrido alguna buena idea?",
    ["Not really. I have noticed that you were allowed entry so I can only hope that the Pharaoh is getting closer to opening the gates again."] = "En realidad, no. Me di cuenta de que se te permitió la entrada, así que sólo puedo esperar que el faraón esté cada vez más cerca de abrir las puertas nuevamente.",
    ["Do you know why the gates have been locked?"] = "¿Sabes por qué se han cerrado las puertas?",
    ["I'm totally clueless, though it may have something to do with Sophanem. Word has it that there has been some strange goings on there, something to do with Icthlarin's priests."] = "No tengo ni idea, aunque puede que tenga algo que ver con Sophanem. Se dice que han ocurrido algunos sucesos extraños allí, algo que tiene que ver con los sacerdotes de Icthlarin.",
    ["I look after the carpet station here. The place is a bit dead, though. Ha! Hoho, I'm just too much."] = "Aquí cuido la estación de alfombras. Aunque el lugar está un poco muerto. Ja! Hoho, soy demasiado.",
    ["You know, Sophanem - city of the dead and all that?"] = "Ya sabes, Sophanem, ¿la ciudad de los muertos y todo eso?",
    ["Aw, come on, the joke wasn't that bad."] = "Oh, vamos, el chiste no fue tan malo.",
    ["Is that your pet monkey nearby?"] = "¿Está cerca tu mono mascota?",
    ["He's his own monkey, he does whatever suits him, a total nuisance."] = "Es su propio mono, hace lo que le conviene, un total fastidio.",
    ["I detect a degree of hostility being directed towards the monkey."] = "Detecto cierto grado de hostilidad hacia el mono.",
    ["I shouldn't say this really, but sometimes I begin to question some of Ali Morrisane's ideas. He says that associating a monkey with any product will increase sales. I just don't know what will be next!"] = "No debería decir esto realmente, pero a veces empiezo a cuestionar algunas de las ideas de Ali Morrisane. Dice que asociar un mono con cualquier producto aumentará las ventas. ¡Simplemente no sé qué será lo próximo!",
    ["Frogs?"] = "¿Ranas?",
    ["I doubt it; amphibians don't have the same cutesy factor as monkeys."] = "Lo dudo; Los anfibios no tienen el mismo factor cursi que los monos.",
    ["I'm confused. I thought you didn't like monkeys."] = "Estoy confundido. Pensé que no te gustaban los monos.",
    ["I don't dislike monkeys, it's just THAT monkey. I don't know, I might just be paranoid, but I think he's, well...evil."] = "No me desagradan los monos, es simplemente ESE mono. No lo sé, puede que esté paranoico, pero creo que él es, bueno... malvado.",
    ["Hmm, interesting."] = "Mmmm, interesante.",
    ["Hang on a second, I have an amulet of monkeyspeak in my bank. Perhaps I could get it and see what it has to say for itself."] = "Espera un segundo, tengo un amuleto de mono en mi banco. Quizás pueda conseguirlo y ver qué tiene que decir por sí mismo.",
    ["Hang on a second, I have an amulet of monkeyspeak in my bag. Perhaps I could have a word with him."] = "Espera un segundo, tengo un amuleto de mono en mi bolso. Quizás podría hablar con él.",
    ["Would you? It sometimes gives me these stares... ~A visible shiver runs down his back."] = "¿Lo harías? A veces me lanza estas miradas... ~Un escalofrío visible recorre su espalda.",
    ["I would be really grateful if you could get that monkey off my back."] = "Te agradecería mucho si pudieras quitarme ese mono de encima.",
    ["Where did you get that hat?"] = "¿De dónde sacaste ese sombrero?",
    ["My fez? I got it from Ali Morrisane; it's a uniform of sorts. Apparently it makes us more visible, but I'm not too sure about it."] = "¿Mi fez? Lo obtuve de Ali Morrisane; es una especie de uniforme. Al parecer nos hace más visibles, pero no estoy muy seguro de ello.",
    ["Well, it is quite distinctive."] = "Bueno, es bastante distintivo.",
    ["Do you like it? I haven't really made my mind up about it yet. You see it's not all that practical for desert conditions."] = "¿Te gusta? Realmente todavía no me he decidido al respecto. Verá, no es tan práctico para las condiciones del desierto.",
    ["How so?"] = "¿Cómo es eso?",
    ["Well, it doesn't keep the sun out of my eyes and after a while sitting out in the desert they really begin to burn."] = "Bueno, no protege el sol de mis ojos y después de un rato sentados en el desierto, realmente empiezan a arder.",
    ["*(If the player has completed at least the easy Desert tasks)* I'd like to see what's lost and found."] = "*(Si el player ha completado al menos las tareas fáciles del Desierto)* Me gustaría ver qué se ha perdido y encontrado.",
    ["Sorry I don't have anything to give you."] = "Lo siento, no tengo nada que darte.",
    ["I'm also after some Spiders, in fact I'll buy up to [number] more while I'm here."] = "También busco algunas arañas; de hecho, compraré hasta [número] más mientras esté aquí.",
    ["Are you sure you want me to take all the Spiders you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me lleve todas las arañas que tienes? No aceptaré ninguno de tus favoritos.",
    ["Sell all of your spiders?"] = "¿Vender todas tus arañas?",
    ["Would you like to try some fine Miscellanian ale, your Royal Highness?"] = "¿Le gustaría probar una buena cerveza miscelánea, Alteza Real?",
    ["Well I say Miscellanian, but it's actually brewed on the mainland."] = "Bueno, digo miscelánea, pero en realidad se elabora en el continente.",
    ["Would you like to try some anyway?"] = "¿Te gustaría probar algunos de todos modos?",
    ["What's it like living down here?"] = "¿Cómo es vivir aquí abajo?",
    ["Business is booming!"] = "¡El negocio está en auge!",
    ["Now, if only I hadn't taken a loss to the beer I sold to those teenagers."] = "Ahora, si tan solo no hubiera sufrido una pérdida con la cerveza que les vendí a esos adolescentes.",
    ["I'm doing the NovtumberFest Bar crawl."] = "Estoy haciendo el recorrido por el bar NovtumberFest.",
    ["Aha, it is my pleasure to help you! you'll be after a cider! It'll cost you 2 coins."] = "¡Ajá, es un placer ayudarte! ¡Estarás detrás de una sidra! Te costará 2 coins.",
    ["You have completed one of the tasks on your bar crawl card!"] = "¡Has completado una de las tareas en tu tarjeta de rastreo de bares!",
    ["Have you ever thought that, when you examine an item, that item is also examining you?"] = "¿Alguna vez has pensado que, cuando examinas un objeto, ese objeto también te está examinando a ti?",
    ["I can't say it's ever occurred to me."] = "No puedo decir que alguna vez se me haya ocurrido.",
    ["How can I succeed in combat?"] = "¿Cómo puedo tener éxito en el combate?",
    ["You must lash out with every limb, like the octopus who plays the bongos."] = "Debes arremeter con cada extremidad, como el pulpo que toca los bongos.",
    ["I thought it was the penguins that played the bongos?"] = "Pensé que eran los pingüinos los que tocaban los bongos.",
    ["Only during 'Happy Hour."] = "Solo durante la 'Hora feliz'.",
    ["What do you want to do now?"] = "¿Qué quieres hacer ahora?",
    ["Seeking wisdom is most fulfilling. It is sometimes disguised as a pebble in your shoe, or a baguette, but it is there."] = "Buscar la sabiduría es lo más gratificante. A veces se disfraza de una piedra en el zapato o de una barra de pan, pero está ahí.",
    ["I'll keep my eyes open."] = "Mantendré los ojos abiertos.",
    ["Hmm, I'm not sure I feel like training today."] = "Hmm, no estoy seguro de tener ganas de entrenar hoy.",
    ["He who questions training only trains himself at asking questions."] = "Quien cuestiona la formación sólo se entrena para hacer preguntas.",
    ["Welcome to the Runecrafting Guild."] = "Bienvenido a Runecrafting Guild.",
    ["What is this place?"] = "¿Qué es este lugar?",
    ["This is the Runecrafting Guild, as I said. After the secret of Runecrafting was re-discovered, I set up the guild as a place for the most advanced runecrafters to work together."] = "Este es el Runecrafting Guild, como dije. Después de que se redescubriera el secreto de Runecrafting, creé el gremio como un lugar para que los creadores de runas más avanzados trabajaran juntos.",
    ["Work together towards what?"] = "¿Trabajar juntos para qué?",
    ["Towards a greater understanding of Runecrafting, of course. The basics of Runecrafting may have been re-discovered, but many of the secrets of the first Wizards' Tower remain unknown."] = "Hacia una mayor comprensión de Runecrafting, por supuesto. Es posible que se hayan redescubierto los conceptos básicos de Runecrafting, pero muchos de los secretos del primer Wizards' Tower siguen siendo desconocidos.",
    ["What secrets?"] = "¿Qué secretos?",
    ["Oh, nothing to interest an adventurer such as yourself, I'm sure."] = "Oh, nada que pueda interesarle a un aventurero como tú, estoy seguro.",
    ["I'm interested."] = "Estoy interesado.",
    ["We all have our projects, adventurer. Acantha and Vief are happy to involve junior runecrafters in their feud, but others prefer to keep their research private until it is revealed. An idea may be subjected to cruel ridicule if it is aired prematurely. you must forgive me if I am not so forthcoming again."] = "Todos tenemos nuestros proyectos, aventurero. Acantha y Vief están felices de involucrar a los creadores de runas jóvenes en su disputa, pero otros prefieren mantener su investigación en privado hasta que se revele. Una idea puede ser objeto de cruel ridículo si se ventila prematuramente. Debes perdonarme si no vuelvo a ser tan comunicativo.",
    ["Go on, tell me."] = "Continúa, cuéntamelo.",
    ["Leave me be!"] = "¡Déjame en paz!",
    ["Acantha and Vief are hardly working together!"] = "¡Acantha y Vief difícilmente trabajan juntos!",
    ["Aren't they? They think their debate about orb colour is so important, but do you really think it matters which team you join?"] = "¿No es así? Creen que su debate sobre el color del orbe es muy importante, pero ¿realmente crees que importa a qué equipo te unas?",
    ["Of course it matters!"] = "¡Por supuesto que importa!",
    ["Of course it does, of course it does. Be careful which team you join, then. I'll accept your reward tokens, either way."] = "Por supuesto que sí, por supuesto que sí. Entonces ten cuidado a qué equipo te unes. Aceptaré tus fichas de recompensa, de cualquier manera.",
    ["No, I suppose not."] = "No, supongo que no.",
    ["No. The important thing is that orbs get pushed back into the altars, whatever colour they are."] = "No. Lo importante es que los orbes sean empujados de regreso a los altares, sin importar el color que sean.",
    ["Where are we, exactly?"] = "¿Dónde estamos exactamente?",
    ["You will notice that, whenever you use a runecrafting altar, you enter another place: a self-contained island, or a cave, or some other place, which contains the true altar. These temples are not exactly in runescape. they are pocket dimensions unto themselves: areas of folded space created by the energy of the rune altar."] = "Notarás que, cada vez que usas un altar de creación de runas, ingresas a otro lugar: una isla autónoma, una cueva o algún otro lugar que contenga el verdadero altar. Estos templos no están exactamente en runescape. son dimensiones de bolsillo en sí mismas: áreas de espacio plegado creado por la energía del altar de las runas.",
    ["so, we're in something similar?"] = "Entonces, ¿estamos en algo similar?",
    ["Quite right. This is a shadow of the Wizards' Tower, created by own magic. What better place to study the mysteries of runecrafting?"] = "Muy cierto. Esta es una sombra del Wizards' Tower, creada por propia magia. ¿Qué mejor lugar para estudiar los misterios de la creación de runas?",
    ["What does that have to do with the guild?"] = "¿Qué tiene eso que ver con el gremio?",
    ["Don't you see? The Runecrafting Guild exists in a similar pocket dimension, created by our own magic. What better place to study the mysteries of runecrafting?"] = "¿No lo ves? El Runecrafting Guild existe en una dimensión de bolsillo similar, creada por nuestra propia magia. ¿Qué mejor lugar para estudiar los misterios de la creación de runas?",
    ["What can I do here?"] = "¿Qué puedo hacer aquí?",
    ["Wizard Acantha and Wizard Vief are running The Great Orb Project. It requires a large number of runecrafters, so you should speak with them if you want something to do."] = "Wizard Acantha y Wizard Vief están ejecutando The Great Orb Project. Requiere una gran cantidad de creadores de runas, por lo que debes hablar con ellos si quieres hacer algo.",
    ["Tell me about Acantha and Vief's project."] = "Cuéntame sobre el proyecto de Acantha y Vief.",
    ["The Orb proj...I beg your pardon, The Great Orb Project? It's truly fascinating. Wizard Acantha and Vief have found that energy energy leaks out of some of the Runecrafting altars. They are recruiting teams of experienced runecrafters, such as yourself, to force the energy back in. Join one of the teams by speaking to Wizard Acantha or Wizard Vief. When the Wizards have enough helpers, I will open a portal to the Air Altar. The energy appears in the form of floating orbs. these can be moved by means of wands that attract or repel them. Acantha or Vief will give you one of each wand. Your goal is to move the correct colour orb to the altar stone, while keeping the other orbs away. Wizard Acantha favours the green orbs, while Wizard Vief favours the yellow ones. You will also have a third wand, which allows you to make magical barriers to block the opposing team's orbs. After two minutes, the team that has absorbed the most orbs wins that altar. I then open a portal to the next altar in the sequence. After you have visited all eight altars, you will be returned hear."] = "El proyecto Orb...Le pido perdón, ¿El Gran Proyecto Orb? Es realmente fascinante. Wizard Acantha y Vief han descubierto que la energía se escapa de algunos de los altares de Runecrafting. Están reclutando equipos de creadores de runas experimentados, como usted, para forzar el regreso de la energía. Únase a uno de los equipos hablando con Wizard Acantha o Wizard Vief. Cuando los Magos tengan suficientes ayudantes, abriré un portal al Altar del Aire. La energía aparece en forma de orbes flotantes. estos se pueden mover mediante varitas que los atraen o repelen. Acantha o Vief te darán una de cada varita. Tu objetivo es mover el orbe del color correcto a la piedra del altar, mientras mantienes alejados los otros orbes. Wizard Acantha favorece los orbes verdes, mientras que Wizard Vief favorece los amarillos. También tendrás una tercera varita, que te permitirá crear barreras mágicas para bloquear los orbes del equipo contrario. Después de dos minutos, el equipo que haya absorbido más orbes gana ese altar. Luego abro un portal al siguiente altar de la secuencia. Después de haber visitado los ocho altares, volverá a escuchar.",
    ["What is in it for me?"] = "¿Qué gano yo con esto?",
    ["A fair question. we have agreed on a token scheme that allows you to choose from several rewards. When you return from the last altar, your senior wizard will give you a number of tokens. you will get 50 tokens per altar that your team has captured, provided that you contribute to the capture in some way. you will get an extra if your team captured more altars overall, or 50 extra if it is a draw. You can exchange the tokens for rewards by speaking to me. you may also find rune essence appearing in your inventory at the end of each round. this is a side product of the absorption process and you are free to use it as you wish."] = "Una pregunta justa. Hemos acordado un esquema de tokens que le permite elegir entre varias recompensas. Cuando regreses del último altar, tu mago mayor te dará una cantidad de fichas. Obtendrás 50 fichas por cada altar que tu equipo haya capturado, siempre que contribuyas a la captura de alguna manera. Obtendrás un extra si tu equipo capturó más altares en general, o 50 extra si hay un empate. Puedes cambiar las fichas por recompensas hablando conmigo. También puedes encontrar esencia rúnica que aparece en tu inventario al final de cada ronda. Este es un producto secundario del proceso de absorción y puedes usarlo como desees.",
    ["Which colour orb is best?"] = "¿Qué color de orbe es mejor?",
    ["Wizard Acantha believes that the green orbs are best. Wizard Vief believes that the yellow ones are. You should help out the wizard whose team you join."] = "Wizard Acantha cree que los orbes verdes son los mejores. Wizard Vief cree que los amarillos lo son. Deberías ayudar al mago a cuyo equipo te unes.",
    ["But what do you think?"] = "¿Pero qué piensas?",
    ["Does it matter?"] = "¿Importa?",
    ["*Talking to her Acantha when teams are not full*"] = "*Hablando con su Acantha cuando los equipos no están llenos*",
    ["You look slightly more intelligent then the rest of these goons. Will you help me?"] = "Te ves un poco más inteligente que el resto de estos matones. ¿Me ayudarás?",
    ["Yes, I'll help."] = "Sí, te ayudaré.",
    ["*If you are wearing a hat slot item or wielding something*"] = "*Si llevas un objeto con ranura para sombrero o empuñas algo*",
    ["You need your head, hand, and two inventory slots, or I can't give you the necessary equipment."] = "Necesitas tu cabeza, tu mano y dos espacios de inventario, o no puedo darte el equipo necesario.",
    ["*Dialogue Ends*"] = "*Termina el diálogo*",
    ["*Else*"] = "*Más*",
    ["*You are on Green team* I knew you were an Intelligent lad. Here are your wands. When each team has enough people, Wizard Elriss will open the portal and you can get started. While we wait, shall I tell you what you need to do?"] = "*Estás en el equipo Verde* Sabía que eras un muchacho inteligente. Aquí están tus varitas. Cuando cada equipo tenga suficientes personas, Wizard Elriss abrirá el portal y podrá comenzar. Mientras esperamos, ¿te digo lo que tienes que hacer?",
    ["You already told me what to do."] = "Ya me dijiste qué hacer.",
    ["I know that! I'm not senile, you know. Repetition is good for understanding. Tell me what you know, Mr. Smarty Pants."] = "¡Lo sé! No estoy senil, ¿sabes? La repetición es buena para comprender. Dígame lo que sabe, Sr. Sabelotodo.",
    ["err, Green orbs good, yellow orbs bad."] = "err, los orbes verdes son buenos, los orbes amarillos son malos.",
    ["You won't be winning any awards for verbosity, but you got the gist of it."] = "No ganarás ningún premio por la verbosidad, pero entendiste lo esencial.",
    ["Help with what?"] = "¿Ayuda con qué?",
    ["Don't you keep up with the runecrafting theory journal? We've been making major discoveries! The youth of today are so lazy. Shall I tell you about it?"] = "¿No te mantienes al día con el diario teórico de creación de runas? ¡Hemos estado haciendo grandes descubrimientos! Los jóvenes de hoy son muy vagos. ¿Te lo cuento?",
    ["Sure, what am I supposed to do?"] = "Claro, ¿qué se supone que debo hacer?",
    ["When we began formally studying the rune altars, we saw a spike in the energy fields surrounding altars when there is an increase in rune production. When an essence is used on the altar, energy is transferred and bound into the essence, creating a rune. As with all transfers of energy, some of it is lost in the process. This lost energy, manifested as green orbs, needs to be returned to the altar to keep them well maintained. When the green energy escapes during the transfer, yellow energy particles in the air gather around the pure green energy. They turn into opposing orbs and must be kept away as they are impure energy forms. I need you to put the green orbs back into the altar. I will give you two wands to move the orbs around and a third wand to create barrios to prevent those pesky yellow orbs from getting in. To further this cause, we've set up a project to repair the altars. I just wanted to call it The Orb Project, but the buffoon wanted it to sound grander, so now it's The Great Orb Project. As if it needed an adjective."] = "Cuando comenzamos a estudiar formalmente los altares de runas, vimos un aumento en los campos de energía que rodean los altares cuando hay un aumento en la producción de runas. Cuando se usa una esencia en el altar, la energía se transfiere y se une a la esencia, creando una runa. Como ocurre con todas las transferencias de energía, parte de ella se pierde en el proceso. Esta energía perdida, que se manifiesta como orbes verdes, debe devolverse al altar para mantenerlos en buen estado. Cuando la energía verde se escapa durante la transferencia, las partículas de energía amarillas en el aire se juntan alrededor de la energía verde pura. Se convierten en orbes opuestos y deben mantenerse alejados ya que son formas de energía impura. Necesito que vuelvas a poner los orbes verdes en el altar. Te daré dos varitas para mover los orbes y una tercera varita para crear barrios y evitar que entren esos molestos orbes amarillos. Para promover esta causa, hemos establecido un proyecto para reparar los altares. Solo quería llamarlo The Orb Project, pero el bufón quería que sonara más grandioso, así que ahora es The Great Orb Project. Como si necesitara un adjetivo.",
    ["Okay, okay. Green orbs into the altar, Yellow orbs away."] = "Está bien, está bien. Orbes verdes en el altar, orbes amarillos lejos.",
    ["Well, at least your aren't as thick as that Wizard Vief. Make sure to stop his apprentices putting yellow orbs into the altars. Use your wands intelligently and you will come out victorious."] = "Bueno, al menos no eres tan gordo como ese Wizard Vief. Asegúrate de evitar que sus aprendices coloquen orbes amarillos en los altares. Usa tus varitas de forma inteligente y saldrás victorioso.",
    ["Right, yellow orbs into the altar, green orbs away."] = "Derecha, orbes amarillos en el altar, orbes verdes lejos.",
    ["Read my lips, Whippersnapper! NO YELLOW ORBS IN THE ALTAR."] = "¡Lee mis labios, Whippersnapper! NO HAY ORBES AMARILLOS EN EL ALTAR.",
    ["Eek! Okay, okay. Green orbs into the altar, yellow orbs away. So what do I get for all this hard work?"] = "¡Eek! Está bien, está bien. Orbes verdes en el altar, orbes amarillos lejos. Entonces, ¿qué obtengo por todo este arduo trabajo?",
    ["Aaaah, a true mercenary. Although we cannot agree scientifically, Vief and I have decided to reward those who help us. If you get more green orbs into the altar than the yellow team gets yellow orbs, you win the altar. You will receive rune essence each round you win. The team who wins the most altars will receive tokens which you exchange with Wizard Elriss in exchange for a reward. I don't know the exact details, so It's best to speak to her."] = "Aaaah, un verdadero mercenario. Aunque científicamente no podemos ponernos de acuerdo, Vief y yo hemos decidido recompensar a quienes nos ayudan. Si obtienes más orbes verdes en el altar que los que obtiene el equipo amarillo, ganarás el altar. Recibirás esencia de runas en cada ronda que ganes. El equipo que gane la mayor cantidad de altares recibirá tokens que intercambiará con Wizard Elriss a cambio de una recompensa. No conozco los detalles exactos, así que es mejor hablar con ella.",
    ["How can you be sure which orb is good?"] = "¿Cómo puedes estar seguro de qué orbe es bueno?",
    ["Do you think I got where I am today on false calculations? I researched it, that's how I know! There was a time when my opinion was respected and accepted without question. Age steals that from you. I will not enplane my findings to fools. If you want to see how I reached my conclusions you should keep up with the scientific Wizarding community. I have no time for laziness! Wizard Vief, in an attempt to progress his career, has decided to disagree with my findings and cast doubt upon my ability as a wizard. What better way to attract attention to one's self than disagree with those more knowledgeable? Pay no attention to that man, he is a buffoon."] = "¿Crees que llegué a donde estoy hoy gracias a cálculos falsos? Lo investigué, ¡así lo sé! Hubo un tiempo en que mi opinión era respetada y aceptada sin lugar a dudas. La edad te roba eso. No comunicaré mis hallazgos a los tontos. Si quieres ver cómo llegué a mis conclusiones, debes mantenerte al día con la comunidad científica mágica. ¡No tengo tiempo para la pereza! Wizard Vief, en un intento por progresar en su carrera, decidió no estar de acuerdo con mis hallazgos y poner en duda mi capacidad como mago. ¿Qué mejor manera de llamar la atención sobre uno mismo que no estar de acuerdo con quienes tienen más conocimientos? No le hagas caso a ese hombre, es un bufón.",
    ["Ahh, you'll help me, won't you?"] = "Ahh, me ayudarás, ¿no?",
    ["Yes, I will help."] = "Sí, te ayudaré.",
    ["*If you are wearing Anything in the head or hand inventory spot*"] = "*Si llevas algo en el inventario de la cabeza o la mano*",
    ["All that junk your carrying will interfere with the magic. I'll need to give you a hat, put something in your hand, and two things in your inventory."] = "Toda esa basura que llevas interferirá con la magia. Necesitaré darte un sombrero, poner algo en tu mano y dos cosas en tu inventario.",
    ["Excellent. Here are your wands. wait here and Wizard Elriss will open the portal when there are enough people to start. now, have I told you what to do yet?"] = "Excelente. Aquí están tus varitas. Espere aquí y Wizard Elriss abrirá el portal cuando haya suficientes personas para comenzar. Ahora, ¿ya te dije qué hacer?",
    ["Yes, you told me what to do."] = "Sí, me dijiste qué hacer.",
    ["Excellent."] = "Excelente.",
    ["Wizard Elriss told me what to do."] = "Wizard Elriss me dijo qué hacer.",
    ["Well, that's something, but I should make sure you have the details right. Remember, you need to get the yellow orbs into the altar. got that? the yellow ones. keep the green ones away."] = "Bueno, eso es algo, pero debo asegurarme de que tienes los detalles correctos. Recuerda, debes llevar los orbes amarillos al altar. ¿entendido eso? los amarillos. Mantén alejados a los verdes.",
    ["Green good, yellow bad. Got it."] = "Verde bueno, amarillo malo. Entiendo.",
    ["Weren't you paying attention? Yellow orbs are good, green orbs are bad! Move the yellow orbs next to the altar and the green ones away. Acantha might have told you that the green ones are good, but she has her calculations the wrong way round. Don't let her fool you!"] = "¿No estabas prestando atención? ¡Los orbes amarillos son buenos, los orbes verdes son malos! Mueve los orbes amarillos al lado del altar y los verdes lejos. Acantha podría haberte dicho que los verdes son buenos, pero sus cálculos están al revés. ¡No dejes que te engañe!",
    ["Wizard Acantha told me what to do."] = "Wizard Acantha me dijo qué hacer.",
    ["You listened to her? You Idiot! 'Wizard' Acantha is old and senile. she made an elementary mistake in her calculations and got the green and yellow orbs mixed up. Remember, it's the yellow orbs that are the good ones. Get them into the altars, keep the green ones away. got that?"] = "¿La escuchaste? ¡Idiota! El 'mago' Acantha es viejo y senil. cometió un error elemental en sus cálculos y confundió los orbes verdes y amarillos. Recuerde, son los orbes amarillos los buenos. Llévalos a los altares, mantén alejados a los verdes. ¿entendido eso?",
    ["How can you be sure your right?"] = "¿Cómo puedes estar seguro de que tienes razón?",
    ["I... but... isn't it obvious? You just need to take Wizard Hellam's discoveries about the elemental rune energy signature and then extrapolate to include all kinds of runes. then, if you apply the lefebvre transformation to them... I assume you know the lefebvre equations?"] = "Yo... pero... ¿no es obvio? Sólo necesitas tomar los descubrimientos del mago Hellam sobre la firma de energía rúnica elemental y luego extrapolarlos para incluir todo tipo de runas. entonces, si les aplicas la transformación de Lefebvre... ¿Supongo que conoces las ecuaciones de Lefebvre?",
    ["Well, I *(Vief cuts you off)*"] = "Bueno, yo *(Vief te interrumpe)*",
    ["Of course you do, I shouldn't have asked. anyway, if you do that, you'll easily see the signature of an external manifestation of runecrafting energy. Then you will need to apply Wizard Bennay's theory of light..."] = "Por supuesto que sí, no debería haber preguntado. de todos modos, si haces eso, verás fácilmente la firma de una manifestación externa de energía de creación de runas. Entonces necesitarás aplicar la teoría de la luz del mago Bennay...",
    ["*Wizard Vief continues at length and you don't understand any of it.*"] = "*Wizard Vief continúa extensamente y no entiendes nada.*",
    ["The runesphere has changed its type!"] = "¡La runesfera ha cambiado de tipo!",
    ["You do not have the rune essence required to siphon from the current layer."] = "No tienes la esencia rúnica necesaria para extraer la esencia rúnica de la capa actual.",
    ["Peace in balance, friend."] = "Paz en equilibrio, amigo.",
    ["Every year, we come back here on pilgrimage to this tribute stone. It is a stack of rune essences brought by all those who wanted to pay Guthix their respects after his passing."] = "Cada año volvemos aquí en peregrinación a esta piedra homenaje. Es una pila de esencias rúnicas traídas por todos aquellos que quisieron presentar sus respetos a Guthix tras su fallecimiento.",
    ["You can use it to pray and commune, just like us."] = "Puedes usarlo para orar y comulgar, como nosotros.",
    ["Hey, you. Got any pearls?"] = "Hola, tú. ¿Tienes alguna perla?",
    ["I like da shiny ones. *sniff*"] = "Me gustan los brillantes. *olfatea*",
    ["What do you trade for them?"] = "¿Qué cambias por ellos?",
    ["Nothing. You just gives me."] = "Nada. Sólo me das.",
    ["*sniff* Can't leave Globin' cos da totems. Scary."] = "*sniff* No puedo dejar Globin porque hay tótems. Aterrador.",
    ["*sniff* Can't collect own pearls."] = "*sniff* No puedo recolectar mis propias perlas.",
    ["Sorry, I don't."] = "Lo siento, no lo hago.",
    ["Aww! Runnynose sad."] = "¡Ay! Runnynose triste.",
    ["I have a telepearl."] = "Tengo una teleperla.",
    ["Ooh, can escapes! Can I have?"] = "¡Oh, puede escapar! ¿Puedo tener?",
    ["Give telepearl to Runnynose?"] = "¿Dar teleperla a Runnynose?",
    ["Here you go."] = "Aquí tienes.",
    ["Thanks! You can have this. Is not shiny anyway."] = "¡Gracias! Puedes tener esto. De todos modos no es brillante.",
    ["Thanks! Shiny! Can't escape anyway, just collect."] = "¡Gracias! ¡Brillante! No puedo escapar de todos modos, solo recoge.",
    ["Good day, your Royal Highness."] = "Buenos días, Alteza Real.",
    ["Oh, leave an old dwarf in peace will you?"] = "Oh, deja en paz a un viejo enano, ¿quieres?",
    ["Why, what's wrong?"] = "¿Por qué? ¿Qué pasa?",
    ["Ninety years down in the mines, and this is all I got out of it. All my life wasted away."] = "Noventa años en las minas, y esto es todo lo que saqué de ello. Toda mi vida se desperdició.",
    ["You've still got a nice house, don't you?"] = "Aún tienes una bonita casa, ¿no?",
    ["A crummy old house in East, that's all my life amounts to."] = "Una casa vieja y de mala muerte en el este, eso es todo lo que representa mi vida.",
    ["I'll leave you alone then."] = "Entonces te dejaré en paz.",
    ["Why are you bothering me, human? I laboured in the mines for ninety years, and I want a bit of peace now that I'm retired."] = "¿Por qué me molestas, humano? Trabajé en las minas durante noventa años y quiero un poco de paz ahora que estoy jubilado.",
    ["Tell me about your life as a miner."] = "Cuéntame sobre tu vida como minero.",
    ["You want me to talk about mining, huh? Ahhh, I remember swinging my pickaxe hour after hour, day after day, down in the dark and damp mines."] = "Quieres que hable de minería, ¿eh? Ahhh, recuerdo balancear mi pico hora tras hora, día tras día, en las minas oscuras y húmedas.",
    ["Old Saggy-face, the supervisor, would be there with his sharpest pickaxe, looking out for slackers to impale. Of course, the trolls got him in the end."] = "El viejo Saggy-face, el supervisor, estaría allí con su pico más afilado, buscando vagos para empalar. Por supuesto, al final los trolls lo atraparon.",
    ["Poor old Saggy-face. We'd found a tribe of trolls roaming the tunnels: huge trolls from the mountains."] = "Pobre cara caída. Habíamos encontrado una tribu de trolls deambulando por los túneles: enormes trolls de las montañas.",
    ["Saggy-face tried to take them on single-handed, and they ripped his head clean off his shoulders."] = "Saggy-face intentó enfrentarse a ellos sin ayuda de nadie, y le arrancaron la cabeza de los hombros.",
    ["Fortunately, we had that mad human, Dissy, staying in the city at the time. He drove those trolls right out of the mines with his magicks."] = "Afortunadamente, teníamos a esa humana loca, Dissy, quedándose en la ciudad en ese momento. Expulsó a esos trolls de las minas con su magia.",
    ["Dissy, huh? Was his full name Dionysius?"] = "Dissy, ¿eh? ¿Era su nombre completo Dionisio?",
    ["All human names sound the same to me. Here, I've got my old diary from that time. Take it and read all about those days."] = "Todos los nombres humanos me suenan igual. Aquí tengo mi viejo diario de esa época. Tómalo y lee todo sobre esos días.",
    ["[The old dwarf gives you a tatty book.]"] = "[El viejo enano te regala un libro gastado.]",
    ["I need another copy of your diary."] = "Necesito otra copia de tu diario.",
    ["Bah! Young people are so careless. I suppose I'll have to give you another copy."] = "¡Bah! Los jóvenes son tan descuidados. Supongo que tendré que darte otra copia.",
    ["Bah! Young people are so careless."] = "¡Bah! Los jóvenes son tan descuidados.",
    ["I gave it to Dionysius, the mage who helped you drive out the trolls from your mines."] = "Se lo di a Dionysius, el mago que te ayudó a expulsar a los trolls de tus minas.",
    ["I'm glad I'm not the only person from those days who's still alive. Here, I'll give you another copy."] = "Me alegro de no ser la única persona de aquellos días que sigue viva. Toma, te daré otra copia.",
    ["My inventory's too full."] = "Mi inventario está demasiado lleno.",
    ["Ah, you young people always have so much stuff. In my day, we just carried a pickaxe, and that was enough for us."] = "Ah, ustedes, los jóvenes, siempre tienen tantas cosas. En mis tiempos solo llevábamos un pico y eso nos bastaba.",
    ["Can you give me any free stuff?"] = "¿Puedes darme algo gratis?",
    ["Bah! In my day, people worked for a living, and anyone who wouldn't work got a short, sharp shock with a pickaxe. That's how it was. Ahhh."] = "¡Bah! En mi época, la gente trabajaba para ganarse la vida, y cualquiera que no quisiera trabajar recibía un golpe corto y fuerte con un pico. Así fue. Ahhh.",
    ["So that's 'no', then?"] = "Entonces, ¿eso es \"no\"?",
    ["Go away!"] = "¡Vete!",
    ["Sorry, I'll leave you alone."] = "Lo siento, te dejaré en paz.",
    ["Good!"] = "¡Bien!",
    ["I say! Where on Gielinor did that voice come from?"] = "¡Yo digo! ¿De dónde vino esa voz en Gielinor?",
    ["Uh, hello there! Can you hear me?"] = "¡Hola! ¿Puedes oírme?",
    ["Why yes. Yes I can. My word. Is that...is that one of the gods? Guthix perhaps? Saradomin?"] = "Por qué sí. Sí puedo. Mi palabra. ¿Es ese... es ese uno de los dioses? ¿Quizás Guthix? ¿Saradomin?",
    ["No, no. I'm not either of them."] = "No, no. Yo no soy ninguno de los dos.",
    ["Egad! You're not...Zamorak...are you? I mean, uh...begging your pardon of course, my Lord. No offence intended!"] = "¡Egad! No eres...Zamorak...¿verdad? Quiero decir, uh... con su perdón, por supuesto, mi Señor. ¡Sin ánimo de ofender!",
    ["Ha ha! No, I'm speaking to you through the pipe here! I'm at the bottom of your tower."] = "¡Ja, ja! ¡No, te estoy hablando a través del tubo! Estoy al pie de tu torre.",
    ["Oh. Oh I see! Oh, yes. How clever! Remarkable idea! However did you think of that? Good show, old bean!"] = "Oh. ¡Ah, claro! Oh sí. ¡Qué inteligente! ¡Excelente idea! ¿Cómo pensaste en eso? ¡Buen espectáculo, viejo frijol!",
    ["Rupert the Beard. At your service, old fruit."] = "Rupert the Beard. A sus ordenes, fruta vieja.",
    ["Yes, old turnip. On account of my wonderfully long bearded chin, you see."] = "Sí, nabo viejo. A causa de mi barbilla maravillosamente larga, ¿sabes?",
    ["So what are you doing up there exactly? And how come you talk so strangely?"] = "Entonces, ¿qué estás haciendo exactamente ahí arriba? ¿Y por qué hablas tan raro?",
    ["What am I doing? Well, I guess I'm stuck in a matter of speaking. Dear me, yes! I'm stuck. And I speak in the King's speech, I'll have you know."] = "¿Qué estoy haciendo? Bueno, supongo que estoy estancado en una cuestión de hablar. ¡Dios mío, sí! Estoy estancado. Y hablo en el discurso del Rey, te lo haré saber.",
    ["Really? Which king?"] = "¿En serio? ¿Qué rey?",
    ["Which K...? Why, THE King old spud! THE King! Only one worth mentioning in my opinion."] = "¿Cuál K...? ¡Vaya, EL Rey, viejo! ¡EL Rey! En mi opinión sólo vale la pena mencionar uno.",
    ["I see. Well is there anything I can do to help you up there?"] = "Ya veo. Bueno, ¿hay algo que pueda hacer para ayudarte ahí arriba?",
    ["Hmmm. No, no, I can't think of anything at the moment. I'm a bit stuck. Let me know if you get any ideas though."] = "Hmmm. No, no, no se me ocurre nada en este momento. Estoy un poco estancado. Déjame saber si tienes alguna idea.",
    ["I'll do my best!"] = "¡Haré lo mejor que pueda!",
    ["Hello, Rupert."] = "Hola, Ruperto.",
    ["Hello again, old cheesecake! Wonderful to see you."] = "¡Hola de nuevo, viejo pastel de queso! Es maravilloso verte.",
    ["How are the investigations going?"] = "¿Cómo van las investigaciones?",
    ["Thanks to you freeing me, very well! I have much more to do of course, but now I am free, I can continue where I left off."] = "¡Gracias a que me liberaste, muy bien! Tengo mucho más que hacer por supuesto, pero ahora soy libre y puedo continuar donde lo dejé.",
    ["That's great news!"] = "¡Es una gran noticia!",
    ["What's the trouble, old bellybutton fluff?"] = "¿Cuál es el problema, viejo pelusa del ombligo?",
    ["I lost that helmet you gave me."] = "Perdí ese casco que me diste.",
    ["I see. Well you might be in luck. I have recently made another one to replace it. I guess you could have it for 60,000 gold. For the materials, you understand."] = "Ya veo. Bueno, puede que tengas suerte. Recientemente hice otro para reemplazarlo. Supongo que podrías tenerlo por 60.000 de oro. En cuanto a los materiales, ya lo entiendes.",
    ["Ok, that sounds fair."] = "Ok, eso suena justo.",
    ["Hmm. It looks like you're going to need more space in your inventory first, old jumper. Come back and see me again when you've made some room."] = "Mmm. Parece que primero necesitarás más espacio en tu inventario, viejo saltador. Vuelve a verme de nuevo cuando hayas hecho espacio.",
    ["Ok."] = "Vale.",
    ["Hmm. It looks like you don't have enough on you, old porridge. Come back and see me again when you have a bit more gold on you."] = "Mmm. Parece que no tienes suficiente, vieja papilla. Vuelve a verme otra vez cuando tengas un poco más de oro contigo.",
    ["There you are! I hope this one serves you well enough, old cabbage."] = "¡Ahí estás! Espero que esto te sirva lo suficiente, repollo viejo.",
    ["Thanks, Rupert!"] = "¡Gracias, Rupert!",
    ["I don't think I can afford that, sorry."] = "No creo que pueda permitirme eso, lo siento.",
    ["No problem! Come back and see me if you change your mind, old garters."] = "¡No hay problema! Vuelvan a verme si cambian de opinión, viejos ligueros.",
    ["What are you after, human? I'm busy making robust glass from red sandstone."] = "¿Qué buscas, humano? Estoy ocupado fabricando vidrio resistente con arenisca roja.",
    ["What brings you to Oo'glog?"] = "¿Qué te trae a Oo'glog?",
    ["There is red sandstone in this area, of the finest quality in all the land."] = "En esta zona hay arenisca roja, de la mejor calidad de todo el terreno.",
    ["At first, it didn't seem safe to venture into a town full of ogresses, but it came to my attention that Oo'glog had become a holiday resort. So now I've come to see what I can find."] = "Al principio, no parecía seguro aventurarse en una ciudad llena de ogresas, pero me llamó la atención que Oo'glog se había convertido en un lugar de vacaciones. Así que ahora he venido a ver qué puedo encontrar.",
    ["What do you want with red sandstone?"] = "¿Qué quieres con arenisca roja?",
    ["This special machine I've made will combine red sandstone with special, secret ingredients to produce robust glass."] = "Esta máquina especial que he creado combinará arenisca roja con ingredientes secretos especiales para producir vidrio resistente.",
    ["What is robust glass?"] = "¿Qué es el vidrio robusto?",
    ["Could I use the machine please?"] = "¿Puedo usar la máquina por favor?",
    ["Where can I find red sandstone?"] = "¿Dónde puedo encontrar arenisca roja?",
    ["The very walls of this town are made from the stuff. The ogresses don't like me chipping away at their walls, but there is a large separate piece near the outside of the north wall."] = "Las mismas murallas de esta ciudad están hechas de ese material. A las ogresas no les gusta que destruya sus paredes, pero hay una gran pieza separada cerca del exterior de la pared norte.",
    ["Big piece of rock that it is, you should be able to mine about fifty pieces of red sandstone a day from it."] = "Por muy grande que sea la roca, deberías poder extraer unas cincuenta piezas de arenisca roja al día.",
    ["What is that machine?"] = "¿Qué es esa máquina?",
    ["Well, I'll leave you to it then."] = "Bueno, te dejo con eso entonces.",
    ["Okay bye."] = "Está bien, adiós.",
    ["I suppose it couldn't do any harm. You'll have to supply the red sandstone yourself, though."] = "Supongo que no podría hacer ningún daño. Pero tendrás que suministrar la piedra arenisca roja tú mismo.",
    ["It's much tougher than ordinary glass. Skilled crafters can use it to make potion flasks which can hold more liquid than ordinary vials."] = "Es mucho más resistente que el vidrio normal. Los artesanos expertos pueden utilizarlo para fabricar frascos de pociones que pueden contener más líquido que los viales normales.",
    ["Ordinary glass comes under too much stress if it contains too much magical liquid. Robust flasks can hold six doses of potion."] = "El vidrio común sufre demasiado estrés si contiene demasiado líquido mágico. En unos robustos frascos caben seis dosis de poción.",
    ["Nothing, sorry to bother you."] = "Nada, perdón por molestarte.",
    ["Do you always use other people's things without asking?"] = "¿Siempre usas las cosas de otras personas sin preguntar?",
    ["Sorry to bother you."] = "Perdón por molestarte.",
}

return dialogues
